    dijkstra_pair ds(h, w);

    rep(i, h) rep(j, w - 1) {
        if ((a[i][j] == '.' || a[i][j] == 'S')
                && (a[i][j + 1] == '.' || a[i][j + 1] == 'S')) {
            ds.set_E(i, j, i, j + 1);
            ds.set_E(i, j + 1, i, j);
        }
    }

    rep(i, h - 1) rep(j, w) {
        if ((a[i][j] == '.' || a[i][j] == 'S')
                && (a[i + 1][j] == '.' || a[i + 1][j] == 'S')) {
            ds.set_E(i, j, i + 1, j);
            ds.set_E(i + 1, j, i, j);
        }
    }
    ll si, sj;

    rep(i, h) rep(j, w) {
        if (a[i][j] == 'S') {
            si = i, sj = j;
            goto loopcut;
        }
    }
loopcut:

    ds.calc(si, sj);
    ll ans = LINF;

    rep(i, h) rep(j, w) {
        if (ds.get_d(i, j) <= k) {
            ll dist = CEIL(min({i, j, h - 1 - i, w - 1 - j}), k) + 1;
            ans = min(ans, dist);
        }
    }

    rep(i, h) rep(j, w) {
        if (i != 0 && i != h - 1 && j != 0 && j != w - 1) continue;
        if (ds.get_d(i, j) <= k) ans = 1;
    }

    cout << ans << endl;
    return 0;
}

