using namespace std;

typedef pair<int,int> ii;

#define MAX 810
int H,W,K;
string A[MAX];
bool first_step[MAX][MAX];
int dx[] = {0,1,0,-1};
int dy[] = {1,0,-1,0};

bool isValid(int x,int y) { return 0 <= x && x < W && 0 <= y && y < H; }

ii getSP() {
  rep(i,H) rep(j,W) if( A[i][j] == 'S' ) { return ii(i,j); }
  assert(false);
}

void first_BFS(int sx,int sy) {
  memset(first_step,false,sizeof first_step);
  deque<ii> deq;
  deq.push_back(ii(sx+sy*W,K));
  first_step[sy][sx] = true;
  while( !deq.empty() ) {
    ii v = deq.front(); deq.pop_front();
    int p = v.first;
    int step = v.second;
    int x = p % W;
    int y = p / W;
    rep(i,4) {
      int nx = x + dx[i];
      int ny = y + dy[i];
      if( !isValid(nx,ny) ) continue;
      if( A[ny][nx] == '#' ) continue;
      if( first_step[ny][nx] ) continue;
      int nstep = step - 1;
      if( nstep < 0 ) continue;
      first_step[ny][nx] = true;
      deq.push_back(ii(nx+ny*W,nstep));
    }
  }
}

int mini[MAX][MAX];

void compute() {
  ii sp = getSP();
  int sx = sp.second, sy = sp.first;
  A[sy][sx] = '.';

  first_BFS(sx,sy);
  /*
  rep(i,H) {
    rep(j,W) {
      if( first_step[i][j] ) cout << "o";
      else cout <<"x";
    }
    puts("");
  }
  */
  rep(i,H) if( first_step[i][0] || first_step[i][W-1] ) {
    puts("1");
    return;
  }
  rep(i,W) if( first_step[0][i] || first_step[H-1][i] ) {
    puts("1");
    return;
  }

  deque<ii> deq;
  rep(i,H) rep(j,W) mini[i][j] = INT_MAX;
  rep(i,H) rep(j,W) if( first_step[i][j] ) {
    mini[i][j] = 0;
    deq.push_back(ii(j+i*W,0));
  }
  while( !deq.empty() ) {
    ii tmp = deq.front(); deq.pop_front();
    int p = tmp.first;
    int cost = tmp.second;
    int x = p % W;
    int y = p / W;
    rep(i,4) {
      int nx = x + dx[i];
      int ny = y + dy[i];
      if( !isValid(nx,ny) ) continue;
      if( mini[ny][nx] > cost + 1 ) {
	mini[ny][nx] = cost + 1;
	deq.push_back(ii(nx+ny*W,mini[ny][nx]));
      }
    }
  }
  int ans = INT_MAX;
  rep(i,H) {
    int cost = 1;
    cost += ceil(mini[i][0]/(double)K);
    ans = min(ans,cost);
    cost = 1;
    cost += ceil(mini[i][W-1]/(double)K);
    ans = min(ans,cost);
  }
  rep(i,W) {
    int cost = 1;
    cost += ceil(mini[0][i]/(double)K);
    ans = min(ans,cost);
    cost = 1;
    cost += ceil(mini[H-1][i]/(double)K);
    ans = min(ans,cost);
  }
  cout << ans << endl;
}

int main() {
  cin >> H >> W >> K;
  rep(i,H) cin >> A[i];
  compute();
  return 0;
}

