	while (d.size()) {
		int x = d.front().first, y = d.front().second;
		d.pop_front();
		if (dis[x][y] <= k) {
			res = min({res, 1 + (x + k - 1) / k, 1 + (y + k - 1) / k, 1 + (n - x + k - 1) / k, 1 + (m - y + k - 1) / k});
		}
		for (int dx = x - 1; dx <= x + 1; dx += 2) {
