ll H, W, K;
const ll inf = 5e15;

ll dist_to_outside(ll h, ll w) {
    return var_min(h, (H - 1) - h,
                   w, (W - 1) - w);
}

ll rest_magic(ll h, ll w) {
    ll dist = dist_to_outside(h, w);
    return dist / K + !!(dist % K);
}

int main() {
    cin >> H >> W >> K;
    V<string> A(H);
