    for(ll i = 0; i < H; i++) for(ll j = 0; j < W; j++) if(A[i][j] == 'S') {
        sh = i;
        sw = j;
        break;
    }

    ll ans = inf;
    queue<pair<PLL, ll>> que;
    que.emplace(PLL(sh, sw), 0);
    VV<ll> dists = make_v<ll>(inf, H, W);
    dists[sh][sw] = 0;
    ll dh[] = { 1, 0, -1, 0 };
    ll dw[] = { 0, 1, 0, -1 };

    while(que.size()) {
        ll h, w, d;
        tie(h, w) = que.front().first;
        d = que.front().second;
        que.pop();
        if(dists[h][w] < d) continue;
        chmin(ans, rest_magic(h, w));
        if(d == K) continue;
        for(ll i = 0; i < 4; i++) {
            ll nh = h + dh[i];
            ll nw = w + dw[i];
            ll nd = d + 1;
