		scanf("%s", mat[i]);
	}

	P t;

	for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) {
		if (mat[i][j] == 'S') {
			t = P(i, j);
		}
	}

	queue<P> que;

	memset(d, -1, sizeof(d));

	d[t.ft][t.sd] = 0;
	que.push(t);

	while (!que.empty()) {
		P p = que.front(); que.pop();

		if (d[p.ft][p.sd] == k) break;

		for (int i = 0; i < 4; i++) {
			int nx = p.ft + dx[i], ny = p.sd + dy[i];

			if (nx >= 0 && nx < n && ny >= 0 && ny < m && mat[nx][ny] == '.' && d[nx][ny] < 0) {
				d[nx][ny] = d[p.ft][p.sd] + 1;
				que.push(P(nx, ny));
			}
		}
	}

	int res = INT_MAX;

	for (int i = 0; i < n; i++) for (int j = 0; j < m; j++) if (~d[i][j]) {
		res = min(res, (min(min(i, n - i - 1), min(j, m - j - 1)) + k - 1) / k + 1);
	}

	printf("%d\n", res);

	return 0;
}

