int H;
int W;

int K;

int SX;
int SY;

vector<string> M;

int dist(int x, int y)
{
    int d1 = x;
    int d2 = W-1 - x;
    int d3 = y;
    int d4 = H-1 - y;

    return min({ d1, d2, d3, d4 });
}

int bfs()
{
    int dmin = INF;

    vector<deque<bool>> visited(H, deque<bool>(W, false));
    queue<tuple<int,int,int>> que;
    que.emplace(SX,SY,K);
    visited[SY][SX] = true;

    while(!que.empty()) {
        int x,y,n; tie(x,y,n) = POP(que);

        chmin(dmin, dist(x,y));
        if(n == 0) continue;

        for(const auto& p : neighbor4(x,y)) {
            int xx,yy; tie(xx,yy) = p;
            if(!in_bounds_wh(xx, yy, W, H)) continue;
            if(M[yy][xx] == '#') continue;
            if(visited[yy][xx]) continue;

            que.emplace(xx,yy,n-1);
            visited[yy][xx] = true;
        }
    }

    return dmin;
}

void solve()
{
    int dmin = bfs();
#ifdef DEBUG
    DBG(dmin);
#endif

    int ans = 1 + div_ceil(dmin, K);

    PRINTLN(ans);
}

signed main(signed /*argc*/, char** /*argv*/)
{
    RD(H);
    RD(W);

    RD(K);

    REP(y, H) {
        string s; RD(s);
        REP(x, W) {
            char c = s[x];
            if(c == 'S') {
                SX = x;
                SY = y;
            }
        }
        M.emplace_back(s);
    }

#ifdef DEBUG
    DBG(SX);
    DBG(SY);
    DBG(M);
#endif

    solve();

    EXIT();
}

