int ans;


int Manhattan(int x, int y)
{
    if (x == 1 || x == h || y == 1 || y == w)
        return 0;
    int ret = min(x - 2, y - 2) / k + 1;
    ret = min(ret, min(h - x - 1, w - y - 1) / k + 1);
    return ret;
}

void Bfs()
{
    q.push(st);
    while (!q.empty())
    {
        Coord nod = q.front();
        q.pop();
        ans = min(ans, 1 + Manhattan(nod.x, nod.y));
        if (dist[nod.x][nod.y] >= k)
            continue;
        for (int d = 0; d < 4; ++ d)
            if (a[nod.x + dx[d]][nod.y + dy[d]] == '.' &&
                    (!dist[nod.x + dx[d]][nod.y + dy[d]] || dist[nod.x + dx[d]][nod.y + dy[d]] > dist[nod.x][nod.y] + 1))
            {
                dist[nod.x + dx[d]][nod.y + dy[d]] = dist[nod.x][nod.y] + 1;
                q.push({nod.x + dx[d], nod.y + dy[d]});
            }
    }
}

