typedef double db;

const int inf = 0x3f3f3f3f;
// const ll inf = 0x3f3f3f3f3f3f3f3f;
const db pi = 3.14159265358979323846264338327950288L;
const db eps = 1e-6;
const int mo = 1e9+7;

char grid[805][805];
bool vis[805][805];
int dr[4] = {1,0,-1,0};
int dc[4] = {0,1,0,-1};

int h,w,si,sj;
double k;

int reach(int i, int j) {
    return min(min(ceil((i)/k), ceil((h-i-1)/k)), min(ceil((j)/k), ceil((w-j-1)/k)));
}

int dist(int i, int j) {
    return abs(si-i) + abs(sj-j);
}

bool hasExit(int i, int j) {
    return i == 0 || i == (h-1) || j == 0 || j == (w-1);
}

int main() {
    R(h,w,k);
    rep(i,0,h-1) rep(j,0,w-1) {
        R(grid[i][j]);
        if (grid[i][j] == 'S') si = i, sj = j;
    }
    int ans = inf;
    queue<ii> q; q.push(ii(si,sj));
    vector<ii> v; v.pb(ii(si,sj));
    memset(vis, false, sizeof vis);
    while (!q.empty()) {
        ii p = q.front(); q.pop();
        vis[p.fi][p.se] = true;
        rep(k,0,3) {
            int ni = p.fi + dr[k], nj = p.se + dc[k];
            if (!vis[ni][nj] && grid[ni][nj] == '.' && dist(ni,nj) <= k) {
                q.push(ii(ni,nj));
                v.pb(ii(ni,nj));
            }
        }
    }
    rep(i,0,sz(v)-1) {
        ii p = v[i];
        if (hasExit(p.fi,p.se)) ans = 1;
        else ans = min(ans, 1+reach(p.fi,p.se));
    }
    W(ans);
    return 0;
}

