using namespace std;
int read()
{
	int x=0,f=1;char ch=getchar();
	while (ch<'0'||ch>'9'){if (ch=='-') f=-1;ch=getchar();}
	while (ch>='0'&&ch<='9'){x=x*10+ch-'0';ch=getchar();}
	return x*f;
}
int n,m,k,nowa,nowb;
char ch[Maxn][Maxn];
int f[Maxn][Maxn][2],a[Maxn][Maxn],dis[Maxn][Maxn];
bool flag[Maxn][Maxn],flag1[Maxn][Maxn][2];
int dx[4]={0,0,1,-1},dy[4]={1,-1,0,0};
int dfs1(int x,int y)
{
	if (flag[x][y]) return dis[x][y];
	flag[x][y]=true;
	if (a[x][y]==1) return inf;
	for (int i=0;i<4;i++)
	{
		int rx=x+dx[i],ry=y+dy[i];
		if (rx>=1&&rx<=n&&ry>=1&&ry<=m&&a[rx][ry]==0)
			dis[x][y]=min(dis[x][y],dfs1(rx,ry)+1);
	}
	return dis[x][y];
}
int dfs(int x,int y,int flag)
{
	if (x==1||x==n||y==1||y==m) return 0;
	if (flag1[x][y][flag]) return f[x][y][flag];
	flag1[x][y][flag]=true;
	if (flag)
	{
		for (int i=1;i<=n;i++)
			for (int j=1;j<=m;j++)
				if (dis[i][j]<=k) f[x][y][flag]=min(f[x][y][flag],dfs(i,j,0)+1);
	} else
	{
		for (int i=1;i<=n;i++)
			for (int j=1;j<=m;j++)
				if (abs(i-x)+abs(j-y)<=k) f[x][y][flag]=min(f[x][y][flag],dfs(i,j,0)+1);
	}
	return f[x][y][flag];
}
int main()
{
	n=read(),m=read(),k=read();
	memset(f,0,sizeof(f));
	for (int i=1;i<=n;i++)
	{
		for (int j=1;j<=m;j++)
		{
			ch[i][j]=getchar();
			while (ch[i][j]!='#'&&ch[i][j]!='S'&&ch[i][j]!='.') ch[i][j]=getchar();
			if (ch[i][j]=='#') a[i][j]=1; else a[i][j]=0;
			if (ch[i][j]=='S') nowa=i,nowb=j;
		}
	}
	for (int i=1;i<=n;i++)
		for (int j=1;j<=m;j++)
			f[i][j][0]=f[i][j][1]=inf,dis[i][j]=inf;
	dis[nowa][nowb]=0;
	memset(flag,false,sizeof(flag));
	for (int i=1;i<=n;i++)
		for (int j=1;j<=m;j++)
			if (a[i][j]==0) dis[i][j]=dfs1(i,j);
	memset(flag1,false,sizeof(flag1));
	printf("%d\n",dfs(nowa,nowb,1));
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
int n,m,k,d[4][2]={{-1,0},{1,0},{0,-1},{0,1}};
char mp[888][888];
bool vis[888][888];
struct node
{
	int x,y,num;
	node(int a=0,int b=0,int c=0) {x=a;y=b;num=c;}
};
queue<node>q;

void bfs(int x,int y)
{
	memset(vis,0,sizeof(vis));
	while(!q.empty()) q.pop();
	q.push(node(x,y,k));
	vis[x][y]=1;
	while(!q.empty())
	{
		node tp=q.front();q.pop();
		if(tp.num==0) continue;
		for(int i=0;i<4;++i)
		{
			int dx=tp.x+d[i][0],dy=tp.y+d[i][1];
			if(dx<0||dx>=n||dy<0||dy>=m) continue;
			if(mp[dx][dy]=='#') continue;
			if(vis[dx][dy]) continue;
			vis[dx][dy]=1;
			q.push(node(dx,dy,tp.num-1));
		}
	}
}
int cal(int L)
{
	if(L%k) return L/k+1;
	else return L/k;
}
int main()
{
    //freopen("3.txt","r",stdin);
	scanf("%d%d%d",&n,&m,&k);
	for(int i=0;i<n;++i) scanf("%s",mp[i]);
	for(int i=0;i<n;++i)
		for(int j=0;j<m;++j) if(mp[i][j]=='S') bfs(i,j);
	int ans=2*n*m;
	for(int i=0;i<n;++i)
	{
		for(int j=0;j<m;++j)
		{
			if(!vis[i][j]) continue;
			if(i==0||i==n-1||j==0||j==m-1) ans=min(ans,1);
			ans=min(ans,1+cal(i));
			ans=min(ans,1+cal(n-i-1));
			ans=min(ans,1+cal(j));
			ans=min(ans,1+cal(m-j-1));
		}
	}
	printf("%d\n",ans);
    return 0;
}

