int cal(int x,int y,int tx,int ty){
  return (abs(tx-x)+abs(ty-y)+K-1)/K;
}
void dfs(int x,int y) {
  vis[x][y]=1;
  ret=min(ret,cal(x,y,x,0)+1);
  ret=min(ret,cal(x,y,x,m-1)+1);
