void solve(){
	int H,W,K;
	cin >> H >> W >> K;
	vector< vector<int> > fld(H,vector<int>(W,0));
	pair<int,int> start;
	for(int r=0;r<H;++r){
		string str;
		cin >> str;
		for(int c=0;c<W;++c){
			if(str[c] == '#'){
				fld[r][c] = -1;
			}else if( str[c] == 'S' ){
				start.first = r;
				start.second = c;
			}
		}
	}
	int Q=K;
	int dr[] = {1,-1,0,0};
	int dc[] = {0,0,1,-1};
	fld[start.first][start.second] = 1;
	queue<pair<int,int> > now,next;
	next.push(start);
	int turn = 0;
	vector<pair<int,int> > List;//行ける場所
	List.push_back(start);//動けない場合=動かない場合
	while(Q--){
		++turn;
		now = next;
		{
			queue<pair<int,int> > zero;
			next = zero;
		}
		while( !now.empty() ){
			pair<int,int> temp;
			temp = now.front();now.pop();
			pair<int,int> move;
			for(int i=0;i<4;++i){
				int R = temp.first+dr[i];
				int C = temp.second+dc[i];
				if( R<0 || H <= R ) continue;
				if( C<0 || W <= C ) continue;
				if( fld[R][C] != 0 ) continue;
				fld[R][C] = turn;
				next.push(pair<int,int>(R,C));
				List.push_back(pair<int,int>(R,C));
			}
		}
	}
	int ans = INF;
	vector<pair<int,int> >::iterator itr,end;
	itr = List.begin();
	end = List.end();
	for(;itr!=end;++itr){
		int R = itr->first;
		int C = itr->second;
		if( R == 0 || C == 0 || R == H-1 || C == W-1 ){
			cout << 1 << endl;
			return;
		}
		//4方向
		int res = INF;
		res = min(res,R);
		res = min(res,C);
		res = min(res,H-1-R);
		res = min(res,W-1-C);
		ans = min(ans,(res+K-1)/K + 1);
	}
	cout << ans << endl;
}

