using P = pair<int, int>;

vector<P> getNear(P s) {
    queue<P> que;
    que.push(s);
    map<P, int> dp;
    dp[s] = 0;
    vector<P> ps;
    ps.push_back(s);

    while (que.size()) {
        auto now = que.front();
        que.pop();
        if(dp[now] > K) continue;
        rep(k, 4) {
            auto next = now;
            next.first += dy[k];
            next.second += dx[k];
            if (next.first < 0 || next.second < 0) continue;
            if (next.first >= H || next.second >= W) continue;
            if (dp.count(next)) continue;
            if (A[next.first][next.second] == '#') continue;
            dp[next] = dp[now] + 1;
            que.push(next);
            ps.push_back(next);
        }
    }
    return ps;
}

