        for(int j=0;j<w;j++)if(a[i][j]=='S')sr=i,sc=j;
    }
    queue<pair<int,int> > q;
    q.push(make_pair(sr,sc));
    d[sr][sc]=0;
    while(!q.empty()){
        pair<int,int> p=q.front();q.pop();
        res=min(res,casts(p.first,p.second)+1);
        if(d[p.first][p.second]==k)continue;
        for(int k=0;k<4;k++){
            int rr=p.first+rd[k],cc=p.second+cd[k];
            if(!inside(rr,cc) || a[rr][cc]=='#')continue;
            if(d[rr][cc]!=inf)continue;
            q.push(make_pair(rr,cc));
            d[rr][cc]=d[p.first][p.second]+1;
        }
    }
    printf("%d\n",res);
    return 0;
}

