        for (int j = 0; j < w; ++j) {
            v[i][j] = (s[j] == '#');
            if(s[j] == 'S') S = make_pair(i, j);
        }
    }
    int dx[] = {1, -1, 0, 0}, dy[] = {0, 0, 1, -1};
    if(k == 1){
        int ans = INF<int>;
        for (int i = 0; i < 4; ++i) {
            int y = S.first+dy[i], x = S.second+dx[i];
            chmin(ans, min({y, h-1-y, x, w-1-x}));
        }
        cout << ans+1 << "\n";
        return 0;
    }
    auto grid = make_v(h, w, make_pair(INF<int>, 0));
    grid[S.first][S.second] = make_pair(0, 0);
