typedef pair<int,int> pii;
const int N = 810;
const int dx[] = {-1, 1, 0, 0};
const int dy[] = {0, 0, -1, 1};
const int INF = 1e9;
int _w;

int n, m, k, a[N][N];
pii s, q[N*N];
int begin, end, d[N][N];

bool inside( int x, int y ) {
	return x >= 1 && x <= n && y >= 1 && y <= m;
}

int calc( int x, int y ) {
	int d = min(x-1, y-1);
	d = min(d, n-x);
	d = min(d, m-y);
	if( d <= 0 ) return 1;
	return 1 + d/k + bool(d%k);
}

void solve() {
	memset(d, -1, sizeof d);
	d[s.first][s.second] = 0;
	q[end++] = s;
	while( begin != end ) {
		pii u = q[begin++];
		int x = u.first;
		int y = u.second;
		if( d[x][y] == k ) continue;
		for( int i = 0; i < 4; ++i ) {
			int nx = x + dx[i];
			int ny = y + dy[i];
			if( inside(nx, ny) && d[nx][ny] == -1 && a[nx][ny] ) {
				d[nx][ny] = d[x][y] + 1;
				q[end++] = pii(nx, ny);
			}
		}
	}
	int ans = INF;
	for( int i = 1; i <= n; ++i )
		for( int j = 1; j <= m; ++j )
			if( d[i][j] != -1 )
				ans = min( ans, calc(i, j) );
	printf( "%d\n", ans );
}

int main() {
	_w = scanf( "%d%d%d", &n, &m, &k );
	for( int i = 1; i <= n; ++i )
		for( int j = 1; j <= m; ++j ) {
			char ch;
			_w = scanf( " %c", &ch );
			if( ch != '#' ) a[i][j] = 1;
			if( ch == 'S' ) s = pii(i, j);
		}
	solve();
	return 0;
}

