template<class T>bool chmin(T &a, const T &b) { if (b<a) { a=b; return 1; } return 0; }
const ll MOD = 1e9+7;

bool X[810][810];
bool isvisit[810][810];
ll H, W, K;

typedef queue<pair<ll, ll>> Q;

void dfs(Q& que, ll y, ll x, int move){
    if(y >= H) return;
    if(x >= W) return;
    if(y < 0) return;
    if(x < 0) return;

    if(!X[y][x]) return;

    if(isvisit[y][x]) return;
    isvisit[y][x] = true;

    que.push(mp(y, x));

    dfs(que, y+1, x, move-1);
    dfs(que, y-1, x, move-1);
    dfs(que, y, x+1, move-1);
    dfs(que, y, x-1, move-1);
}

ll solve(pair<ll, ll> s){
    Q que;
    dfs(que, s.first, s.second, K);
    ll ans = 1000;
    while(!que.empty()){
        auto p = que.front();
        que.pop();
        ll y = p.first;
        ll x = p.second;
        ll dist = 1000;
        chmin(dist, y);
        chmin(dist, x);
        chmin(dist, H-1-y);
        chmin(dist, W-1-x);
        chmin(ans, dist/K + (dist%K != 0));
    }
    return ans+1;
}

