using namespace std;

typedef pair<int, int> P;

class CClosedRooms {
public:
    static constexpr int kStressIterations = 0;

    static void generateTest(std::ostream& test) {
    }


    int dx[4] = {-1, 0, 0, 1};
    int dy[4] = {0, -1, 1, 0};

    int H, W, K;
    vector<P> v;
    set<P> used;
    vector<vector<char>> A;

    void dfs(P p, int n) {
        v.push_back(p);
        if (n == K) {
            return;
        }

        int x, y;
        tie(x, y) = p;
        used.insert(p);

        REP(i, 4) {
            int nx = x + dx[i];
            int ny = y + dy[i];
            if (nx < 0 || nx > H - 1 || ny < 0 || ny > W - 1) continue;
            if (A[nx][ny] == '#') continue;
            if (used.count({nx, ny})) continue;

            dfs({nx, ny}, n + 1);
        }
    }

    void solve(std::istream& cin, std::ostream& cout) {
        cin >> H >> W >> K;

        A = vector<vector<char>>(H, vector<char>(W));
        int sx, sy;
        REP(i, H) {
            REP(j, W) {
                cin >> A[i][j];
                if (A[i][j] == 'S') {
                    sx = i, sy = j;
                }
            }
        }

        dfs({sx, sy}, 0);

        int res = INF;
        REP(i, v.size()) {
            int x, y;
            tie(x, y) = v[i];

            int tmp = min({x, H - 1 - x, y, W - 1, y});
            res = min(res, (tmp + K - 1) / K);
        }
        cout << res + 1 << endl;

    }
};


signed main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    std::istream& in(std::cin);
    std::ostream& out(std::cout);

    CClosedRooms solver;
    solver.solve(in, out);
    return 0;
}

