				sy = i;
				sx = j;
			}
			minCost[i][j] = 11451419;
		}
	}

	typedef pair<int, int> P;
	queue<P> que;
	que.push(P(sy, sx)); minCost[sy][sx] = 0;

	while (!que.empty()) {
		int y = que.front().first;
		int x = que.front().second;
		que.pop();

		for (int dir = 0; dir < 4; dir++) {
			int ny = y + dy[dir];
			int nx = x + dx[dir];
			if (is_range(ny, nx) && s[ny][nx] != '#' && minCost[ny][nx] > minCost[y][x] + 1) {
