	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			dis1 = min(i,j);
			dis2 = min((h-i),(w-j));
			dis = min(dis1, dis2);

			if (k >= d[j][i] & min_out > dis) {
				min_out = dis;
			}
		}
	}

	if (sx == 0 | sx == w-1 | sy == 0 | sy == h-1) {
		printf("0\n");
		return 0;
	}

	ans = 1;
	while(1) {
		if (min_out <= 0) {
			printf("%d\n", ans);
			return 0;
		}
		min_out -= k;
		ans++ ;
	}

}

