//コンビネーション
const int MAXcomb = 200010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}



int H, W, K;
char mp[810][810];
int sy, sx;
bool can[810][810];
void bfs(ll y, ll x, ll rest){
  if(rest == 0) return;
  rep(i, 4){
    ll ny = y + dy[i];
    ll nx = x + dx[i];
    if(ny < 0 || ny >= H || nx < 0 || nx >= W) continue;
    if(mp[ny][nx] == '#') continue;
    if(can[ny][nx]) continue;
    can[ny][nx] = 1;
    bfs(ny, nx, rest - 1);
  }
}
int main(){
  cin >> H >> W >> K;
  K = min(K, 410);
  rep(i, H){
    rep(j, W){
      cin >> mp[i][j];
      if(mp[i][j] == 'S'){
        sy = i;
        sx = j;
      }
    }
  }
  can[sy][sx] = 1;
  bfs(sy, sx, K);
  ll ans = INFL;
  rep(i, H)rep(j, W)if(can[i][j]){
    if(i == 0 || i == H-1 || j == 0 || j == W-1) ans = 1;
    ans = min(ans, (i-1)/K+2);
    ans = min(ans, (H-i-1)/K+2);
    ans = min(ans, (j-1)/K+2);
    ans = min(ans, (W-j-1)/K+2);
  }
  cout << ans << endl;
}

