const int maxn=810;

int n,m,k,bx,by,ans;
string s[maxn];
bool vis[maxn][maxn];
queue<pair<pair<int,int>,int> > q;

int main()
{
	SF("%d%d%d",&n,&m,&k);
	rep(i,n)
	{
		cin>>s[i];
		rep(j,m) if(s[i][j]=='S') bx=i,by=j;
	}

	ans=min(min(bx,by),min(n-bx-1,m-by-1));
	ans=ans/k+bool(ans%k)+1;

	q.push({{bx,by},0});
	vis[bx][by]=1;
	while(!q.empty())
	{
		int x=q.front().fs.fs,y=q.front().fs.sc,step=q.front().sc;q.pop();
		if(step>=k) continue;

		rep(i,4)
		{
			int nx=x+dx[i],ny=y+dy[i];
			if(nx>=0&&nx<n&&ny>=0&&ny<m&&!vis[nx][ny]&&s[nx][ny]!='#')
			{
				int res=min(min(nx,ny),min(n-nx-1,m-ny-1));
				res=res/k+bool(res%k)+1;
				ans=min(ans,res);

				vis[nx][ny]=1;
				q.push({{nx,ny},step+1});
			}
		}
	}

	PF("%d",ans);

	return 0;
}
