bitset<801> vis[801];

int main(){

    cin.sync_with_stdio(0); cin.tie(0); cout.tie(0);

    //freopen("input.txt", "r", stdin);
    //freopen("output.txt", "w", stdout);

    // 2-phase BFS?
    // phase 1: move on normal tile
    // phase 2: move on any tile

    // what if we flip the phases around...
    // unlock rooms first, then move to those unlocked rooms

    // find empty rooms first, then get min

    int h, w, k; cin >> h >> w >> k;

    queue<pair<int, int>> q;

    int best = 1e9;

    for(int i = 0; i < h; ++i){
        for(int j = 0; j < w; ++j){
            cin >> grid[i][j];
            if(grid[i][j] == 'S'){
                //int ree = min(i, min(j, min(h - i - 1, w - j - 1)));
                //best = ree / k + (ree % k > 0);
                q.push(make_pair(i, j));
            }
        }
    }

    while(!q.empty()){
        pair<int, int> state = q.front();
        q.pop();
        int x = state.first, y = state.second;
        //cout << "VIS " << x << " " << y << endl;
        // unlock K, move K, min dist / K
        int mini = min(x, min(y, min(h - x - 1, w - y - 1)));
        best = min(best, 1 + mini / k + (mini % k > 0));
        for(int dx = -1; dx <= 1; ++dx){
            for(int dy = -1; dy <= 1; ++dy){
                if(dx == 0 && dy == 0) continue;
                if(dx != 0 && dy != 0) continue;
                if(x + dx < 0 || x + dx == h) continue;
                if(y + dy < 0 || y + dy == w) continue;
                if(grid[x + dx][y + dy] == '#') continue;
                if(vis[x + dx][y + dy]) continue;
                vis[x + dx][y + dy] = 1;
                q.push(make_pair(x + dx, y + dy));
            }
        }
    }

    cout << best << "\n";

    return 0;

}

