int h, w, k, mini;
vector<vector<char> > buil(801, vector<char>(801));
vvi ma(801, vi(801, 99999));

int tansaku(int gh, int gw, int num) {
  int mmini = min(min(gh, h - gh), min(gw, w - gw));
  if(ma[gh][gw] <= num || buil[gh][gw] == '#' || mini + (k - num) < mmini) {
    return 1;
  }

  if(gh == 0 || gh == h - 1 || gw == 0 || gw == w - 1) {
    return 0;
  }

  if(num == k) {
    int res = min(min(gh, h - gh), min(gw, w - gw));
    if(mini > res) {
      mini = res;
    }
    return 1;
  }

  ma[gh][gw] = num;

  return min(
    min(tansaku(gh + 1, gw, num + 1),
    tansaku(gh - 1, gw, num + 1)),
    min(tansaku(gh, gw + 1, num + 1),
    tansaku(gh, gw - 1, num + 1))
  );
}

int main() {
  cin >> h >> w >> k;

  char a;
  int sh, sw;

  rep(i, 0, h) {
    rep(j, 0, w) {
      cin >> a;
      if(a == 'S') {
        sh = i;
        sw = j;
      }

      buil[i][j] = a;
    }
  }

  mini = min(min(sh, h - sh), min(sw, w - sw));

  if(!tansaku(sh, sw, 0)) {
    out(1);
    return 0;
  }

  out(mini / k + (mini % k == 0 ? 1 : 2));
}

