	int spos = 0;
	int scnt = 0;
	int a = 0 ;

	while(true)
	{
		while(pos < vs.size()){
			if(vs[pos] == '.'){
				pos++;
				cnt++;
				if(cnt == K) break;
			}else break;
		}

		while(spos < vs.size()){
