int h,w,k;
char maze[1010][1010];
int sh,sw;
int d[1010][1010];
int inf = 1e9;
int dh[4] = {0,0,1,-1};
int dw[4] = {1,-1,0,0};

int main() {
    cin >> h >> w >> k;
    for (int i = 0; i < h; i++) cin >> maze[i];
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (maze[i][j] == 'S') {
                sh = i;
                sw = j;
            }
            d[i][j] = inf;
        }
    }
    queue<pair<int,int>> q;
    q.push({sh,sw});
    d[sh][sw] = 0;
    while (!q.empty()) {
        pair<int,int> p = q.front();
        q.pop();
        for (int i = 0; i < 4; i++) {
            int th = p.first + dh[i];
            int tw = p.second + dw[i];
            if (th < 0 || th >= h) continue;
            if (tw < 0 || tw >= w) continue;
            if (maze[th][tw] == '#') continue;
            if (d[th][tw] != inf) continue;
            d[th][tw] = d[p.first][p.second] + 1;
            q.push({th,tw});
        }
    }

    int ans = inf;
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (d[i][j] == inf) continue;
            ans = min(ans, (max(d[i][j] - k, 0) + k - 1 + min(min(i,h - i - 1),min(j,w - j - 1))) / k + 1);
        }
    }
    cout << ans << endl;
    return 0;
}

#include <iostream>
#include <queue>
#include <vector>
#include <algorithm>
using namespace std;
#define p pair<int,int>
#define out(tp) (tp.first < 0 || tp.first >= H || tp.second < 0 || tp.second >= W)

int rs[] = {0,0,1,-1};
int cs[] = {-1,1,0,0};

typedef struct node {
    p tp;
    int r, ml, cl;
} node;
typedef node * Node;

class cmp {
    public: bool operator() (Node a, Node b) { return (b->r < a->r || (b->r == a->r && b->cl > a->cl)); }
};

Node newNode(p tp, int r, int ml, int cl) {
    Node tn = (Node) malloc(sizeof(node));
    tn->tp = tp, tn->r = r, tn->ml = ml, tn->cl = cl;
    return tn;
}

int main() {
    int H, W, K, i, r, c;
    int res = 2000000000;
    p tp;
    string m[800];
    cin >> H >> W >> K;
    for (r = 0; r < H; r++) {
        cin >> m[r];
        for (c = 0; c < W; c++) {
            if (m[r][c] == 'S') {
                m[r][c] = '.';
                tp = p(r, c);
            }
        }
    }

    // each state
    // - coord
    // - moves so far
    // - rooms to move left
    // - rooms to clear left
    priority_queue<Node, vector<Node>, cmp> q;
    q.push(newNode(tp, 0, K, K));

    int seen[800][800] = {};
    while (!q.empty()) {
        Node t = q.top(); q.pop();

        //printf("at %d %d, r:%d, ml:%d, cl:%d\n", t->tp.first, t->tp.second, t->r, t->ml, t->cl);
        // If you moved out of bounds, game over
        if (out(t->tp)) {
            res = min(res, t->r+1+(t->cl != K));
            continue;
        }

        if (seen[t->tp.first][t->tp.second]) continue;
        seen[t->tp.first][t->tp.second] = 1;

        // Move
        for (i = 0; i < 4; i++) {
            tp = p(t->tp.first+rs[i], t->tp.second+cs[i]);

            if (out(tp) || m[tp.first][tp.second] == '.') {
                // push a node where you've moved there
                Node nn = newNode(tp, t->r, t->ml-1, t->cl);
                if (nn->ml < 0) {
                    nn->ml += K, nn->cl += K, nn->r++;
                }
                q.push(nn);
            }
            else {
                // push a node where you've destroyed it AND moved there
                Node nn = newNode(tp, t->r, t->ml-1, t->cl-1);
                if (nn->ml < 0 || nn->cl < 0) {
                    nn->ml += K, nn->cl += K, nn->r++;
                }
                q.push(nn);

            }
        }
    }
    cout << res << '\n';
}

