vec bfs(const vec2& g, lint s)
{
	lint n = g.size();
	vec d(n, inf);

	d[s] = 0;
	queue<lint> q;
	q.push(s);
	while (!q.empty())
	{
		lint pos = q.front();
		q.pop();
		rep(i, g[pos].size())
		{
			if (d[pos] + 1 < d[g[pos][i]])
			{
				d[g[pos][i]] = d[pos] + 1;
				q.push(g[pos][i]);
			}
		}
	}
	return d;
}

