#define pii2p(x) x.first][x.second

int mx[]={1,0,-1,0}, my[]={0,1,0,-1};
int solve(){
    vvector<int> fast(h,vector<int>(h,INF));
    queue<pii> que;
    que.emplace(start);
    fast[pii2p(start)] = k;
    auto is_in = [](pii p){
        return 0 <= p.first && p.first < h && 0 <= p.second && p.second < w;
    };

    auto is_wall = [&](pii p){
        if(!is_in(p))return false;
        return (bool)wall[pii2p(p)];
    };
    auto is_goal = [](pii p){
        return p.first == 0 || p.first == h-1 || p.second == 0 || p.second == w-1;
    };
    while(que.size()){
        pii np = que.front();
        que.pop();
        if(fast[pii2p(np)]==0)continue;
        rep(i,4){
            pii nep(np.first+my[i],np.second+mx[i]);
            if(is_wall(nep))continue;
            int nt = fast[pii2p(np)] - 1;
            if(fast[pii2p(nep)]!=INF && nt <= fast[pii2p(nep)])continue;
            fast[pii2p(nep)] = nt;
            que.emplace(nep);
            if(is_goal(nep))return 1;
        }
    }
    rep(i,h){
        rep(j,w){
            if(fast[i][j]!=INF){
                que.emplace(i,j);
            }
        }
    }

    fast.assign(h,vector<int>(w,INF));

    [&](queue<pii> line){
        while(line.size()){
            pii d = line.front();
            line.pop();
            fast[pii2p(d)] = 0;
        }
    }(que);

    int res = INF;
    while(que.size()){
        pii np = que.front();
        que.pop();
        rep(i,4){
            pii nep(np.first+my[i],np.second+mx[i]);
            if(!is_in(nep))continue;
            int nt = fast[pii2p(np)] + 1;
            if(nt >= fast[pii2p(nep)])continue;
            fast[pii2p(nep)] = nt;
            que.push(nep);
            if(is_goal(nep)){
                chmin(res,(nt + k - 1) / k + 1);
            }
        }
    }
    return res;
}

