            if (ny < 0 || ny >= H || nx < 0 || nx >= W) continue;
            if (A[ny][nx] == '.' && dist[ny][nx] == INF) {
                dist[ny][nx] = dist[v.first][v.second] + 1;
                que.emplace(ny, nx);
            }
        }
    }

    rep(i, H) rep(j, W) {
        if (dist[i][j] <= K) {
            if (i == 0 || i == H - 1 || j == 0 || j == W - 1) {
                write(1);
                return 0;
            }

            dist[i][j] = K;
            que.emplace(i, j);
        }
    }

    while (!que.empty()) {
        auto v = que.front();
        que.pop();
        rep(d, 4) {
            int ny = v.first + dy[d], nx = v.second + dx[d];
            if (ny < 0 || ny >= H || nx < 0 || nx >= W) continue;
            if (dist[ny][nx] == INF) {
                dist[ny][nx] = dist[v.first][v.second] + 1;
                que.emplace(ny, nx);
            }
        }
    }

    int ans = INF;
    rep(j, W) ans = min(ans, (dist[0][j] + K - 1) / K);
    rep(j, W) ans = min(ans, (dist[H - 1][j] + K - 1) / K);
    rep(i, H) ans = min(ans, (dist[i][0] + K - 1) / K);
    rep(i, H) ans = min(ans, (dist[i][W - 1] + K - 1) / K);
    write(ans);
}

