typedef pair<int, int> pi;
typedef pair<int, pi> pip;

const int dx[4] = {  0,   1,  0,  -1 };
const int dy[4] = { -1,   0,  1,   0 };
const int max_hw = 1000;

int H, W, K;
int sx, sy;
vector<string> A;

int calcu_rest(pi pos) {
	int rest_x = min(pos.first, W - 1 - pos.first);
	int rest_y = min(pos.second, H - 1 - pos.second);
	int min_xy = min(rest_x, rest_y);
	return min_xy;
}

int get_rest(void) {
	queue<pip> que;
	pi stt = make_pair(sx, sy);
	que.push(make_pair(0, stt));
	int rest = max_hw;
	while (que.size()) {
		pip p = que.front(); que.pop();
		if ((p.second.first == 0 || p.second.first == W - 1)
				|| (p.second.second == 0 || p.second.second == H - 1)) {
			rest = 0;
			break;
		}
		if (p.first >= K) {
			int rest_xy = calcu_rest(p.second);
			if (rest_xy < rest)
				rest = rest_xy;
			continue;
		}
		for (int i = 0; i < 4; ++i) {
			int nx = p.second.first + dx[i];
			int ny = p.second.second + dy[i];
			if (A[ny][nx] == '.') {
				A[ny][nx] = '@';
				que.push(make_pair(p.first + 1, make_pair(nx, ny)));
			}
			else {
				int rest_xy = calcu_rest(p.second);
				if (rest_xy < rest)
					rest = rest_xy;
			}
		}
	}
	return rest;
}

