		for (int i = 0; i < W; ++i) {
			if (A[j][i] == 'S') {
				sx = i;	sy = j;
				break;
			}
		}
	}

	int ans = 1;
	int rest = get_rest();
	int t2 = rest / K;
	if (rest % K != 0)
		++t2;
	ans += t2;

	cout << ans << '\n';
	return 0;
}

