		for(int i=0;i<4;i++){
			if(inside(cb + dx[i],ck + dy[i]) && arr[cb + dx[i]][ck + dy[i]]!='#' && visited[cb + dx[i]][ck + dy[i]]==false){
				visited[cb + dx[i]][ck + dy[i]]=true;
				q.push(State(cb + dx[i], ck + dy[i], cbyk + 1));							
			}			
		}
	}
}

