i32 solve(i32 tx, i32 ty) {
    i32 ans = INT_MAX;
    times(v.size(), i) {
        if (v[i].first == 0 || v[i].first == h - 1 || v[i].second == 0 || v[i].second == w - 1) {
            ans = 0;
            break;
        }
        i32 d = abs(v[i].second - tx) + abs(v[i].first - ty);
        if ((d % k) == 0) {
            ans = min(ans, d / k);
        }
        else {
            ans = min(ans, d / k + 1);
        }
    }
    return ans + 1;
}

