	int ret2 = min(w-1-x, h-1-y) / k + (min(w-1-x, h-1-y) % k != 0 ? 1 : 0);
	return min(ret1, ret2);
}

void solve(){
	cin >> h >> w >> k;
	rep(i, 0, h){
		string s;
		cin >> s;
		rep(j, 0, w){
			if(s[j] == '.'){
				ma[i][j] = 0;
			}else if(s[j] == '#'){
				ma[i][j] = 1;
			}else{
				sy = i;
				sx = j;
			}
		}
	}

	rep(i, 0, h) rep(j, 0, w) d[i][j] = INF;
	d[sy][sx] = 0;
	q.pb(mp(sy, sx));
	was[sy][sx] = 1;

	while(sz(q)){
		pii cur = q.front();
		q.pop_front();
		int x = cur.second;
		int y = cur.first;
		if(d[y][x] == k) continue;
		rep(i, 0, 4){
			int nx = x + dx[i];
			int ny = y + dy[i];
			if(canMove(ny, nx) && !was[ny][nx]){
				d[ny][nx] = 1 + d[y][x];
				was[ny][nx] = 1;
				q.pb(mp(ny, nx));
			}
		}
	}

	int ans = INF;

	rep(i, 0, h) rep(j, 0, w) if(was[i][j]){
		ans = min(ans, 1 + calc(i, j));
	}

	cout << ans << endl;

}

