      apos.push_back(p);
      int x = p.first;
      int y = p.second;
      checkAdd(x + 1, y, npos);
      checkAdd(x - 1, y, npos);
      checkAdd(x, y + 1, npos);
      checkAdd(x, y - 1, npos);
    }

    swap(pos, npos);
    ct++;
  }
  int ret = 800 * 800 + 1000;
  for (auto &p : apos) {
    int x = p.first;
    int y = p.second;
    int mstep = min({x, y, H - x - 1, W - y - 1});
    if (mstep == 0) {
      ret = 1;
      break;
    }
    ret = min(ret, (mstep + K - 1) / K + 1);
  }

  cout << ret << endl;
}

