const int MAX = 10000;

bool within_board(int w, int h) {
	return (0 <= w && w < W && 0 <= h && h < H);
}

void debug_print_reach(){
    cout << endl;
    REP(h,H) {
        REP(w,W) {
            cout << reach[h][w] << "\t";
        }
        cout << endl;
    }
    cout << endl;
}

int dh[4] = { 1, -1, 0, 0 };
int dw[4] = { 0, 0, 1, -1 };
void fill_room(P start, int turn) {
	set<P> poses{ start };
	REP(k, K) {
		set<P> new_poses;
        for (auto& pos: poses) {
            auto w = pos.first;
            auto h = pos.second;
            new_poses.insert(P(w,h));
            REP(d, 4) {
                auto w2 = w + dw[d];
                auto h2 = h + dh[d];
				if (within_board(w2, h2) && cells[h2][w2] != '#') {
					reach[h2][w2] = turn;
                    new_poses.insert(P(w2,h2));
                }
            }
        }
        poses = new_poses;
    }
}

int main(void)
{
