    reach.resize(H);
	P start;
    REP(h,H) {
        cin >> cells[h];
        reach[h].resize(W, MAX);
        auto loc = cells[h].find('S');
        if (loc != string::npos) {
            start = mp(loc, h);
            reach[h][loc] = 0;
            cells[h][loc] = '.';
        }
    }

	fill_room(start, 0);
    // debug_print_reach();

    int min_dist = 1e9;
    REP(h,H) {
        REP(w,W) {
            if (reach[h][w] == 0) {
                auto dist = min(w, min(h, min(W-1-w, H-1-h)));
                min_dist = min(min_dist, dist);
            }
        }
    }


    cout << ((min_dist + K - 1) / K) + 1 << endl;
    return 0;
}

