            ans = 0;
            break;
        }
        i32 d = abs(v[i].second - ty) + abs(v[i].first - tx);
        if ((d % k) == 0) {
            ans = min(ans, d / k);
        }
        else {
            ans = min(ans, d / k + 1);
        }
    }
    return ans + 1;
}

i32 main()
{
    cin >> h >> w >> k;
    times(h, i) {
        str s; cin >> s;
        times(w, j) {
            a[i][j] = s[j] != '#';
            if (s[j] == 'S') {
                sx = j;
                sy = i;
            }
        }
    }
    bool fp[800][800] = {};
    set<tuple<i32, i32, i32>> s;
    s.insert(make_tuple(0, sy, sx));
    while (s.size() > 0) {
        i32 d, y, x;
        tie(d, y, x) = *s.begin();
        s.erase(s.begin());
        if (fp[y][x]) {
            continue;
        }
        v.append(make_pair(y, x));
        fp[y][x] = true;
        if (d >= k) {
            continue;
        }
        times(4, i) {
            i32 nx, ny;
            nx = x + ox[i];
            ny = y + oy[i];
            if (0 <= nx && nx < w && 0 <= ny && ny < h) {
                if (a[ny][nx] && !fp[ny][nx]) {
                    s.insert(make_tuple(d + 1, ny, nx));
                }
            }
        }
    }

    i32 ans = INT_MAX;
    range(0, w - 1, i) {
        ans = min(ans, solve(i, 0));
        ans = min(ans, solve(i, h-1));
    }
    range(0, h - 1, i) {
        ans = min(ans, solve(0, i));
        ans = min(ans, solve(w - 1, i));
    }
    cout << ans << endl;
    return 0;
}

