        }
    }
    dump(sx, sy);

    Graph g(n);
    auto nid = [&](int i, int j){return (i*w + j);};
    // int u = nid(i, j);
    auto pos = [&](int u) -> pair<int, int> { return {u/w, u%w}; };
    // auto [i,j] = pos(u);

    int dx[] = {1, -1, 0, 0};
    int dy[] = {0, 0, 1, -1};
    rep(i, h) rep(j, w) {
        if (block[i][j]) continue;  // blockから出る辺はない
        rep(dir, 4) {
            int ni = i + dx[dir];
            int nj = j + dy[dir];
            if (is_in(ni, 0, h) && is_in(nj, 0, w)) {
                if (block[ni][nj]) continue;  // blockに入る辺はない
                g.add_edge(nid(i, j), nid(ni, nj));
                // 自分から生える辺だけでよい。そうしないと二重辺になってしまう。
            }
        }
    }
    auto d = g.dijkstra(nid(sx, sy));

    ll ans = 1e9;
    rep(i, h)rep(j, w){
        if (d[nid(i, j)] <= k) {
            ll res = 1e9;
            chmin(res, cdiv(i, k)+1);
            chmin(res, cdiv(j, k)+1);
            chmin(res, cdiv((h-1)-i, k)+1);
            chmin(res, cdiv((w-1)-j, k)+1);
            chmin(ans, res);
            dump(i, j, res);
        }
    }
    cout << ans << endl;

    return 0; 
