void go(int h, int w, int k){
    queue<pair<pair<int, int>, int> > Q;
    Q.push(make_pair(make_pair(h, w), k));
    while(!Q.empty()){
        pair<pair<int, int>, int> now = Q.front();
        Q.pop();
        int h = now.first.first;
        int w = now.first.second;
        int k = now.second;
        is_first[h][w] = k;
        if(k > 1){
