                if((0 <= h_) && (h_ < H) && (0 <= w_) && (w_ < W) && (A[h_][w_] == '.') && (is_first[h_][w_] < k - 1)){
                    Q.push(make_pair(make_pair(h_, w_), k - 1));
                }
            }
        }
    }
}

