		rep(j,w){
			used[i][j] = false;
		}
	}
	bool me = true;
	int mi,mj;
	rep(i,h){
		rep(j,w){
			if(A[i][j] == 'S'){
				me = false;
				mi=i;
				mj=j;
			}
			if(!me){
				break;
			}
		}
		if(!me){
			break;
		}
	}
	queue<pair<int, int> > Q;
	pair<int,int> p2;
	p2.first = mi;
	p2.second = mj;
	Q.push(p2);

	while(Q.size() > 0 && k>0){
		queue<pair <int, int> > Q2;
		while(Q.size() > 0){
			pair<int, int> p = Q.front(); Q.pop();
			for(int i=-1;i<=1;i++){
				for(int j=-1;j<=1;j++){
					if(abs(i)+abs(j) != 1) continue;
					if(p.first+i < 0 || p.first+i >= h || p.second+j < 0 || p.second + j >= w) continue;
					if(!used[p.first+i][p.second+j] && A[p.first+i][p.second+j] != '#'){
						pair<int, int> next;
						next.first = p.first+i;
						next.second = p.second+j;
						Q2.push(next);
						used[p.first+i][p.second+j] = true;
					}
				}
			}

		}
		Q = Q2;
		k--;
	}
	int ans = min(INF,min(mi,min(h-mi-1,min(mj,w-mj-1))));
	rep(i,h){
		rep(j,w){
			if(used[i][j]){
				ans = min(ans,min(i,min(h-i-1,min(j,w-j-1))));
			}
		}
	}
	cout<<1+(ans/memok) + (ans%memok == 0 ? 0 : 1)<<endl;
	return 0;
}

