int cal(int x)
{
	return hh(x);
}

void bfs()
{
	int tmp=INF;
	q.push((xx){x1,y1,0});
	while (!q.empty())
	{
		xx now=q.front();q.pop();
		int x=now.x,y=now.y,dep=now.dep;
		if (dep>K) continue;
		vis[x][y]=1;
		tmp=min(tmp,min(cal(x-1),cal(y-1)));
		tmp=min(tmp,min(cal(H-x),cal(W-y)));
		if (tmp+1>ans) continue;
	//printf("-- x:%d y:%d dep:%d tmp+1:%d\n--",x,y,dep,tmp+1);
		for (int i=0;i<4;++i)
