                check[x][y+i]=true;
                que.emplace(x,y+i);
                chmin(d,x);
                chmin(d,y+i);
                chmin(d,h-1-x);
                chmin(d,w-1-y-i);
            }
        }
    }
    if(d==0){
        cout << 1 << endl;
        return 0;
    }
    ll res = 1;
    res += (d-1)/k+1;
    cout << res << endl;
    return 0;
}

