      int nK1 = K1-1;
      int nK2 = K2;
      int ncost = cost;
      if(nx<0||ny<0||nx>=w||ny>=h){res=min(res,cost);continue;}
      if(nK1 <  0) ncost++,nK1 = sK-1,nK2 += sK;
