int main()
{
    scanf("%d%d%d",&H,&W,&K);
    for(int i = 0; i < H; i++)
    {
        for(int j = 0; j < W; j++)
        {
            char c;
            scanf(" %c",&c);
            if(c == '#')
            {
                fid[i][j] = -1;
            }
            if(c == 'S')
            {
                sx = j;
                sy = i;
            }
        }
    }
    solve();
    return 0;
