void solve()
{
    queue<pipii> Q;
    Q.push(make_pair(K,make_pair(sy,sx)));
    while(Q.size())
    {
        pipii now = Q.front();
        Q.pop();
        if(fid[now.second.first][now.second.second])continue;
        fid[now.second.first][now.second.second] = now.first;
        if(now.second.first < minx)minx = now.second.first;
        if(now.second.first > maxx)maxx = now.second.first;
        if(now.second.second < miny)miny = now.second.second;
        if(now.second.second > maxy)maxy = now.second.second;
        if(now.first == 0)continue;
        for(int i = 0; i < 4; i++)
        {
            int x = now.second.first + dx[i],
                y = now.second.second + dy[i];
            if(0 <= x && x < W && 0 <= y && y < H)
            {
                Q.push(make_pair(now.first - 1,make_pair(x,y)));
            }
        }
    }
    int ans = min(min(minx,H - maxx - 1),min(miny,W - maxy - 1));
    printf("%d",(ans + K - 1) / K + 1);
    return;
}

