class Grid_Breadth_First_Dearch{
public:
	int H,W;
	vector<string> S;
	vector<vector<int>> dist;

	Grid_Breadth_First_Dearch(int H,int W):H(H),W(W),S(H),dist(H,vector<int>(W)){
		//do nothing
	}

	void solve(int sy,int sx){
		for(int i = 0; i < H; ++i) for(int j = 0; j < W; ++j) dist[i][j] = -1;
		queue<pair<int,int>> q;
		dist[sy][sx] = 0;
		q.push({sy,sx});
		while(q.size()){
			int y = q.front().first;
			int x = q.front().second;
			q.pop();

			if(0 < y && S[y-1][x] == '.' && dist[y-1][x] == -1){
				dist[y-1][x] = dist[y][x] + 1;
				q.push({y-1,x});
			}
			if(y < H - 1 && S[y+1][x] == '.' && dist[y+1][x] == -1){
				dist[y+1][x] = dist[y][x] + 1;
				q.push({y+1,x});
			}
			if(0 < x && S[y][x-1] == '.' && dist[y][x-1] == -1){
				dist[y][x-1] = dist[y][x] + 1;
				q.push({y,x-1});
			}
			if(x < W - 1 && S[y][x+1] == '.' && dist[y][x+1] == INTINF){
				dist[y][x+1] = dist[y][x] + 1;
				q.push({y,x+1});
			}
		}
	}
};

int main() {
	int H,W,K; cin >> H >> W >> K;
	Grid_Breadth_First_Dearch gridBFS(H,W);
	REP(i,H) cin >> gridBFS.S[i];
	int y,x;
	REP(i,H) REP(j,W) if(gridBFS.S[i][j] == 'S') y = i,x = j;
	gridBFS.solve(y,x);

	int ans = INTINF;
	REP(i,H) REP(j,W){
		if(gridBFS.dist[i][j] == -1) continue;
		if(gridBFS.dist[i][j] > K) continue;

		int cnt;
		cnt = i/K + (i%K==0?0:1) + 1;
		chmin(ans,cnt);
		cnt = (W - 1 -j)/K + ((W - 1 -j)%K==0?0:1) + 1;
		chmin(ans,cnt);
		cnt = (H - 1 -i)/K + ((H - 1 -i)%K==0?0:1) + 1;
		chmin(ans,cnt);
		cnt = j/K + (j%K==0?0:1) + 1;
		chmin(ans,cnt);		
	}
	cout << ans << endl;
	return 0;
}

