typedef pair<int,int> P;

int calc( int i, int j, int H, int W, int K )
{
  int ret = 10000;
  ret = min( ret, i );
  ret = min( ret, j );
  ret = min( ret, H-1-i );
  ret = min( ret, W-1-j );
  return (ret + K - 1) / K;
}

int main( void )
{
  ios::sync_with_stdio(false);
  string S[801];
  int H, W, K;
  queue<P> q;
  int ret = 1000;
  cin >> H >> W >> K;
  for( int i=0; i<H; i++ ){
    cin >> S[i];
  }
  for( int i=0; i<H; i++ ){
    for( int j=0; j<W; j++ ){
      if( S[i][j] == 'S' ){
        q.push( P( i*1000+j, K ) );
        goto L1;
      }
    }
  }
L1:
  while( !q.empty() ){
    int px = q.front().first % 1000;
    int py = q.front().first / 1000;
    int cnt = q.front().second;
    q.pop();
    ret = min( ret, calc(py, px, H, W, K) );
    if( ret == 0 ) break;
    S[py][px] = 'S';
