      if( py > 0   && S[py-1][px] == '.' ) q.push( P((py-1)*1000+px, cnt-1) );
      if( py < H-1 && S[py+1][px] == '.' ) q.push( P((py+1)*1000+px, cnt-1) );
    }
  }
  cout << ret+1 << endl;
}

