vector<P> getNear(P s) {
    queue<P> que;
    que.push(s);
    map<P, int> dp;
    dp[s] = 0;
    vector<P> ps;
    ps.push_back(s);

    while (que.size()) {
        auto now = que.front();
        que.pop();
        rep(k, 4) {
            auto next = now;
            next.first += dy[k];
            next.second += dx[k];
