{
  if (v[y][x] > l){
    v[y][x] = l;
    if (nl == l)
      return;
    if (y != 0 && v[y-1][x] > l){
      f(v, y-1, x, nl, l+1);
    }
    if (y != v.size()-1 && v[y+1][x] > l){
      f(v, y+1, x, nl, l+1);
    }
    if (x != 0 && v[y][x-1] > l){
      f(v, y, x-1, nl, l+1);
    }
    if (x != v[0].size()-1 && v[y][x+1] > l){
      f(v, y, x+1, nl, l+1);
    }
  }
}

