int solve() {
    int H, W, K;
    cin >> H >> W >> K;
    vector<string> fi(H);
    rep(i, H) {
        cin >> fi[i];
    }

    pii start;
    int nearest = -1;
    rep(r, H) {
        rep(c, W) {
            if(fi[r][c] == 'S') {
                start = mp(r, c);
                nearest = min(min(r, H-r), min(c, W-c));
            }
        }
    }

    if(nearest == 0) {
        return 1;
    }

    priority_queue<pair<int, pii>> que;
    que.push(mp(K-1, start));

    vvb dp(H, vb(W, false));

    while(!que.empty()) {
        auto f = que.top(); que.pop();
        int d = f.first;
        int r = f.second.first;
        int c = f.second.second;

        chmin(nearest, min(min(r, H-r), min(c, W-c)));
