void dfs(long long i, long long j){
    visited[i][j] =1 ;
    if(!visited[i-1][j] && s[i-1][j]!='#' && i-1>=0)dfs(i-1,j);
    if(!visited[i+1][j] && s[i+1][j]!='#' && i+1<n)dfs(i+1,j);
    if(!visited[i][j-1] && s[i][j-1]!='#' && j-1>=0)dfs(i,j-1);
    if(!visited[i][j+1] && s[i][j+1]!='#' && j+1<n)dfs(i,j+1);
    ans = min(dp[0][i][j],min(dp[1][i][j],min(dp[2][i][j],dp[3][i][i])));
    return;
}

