	cin >> n >> m >> k;
	int x, y;
	for (int i = 0; i < n; i++) {
		cin >> grid[i];
		for (int j = 0; j < m; j++) {
			if(grid[i][j] == 'S')
				x = i, y = j;
		}
	}
	bfs(x, y);
	int ans = N;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			if(dist[i][j] <= k) {
				ans = min(ans, (i / k) + (bool)(i % k) + 1);
				ans = min(ans, (j / k) + (bool)(j % k) + 1);
				ans = min(ans, (n - i - 1) / k + (bool) ((n - i - 1) % k) + 1);
				ans = min(ans, (m - j - 1) / k + (bool) ((m - j - 1) % k) + 1);
			}
		}
	}
	if(x == 0 || y == 0 || x == n - 1 || y == m - 1)	ans = 0;
	cout << ans << "\n";
}

