using namespace std;

int H, W, K;

void print(bset b){
	for (int y = 0; y < H; y++){
		for (int x = 0; x < W; x++){
			cerr << b[y*W + x];
		}
		cerr << endl;
	}
	cerr << endl;
}

bool check(bset s){
	for (int y = 0; y < H; y++){ if (s[y*W + 0])return true; if (s[y*W + W - 1])return true; }
	for (int x = 0; x < W; x++){ if (s[0*W + x])return true; if (s[(H-1)*W + x])return true; }
	return false;
}

bset calc_kabe(bset kabe, bset s){
	for (int k = 0; k < 800; k++){
		bset ns = bset();
		ns |= s << W;
		ns |= s << 1;
		ns |= s >> 1;
		ns |= s >> W;
		ns &= ~kabe;
		ns|= s;


	}
	bset ns = bset();
	ns |= s << W;
	ns |= s << 1;
	ns |= s >> 1;
	ns |= s >> W;
	bset t = ns&kabe;
	return kabe&~t;
}

int main(){

	cin >> H >> W >> K;
	bset kabe = ~bset();
	bset s = bset();
	for (int y = 0; y < H; y++){
		for (int x = 0; x < W; x++){
			char c;
			cin >> c;
			if (c != '#')kabe[y*W + x] = false;
			if (c == 'S')s[y*W + x] = true;
		}

	}
	print(kabe);
	cerr << endl;
	cerr << "s" << endl;
	print(s);

	for (int cnt = 1;; cnt++){
		cerr << "cnt:" << cnt << endl;
		for (int k = 0; k < K; k++){
			bset ns = bset();
			ns |= s << W;
			ns |= s << 1;
			ns |= s >> 1;
			ns |= s >> W;
			ns &= ~kabe;
			s |= ns;
			if (check(s)){ cout << cnt << endl; return 0; }
			print(s);

		}
		for (int k = 0; k < K; k++){
			kabe = calc_kabe(kabe, s);
			if (check(~kabe))break;
		}
	}
	return 0;


}


