    cin >> H >> W >> K;

    pair<ll, ll> S;
    REP(i,H){
        REP(j,W){
            char c;
            cin >> c;
            if(c == 'S'){
                S = mp(i, j);
                X[i][j] = true;
            }
            else if(c == '.')
                X[i][j] = true;
        }
    }

    ll ans = solve(S);
    cout << ans << endl;
    return 0;
}

