				res=min(res,(dist[i][j]-1)/k+1+(min(min(l[i][j],u[i][j]),min(l[i][Y-1]-l[i][j],u[X-1][j]-u[i][j]))-1)/k+1);
			}
			else if(s[i][j]=='.')
			{
				res=min(res,(int)ceil(1.0*(dist[i][j])/k));
			}
		}
	}
	printf("%d\n",res);
}
