void move(long long orih, long long oriw){
	queue<pair<long long, pair<long long, long long> > > Q;
	set<pair<long long, long long> > done;
	Q.push(make_pair(0, make_pair(orih, oriw)));

	while(Q.size() > 0 && Q.front().first <= K){
		long long cost = Q.front().first;
		long long h = Q.front().second.first;
		long long w = Q.front().second.second;
		done.insert(make_pair(h, w));
		A[h][w] = cost;
		Q.pop();

		if(valid(h-1, w) == true && A[h-1][w] != CLOSED && done.count(make_pair(h-1, w)) == 0){
			Q.push(make_pair(cost + 1, make_pair(h-1, w)));
		}
		if(valid(h+1, w) == true && A[h+1][w] != CLOSED && done.count(make_pair(h+1, w)) == 0){
			Q.push(make_pair(cost + 1, make_pair(h+1, w)));
		}
		if(valid(h, w-1) == true && A[h][w-1] != CLOSED && done.count(make_pair(h, w-1)) == 0){
			Q.push(make_pair(cost + 1, make_pair(h, w-1)));
		}
		if(valid(h, w+1) == true && A[h][w+1] != CLOSED && done.count(make_pair(h, w+1)) == 0){
			Q.push(make_pair(cost + 1, make_pair(h, w+1)));
		}

	}



}


void firstmove(){
	for(long long h = 0; h < H; h++){
		for(long long w = 0; w < W; w++){
			if(A[h][w] == 0){
				move(h, w);
				return;
			}
		}
	}
}


