template <typename T = ll, typename U = ll> class dijkstra {
public:

    struct edge {
        T to;
        U cost;
    };

    using P = pair<U, T>;
    map<T, vector<edge> > E;
    map<T, U> d;

    void calc(T s) {
        priority_queue <P, vector<P>, greater<P> > que;
        rep(i, 801) rep(j, 801) d[MP(i, j)] = LINF; //INF
        que.emplace(U(0), s);
        d[s] = U(0);
        while (!que.empty()) {
            P p = que.top();
            que.pop();
            T v = p.second;
            if (d[v] < p.first) continue;

            for (auto&& e : E[v]) {
                //if (d.find(e.to) == d.end()) d[e.to] = INF;
                if (d[e.to] > d[v] + e.cost) {
                    d[e.to] = d[v] + e.cost;
                    que.emplace(d[e.to], e.to);
                }
            }
        }
    }
};

inline ll CEIL(ll a, ll b) {
    return (a + b - 1) / b;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int h, w, k;
    cin >> h >> w >> k;
    string a[h];
    rep(i, h) cin >> a[i];
    dijkstra<pll> ds;

    rep(i, h) rep(j, w - 1) {
        if ((a[i][j] == '.' || a[i][j] == 'S')
                && (a[i][j + 1] == '.' || a[i][j + 1] == 'S')) {
            ds.E[MP(i, j)].push_back({MP(i, j + 1), 1});
            ds.E[MP(i, j + 1)].push_back({MP(i, j), 1});
        }
    }

    rep(i, h - 1) rep(j, w) {
        if ((a[i][j] == '.' || a[i][j] == 'S')
                && (a[i + 1][j] == '.' || a[i + 1][j] == 'S')) {
            ds.E[MP(i, j)].push_back({MP(i + 1, j), 1});
            ds.E[MP(i + 1, j)].push_back({MP(i, j), 1});
        }
    }

    pll S;

    rep(i, h) rep(j, w) {
        if (a[i][j] == 'S') {
            S = MP(i, j);
            goto loopcut;
        }
    }
loopcut:

    ds.calc(S);
    ll si = S.first, sj = S.second;
    ll ans = CEIL(min({si, sj, h - si, w - sj}), k) + 1;

    rep(i, h) rep(j, w) {
        if (ds.d[MP(i, j)] <= k) {
            ll dist = CEIL(min({i, j, h - i, w - j}), k) + 1;
            ans = min(ans, dist);
        }
    }

    rep(i, h) rep(j, w) {
        if (i != 0 && i != h - 1 && j != 0 && j != w - 1) continue;
        if (ds.d[MP(i, j)] <= k) ans = 1;
    }

    cout << ans << endl;
    return 0;
}

