void solve() {
    Fill(d, -1);
    priority_queue<pair<int, pair<int, int>>> que;
    que.push(make_pair(K, make_pair(Sx, Sy)));
    while (!que.empty()) {
        auto p = que.top();
        que.pop();
        int now = p.first, x = p.second.first, y = p.second.second;
        if (now <= d[x][y])
            continue;
        d[x][y] = now;
        if (now == 0)
            continue;
        int nxt = now - 1;
        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i], ny = y + dy[i];
            if (0 <= nx && nx < H && 0 <= ny && ny < W) {
                if (A[nx][ny] == '.' && d[nx][ny] < nxt) {
                    que.push(make_pair(nxt, make_pair(nx, ny)));
