	cin >> H >> W >> K;
	PII s;
	REP(i, H){
		cin >> f[i];
		REP(j, f[i].size()){
			if(f[i][j] == 'S'){
				s.first = i; s.second = j;
			}
		}
	}
	priority_queue<pair<int, PII>, vector<pair<int, PII> >, greater<pair<int, PII> > > q;
	q.push({0, s});
	int d[810][810];
	REP(i, 810) fill(d[i], d[i]+810, INF);
	d[s.fst][s.snd] = 0;
	while(q.size()){
		PII p = q.top().snd;
		int dis = q.top().fst; q.pop();
		if(d[p.fst][p.snd] < dis) continue;
		d[p.fst][p.snd] = dis;
		if(dis == K) continue;
		if(p.fst == 0 || p.fst == H-1 || p.snd == 0 || p.snd == W-1){
			cout << 1 << endl;
			return 0;
		}
		REP(i, 4){
			if(f[p.fst+dx[i]][p.snd+dy[i]] == '.' && d[p.fst+dx[i]][p.snd+dy[i]] > dis+1){
				q.push({dis+1, {p.fst+dx[i], p.snd+dy[i]}});
			}
		}
	}
	int res = INF;
	REP(i, H){
		REP(j, W){
			if(d[i][j] != INF){
				res = min(res, min(min(i, H-i-1), min(j, W-j-1)));
			}
		}
	}
	cout << (res+K-1)/K+1 << endl;
}

