    if (x+1 == w-1) { return true; }
    else if (heya_[y][x+1] == 'S') {}
    else if (heya_[y][x+1] == '.') {
        heya_[y][x+1] = 'S';
        if(fill_s(y, x+1, k-1)) return true;
    }

    if (y-1 == 0) { return true; }
    else if (heya_[y-1][x] == 'S') {}
    else if (heya_[y-1][x] == '.') {
        heya_[y-1][x] = 'S';
        if(fill_s(y-1, x, k-1)) return true;
    }

    if (y+1 == h-1) { return true; }
    else if (heya_[y+1][x] == 'S') {}
    else if (heya_[y+1][x] == '.') {
        heya_[y+1][x] = 'S';
        if(fill_s(y+1, x, k-1)) return true;
