int main() 
{
	scanf("%d %d %d",&n,&m,&k);

	for(int i=0;i<n;i++)
	{
		cin>>s[i];

		for(int j=0;j<s[i].size();j++)
		{
			if(s[i][j]=='S')
			{
				q.push(make_pair(i,j));
				vis[i][j]=1;
			}
		}
	}

	while(!q.empty())
	{
		pair<int,int> tmp=q.front();
		q.pop();
		int curx=tmp.first;
		int cury=tmp.second;

		for(int i=0;i<4;i++)
		{
			int newx=curx+dirx[i];
			int newy=cury+diry[i];
			if(isValid(newx,newy)&&s[newx][newy]!='#')
