typedef struct {
  size_t init; // dots
  size_t dot;
  size_t blk;
} value_t;

inline bool operator!=(const value_t & a, const value_t & b)
{
  return a.init != b.init || a.dot != b.dot || a.blk != b.blk;
}

std::ostream & operator<< ( std::ostream & out, const value_t & a)
{
  out << "{" << a.init << ", " << a.dot << ", " << a.blk << "}";
  return out;
}


inline size_t getval(const size_t k, const value_t & v)
{
  // how many can move before first blk removal
  // const auto inc = min(k, init);
  // return max((v.blk + k - 1) / k, (v.init + v.dot + v.blk + k - 1) / k);

  if(!v.blk)
    return (v.init + v.dot + k - 1) / k;

  if(v.init < k)
    return 1 + max((v.blk + k - 1) / k, (v.dot + v.blk + k - 1) / k);

  // always room to advance k
  return max((v.blk + k - 1) / k, (v.dot + v.init + v.blk + k - 1) / k);
}

inline value_t add(const value_t & v, const char c)
{
  if(c == '.')
    return v.blk ? value_t({v.init, v.dot + 1, v.blk}): value_t({v.init + 1, v.dot, v.blk});

  return value_t({v.init, v.dot, v.blk + 1});
}

