        heap.push({{i + 1, j}, dist[i + 1][j] = e});
    }


    if(0 < j)
    {
      const auto e = add(d, a[i][j - 1]);
      if(comp(e, dist[i][j - 1]))
        heap.push({{i, j - 1}, dist[i][j - 1] = e});
    }

    if(j + 1 < m)
    {
      const auto e = add(d, a[i][j + 1]);
      if(comp(e, dist[i][j + 1]))
        heap.push({{i, j + 1}, dist[i][j + 1] = e});
    }
  }

  // DEBUG(dist);

  value_t out = {inf, inf, inf};
  for(size_t i = 0; i < n; ++i)
  {
    if(comp(dist[i][0], out)) out = dist[i][0];
    if(comp(dist[i][m - 1], out)) out = dist[i][m - 1];
  }

  for(size_t j = 0; j < m; ++j)
  {
    if(comp(dist[0][j], out)) out = dist[0][j];
    if(comp(dist[n - 1][j], out)) out = dist[n - 1][j];
  }

  DEBUG(out);
  // DEBUG((out.first + k - 1) / k);
  // XXX
  // cout <<  (out.second ? max((out.second + k - 1) / k + 1, (out.second + out.first + k - 1) / k) : (out.first + k - 1) / k);

  cout << getval(k, out);
  return EXIT_SUCCESS;
}

