	template<typename T>
	struct edge {
		int to;
		T cost;
		edge(int t, T c) {
			to = t;
			cost = c;
		}
	};

	template<typename T>
	void dijkstra(int s, vector<vector<edge<T>>>& path, vector<T>& d) {
		using pi = pair<T, int>;
		priority_queue<pi, vector<pi>, greater<pi>> q;
		q.push(P(0, s));
		d[s] = 0;
		while (!q.empty()) {
			P p = q.top();
			q.pop();
			int v = p.second;
			if (d[v] < p.first)continue;
			REP(i, path[v].size()) {
				edge<T> e = path[v][i];
				if (d[e.to] > d[v] + e.cost) {
					d[e.to] = d[v] + e.cost;
					q.push(P(d[e.to], e.to));
				}
			}
		}
		return;
	}

	void solve() {
		IOS;
		int h, w, k;
		cin >> h >> w >> k;
		vector<string> a(h);
		REP(i, h) {
			cin >> a[i];
		}
		int s;
		REP(i, h) {
			REP(j, w) {
				if (a[i][j] == 'S') {
					s = i * w + j;
				}
			}
		}
		using ei=edge<int>;
		vector<vector<ei>> path(h* w);
		int dx[4] = { 0,0,1,-1 };
		int dy[4] = { 1,-1,0,0 };
		REP(i, h) {
			REP(j, w) {
				REP(o, 4) {
					int ny = i + dy[o];
					int nx = j + dx[o];
					if (0 <= ny && ny < h && 0 <= nx && nx < w) {
						int nex = ny * w + nx;
						int now = i * w + j;
						int cost = 0;
						if (a[ny][nx] == '#') {
							cost = k + 1;
						} else {
							cost = 1;
						}
						path[now].push_back(ei(nex, cost));
					}
				}
			}
		}
		vector<int> d(h* w, INT_MAX / 3);
		dijkstra(s, path, d);
		int res = INT_MAX;
		REP(i, h) {
			REP(j, w) {
				int now = i * w + j;
				if (d[now] <= k) {
					int dy = min(i, h - 1 - i);
					int dx = min(j, w - 1 - j);
					int d = min(dy, dx);
					int tmp = (d + k - 1) / k;
					chmin(res, tmp + 1);
				}
			}
		}
		put(res);
	}

