class prime {
private:
public:
	std::vector<int> primes;
	std::vector<bool> isPrime;
	prime(int num = 0) {
		if (num == 0) return;
		isPrime.resize(num + 1);
		fill(isPrime.begin(), isPrime.end(), true);
		int ma = sqrt(num) + 1;
		isPrime[0] = isPrime[1] = false;
		int cnt = 0;
		for (int i = 2; i <= ma; ++i) if (isPrime[i]) {
			for (int j = 2; i * j <= num; ++j) {
				isPrime[i * j] = false;
				cnt++;
			}
		}
		primes.reserve(cnt);
		for (int i = 0; i < isPrime.size(); ++i) if (isPrime[i]) {
			primes.push_back(i);
		}
	}

	bool IsPrime(int num) {
		if (num < isPrime.size()) return isPrime[num];
		for (auto p : primes) {
			if (num % p == 0) return false;
		}
		int ma = sqrt(num) + 1;
		for (int i = primes.back(); i <= ma; i += 2) {
			if (num % i == 0) return false;
		}
		return true;
	}

	std::map<int, int> GetFactor(int num) {
		std::map<int, int> res;
		int a = 2;
		auto it = primes.begin();
		while (num >= a * a) {
			if (num % a == 0) {
				res[a]++;
				num /= a;
			}
			else {
				++it;
				if (it == primes.end()) {
					break;
				}
				a = *it;
			}
		}
		res[num]++;
		return res;
	}
};

int gcd(int a, int b) {
	return b != 0 ? gcd(b, a % b) : a;
}

int lcm(int a, int b) {
	return a * b / gcd(a, b);
}

// a x + b y = gcd(a, b)
int extgcd(int a, int b, int& x, int& y) {
	int g = a; x = 1; y = 0;
	if (b != 0) g = extgcd(b, a % b, y, x), y -= (a / b) * x;
	return g;
}

inline long long mod(long long a, long long m) {
	return (a % m + m) % m;
}

// condition: gcd(a,m) == 1
long long modinv(long long a, long long m) {
	long long x, y;
	extgcd(a, m, x, y);
	return mod(x, m);
}

void solve() {
	int H, W, K; cin >> H >> W >> K;
	vector<string > A(H);
	for (auto& a : A) cin >> a;

	pii S;
	REP(i, H) REP(j, W) if (A[i][j] == 'S') {
		S.first = i;
		S.second = j;
	}

	queue<pii> que;
	que.push(S);

	vector<vector<int> > d(A.size(), vector<int>(A[0].size(), inf));
	d[S.first][S.second] = 0;

	int dx[] = { 1,0,-1,0 };
	int dy[] = { 0,1,0,-1 };

	while (not que.empty()) {
		int i, j; tie(i, j) = que.front(); que.pop();
		if (d[i][j] == K) continue;
		REP(r, 4) {
			int nxt_i = i + dy[r];
			int nxt_j = j + dx[r];
			if (0 <= nxt_i and nxt_i < A.size() and 0 <= nxt_j and nxt_j < A[0].size() and A[nxt_i][nxt_j] == '.') {
				if (d[nxt_i][nxt_j] > d[i][j] + 1) {
					d[nxt_i][nxt_j] = d[i][j] + 1;
					que.push({ nxt_i, nxt_j });
				}
			}
		}
	}

	vector<pii> ps;
	REP(i, A.size()) REP(j, A[i].size()) {
		if (d[i][j] <= K) {
			ps.emplace_back(i, j);
		}
	}

	int res = inf;
	for (auto& p : ps) {
		int dy = min(p.first, H - p.first);
		int dx = min(p.second, W - p.second);
		int val = min(dy, dx);
		int temp = val / K;
		if (val % K != 0) temp++;
		chmin(res, temp);
	}
	cout << res+1 << endl;
}

