int main() {

    ll H, W, K;
    cin >> H >> W >> K;

    vector<vector<char>> A(H + 1, vector<char>(W + 1));
    vector<vector<ll>> dis(H + 1, vector<ll>(W + 1,INF));
    queue<ll> qh;
    queue<ll> qw;

    repn(i, H)repn(j, W) {
        cin >> A[i][j];
        if (A[i][j] == 'S') {
            dis[i][j] = 0;
            qh.push(i);
            qw.push(j);
        }
    }

    while (!qh.empty()) {
        ll i = qh.front();
        qh.pop();
        ll j = qw.front();
        qw.pop();

        rep (k, 4) {
            ll x = i;
            ll y = j;

            if (k < 2) { x += -1 + 2 * (k % 2); }
            else { y += -1 + 2 * (k % 2); }

            if (x <= 0 || x > H || y <= 0 || y > H) { continue; }
            if (A[x][y] == '#') { continue; }
            if (dis[x][y] != INF) { continue; }
            dis[x][y] = dis[i][j] + 1;
            qh.push(x);
            qw.push(y);
        }

    }

    ll ans = INF;

    repn(i, H)repn(j, W) {
        //cout << i << j << dis[i][j] << endl;
        if (dis[i][j] > K) { continue; }
        ll x = min(i - 1, min(j - 1, min(H - i, W - j)));
        if (x > 0) { x = (x - 1) / K + 1; }
        ans = min(ans, x + 1);
    }

    cout << ans;

	system("PAUSE");
}

