int main(){
	int H,W,K;
	cin>>H>>W>>K;
	char A[810][810];
	int sx,sy;
	REP(i,0,H) REP(j,0,W) {
		cin>>A[i][j];
		if(A[i][j]=='S'){
			sx=j;
			sy=i;
		}
	}

	int mn=min(abs(sx-0),abs(W-1-sx));
	mn=min(mn,min(abs(sy-0),abs(H-1-sy)));
	REP(i,max(0,sy-K),min(H,sy+K+1)){
		REP(j,max(0,sx-K),min(H,sx+K+1)){
			int dy=sy-i,dx=sx-j;
			if(A[i][j]=='#'||dy+dx>K) continue;
			if((dy+dx)%2==K%2){
				mn=min(mn,min(abs(j-0),abs(W-1-j)));
				mn=min(mn,min(abs(i-0),abs(H-1-i)));
			}
		}
	}

	int ans=1;
	while(mn>0){
		ans++;
		mn-=K;
	}
	p(ans);
	return 0;
}

