void bfs(int cur_h, int cur_w, int cur_dist, int K, int H, int W){
    reachable_in_one[cur_h][cur_w] = true;
    ans = min(ans, min(min(cur_h, H - 1 - cur_h), min(cur_w, W - 1 - cur_w)));
    if(cur_dist >= K){
        return;
    }
    for(int i = 0; i < 4; i++){
        int next_h = cur_h + h_moves[i];
        int next_w = cur_w + w_moves[i];
        if(0 <= next_h && next_h < H && 0 <= next_w && next_w < W 
            && !reachable_in_one[next_h][next_w] && A[next_h][next_w] != '#'){
            bfs(next_h, next_w, cur_dist + 1, K, H, W);
        }
    }
}
