const int mmax=810;
int ans=1E9+7;
int h,w,k;
bool a[mmax][mmax];
int sx,sy;
bool b[mmax][mmax];

void dfs(int i,int j,int p){
	if(i>=0&&i<h&&j>=0&&j<w&&a[i][j]==true){
		if(b[i][j]==false){
			b[i][j]==true;
			int d=min(min(min(i,j),(h-i-1)),(w-j-1));
			d=((d+k-1)/k)+1;
			ans=min(ans,d);
			if(p!=k){
				dfs(i-1,j,p+1);
				dfs(i,j-1,p+1);
				dfs(i+1,j,p+1);
				dfs(i,j+1,p+1); 
			}
		}	
	}

}

