			if(c[j]=='#'){
				a[i][j]=false;
			}else{
				a[i][j]=true;
				if(c[j]=='S'){
					sx=i;
					sy=j;
				}
			}
		}
	}
	dfs(sx,sy,0);
	cout<<ans;
	return 0;
}

