void Dfs(int x, int y, int dep, int temp) {
	if(dep > k || unlock[x][y]) return;
	unlock[x][y] = 1;
	cast[x][y] = temp + 1;
	Node now; now.x = x; now.y = y;
	p.push_back(now);
