	vis[x][y] = 1;
	tim[x][y] = max(cast[x][y] + 1, temp + 1);
	Node now; now.x = x; now.y = y;
	seq.push_back(now);
	for(int i = 1; i <= 4; i++) 
		if(Check(x + dx[i], y + dy[i]))
