int di[4] = {-1, 0, 1, 0};
int dj[4] = {0, 1, -1, 0};

void dfs(int i, int j, vector<vector<bool> > &G, vector<pair<int, int> > &ans){

    ans.push_back({i, j});

    for(int h = 0; h < 4; h++){
        int ni = i + di[h];
        int nj = j + dj[h];

        if(G[ni][nj]){
            G[i][j] = false;
            dfs(ni, nj, G, ans);
        }
    }
}

