const int MAX=800;
char maze[MAX][MAX+1];
int N, M, K;
int sx, sy;

int d[MAX][MAX];

int dx[4]={1,0,-1,0}, dy[4]={0,1,0,-1};
int ans=INF;
int bfs(){
    queue<P> que;

    rep(i,0,N)
    rep(j,0,M) d[i][j]=INF;
    que.push(P(sx, sy));
    d[sx][sy]=0;
    ans=ans=min(ans,1+(K-1+min(min(sx,N-sx-1),min(sy,M-sy-1)))/K);
    while(que.size()){
        P p=que.front(); que.pop();
        rep(i,0,4){
            int nx=p.first+dx[i], ny=p.second+dy[i];

            if (0<=nx && nx<N && 0<=ny && ny<M && maze[nx][ny]!='#' && d[nx][ny]==INF){
                que.push(P(nx,ny));
                d[nx][ny]=d[p.first][p.second]+1;
