using namespace std;

char v[1000][1000];
int b[1000][1000];

int main() {
	int n, m, k;
	cin>>n>>m>>k;
	int cy;
	int cx;
	for (int y = 1; y <= n; y++) {
		for (int x = 1; x <= m; x++) {
			cin>>v[y][x];
			if (v[y][x] == 'S') {
				v[y][x] = '.';
				cy = y;
				cx = x;
			}
		}
	}
	priority_queue<pair<pii, pii>> q;
	q.push({{0, -k}, {cy, cx}});
	int ans = INF;
	while (!q.empty()) {
		int i = -q.top().F.F;
		int l = q.top().F.S;
		if (i % k == 0) {
			l += k;
		}
		int y = q.top().S.F;
		int x = q.top().S.S;
		q.pop();
		if (y == 1 || x == 1 || y == n || x == m) {
			ans = min(ans, i);
			continue;
		}
		if (b[y][x]) continue;
		b[y][x] = i;

		if (l) {
			if (v[y + 1][x] == '#') q.push({{-(i + 1), l - 1}, {y + 1, x}});
			else q.push({{-(i + 1), l}, {y + 1, x}});

			if (v[y - 1][x] == '#') q.push({{-(i + 1), l - 1}, {y - 1, x}});
			else q.push({{-(i + 1), l}, {y - 1, x}});

			if (v[y][x + 1] == '#') q.push({{-(i + 1), l - 1}, {y, x + 1}});
			else q.push({{-(i + 1), l}, {y, x + 1}});

			if (v[y][x - 1] == '#') q.push({{-(i + 1), l - 1}, {y, x - 1}});
			else q.push({{-(i + 1), l}, {y, x - 1}});
		} else {
			int w = i / k * k + k + 1;
			if (v[y + 1][x] == '#') q.push({{-w, k - 1}, {y + 1, x}});
			else q.push({{-(i + 1), l}, {y + 1, x}});

			if (v[y - 1][x] == '#') q.push({{-w, k - 1}, {y - 1, x}});
			else q.push({{-(i + 1), l}, {y - 1, x}});

			if (v[y][x + 1] == '#') q.push({{-w, k - 1}, {y, x + 1}});
			else q.push({{-(i + 1), l}, {y, x + 1}});

			if (v[y][x - 1] == '#') q.push({{-w, k - 1}, {y, x - 1}});
			else q.push({{-(i + 1), l}, {y, x - 1}});
		}
	}
	if (ans % k == 0) cout<<ans / k<<endl;
	else cout<<ans / k + 1<<endl;
}

#include <stdio.h>
