int main(){
    int h, w, K;
    scanf("%d%d%d", &h, &w, &K);
    char a[h][w];
    int sx ,sy;
    rep(i, h)rep(j, w){
        scanf(" %c", &a[i][j]);
        if(a[i][j] == 'S') sx = i, sy = j;
    }

    const int INF = 1000000;
    pii d[h][w];
    rep(i, h)rep(j, w) d[i][j] = pii(INF, INF);
    queue<ppp> que;
    d[sx][sy] = pii(1, 0);
    que.push(ppp(pii(sx, sy), pii(1, 0)));
    int dx[4] = {0, 1, 0, -1};
    int dy[4] = {1, 0, -1, 0};

    while(!que.empty()){
        ppp p = que.front(); que.pop();
        int x = p.fi.fi;
        int y = p.fi.se;
        int td = p.se.fi;
        int tk = p.se.se;
        if(d[x][y] < p.se) continue;

        rep(i, 4){
            int nx = x + dx[i];
            int ny = y + dy[i];
            if(0<=nx && nx<h && 0<=ny && ny<w){
                pii nd;
