using namespace std;

vector<vector<int> > a;

struct state_t
{
	int r, x, y;
	bool operator < (const state_t& rhs) const
	{
		if(r<rhs.r) return 1;
		return 0;
	}
};

priority_queue<state_t> que;
int w, h;


void push(int x, int y, int r)
{
	que.push((state_t){r, x, y});
}


int pop(int& x, int& y, int& r)
{
	if(que.empty()) return 0;
	state_t s=que.top();
	x=s.x;
	y=s.y;
	r=s.r;
	que.pop();
	return 1;
}



void move(int sx, int sy, int k)
{
	int vx[]={ 1, 0,-1, 0};
	int vy[]={ 0,-1, 0, 1};
	int x, y, r, nx, ny, i;

	push(sx, sy, k);
	while(pop(x, y, r))
	{
		if(a[y][x]!='.') continue;
		a[y][x]='C';
		if(r<=0) continue;
		for(i=0;i<4;i++)
		{
			nx=x+vx[i];
			ny=y+vy[i];
			if(nx<0 || w<=nx || ny<0 || h<=ny) continue;
			push(nx, ny, r-1);
		}
	}
}


