#define INF 2000000000
#define mod 1000000007
#define INF2 1000000000000000000

typedef pair<int, int> P;
vector<P> start;
int H, W, K;
int d[1000][1000];
string S[1000];
int dx[4] = {1, 0, -1, 0};
int dy[4] = {0, 1, 0, -1};


void bfs(int sx, int sy) {
    queue<P> que;

    rep(i, H) rep(j, W) d[i][j] = INF;
    que.push(P(sx, sy));
    d[sx][sy] = 0;

    while(que.size()) {
        P p = que.front(); que.pop();
        if (p.first == 0 || p.first == H - 1 || p.second == 0 || p.second == W - 1) break;
        rep(i, 4) {
            int nx = p.first + dx[i], ny = p.second + dy[i];

            if (S[nx][ny] == '.' && d[nx][ny] == INF) {
                que.push(P(nx, ny));
                d[nx][ny] = d[p.first][p.second] + 1;
                //cout << "d[" << nx << "][" << ny << "] = " << d[nx][ny] << endl;
            }
        }
    }
}



int main(void)
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> H >> W >> K;
    rep(i, H) cin >> S[i];
    int sx, sy;
    rep(i, H) {
        bool b = false;
        rep(j, W) {
            if (S[i][j] == 'S') {
                sx = i;
                sy = j;
                b = true;
            }
            if (b) break;
        }
        if (b) break;
    }
    bfs(sx, sy);

    int ans = INF;
    rep(i, H) {
        rep(j, W) {
            if (d[i][j] <= K) {
                int x = i + 1;
                int y = j + 1;
                //cout << x << " " << y << endl;
                ans = min(ans, (min({x, y, H - x, W - y}) + K - 1) / K + 1);
            }
        }
    }
    cout << ans << endl;

    return 0;
}

