bool valid(int x, int y) {
    return 1 <= x && x <= n && 1 <= y && y <= m;
}

bool win(int x, int y) {
    return (x == 1) || (x == n) || (y == 1) || (y == m);
}

void dfs(int x, int y, int can) {
    if(can == 0)
        return;
    used[x][y] = 1;
    for(int i = 0; i < 4; i++) {
        int dx = x + mv[i][0];
        int dy = y + mv[i][1];
        if(valid(dx, dy) && d[dx][dy] == -1 && !used[dx][dy]) {
            if(f[dx][dy] == '#')
                f[dx][dy] = '.', can--;
            dfs(dx, dy, can);
            calc++;
        }
    }
}

