        for(int i = 0; i < 4; i++) {
            int dx = x + mv[i][0];
            int dy = y + mv[i][1];
            if(valid(dx, dy) && d[dx][dy] == -1 && f[dx][dy] != '#') {
                d[dx][dy] = d[x][y] + 1;
