#define MAXN 1000

int mat[MAXN][MAXN];
int memo [MAXN][MAXN];
int x, y, n, m, k;

void BFS () {

	queue <pair<int, int> > q;
	q.push(make_pair(x, y));

	memo[x][y] = 1;

	while (!q.empty()) {
		x = q.front().first;
		y = q.front().second;
		q.pop();

		if (memo[x][y] == 0) memo[x][y] = 3;

		for (int i=1; i<=k; i++) {
			if (x+i < n) {
				if (memo[x+i][y] == 0) {
				 	if (mat[x+i][y] == 1) memo[x+i][y] = memo[x][y]+1;
				 	else mat[x+i][y] = 1;
					q.push(make_pair(x+i, y));
				}
			}

			if (x-i >= 0) {
				if (memo[x-i][y] == 0) {
					if (mat[x-i][y] == 1) memo[x-i][y] = memo[x][y]+1;
					else mat[x-i][y] = 1;
					q.push(make_pair(x-i, y));
				}
			}

			if (y+i < m) {
				if (memo[x][y+i] == 0) {
					if (mat[x][y+i] == 1) memo[x][y+i] = memo[x][y]+1;
					else mat[x][y+i] = 1;
					q.push(make_pair(x, y+i));
				}
			}

			if (y-i >= 0) {
				if (memo[x][y-i] == 0) {
					if (mat[x][y-i] == 1) memo[x][y-i] = memo[x][y]+1;
					else mat[x][y-i] = 1;
					q.push(make_pair(x, y-i));
				}
			}
		}
	}

}

