struct state{
  int i, j, k, m, r;
  state(){}
  state(int i, int j, int k, int m, int r): i(i), j(j), k(k), m(m), r(r){}
  bool operator<(const state &R) const{
    if(m != R.m)return m > R.m;
    if(k != R.k)return k > R.k;
    return r < R.r;
  }
};

