  dis[sx][sy] = 1;
  pq.push(state(sx, sy, 0, 1, 0));
  while(!pq.empty()){
    auto p = pq.top(); pq.pop();
    if(dis[p.i][p.j] < p.m)continue;
    rep(l, 4){
      int nx = p.i + dx[l];
      int ny = p.j + dy[l];
      if(nx >= 0 && nx < h && ny >= 0 && ny < w){
        if(s[nx][ny] == '#'){
          state s = state(nx, ny, p.k + 1, p.m, p.r - 1);
          if(s.r < 0){
            s.r = k - 1;
            s.k = 1;
            s.m++;
          }
          if(s.k > k){
            s.k = 1;
            s.m++;
            s.r += k;
          }
          if(dis[nx][ny] > s.m){
            dis[nx][ny] = s.m;
            pq.push(s);
          }
