          state s = state(nx, ny, p.k + 1, p.m, p.r);
          if(s.k > k){
            s.k = 1;
            s.m++;
            s.r += k;
          }
          if(dis[nx][ny] > s.m){
            dis[nx][ny] = s.m;
            pq.push(s);
          }
        }
      }
    }
  }
  int res = inf;
  rep(i, h){
    chmin(res, dis[i][0]);
    chmin(res, dis[i][w-1]);
  }
  rep(j, w){
    chmin(res, dis[0][j]);
    chmin(res, dis[h-1][j]);
  }
