        if(grid[i][j] == 'S'){
            sy = i;
            sx = j;
        }
        dist[i][j] = INF;
    }
    dist[sy][sx] = 0;
    int ans = INF;
    queue<P> que;
    que.push(P(sy, sx));
    while(!que.empty()){
        P p = que.front();
        que.pop();
        int cost = INF;
        chmin(cost, 1 + (p.first + k - 1) / k);
        chmin(cost, 1 + (h - 1 - p.first + k - 1) / k);
        chmin(cost, 1 + (p.second + k - 1) / k);
        chmin(cost, 1 + (w - 1 - p.second + k - 1) / k);
        chmin(ans, cost);
