int h,w,k;
bool locked[801][801]={};
bool found[801][801]={};
int depth[801][801]={};
pair<int , int> parent[801][801]={};


int main()
{

  cin >> h >> w >> k;

  //入力する
  int s,t;
  for(int i=0;i<h;i++){
    for(int j=0;j<w;j++){
      char tmp;
      cin >> tmp;
      if(tmp == '.')
        locked[i][j] = 0;
      else if(tmp == '#')
        locked[i][j] = 1;
      else{
        locked[i][j] = 0;
        s = i;
        t = j;
      }
    }
  }


  queue<pair<int ,int>> q;
  q.push(make_pair(s,t));
  found[s][t] = 1;
  //sからbfsを実施し、距離k以内で行ける点の距離を計算する

  while(!q.empty()){
    pair<int ,int> p = q.front();
    q.pop();
    if(p.first > 0){
      //上を調査
      if(!found[p.first - 1][p.second] && !locked[p.first - 1][p.second]){
        q.push(make_pair(p.first - 1,p.second));
        found[p.first - 1][p.second] = true;
        depth[p.first - 1][p.second] = depth[p.first][p.second] + 1;
      }
    }
    if(p.first < h-1){
      //下を調査
      if(!found[p.first + 1][p.second] && !locked[p.first + 1][p.second]){
        q.push(make_pair(p.first + 1,p.second));
        found[p.first + 1][p.second] = true;
        depth[p.first + 1][p.second] = depth[p.first][p.second] + 1;
      }
    }
    if(p.second > 0){
      //左を調査
      if(!found[p.first][p.second - 1] && !locked[p.first][p.second -1]){
        q.push(make_pair(p.first,p.second - 1));
        found[p.first][p.second - 1] = true;
        depth[p.first][p.second - 1] = depth[p.first][p.second] + 1;
      }
    }
    if(p.second < w-1){
      //右を調査
      if(!found[p.first][p.second + 1] && !locked[p.first][p.second +1]){
        q.push(make_pair(p.first,p.second + 1));
        found[p.first][p.second + 1] = true;
        depth[p.first][p.second + 1] = depth[p.first][p.second] + 1;
      }
    }
  }

  //最小値を出力する

  int ans = 2000;

  for(int i=0;i<h;i++){
    for(int j=0;j<w;j++){
      if(found[i][j] && depth[i][j] <= k ){
        if(i == 0 || i == h-1 || j == 0 || j == w-1 ){
          ans = 1;
        }
        else{
          int tmp = 2000;
          tmp = min(min( i , h - 1 -i ),min( j , w - 1 - j));
          ans = min(ans, 1 + tmp/k + (tmp%k > 0 ));
        }
      }
    }
  }

  cout << ans << endl;

  return 0;
}

