void solve(){
    int H,W,K;
    cin >> H >> W >> K;
    vector<string> A(H);
    int sy,sx;
    rep(i,0,H){
        cin >> A[i];
        rep(j,0,W) if(A[i][j]=='S'){
            sy=i;
            sx=j;
            break;
        }
    }

    vector<vector<int>> dist(H,vector<int>(W,inf));
    queue<pair<int,int>> que;
    vector<int> dy({0,-1,0,1}),dx({1,0,-1,0});
    que.push(make_pair(sy,sx));
    dist[sy][sx]=0;
    while(!que.empty()){
        auto p=que.front();
        que.pop();
        int y=p.first,x=p.second;
        rep(i,0,4){
            int y_=y+dy[i],x_=x+dx[i];
            if(y_<0 or H<=y_ or x_<0 or W<=x_ or A[y_][x_]=='#') continue;
            if(dist[y_][x_]!=inf) continue;
            que.push(make_pair(y_,x_));
            dist[y_][x_]=dist[y][x]+1;
        }
    }

    vector<int> mi1(H,inf),ma1(H,-inf),mi2(W,inf),ma2(W,-inf);
    rep(i,0,H) rep(j,0,W) if(dist[i][j]<=K){
        mi1[i]=min(mi1[i],j);
        ma1[i]=max(ma1[i],j);
    }
    rep(i,0,W) rep(j,0,H) if(dist[j][i]<=K){
        mi2[i]=min(mi2[i],j);
        ma2[i]=max(ma2[i],j);
    }

    int ans=inf;
    rep(i,0,H){
        int y=i,x=0;
        rep(j,0,H){
            if(mi1[j]==inf) continue;
            ans=min(ans,1+(abs(y-j)+abs(x-mi1[j])+K-1)/K);
        }
    }
    rep(i,0,H){
        int y=i,x=W-1;
        rep(j,0,H){
            if(ma1[j]==-inf) continue;
            ans=min(ans,1+(abs(y-j)+abs(x-ma1[j])+K-1)/K);
        }
    }
    rep(i,0,W){
        int y=0,x=i;
        rep(j,0,W){
            if(mi2[j]==inf) continue;
            ans=min(ans,1+(abs(y-mi2[j])+abs(x-j)+K-1)/K);
        }
    }
    rep(i,0,W){
        int y=H-1,x=i;
        rep(j,0,W){
            if(ma2[j]==-inf) continue;
            ans=min(ans,1+(abs(y-mi2[j])+abs(x-j)+K-1)/K);
        }
    }
    cout << ans << endl;
}

