const ll MOD=10000;
const ll INF=1000000010;
const ll LINF=1000000000000000010;
int dx[4]={1,0,-1,0};
int dy[4]={0,-1,0,1};
int h,w,k;
bool field(int x,int y){
    if(x<1||x>w||y<1||y>h){
        return false;
    }
    return true;
}
int main(){
    cin>>h>>w>>k;
    char a[810][810];
    int sx,sy;
    for(int i=1;i<=h;i++){
        string s;cin>>s;
        for(int j=1;j<=w;j++){
            a[i][j]=s[j-1];
            if(a[i][j]=='S'){
                sx=j;sy=i;
                break;
            }
        }
    }
    queue<P> q;
    q.push(P(sx,sy));
    int v[810][810];memset(v,-1,sizeof(v));
    v[sy][sx]=0;
    while(!q.empty()){
        int x=q.front().first;
        int y=q.front().second;
        q.pop();
        for(int j=0;j<4;j++){
            int nx=x+dx[j];
            int ny=y+dy[j];
            if(field(nx,ny)&&a[ny][nx]!='#'&&v[ny][nx]==-1){
                v[ny][nx]=v[y][x]+1;
                q.push(P(nx,ny));
            }
        }
