        flg[y][x] = INF;
        if(mp[y][x] == 'S'){
            sx = x;
            sy = y;
        }
    }
    flg[sy][sx] = 0;
    queue<P>Q;
    Q.push(P(sx, sy));
    while(!Q.empty()){
        ll x = Q.front().first;
        ll y = Q.front().second;
        Q.pop();
        rep(i, 4){
            ll nx = x + dx[i];
            ll ny = y + dy[i];
            if(flg[ny][nx] < INF)continue;
            if(mp[ny][nx] == '#')continue;
            flg[ny][nx] = flg[y][x] + 1;
            Q.push(P(nx, ny));
        }
    }
    ll ans = INF;
    rep1(y, H)rep1(x, W)if(flg[y][x] <= K){
