}

bool check(bset s){
	for (int y = 0; y < H; y++){ if (s[y*W + 0])return true; if (s[y*W + W - 1])return true; }
	for (int x = 0; x < W; x++){ if (s[0*W + x])return true; if (s[(H-1)*W + x])return true; }
	return false;
}

bset calc_kabe(bset kabe, bset s){
	cerr << "kabe" << endl;
	bset ts=s;
	for (int k = 0; k < 800; k++){
		bset ns = bset();
		ns |= ts << W;
		ns |= ts << 1;
		ns |= ts >> 1;
		ns |= ts >> W;
		ns &= ~kabe;
		ts |= ns;


	}
	bset ns = bset();
	ns |= ts << W;
	ns |= ts << 1;
	ns |= ts >> 1;
	ns |= ts >> W;
	bset t = ns&kabe;
	return kabe&~t;
}

int main(){

	cin >> H >> W >> K;
	bset kabe = ~bset();
	bset s = bset();
	for (int y = 0; y < H; y++){
		for (int x = 0; x < W; x++){
			char c;
			cin >> c;
			if (c != '#')kabe[y*W + x] = false;
