			ns |= s << W;
			ns |= s << 1;
			ns |= s >> 1;
			ns |= s >> W;
			ns &= ~kabe;
			s |= ns;
			if (check(s)){ cout << cnt << endl; return 0; }
			print(s);

		}
		cerr << "endk" << endl;
		for (int k = 0; k < K; k++){
			cerr << "\tk:" << k << endl;
			//なぜかこの後calc_kabe内のエラー出力が吐かれない！（入力例 2）
			kabe = calc_kabe(kabe, s);
