template<class T>bool chmax(T & a, const T & b) { if (a < b) { a = b; return 1; } return 0; }
template<class T>bool chmin(T& a, const T& b) { if (b < a) { a = b; return 1; } return 0; }

lli data[900][900];
bool vis[900][900];

int main(){

	lli h,w,k;
	cin>>h>>w>>k;

	lli si,sj;
	REP(i,0,h)REP(j,0,w){
		char tmp;
		cin>>tmp;
		if(tmp=='#')data[i][j]=-1;
		else if(tmp=='S')si=i,sj=j;
	}

	queue<lli> qi,qj;
	queue<lli> qd;
	qi.push(si);
	qj.push(sj);
	qd.push(0);
	vis[si][sj]=true;


	while(qi.size()){
		lli topI = qi.front();
		lli topJ = qj.front();
		qi.pop(),qj.pop();
		lli topD = qd.front();
		qd.pop();
		data[topI][topJ]=1;

		if(topD>=k)continue;

		lli di[4]={-1,0,1,0};
		lli dj[4]={0,1,0,-1};

		REP(i,0,4){
			lli nextI = topI + di[i];
			lli nextJ = topJ + dj[i];
			if(nextI<0 || nextI>=h || nextJ<0 || nextJ>=w)continue;
			if(data[nextI][nextJ]<0)continue;
			if(vis[nextI][nextJ])continue;

			vis[nextI][nextJ]=true;
			qi.push(nextI);
			qj.push(nextJ);
			qd.push(topD+1);
		}
	}

	lli ans = INF;

	REP(i,0,h)REP(j,0,w){
		if(data[i][j]==1){
			lli length = min({i,j,(int)h-1-i,(int)w-1-j});
			if(length==0){
				cout<<1<<endl;
				return 0;
			}
			ans = min(ans,(length-1)/k+2);
		}
	}
	cout<<ans<<endl;

}

