		int y=q.front().second;
		q.pop();
		Ans=min(Ans,dis[x][y]+1);
		if (dep[x][y]==K) continue;
		if (g[x-1][y]&&!vis[x-1][y]) dep[x-1][y]=dep[x][y]+1,vis[x-1][y]=1,q.push(make_pair(x-1,y));
		if (g[x+1][y]&&!vis[x+1][y]) dep[x+1][y]=dep[x][y]+1,vis[x+1][y]=1,q.push(make_pair(x+1,y));
		if (g[x][y-1]&&!vis[x][y-1]) dep[x][y-1]=dep[x][y]+1,vis[x][y-1]=1,q.push(make_pair(x,y-1));
		if (g[x][y+1]&&!vis[x][y+1]) dep[x][y+1]=dep[x][y]+1,vis[x][y+1]=1,q.push(make_pair(x,y+1));
	}
}

