const ll INF = 0x3fffffff;

const int vx[4]={1,0,-1,0}, vy[4]={0,1,0,-1};

int H, W, K, ans=0;
vector<string> mp(805);
bool visited[805][805]={};
int solve(int x, int y, int K){
	int ret = INF;
	queue< pair<pii, int> > que;
	que.emplace(pii(x,y), K);
	while( !que.empty() ){
		int x = que.front().X.X;
		int y = que.front().X.Y;
		int limit = que.front().Y;
		que.pop();
		//cout << x << "," << y << " " << limit << endl;
		chmin(ret, x);
		chmin(ret, W-1-x);
		chmin(ret, y);
		chmin(ret, H-1-y);
		if( limit == 0 ){
			continue;
		}
		if( x == 0 || y == 0 || x == H-1 || y == W-1 ) continue;
		rep(k,4){
			int nx = x + vx[k];
			int ny = y + vy[k];
			//cout << "nex: " << nx << "," << ny << endl;
			if( nx < 0 && ny < 0 && nx >= H && ny >= W ) continue;
			if( mp[ny][nx] == '.' && !visited[ny][nx] ){
				que.emplace(pii(nx,ny), limit-1);
				visited[ny][nx] = true;
			}
		}
	}
	return ret;
}

