};
int judge(int x,int y){
    if(x<1 || x>n || y<1 || y>m)
        return 1;
    if(u[x][y] == 1 || a[x][y] == '#')
        return 1;
    return 0; 
}
void bfs(){
    node init;
    queue<node> q;
    node next;
    init.x = x;
    init.y = y;
    init.step = 0;
    u[x][y] = 1;
    q.push(init);
    while(!q.empty()){
        node tmp = q.front();
        q.pop();
        for(int i=0;i<4;i++){
            next.x = tmp.x+dir[i][0];
            next.y = tmp.y+dir[i][1];
            if(judge(next.x,next.y)) continue;
            a[next.x][next.y]='c';
            next.step = tmp.step+1;
            u[next.x][next.y] = 1;
            if(next.step<k)q.push(next);
        }
    }
}
