		sr = min(sr,min(min(x, W - x - 1), min(y, H - y - 1)));
	};

	sr = min(min(sx, W - sx - 1), min(sy, H - sy - 1));
	push_move(K, sx, sy);

	while(moveque.size()){
		auto val = moveque.top();
		moveque.pop();
		int x = val.second % W;
		int y = val.second / W;
		if (x > 0)push_move(val.first - 1, x -1, y);
		if (x < W - 1)push_move(val.first + 1, x + 1, y);
		if (y > 0)push_move(val.first - 1, x, y - 1);
		if (y < H -1)push_move(val.first - 1, x, y + 1);
	};

	if (sr == 0) MC = 1;
	else {
		MC = (sr - 1) / K + 2;
	}
	cout << MC;
	return 0;
}

