#include <bits/stdc++.h>
#define N 1005
#define INF 0x3f3f3f3f
using namespace std;
typedef long long ll;
int X,Y,k;
const int dx[]={-1,0,1,0};
const int dy[]={0,1,0,-1};
bool In(int x,int y)
{
	return x>=0 and x<X and y>=0 and y<Y;
}
char s[N][N];
int sx,sy;
int dist[N][N];
int rev_dis[N][N];
struct Node
{
	int x,y,dis;
	Node(){}
	Node(int a,int b,int c)
	{
		x=a;
		y=b;
		dis=c;
	}
};
void Init()
{
	scanf("%d%d%d",&X,&Y,&k);
	for(int i=0;i<X;i++)
	{
		scanf("%s",s[i]);
	}
	for(int i=0;i<X;i++)
	{
		for(int j=0;j<Y;j++)
		{
			if(s[i][j]=='S')
			{
				sx=i;
				sy=j;
				s[i][j]='.';
			}
		}
	}
}
queue <Node> q;
void Solve()
{
	memset(dist,0x3f,sizeof(dist));
	q.push(Node(sx,sy,0));
	while(not q.empty())
	{
		Node t=q.front();
		q.pop();
		if(dist[t.x][t.y]>t.dis)
		{
			dist[t.x][t.y]=t.dis;
			for(int i=0;i<4;i++)
			{
				int xx=t.x+dx[i];
				int yy=t.y+dy[i];
				if(not In(xx,yy))continue;
				if(s[xx][yy]=='#')continue;
				q.push(Node(xx,yy,t.dis+1));
			}
		}
	}
	while(not q.empty())q.pop();
	memset(rev_dis,0x3f,sizeof(rev_dis));
	for(int i=0;i<X;i++)
	{
		q.push(Node(i,0,s[i][0]=='#'));
		q.push(Node(i,Y-1,s[i][Y-1]=='#'));
	}
	for(int i=0;i<Y;i++)
	{
		q.push(Node(0,i,s[0][i]=='#'));
		q.push(Node(X-1,i,s[X-1][i]=='#'));
	}
	while(not q.empty())
	{
		Node t=q.front();
		q.pop();
		if(rev_dis[t.x][t.y]>t.dis)
		{
			rev_dis[t.x][t.y]=t.dis;
			for(int i=0;i<4;i++)
			{
				int xx=t.x+dx[i];
				int yy=t.y+dy[i];
				if(not In(xx,yy))continue;
				bool cost=s[xx][yy]=='#';
				q.push(Node(xx,yy,t.dis+cost));
			}
		}
	}
	int res=INF;
	for(int i=0;i<X;i++)
	{
  		for(int j=0;j<Y;j++)
		{
			res=min(res,(int)ceil(1.0*rev_dis[i][j]/k)+(int)ceil(1.0*dist[i][j]/k)+1);
  		}
	}
	printf("%d\n",res);
}
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    Init();
    Solve();
	return 0;
}

