    step[S.x][S.y] = S.step;
    vis[S.x][S.y] = 1;
    while (!Q.empty())
    {
        info u = Q.front();
        Q.pop();
        for (int i = 0; i < 4; ++i)
        {
            info v = u + dir[i];
            if (check(v))
            {
                vis[v.x][v.y] = 1;
                step[v.x][v.y] = v.step;
                Q.push(v);
            }
        }
    }
}
inline int calc(int a,int b)
{
    return a/b+(a%b!=0);
}
