                        ans=min(ans,calc(step[i][j],k));
                    else
                    {
                        int L=j;
                        int R=m-1-j;
                        int U=i;
                        int D=n-1-i;
                        int base=calc(step[i][j],k);
                        ans=min(ans,base+calc(L,k));
