	tmp = min(tmp, w);
	tmp = min(tmp, H - h - 1);
	tmp = min(tmp, W - w - 1);
	if(tmp % K == 0){
		ans = min(ans, tmp/K);
	}else{
		ans = min(ans, tmp/K + 1);
	}

	move(h-1, w, cost+1);
	move(h+1, w, cost+1);
	move(h, w-1, cost+1);
	move(h, w+1, cost+1);
}

