int dfs(int yo, int xo, int type, int move, int cnt) {

	if(yo==0 || yo==n-1|| xo==0 || xo==m-1) {
		return cnt;
	}
	for(int k = 0;k<4;k++) {
		int xi = xo + x[k];
		int yi = yo + y[k];
		if(yi>=0 && yi<n && xi>=0 && xi<m) {
			if(vis[yi][xi]>cnt) {
				vis[yi][xi] = cnt;
				if(arr[yi][xi]==arr[yo][xo]) {
					if(move==0) {
						ans = min(ans, dfs(yi, xi, type, p, cnt+1));
					} else {
						ans = min(ans, dfs(yi, xi, type, move-1, cnt));
					}				
				} else {
					ans = min(ans, dfs(yi, xi, 1-type, p, cnt+1));
				}
			}
		}
	}
	return ans;
}
