            if(0 > nx || nx >= h || 0 > ny || ny >= w){
                continue;
            }
            if(d[nx][ny] <= dist){
                continue;
            }

            q.push({{nx, ny}, {1, dist.second + 1}});
        }
    }

    int ans = INF;
    rep(i, h){
        rep(j, w){
            if(i != 0 && i != h - 1 && j != 0 && j != w - 1){
                continue;
            }

            int tmp = d[i][j].first + (d[i][j].second + k - 1) / k;
            ans = min(ans, tmp);
        }
    }
