template<class T>bool chmax(T &a, const T &b) { if (a<b) { a=b; return 1; } return 0; }
template<class T>bool chmin(T &a, const T &b) { if (b<a) { a=b; return 1; } return 0; }
const ll MOD = 1e9+7;

bool X[810][810];
bool isvisit[810][810];
ll H, W, K;

typedef queue<pair<ll, ll>> Q;

bool dfs(Q& que, ll y, ll x, int num){
    if(y >= H) return false;
    if(x >= W) return false;
    if(y < 0) return false;
    if(x < 0) return false;

    if(isvisit[y][x]) return false;

    if(!X[y][x]) {
        if(num > 0)
            num--;
        else{
            que.push(mp(y, x));
            return false;
        }
    }

    isvisit[y][x] = true;
    if(y == 0) return true;
    if(x == 0) return true;
    if(y == H-1) return true;
    if(x == W-1) return true;

    bool ret = false;
    chmax(ret, dfs(que, y+1, x, num));
    chmax(ret, dfs(que, y-1, x, num));
    chmax(ret, dfs(que, y, x+1, num));
    chmax(ret, dfs(que, y, x-1, num));

    return ret;
}

ll solve(pair<ll, ll> s){
    // (y, x, num)
    Q tmp;
    if(dfs(tmp, s.first, s.second, 0))
        return 1;
    MEMS(isvisit, false);

    Q que;
    int num = 1;
    que.push(s);
    while(1){
        num++;
        while(!que.empty()){
            auto p = que.front();
            que.pop();
            bool end = dfs(que, p.first, p.second, K);
            if(end) return num;
        }
    }
}

