queue<PII> q;
int Get(int i,int j)
{
	int tmp=(i+k-2)/k;
	tmp=min(tmp,(j+k-2)/k);
	tmp=min(tmp,(h-i+k-1)/k);
	tmp=min(tmp,(w-j+k-1)/k);
	return tmp;
}
int main()
{
	scanf("%d%d%d",&h,&w,&k);
	for(int i=1;i<=h;i++) scanf("%s",s[i]+1);
