const int SIZE = 1e3+10;
char s[SIZE][SIZE];
PII bfs[SIZE*SIZE];
int v[SIZE][SIZE];
int dx[4]={1,0,-1,0};
int dy[4]={0,1,0,-1};
int H,w,K;
bool out(int x,int y){
    return x<=0||y<=0||x>H||y>w;
}
bool ending(int x,int y){
    return x==0||y==0||x==H||y==w;
}
int main(){
    R(H,w,K);
    FOR(i,1,H)RS(s[i]+1);
    PII st;
    FOR(i,1,H)FOR(j,1,w){
        if(s[i][j]=='S'){
            st={i,j};
        }
    }
    bfs[0]=st;
    int rr=1;
    MS1(v);
    v[st.F][st.S]=0;
    int an=10000;
    REP(i,rr){
        auto now=bfs[i];
        int me=min({now.F-1,now.S-1,H-now.F,w-now.S});
        an=min(an,(me+K-1)/K+1);
        if(v[now.F][now.S]==K)continue;
        REP(j,4){
            PII nxt=MP(now.F+dx[j],now.S+dy[j]);
            if(out(nxt.F,nxt.S))continue;
            if(s[nxt.F][nxt.S]=='#')continue;
            if(ending(nxt.F,nxt.S)){
                W(1);
                return 0;
            }
            if(v[nxt.F][nxt.S]!=-1)continue;
            v[nxt.F][nxt.S]=v[now.F][now.S]+1;
            bfs[rr++]=nxt;
        }
    }
    W(an);
    return 0;
}

