using namespace std;

int h, w, k;
char map[801][802] = {0};
char visited[801][802] = {0};
int nd = INT_MAX;

void searchNearest( int cx, int cy, int ck )
{
  if( cy < 1 || h < cy || cx < 1 || w < cx)
    return;
  if( map[cy][cx] == '#')
    return;
  if( visited[cy][cx] != 0 )
    return;
  visited[cy][cx] = 1;

  // check distance
  int dy = ( h / 2 >= cy )? cy : h - cy;
  int dx = ( w / 2 >= cx )? cx : w - cx;
  int md = ( dy < dx )? dy : dx;
  if( md < nd )
    nd = md;

  // check neighber
  if( ck > 0 )
  {
    --ck;
    searchNearest( cx - 1, cy, ck );
    searchNearest( cx + 1, cy, ck );
    searchNearest( cx, cy - 1, ck );
    searchNearest( cx, cy + 1, ck );
  }
}

int main()
{
  cin >> h >> w >> k;

  int sx = 0, sy = 0;
  for( int i = 1;i <= h;++i )
  {
    cin >> &map[i][1];

    // search start pos
    if( sx == 0 )
    {
      for( int j = 1;j <= w;++j )
      {
        if( map[i][j] == 'S' )
        {
          sx = j;
          sy = i;
          break;
        }
      }
    }
  }

  // search nearest point
  searchNearest( sx, sy, k );
  int count = ( nd / k + 1 );
  if( nd % k )
    ++count;
  cout << count << endl;
}

#include <bits/stdc++.h>

using namespace std;


#define MAXN 810
typedef pair<int, int> pii;
int h, w, k;
char a[MAXN][MAXN];
int d[MAXN][MAXN];
int dx[4] = {1,  0, -1,  0};
int dy[4] = {0, -1,  0,  1};

int intceil(int a, int b) {
  return a/b + (a%b>0);
}

void bfs(int i, int j) {
  priority_queue<pair<int, pii>, vector<pair<int, pii>>, greater<pair<int, pii>> > pq;
  for (int i = 0; i < h; ++i) {
    for (int j = 0; j < w; ++j) {
      d[i][j] = 1e9;
    }
  }
  pq.push({0, {i, j}});
  d[i][j] = 0;
  while(!pq.empty()) {
    auto u = pq.top();
    int cost = u.first;
    i = u.second.first;
    j = u.second.second;
    pq.pop();
    if (cost>k) break;
    for (int di = 0; di < 4; ++di) {
      int ni = i+dy[di];
      int nj = j+dx[di];
      if (ni<0 || ni>h-1 || nj<0 || nj>w-1) continue;
      if (a[ni][nj]=='#') continue;
      int nc = cost + 1;
      if (d[ni][nj] > nc) {
        d[ni][nj] = nc;
        pq.push({nc, {ni, nj}});
      }
    }
  }
}


int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL);
  int I, J, ans=MAXN;
  cin >> h >> w >> k;
  for (int i = 0; i < h; ++i) {
    for (int j = 0; j < w; ++j) {
      cin >> a[i][j];
      if (a[i][j]=='S') {
        I = i;
        J = j;
      }
    }
  }
  bfs(I, J);
  for (int i = 0; i < h; ++i) {
    for (int j = 0; j < w; ++j) {
      //cout << d[i][j] << " ";
      if (d[i][j]<MAXN) ans = min(ans, intceil(min(min(i, h-1-i), min(j, w-1-j)), k)+1);
    }
    //cout << endl;
  }
  cout << ans << endl;
  return 0;
}

