signed main() {
	ll h, w, k;
	cin >> h >> w >> k;
	VS mp(h);
	cin >> mp;

	PAIR s;
	REP(i, h)REP(j, w) {
		if (mp[i][j] == 'S') { s = {i,j}; }
	}

	using type = pair<ll, PAIR>;
	VVL cost(h, VL(w, 1e9));
	priority_queue<type, V<type>, std::greater<type>> q;
	q.emplace(1, s);
	cost[s.first][s.second] = 1;

	auto go = [&](ll y, ll x, ll c) {
		if (y < 0 || y >= h || x < 0 || x >= w) { return; }
		if (mp[y][x] == '#') { return; }
		if (cost[y][x] < 1e8) { return; }
		if (c == k) { return; }
		q.emplace(c, PAIR{y,x});
		cost[y][x] = c;
	};

	while (!q.empty()) {
		ll cost = q.top().first;
		PAIR from = q.top().second;
		q.pop();
		go(from.first + 1, from.second, cost);
		go(from.first - 1, from.second, cost);
		go(from.first, from.second + 1, cost);
		go(from.first, from.second - 1, cost);
	}

	ll ans = 1e9;
	REP(i, h)REP(j, w) {
		MIN(ans, cost[i][j] + ((h - i - 1) + k - 1) / k);
		MIN(ans, cost[i][j] + ((w - j - 1) + k - 1) / k);
		MIN(ans, cost[i][j] + (i + k - 1) / k);
		MIN(ans, cost[i][j] + (j + k - 1) / k);
	}
	cout << ans << endl;
}

