int main() {
    cin >> h >> w >> k;
    for (int i = 0; i < h; i++) cin >> maze[i];
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (maze[i][j] == 'S') {
                sh = i;
                sw = j;
            }
            d[i][j] = inf;
        }
    }
    queue<pair<int,int>> q;
    q.push({sh,sw});
    d[sh][sw] = 0;
    while (!q.empty()) {
        pair<int,int> p = q.front();
        q.pop();
        for (int i = 0; i < 4; i++) {
            int th = p.first + dh[i];
            int tw = p.second + dw[i];
            if (th < 0 || th >= h) continue;
            if (tw < 0 || tw >= w) continue;
            if (maze[th][tw] == '#') continue;
            if (d[th][tw] != inf) continue;
            d[th][tw] = d[p.first][p.second] + 1;
