int H,W,K,Sx,Sy,dis[810][810],Ans=1e9;
bool g[810][810],vis[810][810];

void search(int x,int y,int k)
{
	if (!g[x][y]) return;
	Ans=min(Ans,dis[x][y]+1);
	if (!k) return;
	if (vis[x][y]) return;
	vis[x][y]=1;
	search(x-1,y,k-1);
	search(x+1,y,k-1);
	search(x,y-1,k-1);
	search(x,y+1,k-1);
}

