#include <vector>
using namespace std;
#define p pair<int,int>
#define out(tp) (tp.first < 0 || tp.first > W || tp.second < 0 || tp.second > H)

int rs[] = {0,0,1,-1};
int cs[] = {-1,1,0,0};

typedef struct node {
    p tp;
    int r, ml, cl;
} node;
typedef node * Node;

class cmp {
    public: bool operator() (Node a, Node b) { return (b->r < a->r || (b->r == a->r && b->cl > a->cl)); }
};

Node newNode(p tp, int r, int ml, int cl) {
    Node tn = (Node) malloc(sizeof(node));
    tn->tp = tp, tn->r = r, tn->ml = ml, tn->cl = cl;
    return tn;
}

int main() {
    int H, W, K, i, r, c;
    p tp;
    string m[800];
    cin >> H >> W >> K;
    for (r = 0; r < H; r++) {
        cin >> m[r];
        for (c = 0; c < W; c++) {
            if (m[r][c] == 'S') {
                m[r][c] = '.';
                tp = p(r, c);
            }
        }
    }

    // each state
    // - coord
    // - moves so far
    // - rooms to move left
    // - rooms to clear left
    priority_queue<Node, vector<Node>, cmp> q;
    q.push(newNode(tp, 0, K, K));

    int seen[800][800] = {};
    while (!q.empty()) {
        Node t = q.top(); q.pop();

        //printf("at %d %d, r:%d, ml:%d, cl:%d\n", t->tp.first, t->tp.second, t->r, t->ml, t->cl);
        // If you moved out of bounds, game over
        if (out(t->tp)) {
            cout << t->r+1+(t->cl != K) << '\n';
            return 0;
        }

        if (seen[t->tp.first][t->tp.second]) continue;
        seen[t->tp.first][t->tp.second] = 1;

        // Move
        for (i = 0; i < 4; i++) {
            tp = p(t->tp.first+rs[i], t->tp.second+cs[i]);

            if (out(tp) || m[tp.first][tp.second] == '.') {
                // push a node where you've moved there
                Node nn = newNode(tp, t->r, t->ml-1, t->cl);
                if (nn->ml < 0) {
                    nn->ml += K, nn->cl += K, nn->r++;
                }
                q.push(nn);
            }
            else {
                // push a node where you've destroyed it AND moved there
                Node nn = newNode(tp, t->r, t->ml-1, t->cl-1);
                if (nn->ml < 0 || nn->cl < 0) {
                    nn->ml += K, nn->cl += K, nn->r++;
                }
                q.push(nn);

            }
        }
    }
}

