}
bool inside(PII p) {
    return inside(p.first, p.second);
}

int main(void) {
    REP(i, MAX) REP(j, MAX) minCost[i][j] = INF;
    scanf("%d%d%d", &H, &W, &K);
    PII start;
    REP(i, H) {
        A[i] = next();
        assert(A[i].length() == W);
        REP(j, W) {
            if (A[i][j] == 'S') {
                start = MP(i, j);
            }
        }
    }
    priority_queue<tuple<int, PII, int, int>, VT<tuple<int, PII, int, int>>, greater<tuple<int, PII, int, int>>> pq;
    // (cost, point, 動ける数, 開けられる数)
    pq.push(MT(0, start, 0, 0));
    while (!pq.empty()) {
        PII nowPoint;
        int nowCost, canMove, canOpen;
        tie(nowCost, nowPoint, canMove, canOpen) = pq.top(); pq.pop();
        if (minCost[nowPoint.first][nowPoint.second] <= nowCost) {
            continue;
        }
        minCost[nowPoint.first][nowPoint.second] = nowCost;
        bool f = false;
        if (canMove == 0) {
            f = true;
            nowCost++;
            canMove = K;
            canOpen += K;
        }
        REP(i, 4) {
            PII nextPoint = MP(nowPoint.first + dh[i], nowPoint.second + dw[i]);
