                    pq.push(MT(nowCost, nextPoint, canMove - 1, canOpen - 1));
                } else {
                    pq.push(MT(nowCost + 1, nextPoint, K, K));
                }
            } else {
                pq.push(MT(nowCost, nextPoint, canMove - 1, canOpen));
            }
        }
    }
    int ans = INF;
    REP(i, H) {
        if (i == 0 || i == H - 1) {
            REP(j, W) {
                chmin(ans, minCost[i][j]);
            }
        } else {
            chmin(ans, minCost[i][0]);
            chmin(ans, minCost[i][W - 1]);
        }
    }
