    }

    REP(i,W) {
        if(cnt[H-1][i] == K || cnt[0][i] == K) {
            cout << 0 << endl;
            return 0;
        }
    }

    /*REP(i,H){
        REP(j,W) cout << cnt[i][j] << " ";
        cout << endl;
    }*/

    int ans = 1e9;
    REP(i,H)REP(j,W) {
        if(cnt[i][j] <= K) {
            ans = min(ans,(i));
            ans = min(ans,(j));
            ans = min(ans,(H-i-1));
            ans = min(ans,(W-j-1));
        }
    }

    if(ans%K == 0)  ans = ans/K + 1;
    else ans = ans/K + 2;

    cout << ans << endl;

    return 0;
}

