int main() {
	int H,W,K; cin >> H >> W >> K;
	V<string> A(H);
	REP(i,H) cin >> A[i];
	int y,x;
	REP(i,H) REP(j,W) if(A[i][j] == 'S') y = i,x = j;

	V<V<int>> dist(H,V<int>(W,INTINF));
	dist[y][x] = 0;

	queue<P<int,int>> q;
	q.push({y,x});
	while(q.size()){
		int s = q.front().first;
		int t = q.front().second;
		q.pop();
		int d = dist[s][t];
		if(d == K) continue;

		if(0 < s && A[s-1][t] == '.' && dist[s-1][t] > d){
			dist[s-1][t] = d + 1;
			q.push({s-1,t});
		}
		if(s < H - 1 && A[s+1][t] == '.' && dist[s+1][t] > d){
			dist[s+1][t] = d + 1;
			q.push({s+1,t});
		}
		if(0 < t && A[s][t-1] == '.' && dist[s][t-1] > d){
			dist[s][t-1] = d + 1;
			q.push({s,t-1});
		}
		if(t < W - 1 && A[s][t+1] == '.' && dist[s][t+1] > d){
			dist[s][t+1] = d + 1;
			q.push({s,t+1});
		}
	}
	int ans = INTINF;
	REP(i,H) REP(j,W){
		if(dist[i][j] == INTINF) continue;
		int cnt;
		cnt = i/K + (i%K==0?0:1) + 1;
		chmin(ans,cnt);
		cnt = (W - 1 -j)/K + ((W - 1 -j)%K==0?0:1) + 1;
		chmin(ans,cnt);
		cnt = (H - 1 -i)/K + ((H - 1 -i)%K==0?0:1) + 1;
		chmin(ans,cnt);
		cnt = j/K + (j%K==0?0:1) + 1;
		chmin(ans,cnt);		
	}
	cout << ans << endl;
	return 0;
}

