int dh[] = {1, 0, -1, 0}, dw[] = {0, 1, 0, -1};

void go(int h, int w, int k){
    is_first[h][w] = true;
    if(k == 0){
        return;
    }
    for(int i = 0; i < 4; i++){
        int h_ = h + dh[i];
        int w_ = w + dw[i];
        if((0 <= h_) && (h_ < H) && (0 <= w_) && (w_ < W) && (A[h_][w_] == '.') && (!is_first[h_][w_])){
            go(h_, w_, k - 1);
        }
    }
}

int main(){
    cin >> H >> W >> K;
    for(int h = 0; h < H; h++){
        cin >> A[h];
