    }
    go(S_h, S_w, K);

    int ans = 1000;
    for(int h = 0; h < H; h++){
        for(int w = 0; w < W; w++){
            if(is_first[h][w]){
                int dist = min(h, min(H - 1 - h, min(w, W - 1 - w)));
                ans = min(ans, 1 + (dist + K - 1) / K);
