void update(int x,int y){
    vis[x][y]=1;
    ans=min(ans,y);
    ans=min(ans, m-1-y);
    ans=min(ans, x);
    ans=min(ans,n-1-x);
}

struct Point{
    int x,y,k;
    Point(int tx,int ty,int tk){
        x=tx;
        y=ty;
        k=tk;
    }
};
stack<Point> s;

void dfs(int x,int y,int k){
    //printf("%d %d %d\n",x,y,k);
    s.push(Point(x,y,k));
    while(!s.empty()){
        Point a=s.top();
        s.pop();
        x=a.x;
        y=a.y;
        k=a.k;

        if (k<0 || x<0 || x>=n || y<0 || y>=m || mp[x][y]=='#' || vis[x][y]==1) continue;
        update(x,y);
        s.push(Point(x-1,y,k-1));
        s.push(Point(x+1,y,k-1));
        s.push(Point(x,y-1,k-1));
        s.push(Point(x,y+1,k-1));
    }
}

