int main() {
  cin>>H>>W>>K;
  int startX, startY;
  REP(i,0,H){
    cin>>A[i];
    REP(j,0,W){
      if(A[i][j]=='S'){
        startY = i;
        startX = j;
      }
    }
  }

  int d[810][810];
  REP(i,0,H)REP(j,0,W) d[i][j] = INF;
  queue< pair<int,int> > tq;
  queue< pair<int,int> > q;
  tq.push(make_pair(startY,startX));
  q.push(make_pair(startY,startX));
  d[startY][startX] = 0;

  while(!tq.empty()){
    pair<int,int> nowPos = tq.front();
    tq.pop();
    REP(k,0,4){
      int nextY = nowPos.F + dy[k], nextX = nowPos.S + dx[k];
      if(!CH(nextY,0,H) || !CH(nextX,0,W)) continue;
      if(A[nextY][nextX] == '#' || d[nextY][nextX] != INF) continue;
      d[nextY][nextX] = 0;
      tq.push(make_pair(nextY,nextX));
      q.push(make_pair(nextY,nextX));
    }
  }

  int ans = INF;
  while(!q.empty()){
    pair<int,int> nowPos = q.front();
    q.pop();
    REP(k,0,4){
      int nextY = nowPos.F + dy[k], nextX = nowPos.S + dx[k];
      if(!CH(nextY,0,H) || !CH(nextX,0,W)) continue;
      if(d[nextY][nextX] != INF) continue;

      d[nextY][nextX] = d[nowPos.F][nowPos.S]+1;
      q.push(make_pair(nextY,nextX));

      if(nextY==0||nextY==H-1||nextX==0||nextX==W-1){
        /*
        cout<<(d[nextY][nextX]+(K-1))/K + 1<<endl;
        return 0;
        */
        ans = min(ans, d[nextY][nextX]);
      }
    }
  }

  cout<<(ans+(K-1))/K + 1<<endl;

  return 0;
}

