		return 0;
	}
	ans = INF;
	for (int i = 2; i <= h - 1; i++){
		for (int j = 2; j <= w - 1; j++){
			if (used[i][j]){
				minx = min(i - 1, h - i);
				minx = min(minx, j - 1);
				minx = min(minx, w - j);
				ans = min(ans, (minx + k - 1) / k + 1);
			}
		}
	}
	printf("%d\n", ans);
