int calc(int x, int y)
{
	return max(x / k + (x % k), y / k + (y % k) + (y != 0));
}

void bfs(int x, int y)
{
	queue< pair<int ,int> >  q;
	d[x][y] = {0, 0};
	q.push({x, y});
	while (q.size())
	{
		pair<int, int> t = q.front();
		q.pop();
		x = t.first;
		y = t.second;
		mark[x][y] = true;
		if (isval(x + 1, y) && !mark[x + 1][y])
		{
			int tmp1 = d[x][y].first;
			int tmp2 = d[x][y].second;
			tmp1++;
			if (a[x + 1][y] == '#')
			{
				tmp2++;
			}
			if (calc(tmp1, tmp2) < calc(d[x + 1][y].first, d[x + 1][y].second))
			{
				d[x + 1][y].first = tmp1;
				d[x + 1][y].second = tmp2;
				q.push({x + 1, y});
			}
		}
		if (isval(x - 1, y) && !mark[x - 1][y])
		{
			int tmp1 = d[x][y].first;
			int tmp2 = d[x][y].second;
			tmp1++;
			if (a[x - 1][y] == '#')
