			{
				d[x - 1][y].first = tmp1;
				d[x - 1][y].second = tmp2;
				q.push({x - 1, y});
			}
		}
		if (isval(x, y + 1) && !mark[x][y + 1])
		{
			int tmp1 = d[x][y].first;
			int tmp2 = d[x][y].second;
			tmp1++;
			if (a[x][y + 1] == '#')
			{
				tmp2++;
			}
			if (calc(tmp1, tmp2) < calc(d[x][y + 1].first, d[x][y + 1].second))
			{
				d[x][y + 1].first = tmp1;
				d[x][y + 1].second = tmp2;
				q.push({x, y + 1});

			}
		}
		if (isval(x, y - 1) && !mark[x][y - 1])
		{
			int tmp1 = d[x][y].first;
			int tmp2 = d[x][y].second;
			tmp1++;
			if (a[x][y - 1] == '#')
			{
				tmp2++;
			}
