		}
	}

	std::function<int(int, int)> f = [&] (int i, int j) {
		return std::abs(i - sx) + std::abs(j - sy);
	};

	bool seen[h][w] = {};
	std::queue<std::pair<int, int>> que;
	que.emplace(sx, sy);

	while (not que.empty()) {
		auto [x, y] = que.front(); que.pop();
		if (seen[x][y]) continue;
		seen[x][y] = true;
		for (std::pair<int, int> &p : delta) {
