bool visited[1000][1000];

void dfs(int r, int c, ll nokori){

  if (visited[r][c]){
    return;
  }
  visited[r][c] = 1;

  ll curres;
  if ((r == 0) || (c == 0) || (r == h - 1) || (c == w - 1)){
    curres = 1;
  }
  else {
    curres = min((r + k - 1) / k, min((c + k - 1) / k, min((h - 1 - r + k - 1)/k, (w - 1 - c + k - 1)/k))) + 1;
  }
  res = min(res, curres);
  if (nokori > 0){
    if (r > 0 && a[r-1][c] != '#')
      dfs(r - 1, c, nokori - 1);
    if (r < h - 1 && a[r+1][c] != '#')
      dfs(r + 1, c, nokori - 1);
    if (c > 0 && a[r][c-1] != '#')
      dfs(r, c - 1, nokori - 1);
    if (c < w - 1 && a[r][c+1] != '#')
      dfs(r, c + 1, nokori - 1);
  }

  return;
}

