signed main(){
	int H,W,K;
	cin>>H>>W>>K;
	string s[H];
	REP(i,H)cin>>s[i];
	int sx,sy;
	REP(i,H)REP(j,W)if(s[i][j]=='S'){sx = j,sy = i;}
	queue<pair<pair<int,int>,int>>que;
	vector<vector<int>>visit(H,vector<int>(W,0));
	que.push({{sy,sx},K});
	visit[sy][sx] = true;
	int mi = min({sy,sx,H-sy-1,W-sx-1});
	while(!que.empty()){
		int i = que.front().first.first;
		int j = que.front().first.second;
		int cost = que.front().second;
		que.pop();
		if(cost == 0)continue;
		REP(k,4){
			int ni = i + dx[k];
			int nj = j + dy[k];
			if(!IN(0,ni,H)||!IN(0,nj,W))continue;
			if(s[ni][nj]=='#')continue;
			if(visit[ni][nj])continue;
			visit[ni][nj] = true;
			que.push({{ni,nj},cost-1});
			CHMIN(mi,min({ni,nj,H-ni-1,W-nj-1}));
