signed main() {
	INIT;
	VAR(int, h, w, k);
	MAT(char, a, h, w);
	int sy, sx;
	REP(i, h) REP(j, w) {
		if (a[i][j] == 'S') {
			sy = i; sx = j;
			break;
		}
	}
	int d = INFINT;
	std::vector<std::vector<int>> used(h, std::vector<int>(w, -1));
	used[sy][sx] = k;
	std::queue<PAIR> que;
	que.push(PAIR(sy, sx));
	while (!que.empty()) {
		auto now = que.front(); que.pop();
		int y = now.first, x = now.second;
		CHMIN(d, std::min({ y, h - y - 1, x, w - x - 1 }));
		if (used[y][x] == 0) continue;
		REP(d, 4) {
			int dy = y + dy4[d];
			int dx = x + dx4[d];
			if (!IN(0, dy, h) || !IN(0, dx, w)) continue;
			if (used[dy][dx] != -1) continue;
			if (a[dy][dx] == '#') continue;
			used[dy][dx] = used[y][x] - 1;
			que.push(PAIR(dy, dx));
		}
	}
	if (d == 0) {
		OUT(1)BR;
		return 0;
	}
	OUT((d - 1) / k + 2)BR;
	return 0;
}

