	cin.tie(0); ios::sync_with_stdio(false);

	cin >> h >> w >> k;
	rep(i, 1, h){
		string buf;
		cin >> buf;
		rep(j, 1, w){
			a[i][j] = (buf[j-1] == '#')? -1 : h*w;
			if(buf[j-1] == 'S'){si = i; sj = j;}
		}
	}

	queue<P> q;
	q.push(P(si, sj));
	a[si][sj] = 0;
	//rep(i, 1, h){rep(j, 1, w){cout << a[i][j];}cout << endl;}
