		if(a[si][sj] + 1 < a[si-1][sj] && a[si][sj] + 1 <= k){
			a[si-1][sj] = a[si][sj] + 1;
			q.push(P(si-1, sj));
		}
		if(a[si][sj] + 1 < a[si+1][sj] && a[si][sj] + 1 <= k){
			a[si+1][sj] = a[si][sj] + 1;
			q.push(P(si+1, sj));
		}
		if(a[si][sj] + 1 < a[si][sj-1] && a[si][sj] + 1 <= k){
			a[si][sj-1] = a[si][sj] + 1;
			q.push(P(si, sj-1));
		}
		if(a[si][sj] + 1 < a[si][sj+1] && a[si][sj] + 1 <= k){
			a[si][sj+1] = a[si][sj] + 1;
