				ll ansbuf = 1+min(min((i-1+k-1)/k, (h-i+k-1)/k), min((j-1+k-1)/k, (w-j+k-1)/k));
				ans = min(ansbuf, ans);
			}
		}
	}
	print(ans);
	return 0;
}

#include <iostream>
