  char s[h][w + 10];
  bool flg[h][w];
  ll d[h][w][2];
  for(i = 0; i < h; ++i) for(j = 0; j < w; ++j) d[i][j][0] = d[i][j][1] = 1e9, flg[i][j] = true;
