bool check(info t)
{
    return t.x>=0&&t.x<n&&t.y>=0&&t.y<m&&!vis[t.x][t.y];
}
void init()
{
    CLR(vis,0);
}
int bfs()
{
    priority_queue<info>Q;
    Q.push(S);
    vis[S.x][S.y]=1;
    while (!Q.empty())
    {
        info u=Q.top();
        Q.pop();
        if(u.x==0||u.x==n-1||u.y==0||u.y==m-1)
            return u.step;
        for (int i=0; i<4; ++i)
        {
            info v=u+dir[i];
            if(!check(v))
                continue;
            if(pos[v.x][v.y]=='.')
            {
                ++v.run;
                if(v.run==1)
                    ++v.step;
                else if(v.run>k)
                {
                    v.run=1;
                    v.loc=0;
                    ++v.step;
                }
                Q.push(v);
            }
            else
            {
                ++v.loc;
                pos[v.x][v.y]='.';
                if(v.loc==1)
                {
                    v.run=1;
                    v.loc=1;
                    v.step+=2;
                }
                else if(v.loc>k)
                {
                    v.loc=1;
                    v.run=1;
                    v.step++;
                }
                Q.push(v);
            }
        }
    }
    return 0;
}
