signed main() {

    cin >> H >> W >> K;
    board.resize(H);
    REP(i, H) cin >> board[i];

    dist.assign(H, vector<int>(W, INF));

    int sx, sy;
    REP(i, H) REP(j, W) {
        if (board[i][j] == 'S') {
            sx = i;
            sy = j;
            board[i][j] = '.';
        }
    }

    auto inside = [&](int x, int y) -> bool {
        return 0 <= x and x < H and 0 <= y and y < W;
    };

    // [[x, y], dist]
    queue<pair<pair<int, int>, int>> Q;
    dist[sx][sy] = 0;
    Q.emplace(make_pair(sx, sy), 0);
    while (not Q.empty()) {
        auto [p, d] = Q.front();    Q.pop();
        auto [x, y] = p;
        if (dist[x][y] < d) continue;
        int nd = d + 1;
        REP(k, 4) {
            int nx = x + dx[k];
            int ny = y + dy[k];
            if (not inside(nx, ny)) continue;
            if (board[nx][ny] == '#') continue;
            if (chmin(dist[nx][ny], nd)) {
                Q.emplace(make_pair(nx, ny), nd);
            }
        }
    }

    int res = INF;
    REP(i, H) REP(j, W) {
        // debug(i, j, dist[i][j]);
        if (dist[i][j] > K) continue;
        int d = min({i, H - 1 - i, j, W - 1 - j});
        chmin(res, 1 + (d + K - 1) / K);
    }
    print(res);

}

