    vector<int> dir = {1, 0, -1, 0};
    queue<pair<P, P>> q;
    q.push({s, {0, 0}});
    while(not q.empty()){
        int x = q.front().first.first;
        int y = q.front().first.second;
        P dist = q.front().second;
        q.pop();

        if(dist >= d[x][y]){
            continue;
        }
        /*
        if(dist.first > d[x][y].first){
            continue;
        }
        if(dist.first == d[x][y].first && dist.second > d[x][y].second){
            continue;
        }
        */
        d[x][y] = dist;

        rep(i, 4){
            int nx = x + dir[i];
            int ny = y + dir[i^1];

            if(0 > nx || nx >= h || 0 > ny || ny >= w){
                continue;
            }

            P nd;
            if(not a[nx][ny]){
                nd = {dist.first + 1, dist.second + 1};
            }else{
                nd = {dist.first + 1, dist.second};
            }
            if(nd >= d[nx][ny]){
                continue;
            }

            q.push({{nx, ny}, nd});
        }
    }

    int ans = INF;
    rep(i, h){
        rep(j, w){
            if(i != 0 && i != h - 1 && j != 0 && j != w - 1){
                continue;
            }
            int mv = (d[i][j].first + k - 1) / k;
            int open = (d[i][j].second + k - 1) / k;
            if(mv == open){
                mv++;
            }
            ans = min(ans, mv);
        }
    }
    cout << ans << endl;

    return 0;
}

