  ll H, W, K;
  cin >> H >> W >> K;
  vvl A = VVL(H, W, 0);
  pll start;
  REP(i, H) REP(j, W) {
    char s;
    cin >> s;
    if (s == '#')
      A[i][j] = 1;
    else if (s == 'S')
      start = make_pair(i, j);
  }
  // 次に移動する分の部屋の鍵は開けられるので、扉の制約があるのは1回目だけ！！
  ll ans = llINF;
  queue<pair<ll, pll>> Q;
  Q.push(make_pair(0, start));
  while (!Q.empty()) {
    auto po = Q.front();
    Q.pop();
    ll count = po.first;
    if (po.second.first < 0 || po.second.first >= H || po.second.second < 0 ||
        po.second.second >= W || A[po.second.first][po.second.second] == 1)
      continue;
    ans = min(ans, min(min(po.second.first, po.second.second),
                       min(H - po.second.first, W - po.second.second)));
    if (count < K) {
      Q.push(make_pair(count + 1,
                       make_pair(po.second.first + 1, po.second.second)));
      Q.push(make_pair(count + 1,
                       make_pair(po.second.first - 1, po.second.second)));
      Q.push(make_pair(count + 1,
                       make_pair(po.second.first, po.second.second + 1)));
      Q.push(make_pair(count + 1,
                       make_pair(po.second.first, po.second.second - 1)));
    }
  }
  if (ans == 0)
    cout << 1 << endl;
  else {
    cout << 1 + ceil((long double)ans / K) << endl;
  }
