                vis[vx][vy] = 1;
                qx.push(vx), qy.push(vy), qs.push(us+1);
            }
        }
    }

    if (flag) return puts("1"), 0;

    int ans = 2147483647;   
    for (int i=1;i<=n;i++)
        for (int j=1;j<=m;j++) if (vis[i][j]) {
            int t = min( min(i-1,j-1) , min(n-i,m-j) );
            int cur = (t+k-1) / k;
            ans = min(ans, cur+1);
        }
    cout << ans << endl;
    return 0;
}

