// K,K


pair<int,int> BFS[2][888*888];
bool done[888][888];
int main() {
    int H,W,K;
    cin>>H>>W>>K;

    for(int i=0;i<H;i++)
        cin>>G[i];

    int stx,sty;

    for(int i=0;i<H;i++)
        for(int j=0;j<W;j++)
        {
            done[i][j]=false;
            if (G[i][j]=='S') {
                stx=i;
                sty=j;
            }
        }


    vector<pair<int,int> > all_pts;

    BFS[0][0]=make_pair(stx,sty);
