    done[stx][sty]=true;
    int sz=1;

    for(int iters=0;iters<K;iters++) {
        int nsz=0;

        for(int j=0;j<sz;j++) {
            int cx=BFS[iters&1][j].first;
            int cy=BFS[iters&1][j].second;

            if (InBoundary(cx,cy,H,W)) {
                break;
