}

#include <bits/stdc++.h>
using namespace std;
using pii = pair<int,int>;

int solve() {
    int H, W, K;
    cin >> H >> W >> K;
    vector<string> A(H);
    pii s;
    for ( int h = 0; h < H; h++ ) {
        cin >> A[h];
        for ( int w = 0; w < W; w++ ) {
            if ( A[h][w] == 'S' ) s = pii(h,w);
        }
    }
    auto dist = [&](pii& x) {
        return min({x.first, H-1-x.first, x.second, W-1-x.second});
    };
    vector<int> dh = {0, 1, 0, -1}, dw = {1, 0, -1, 0}, hh = {0, 1, 0, 1};
    queue<pii> q;
    q.push(s);
    int m = dist(s);
    int INF = 1e9;
    vector<vector<int>> dk(H,vector<int>(W, INF));
    dk[s.first][s.second] = 0;
    while ( !q.empty() ) {
        auto p = q.front();
        q.pop();
        for ( int i = 0; i < 4; i++ ) {
            int h = p.first + dh[i];
            int w = p.second + dw[i];
            if ( h < 0 || h >= H || w < 0 || w >= W ) continue;
            if ( A[h][w] == '.' && dk[h][w] > dk[p.first][p.second] + 1 && dk[p.first][p.second] < K ) {
                pii u(h,w);
                q.push(u);
                m = min(m, dist(u));
                dk[h][w] = dk[p.first][p.second] + 1;
            }
        }
    }
    int ans = (m + K - 1)/K + 1;
    return ans;
}

int main() {
    auto ans = solve();
    cout << ans << "\n";
    return 0;
}

