#include <bits/stdc++.h>
using namespace std;

int ceil(int x, int y) {
    if (x % y == 0) return x / y;
    else return x / y + 1;
}

int main()
{
    int H, W, K;
    cin >> H >> W >> K;
    vector<string> bar(H);
    for (int i = 0; i < H; ++ i) {
        cin >> bar[i];
    }
    int sx, sy;
    for (int i = 0; i < H; ++ i) {
        for (int j = 0; j < W; ++ j) {
            if (bar[i][j] == 'S') {
                sx = i;
                sy = j;
            }
        }
    }
    queue<int> qx;
    queue<int> qy;
    auto vis = vector<vector<int>>(H, vector<int>(W, -1));
    int dir[4][2] = {{-1,0}, {0,1}, {1,0}, {0,-1}};
    vis[sx][sy] = 0;
    qx.push(sx); qy.push(sy);
    while (!qx.empty()) {
        int x = qx.front();
        int y = qy.front();
        qx.pop();
        qy.pop();
        int step = vis[x][y] + 1;
        if (step > K) continue;
        for (int i = 0; i < 4; ++ i) {
            int nx = x + dir[i][0];
            int ny = y + dir[i][1];
            if (nx>=0 && nx<H && ny>=0 && ny<W && vis[nx][ny] == -1) {
                vis[nx][ny] = step;
                qx.push(nx);
                qy.push(ny);
            }
        }
    }
    int ans = 1000000;
    for (int x = 0; x < H; ++ x) {
        for (int y = 0; y < W; ++ y) {
            if (vis[x][y] == -1) continue;
            ans = min(ans, ceil(x, K));
            ans = min(ans, ceil((H-1-x), K));
            ans = min(ans, ceil(y, K));
            ans = min(ans, ceil((W-1-y), K));
        }
    }
    cout << ans + 1 << endl;
    return 0;
}

#include <iostream>
#include <queue>
#include <vector>
#include <algorithm>
using namespace std;
#define p pair<int,int>
#define out(tp) (tp.first < 0 || tp.first >= H || tp.second < 0 || tp.second >= W)

int rs[] = {0,0,1,-1};
int cs[] = {-1,1,0,0};

typedef struct node {
    p tp;
    int r, ml, cl;
} node;
typedef node * Node;

class cmp {
    public: bool operator() (Node a, Node b) { return (b->r < a->r || (b->r == a->r && b->cl > a->cl)); }
};

Node newNode(p tp, int r, int ml, int cl) {
    Node tn = (Node) malloc(sizeof(node));
    tn->tp = tp, tn->r = r, tn->ml = ml, tn->cl = cl;
    return tn;
}

int main() {
    int H, W, K, i, r, c;
    int res = 2000000000;
    p tp;
    string m[800];
    cin >> H >> W >> K;
    for (r = 0; r < H; r++) {
        cin >> m[r];
        for (c = 0; c < W; c++) {
            if (m[r][c] == 'S') {
                m[r][c] = '.';
                tp = p(r, c);
            }
        }
    }

    // each state
    // - coord
    // - moves so far
    // - rooms to move left
    // - rooms to clear left
    priority_queue<Node, vector<Node>, cmp> q;
    q.push(newNode(tp, 0, K, K));

    int seen[800][800] = {};
    while (!q.empty()) {
        Node t = q.top(); q.pop();

        //printf("at %d %d, r:%d, ml:%d, cl:%d\n", t->tp.first, t->tp.second, t->r, t->ml, t->cl);
        // If you moved out of bounds, game over
        if (out(t->tp)) {
            res = min(res, t->r+1+(t->cl < K));
            continue;
        }

        if (seen[t->tp.first][t->tp.second]) continue;
        seen[t->tp.first][t->tp.second] = 1;

        // Move
        for (i = 0; i < 4; i++) {
            tp = p(t->tp.first+rs[i], t->tp.second+cs[i]);

            if (out(tp) || m[tp.first][tp.second] == '.') {
                // push a node where you've moved there
                Node nn = newNode(tp, t->r, t->ml-1, t->cl);
                if (nn->ml < 0) {
                    nn->ml += K, nn->cl += K, nn->r++;
                }
                q.push(nn);
            }
            else {
                // push a node where you've destroyed it AND moved there
                Node nn = newNode(tp, t->r, t->ml-1, t->cl-1);
                if (nn->ml < 0 || nn->cl < 0) {
                    nn->ml += K, nn->cl += K, nn->r++;
                }
                q.push(nn);
            }
        }
    }
    cout << res << '\n';
}

