  }
  else {
    curres = min((r + k - 1) / k, min((c + k - 1) / k, min((h - r + k - 1)/k, (w - c + k - 1)/k))) + 1;
  }
  res = min(res, curres);
  if (nokori > 0){
    if (r > 0 && a[r-1][c] != '#')
      dfs(r - 1, c, nokori - 1);
