int n, m, k;
char mp[MAXN][MAXN];
int dist[MAXN][MAXN];
void work(int sx, int sy) {
	int l = 0, r = 0;
	static int qx[MAXN * MAXN], qy[MAXN * MAXN];
	qx[0] = sx, qy[0] = sy;
	memset(dist, -1, sizeof(dist));
	dist[sx][sy] = 0;
	while (l <= r) {
		if (dist[qx[l]][qy[l]] == k) return;
		int tx, ty;
		tx = qx[l] - 1, ty = qy[l];
		if (mp[tx][ty] == '.' && dist[tx][ty] == -1) {
			dist[tx][ty] = dist[qx[l]][qy[l]] + 1;
			qx[++r] = tx;
			qy[r] = ty;
		}
		tx = qx[l] + 1, ty = qy[l];
		if (mp[tx][ty] == '.' && dist[tx][ty] == -1) {
			dist[tx][ty] = dist[qx[l]][qy[l]] + 1;
			qx[++r] = tx;
			qy[r] = ty;
		}
		tx = qx[l], ty = qy[l] - 1;
		if (mp[tx][ty] == '.' && dist[tx][ty] == -1) {
			dist[tx][ty] = dist[qx[l]][qy[l]] + 1;
			qx[++r] = tx;
			qy[r] = ty;
		}
		tx = qx[l], ty = qy[l] + 1;
		if (mp[tx][ty] == '.' && dist[tx][ty] == -1) {
			dist[tx][ty] = dist[qx[l]][qy[l]] + 1;
			qx[++r] = tx;
			qy[r] = ty;
		}
		l++;
	}
}
int main() {
	scanf("%d%d%d", &n, &m, &k);
	for (int i = 1; i <= n; i++)
		scanf("\n%s", mp[i] + 1);
	for (int i = 1; i <= n; i++)
	for (int j = 1; j <= m; j++)
		if (mp[i][j] == 'S') work(i, j);
	int ans = INF;
	for (int i = 1; i <= n; i++)
	for (int j = 1; j <= m; j++) {
		if (dist[i][j] == -1) continue;
		int tmp;
		tmp = i - 1;
		if (tmp == 0) ans = 0;
		else ans = min(ans, (tmp - 1) / k + 1);
		tmp = j - 1;
		if (tmp == 0) ans = 0;
		else ans = min(ans, (tmp - 1) / k + 1);
		tmp = n - i;
		if (tmp == 0) ans = 0;
		else ans = min(ans, (tmp - 1) / k + 1);
		tmp = m - j;
		if (tmp == 0) ans = 0;
		else ans = min(ans, (tmp - 1) / k + 1);
	}
	cout << ans + 1 << endl;
	return 0;
}

