const int INF = 0x3fffffff;
using Pair = pair<int, pii>;
priority_queue<Pair, vector<Pair>, greater<Pair>> que;

bool WithinRange(int y, int x) {
  if (y < 0 || H <= y) return false;
  if (x < 0 || W <= x) return false;
  return true;
}

int main() {
  scanf("%d%d%d", &H, &W, &K);
  fill(mind[0], mind[H], INF);
  rep(i, H) {
    rep(j, W) {
      scanf(" %c", &A[i][j]);
      if (A[i][j] == 'S') {
        st = pii(i, j);
        mind[i][j] = 0;
      }
    }
  }

  que.push(Pair(0, st));

  int ans = INF;
  while (!que.empty()) {
    auto p = que.top(); que.pop();
    int cost = p.first;
    int y, x;
    tie(y, x) = p.second;
    if (mind[y][x] < cost) continue;

    rep(i, 4) {
      int ny = y + dy[i];
