int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int H, W, K;
    cin >> H >> W >> K;
    vector<string> A;
    int diff = 1000000;
    vector<vector<bool>> visited(H, vector<bool>(W, false));

    P start;
    for (int i = 0; i < H; ++i) {
        string s;
        cin >> s;
        A.push_back(s);
        for (int j = 0; j < W; ++j) {
            if (s[j] == 'S') {
                start = {i, j};
                diff = min(min(i, H - 1 - i), min(j, W - 1 - j));
                visited[i][j] = true;
            }
        }
    }
    deque<P> queue;
    queue.push_back(start);

    while (!queue.empty()) {
        P q = queue.front();
        queue.pop_front();
        for (int i = 0; i < 4; ++i) {
            int x = dx[i];
            int y = dy[i];
            int a = q.first;
            int b = q.second;
            if (abs(a - start.first) + abs(b - start.second) > K) {
                continue;
            }
            if ((0 <= a + y && a + y <= H - 1) && 0 <= b + x && b + x <= W - 1) {
                if (visited[a + y][b + x] || A[a + y][b + x] == '#') {
                    continue;
