template<typename T>
void fin(T const& t){ std::cout << t << std::endl; exit(0); }

template<typename T>
std::vector<std::vector<T>> mk2d(size_t s1, size_t s2, T const& val) {
  std::vector<T> tmp(s2, val);
  return std::vector<std::vector<T>>(s1, tmp);
}

int main() {
  std::cin.tie(0); std::ios::sync_with_stdio(false);
  int H, W, K; std::cin >> H >> W >> K;
  auto dist = [&](int h, int w)->int {
    int d = std::min(std::min(h, w), std::min(H-1-h, W-1-w));
    return (d+K-1)/K;
  };
  std::vector<std::string> rooms(H);
  int sH, sW;
  for(int h = 0; h < H; ++h) {
    std::cin >> rooms[h];
    for(int w = 0; w < W; ++w) if(rooms[h][w] == 'S') {
      sH = h;
      sW = w;
    }
  }
  int dh[4] = {0, -1, 0, 1};
  int dw[4] = {-1, 0, 1, 0};
  auto mhp = mk2d<int>(H, W, -100);
  std::queue<std::tuple<int,int,int>> q;
  q.emplace(sH, sW, K);
  int ans = H+W;
  while(!q.empty()) {
    int h, w, hp;
    std::tie(h, w, hp) = q.front(); q.pop();
    if(hp <= mhp[h][w]) continue;
    int cur = dist(h, w);
    ans = std::min(ans, cur);
    if(ans == 0) break;
    mhp[h][w] = hp;
    if(hp == 0) continue;
    for(int i = 0; i < 4; ++i) {
      int nh = h+dh[i], nw = w+dw[i];
      if(rooms[nh][nw]!='.') continue;
      q.emplace(nh, nw, hp-1);
    }
  }
  fin(ans+1);
  return 0;
}

