	dy[] = { 1, -1, 0, 0 };

void Bfs() {
	queue<Node> q;
	q.push((Node){ s, t });
	d[s][t] = 0;
	while (!q.empty()) {
		Node t = q.front(); q.pop();
		for (int i = 0; i < 4; ++i) {
			int xx = t.x + dx[i],
				yy = t.y + dy[i];
			if (xx < 1 || xx > h || yy < 1 || yy > w || d[xx][yy] != 0x3f3f3f3f || r[xx][yy] == '#') continue;
			d[xx][yy] = d[t.x][t.y] + 1;
		}
	}
}

int Calc(int c) {
	return (c + k - 1) / k;
}

int main() {
	scanf("%d%d%d", &h, &w, &k);
	for (int i = 1; i <= h; ++i) {
		scanf("%s", r[i] + 1);
	}
	for (int i = 1; i <= h; ++i) {
		for (int j = 1; j <= w; ++j) {
			if (r[i][j] == 'S') {
				s = i; t = j;
				break;
			}
		}
	}
