        if (grid[x][i]=='#') return true;
    }
    return false;
}

bool lock_v(int u,int d,int y) {
    for (int i=u;i<=d;i++) {
        if (grid[i][y]=='#') return true;
    }
    return false;
}

int foo(int x,int y) {
    if (x==0||x==h-1||y==0||y==w-1) return 0;
    int res=INF;
    int tmp=(x-1)/k+1;
    if (lock_v(x-(((x-1)%k)+1),x-1,y)) tmp++;
    res=min(res,tmp);
    tmp=(h-1-x-1)/k+1;
    int xx=h-1-x;
    if (lock_v(x+1,x+((xx-1)%k)+1,y)) tmp++;
    res=min(res,tmp);
    tmp=(y-1)/k+1;
    if (lock_h(y-(((y-1)%k)+1),y-1,x)) tmp++;
    res=min(res,tmp);
    tmp=(w-1-y-1)/k+1;
    int yy=w-1-y;
    if (lock_v(y+1,y+((yy-1)%k)+1,x)) tmp++;
    res=min(res,tmp);
    return res;
}

