int main() {
  int H, W, K;
  cin >> H >> W >> K;

  vector<string> grid(H);
  int sx, sy;
  rep(i, H) {
    cin >> grid[i];
    rep(j, W) {
      if (grid[i][j] == 'S') {
        sx = i;
        sy = j;
      }
    }
  }

  boost::multi_array<int, 2> dist(boost::extents[H][W]);
  fill(dist.origin(), dist.origin() + H * W, H * W);

  using P = pair<int, int>;
  queue<P> q;

  int lx = H, rx = 0, ly = W, ry = 0;
