int GetCnt(int x, int y)
{
	int d1 = (x - 1) / K;
	int d2 = (y - 1) / K;
	int d3 = ((W - 1) - (x + 1)) / K;
	int d4 = ((H - 1) - (y + 1)) / K;
	return MIN(d1, MIN(d2, MIN(d3, d4))) + 1;
}

