			{
				sx = x;
				sy = y;
			}
		}
	}

	if (sx == 0 || sy == 0 || sx == W - 1 || sy == H - 1)
	{
		cout << 0 << endl;
		return 0;
	}

	int ans = INT_MAX;
	int dx[4] = {1, 0, -1, 0};
	int dy[4] = {0, 1, 0, -1};
	for (int d = 0; d < 4; d++)
	{
