			if (room[x][y] == 1)
			{
				break;
			}
			if (x == 0 || y == 0 || x == W - 1 || y == H - 1)
			{
				cout << ans << endl;
				return 0;
			}
			ans = MIN(ans, GetCnt(x, y));
			x += dx[d];
			y += dy[d];
		}
	}
	cout << ans + 1 << endl;
}

