    int x, y, c, s;
    tie(x, y, c, s) = q.front();
    q.pop();
    if (dp[x][y] != 1e9) continue;
    dp[x][y] = c;
    if (s == 0) {
      c += 1;
      s = k;
    }
    rep(i, 4) {
      int nx = x + dx[i];
      int ny = y + dy[i];
      if (nx < 0 || nx >= h || ny < 0 || ny >= w) continue;
      q.emplace(nx, ny, c, s - 1);
    }
  }
  int ans = 1e9;
  rep(i, h) {
    amin(ans, dp[i][0]);
