/*
一次魔法，走k个没锁的房间，解锁k个房间。
如果周围是.一次魔法直接走过去，然后解锁后面自己想走的方向。
如果周围是#，先需要魔法解锁，然后走过去
因此：走完第一次k，整个棋盘就解锁了。
所以只需要跑一次dfs，看第一次的k步走到哪里是距离边界最近的点。
*/
#include <cstdio>
#include <iostream>
#include <cstring>
#include <string>
#include <queue>
using namespace std;

const int INF=0x7ffffff,N=810;

int ans=INF;
int movee[4][2]= {1,0,-1,0,0,1,0,-1};
bool visited[N][N];
int r,c,k;
int sx,sy;
int a[N][N];
char s[N];
queue<int> q;

void bfs(int x,int y,int step) {
	q.push(x);
	q.push(y);
	q.push(0);
	int cur_ans,cx,cy,cd,xx,yy,dd;
	visited[x][y]=true;
	while (!q.empty()) {
		cx=q.front();
		q.pop();
		cy=q.front();
		q.pop();
		cd=q.front();
		q.pop();
		//cout<<cx<<" "<<cy<<" "<<cd<<endl;
		cur_ans=cx-1;
		cur_ans=min(cur_ans,cy-1);
		cur_ans=min(cur_ans,r-cx);
		cur_ans=min(cur_ans,c-cy);
		ans=min(ans,cur_ans);//看向哪个跑最近
		if (cd==k) continue;//只需要走k步，后面的就想怎么走就怎么走，后面直接计算魔法步数
		for (int i=0; i<4; i++) {
			xx=cx+movee[i][0];
			yy=cy+movee[i][1];
			if (xx<1 || xx>r || yy<1 || yy>c) continue;
			if (a[xx][yy]==1 || visited[xx][yy]) continue;//#不过去
			visited[xx][yy]=true;
			q.push(xx);
			q.push(yy);
			q.push(cd+1);//到.上去 ，最多走k步
		}
	}
}

int main () {
	int i,j;
	scanf("%d%d%d",&r,&c,&k);
	for (i=1; i<=r; i++) {
		scanf("%s",s);
		for (j=1; j<=c; j++) {
			if (s[j-1]=='#') a[i][j]=1;
			if (s[j-1]=='S')
				sx=i,sy=j;
		}
	}
	bfs(sx,sy,0);
	int fans=1+(ans+k-1)/k;
	printf("%d\n",fans);
	return 0;
}

