  std::vector<int> cost1;
  std::vector<int> hosu2;
  std::vector<int> done;
  int mcost;
  void from(int x,int y, int rest_hosu,int cost){
    walk_into(x-1,y,rest_hosu, cost);
    walk_into(x+1,y,rest_hosu, cost);
    walk_into(x,y-1,rest_hosu, cost);
    walk_into(x,y+1,rest_hosu, cost);
  }
  void walk_into(int x, int y, int rest_hosu, int cost){
    if(x<0||y<0||x>=W||y>=H)return;
    if(done[y*W+x])return;
    if(rest_hosu--==0)return;
    if(dan[y*W+x]=='#')cost++;
    if(cost>mcost)return;
    if(cost1[y*W+x]<0||cost1[y*W+x]>cost||hosu2[y*W+x]<rest_hosu){
      cost1[y*W+x]=cost;
      hosu2[y*W+x]=rest_hosu;
      from(x,y,rest_hosu,cost);
    }
  }
  void dbg_print_stat(){
    for(int y=0;y<H;y++){
      for(int x=0;x<W;x++){
        char c = cost1[y*W+x]>=0?'0'+cost1[y*W+x]:dan[y*W+x];
        std::cout<<c;
      }
      std::cout<<std::endl;
    }
    std::cout<<std::endl;
  }
  void run(){
    std::cin>>H>>W>>K;
    dan.resize(H*W,0);
    cost1.resize(H*W,-1);
    hosu2.resize(H*W,-1);
    done.resize(H*W,0);
