    int x0=0,y0=0;
    for(int y=0;y<H;y++){
      std::getline(std::cin,line);
      for(int x=0;x<W;x++){
        char c = line[x];
        if(c=='S'){
          c='.';
          x0=x;y0=y;
        }
        dan[y*W+x]=c;
      }
    }
    mcost=0;
    cost1[y0*W+x0]=0;

    int count=0;
    for(;;){
      count++;
      std::fill(hosu2.begin(), hosu2.end(), -1);
      std::vector<int> cost2=cost1;
      for(int y=1;y<H-1;y++){
