int main(){

    int h, w, k; cin >> h >> w >> k;
    vector<vector<bool> > G(h + 2, vector<bool> (w + 2, false));


    int si, sj;
    for(int i = 1; i <= h; i++){
        for(int j = 1; j <= w; j++){
            char in; cin >> in;
            if(in == '#') continue;

            G[i][j] = true;
            if(in == 'S'){
                si = i;
                sj = j;
            }
        }
    }

    vector<pair<int, int> > ans;
    G[si][sj] = false;
    queue<pair<int, pair<int, int> > > que;
    que.push({k, {si, sj}});
    while(!que.empty()){
        pair<int, pair<int, int> > info = que.front();
        que.pop();
        int i = info.second.first;
        int j = info.second.second;
        ans.push_back({i, j});
        for(int h = 0; h < 4 && info.first > 0; h++){
