	while(!st.empty()){
		p = st.top();
		st.pop();
		int w = p.w;
		int h = p.h;
		A[h][w] = 'T';
		if(a[h][w] == K) continue;
		if(f(w-1, h)){a[h][w-1] = min(a[h][w] + 1, a[h][w-1]); p.w = w-1; p.h = h; st.push(p);}
		if(f(w+1, h)){a[h][w+1] = min(a[h][w] + 1, a[h][w+1]); p.w = w+1; p.h = h; st.push(p);}
		if(f(w, h-1)){a[h-1][w] = min(a[h][w] + 1, a[h-1][w]); p.w = w; p.h = h-1; st.push(p);}
		if(f(w, h+1)){a[h+1][w] = min(a[h][w] + 1, a[h+1][w]); p.w = w; p.h = h+1; st.push(p);}
	}
