template< typename G >
struct DoublingLowestCommonAncestor {
  const int LOG;
  vector< int > dep;
  const G &g;
  vector< vector< int > > table;

  DoublingLowestCommonAncestor(const G &g) : g(g), dep(g.size()), LOG(32 - __builtin_clz(g.size())) {
    table.assign(LOG, vector< int >(g.size(), -1));
  }

  void dfs(int idx, int par, int d) {
    table[0][idx] = par;
    dep[idx] = d;
    for(auto &to : g[idx]) {
      if(to != par) dfs(to, idx, d + 1);
    }
  }

  void build() {
    dfs(0, -1, 0);
    for(int k = 0; k + 1 < LOG; k++) {
      for(int i = 0; i < table[k].size(); i++) {
        if(table[k][i] == -1) table[k + 1][i] = -1;
        else table[k + 1][i] = table[k][table[k][i]];
      }
    }
  }

  int query(int u, int v) {
    if(dep[u] > dep[v]) swap(u, v);
    for(int i = LOG - 1; i >= 0; i--) {
      if(((dep[v] - dep[u]) >> i) & 1) v = table[i][v];
    }
    if(u == v) return u;
    for(int i = LOG - 1; i >= 0; i--) {
      if(table[i][u] != table[i][v]) {
        u = table[i][u];
        v = table[i][v];
      }
    }
    return table[0][u];
  }
};


char A[1000][1000];
ll dist[1000][1000];
ll H,W,K; 

void bfs(ll i,ll j, ll d){
  if(i < 0 || i >= H || j < 0 || j >= W ) return;
  if(dist[i][j] <= K) return;
  if(A[i][j] == '#') return;
  dist[i][j] = d;
  if(d >= K) return;

  bfs(i-1,j, d+1);
  bfs(i+1,j,d+1);
  bfs(i,j-1,d+1);
  bfs(i,j+1,d+1);
  return;
}


int main() {


  cout<<fixed<<setprecision(10);

  cin>>H>>W>>K;

  rep(i,H)rep(j,W) cin>>A[i][j];
  rep(i,H)rep(j,W) dist[i][j] = K+1;

  ll si, sj;
  si = -1;
  sj = -1;
  rep(i,H)rep(j,W){
    if(A[i][j] == 'S'){
      si = i; sj = j;
      break;
    }
  }

  assert(!(si == -1 && sj == -1));

  bfs(si, sj, 0);

  // rep(i,H){
  //   rep(j,W){
  //     cout<<dist[i][j];
  //   }
  //   cout<<endl;
  // }

  ll dmin = H*W;

  repf(i,1,H-1){
    // down
    ll cnt = 0;
    ll j = 0;
    while( (j <= W-1) && (dist[i][j] > K) ){
      cnt++;
      j++;
    }
    chmin(dmin, cnt);

    // up
    cnt = 0;
    j = W-1;
    while( (j >= 0) && (dist[i][j] > K) ){
      cnt++;
      j--;
    }

    chmin(dmin, cnt);
  }

  repf(j,1,W-1){
    // right
    ll cnt = 0;
    ll i = 0;
    while( (i <= H-1) && (dist[i][j] > K) ){
      cnt++;
      i++;
    }
    chmin(dmin, cnt);

    // left
    cnt = 0;
    i = H-1;
    while( (i >= 0) && (dist[i][j] > K) ){
      cnt++;
      i--;
    }

    chmin(dmin, cnt);
  }

  ll ans = 1 + (dmin + K - 1)/K;
  cout<<ans<<endl;
}




