    if (sh!=0&&A[sh-1][sw]=='.'&&!ok[sh-1][sw]) dfs(sh-1,sw,K);
    if (sw!=W-1&&A[sh][sw+1]=='.'&&!ok[sh][sw+1]) dfs(sh,sw+1,K);
    if (sw!=0&&A[sh][sw-1]=='.'&&!ok[sh][sw-1]) dfs(sh,sw-1,K);
  }
}

int main() {
  cin >> H >> W >> K;
  A.resize(H); rep(i,H) cin >> A[i];
  ok.resize(H,vector<bool>(W,false));
  int sh, sw; rep(i,H) rep(j,W) if (A[i][j]=='S') { sh=i; sw=j; }
  dfs(sh,sw,K);
  // rep(i,H) { rep(j,W) cout << ok[i][j]; cout << endl; }
  // cout << sh << " " << sw << endl;

  int d = H+W;
  rep(i,H) rep(j,W) {
    if (ok[i][j]) {
      int dh = min(i,(H-1)-i);
      int dw = min(j,(W-1)-j);
      d = min(d,min(dh,dw));
    }
  }
  int result = (d+K-1)/K + 1;
  cout << result << endl;
  return 0;
}

