    first[sy][sx] = 1;
    deque<pii> que;
    que.emplace_front(sy, sx);
    const int dx[4] = {-1, 1, 0, 0};
    const int dy[4] = {0, 0, -1, 1};

    for (int i = 0; i < k; ++i) {
        auto p = que.back();
        que.pop_back();
        for (int i = 0; i < 4; ++i) {
            int ny = p.first + dy[i];
            int nx = p.second + dx[i];
            if (0 <= ny && ny < h && 0 <= nx && nx < w && a[ny][nx] != '#') {
                que.emplace_front(ny, nx);
                a[ny][nx]     = '#';
