		mi = std::min(mi, (dp[0][i][0] + K - 1) / K);
		mi = std::min(mi, (dp[i][0][0] + K - 1) / K);
		mi = std::min(mi, (dp[h - 1][i][0] + K - 1) / K);
		mi = std::min(mi, (dp[i][w - 1][0] + K - 1) / K);
	}


