const int N=810,Inf=1e9+10;

int n,m,k,sx,sy;
int d[N][N];
bool map[N][N],inq[N][N];

void Init() {
	scanf("%d%d%d",&n,&m,&k);
	for (int i=1;i<=n;++i) {
		for (int j=1;j<=m;++j) {
			char ch=getchar();
			while (ch!='.' && ch!='#' && ch!='S') ch=getchar();
			if (ch=='#') map[i][j]=1;
			if (ch=='S') sx=i,sy=j;
		} 
	} 
} 

std::pair<int,int>que[N*N]; 
void Bfs(int x,int y) {
	int h=0,t=0; que[++t]=std::make_pair(x,y);
	for (int i=1;i<=n;++i) 
		for (int j=1;j<=m;++j) d[i][j]=Inf;
	d[x][y]=0;
	while (h!=t) {
		std::pair<int,int> u=que[++h]; int dnow=d[u.first][u.second];
		if (dnow>k || map[u.first][u.second]) { d[u.first][u.second]=Inf; continue;}
		if (u.first>1 && d[u.first-1][u.second]>dnow+1) { 
			d[u.first-1][u.second]=dnow+1;
			if (!inq[u.first-1][u.second]) que[++t]=std::make_pair(u.first-1,u.second),inq[u.first-1][u.second]=1;
		}
		if (u.first<n && d[u.first+1][u.second]>dnow+1) { 
			d[u.first+1][u.second]=dnow+1;
			if (!inq[u.first+1][u.second]) que[++t]=std::make_pair(u.first+1,u.second),inq[u.first+1][u.second]=1;
		}
		if (u.second>1 && d[u.first][u.second-1]>dnow+1) { 
			d[u.first][u.second-1]=dnow+1;
			if (!inq[u.first][u.second-1]) que[++t]=std::make_pair(u.first,u.second-1),inq[u.first][u.second-1]=1;
		}
		if (u.second<m && d[u.first][u.second+1]>dnow+1) { 
			d[u.first][u.second+1]=dnow+1;
			if (!inq[u.first][u.second+1]) que[++t]=std::make_pair(u.first,u.second+1),inq[u.first][u.second+1]=1;
		}
	} 
}

void Solve() {
	Bfs(sx,sy);
	int dis=max(n,m); 
	for (int i=1;i<=n;++i)
		for (int j=1;j<=m;++j) if (d[i][j]!=Inf) {
			dis=min(dis,min(min(i-1,n-i),min(j-1,m-j)));
		}
	printf("%d\n",(dis+k-1)/k+1);
}

int main() {
	Init();
	Solve(); 
	return 0;
}

