const array<int,4> DI = {{0, -1, 0, 1}}, DJ = {{1, 0, -1, 0}};

#ifdef ONLINE_JUDGE
void solve(ostream& rout)
#else
void solve(outboth rout)
#endif
{

  int M, N, K; cin >> M >> N >> K; if (!cin) return;
  vector<string> A(M); read(A);
  dout << "============================================================" << endl;
  dout << db(K) << endl; for (auto& a : A) dout << a << endl;

  int iStart = -1, jStart = -1;
  Loop(i, M) Loop(j, N) if (A[i][j] == 'S') {
    assert(iStart == -1);
    A[i][j] = '.', iStart = i, jStart = j;
  }

  vector<Vi> dist(M, Vi(N, INT_MAX));
  queue<Pii> q;
  push(q, {iStart, jStart});
  dist[iStart][jStart] = 0;
  while (!q.empty()) {
    int i, j; tie(i, j) = pop(q);
    dout << db(i) << db(j) << endl;
    assert(dist[i][j] < INT_MAX);
    Loop(d, 4) {
      int u = i + DI[d], v = j + DJ[d];
      if (Bounded(u, 0, M-1) && Bounded(v, 0, N-1) && A[u][v] != '#' && dist[u][v] == INT_MAX) {
        dist[u][v] = 1 + dist[i][j];
        push(q, {u, v});
        dout << db(i) << db(j) << db(u) << db(v) << endl;
      }
    }
  }
  int ans = INT_MAX;
  Loop(i, M) Loop(j, N) if (dist[i][j] <= K) {
    int d = min(min(i, M-1-i), min(j, N-1-j));
    umin(ans, 1 + (d + K - 1) / K);
  }

  rout << ans << endl;
}

