            _q.push(mp(cd + 1 , mp(cr + dr[dir] , cc + dc[dir])));
    }
    memset (grid , 0 , sizeof grid);
    memset (vis , false , sizeof vis);
    int sol = 1;
    while (!q.empty()) {
        i3 curr = q.front(); q.pop();
        int cd = curr.fi, cr = curr.se.fi, cc = curr.se.se;
        if (!inside(cr , cc)) continue;
        if (cr == ir || cr == 1 || cc == ic || cc == 1) {
            sol += updiv(cd , k);
            return sol;
        }
        if (vis[cr][cc]) continue;
        vis[cr][cc] = true;
        for (int dir = 0 ; dir < 4 ; dir++)
            q.push(mp(cd + 1 , mp(cr + dr[dir] , cc + dc[dir])));
    }
    return sol;
}

