	q.push(make_pair(sx, sy));
	int d[810][810];
	memset(d, -1, sizeof(d));
	int res = min({ (int)abs((h - 1) - sx), (int)abs((w - 1) - sy),sx,sy });
	while (!q.empty())
	{
		auto p = q.front();
		q.pop();
		if (d[p.first][p.second] == k) continue;
		for (size_t i = 0; i < 4; i++)
