int solve(int H, int W, int K, vs& a) {
    vvi d(H, vi(W));
    for(int i=0,j=H-1; i<=j; ++i,--j){
        int k = (i+K-1)/K;
        rep(c,W) d[i][c] = d[j][c] = k;
    }
    for(int i=0,j=W-1; i<=j; ++i,--j){
        int k = (i+K-1)/K;
        rep(r,H) {
            d[r][i] = min(d[r][i], k);
            d[r][j] = min(d[r][j], k);
        }
    }

    int best = INT_MAX;

    ii start;
    rep(i,H) rep(j,W) {
        if (a[i][j] == 'S') { start=ii(i,j); break; }
    }
    queue<pair<ii,int>> q; // (x,y),d
