    vvi v(H, vi(W, 0));
    while (!q.empty()) {
        ii p = q.front().first; int k = q.front().second;
        int i=p.first, j=p.second;
        q.pop();
        if (v[i][j]) continue;
        if (a[i][j] == '#') continue;
        if (k > K) break;
        v[i][j] = 1; // visited

        best = min(best, 1+d[i][j]);

        if (0 < i) q.push(cons(ii(i-1,j), k+1));
        if (i < H-1) q.push(cons(ii(i+1,j), k+1));
        if (0 < j) q.push(cons(ii(i,j-1), k+1));
        if (j < W-1) q.push(cons(ii(i,j+1), k+1));
    }
    return best;
}

