		if(dp[x][y] == k)
			continue;
		for(int dir = 0; dir < 4; ++dir){
			int xa = x + dx[dir], ya = y + dy[dir];
			if(c[xa][ya] == '.' && dp[xa][ya] > dp[x][y] + 1){
				dp[xa][ya] = dp[x][y] + 1;
				q.push(mp(xa, ya));
			}
		}
	}

	for(int i = 1; i <= n; ++i)
	for(int j = 1; j <= m; ++j){
		if(dp[i][j] <= k){
			ans = min(ans, min(min(f(i - 1), f(j - 1)), min(f(n - i), f(m - j))) + 1);
		}
	}

	cout << ans;

	return 0;
}

#include <bits/stdc++.h>
