void move(long long h, long long w, long long cost){
	if(valid(h, w) == false || A[h][w] == CLOSED || cost > K || A[h][w] < cost){
		return;
	}
	A[h][w] = cost;
	move(h-1, w, cost+1);
	move(h+1, w, cost+1);
	move(h, w-1, cost+1);
	move(h, w+1, cost+1);
}

void firstmove(){
	for(long long h = 0; h < H; h++){
		for(long long w = 0; w < W; w++){
			if(A[h][w] == 0){
				move(h-1, w, A[h][w]+1);
				move(h+1, w, A[h][w]+1);
				move(h, w-1, A[h][w]+1);
				move(h, w+1, A[h][w]+1);
				return;
			}
		}
	}
}


