  c[x][y] = ck;
  if(ck==1) return;
  if(x>0 && vs[x-1][y]!='#' && c[x-1][y] < ck-1) dfs(x-1,y,ck-1);
  if(y>0 && vs[x][y-1]!='#' && c[x][y-1] < ck-1) dfs(x,y-1,ck-1);
  if(x<h-1 && vs[x+1][y]!='#' && c[x+1][y] < ck-1) dfs(x+1,y,ck-1);
  if(y<w-1 && vs[x][y+1]!='#' && c[x][y+1] < ck-1) dfs(x,y+1,ck-1);  
}

