    V<string> grid;
    rep (hh, h) {
        string tmp; CIN(tmp);
        grid.pb(tmp);
    }

    queue<t3> q;

    rep (hh, h) rep (ww, w) {
        if (grid[hh][ww] == 'S') q.push(t3(hh, ww, 0));
    }

    ll diffx[4] = {1, 0, -1, 0};
    ll diffy[4] = {0, 1, 0, -1};

    while (q.size()) {
        auto item = q.front(); q.pop();
        ll hh = get<0>(item);
        ll ww = get<1>(item);
        ll d = get<2>(item);
        if (d >= k) continue;
        rep (di, 4) {
            ll dh = diffx[di];
            ll dw = diffy[di];
            ll hhh = hh + dh;
            ll www = ww + dw;
            if (hhh < 0) continue;
            if (hhh >= h) continue;
            if (www < 0) continue;
            if (www >= w) continue;
            if (grid[hhh][www] != '.') continue;
            grid[hhh][www] = 'S';
            q.push(t3(hhh, www, d+1));
        }
    }

    ll ans = 1e18;
    rep (hh, h) rep (ww, w) {
        if (grid[hh][ww] != 'S') continue;
        ans = min(ans, hh / k + !!(hh % k));
        ans = min(ans, ww / k + !!(ww % k));
        ans = min(ans, (h - hh - 1LL) / k + !!((h - hh - 1LL) % k));
        ans = min(ans, (w - ww - 1LL) / k + !!((w - ww - 1LL) % k));
    }

    cout << ans + 1LL << endl;
}

