void traverse(int x, int y, int rem, int now){
	fille[x][y] = now;
	FOR(i, 0, 4){
		if(x+dr[i] < 0 || x+dr[i] == n || y+dc[i] < 0 || y + dc[i] > m)
			continue;
		if(arr[x+dr[i]][y+dc[i]] == '.' && fille[x+dr[i]][y+dc[i]] == -1){
			if(arr[x][y] == '#')
				traverse(x+dr[i], y+dc[i], k, now+1);
			else if(rem > 0)
				traverse(x+dr[i], y+dc[i], rem-1, now);
			else
				traverse(x+dr[i], y+dc[i], k, now+1);
		}
		else if(arr[x+dr[i]][y+dc[i]] == '#' && fille[x+dr[i]][y+dc[i]] == -1){
			if(arr[x][y] == '.' || arr[x][y] == 'S')
				traverse(x+dr[i], y+dc[i], k, now+2);
			else if(rem > 0)
				traverse(x+dr[i], y+dc[i], rem-1, now);
			else
				traverse(x+dr[i], y+dc[i], k, now+1);
		}
	}
}

