int foo(int x,int y) {
    if (x==0||x==h-1||y==0||y==w-1) return 0;
    int res=INF;

    int tmp=(x-1)/k+1;
    res=min(res,tmp);

    int xx=h-1-x;
    tmp=(xx-1)/k+1;
    res=min(res,tmp);

    tmp=(y-1)/k+1;
    res=min(res,tmp);

    int yy=w-1-y;
    tmp=(yy-1)/k+1;
    res=min(res,tmp);

    return res;
}

int ans=INF;

struct node {
    int x,y,dis;
};

void bfs(int x,int y) {
    queue<node> q;
    q.push({x,y,0});
    vis[x][y]=1;
    ans=min(ans,foo(x,y)+1);
    while (!q.empty()) {
        node cur=q.front();
        q.pop();
        for (int i=-1;i<=1;i++) {
            for (int j=-1;j<=1;j++) {
                if ((i==0&&j==0)||(i!=0&&j!=0)) continue;
                int xx=cur.x+i;
