inline void calc_opening_turn() {
    priority_queue<pair<int, Pii>, vector<pair<int, Pii>>, greater<pair<int, Pii>>> que;
    for(int i=0;i<H;++i){
        for(int j=0;j<W;++j) {
            if(opening_turn[i][j] == 0) {
                que.emplace(0, Pii(i, j));
            }
        }
    }

    int turn;
    Pii p;
    while(!que.empty()) {
        tie(turn, p) = que.top(); que.pop();
        if(opening_turn[p.first][p.second] < turn) continue;
        for(int k=0;k<4;++k) {
            Pii q = {p.first + dyx[k][0], p.second + dyx[k][1]};
            if(q.first < 0 || H <= q.first || q.second < 0 || W <= q.second) continue;
            if(opening_turn[q.first][q.second] > turn + 1) {
                opening_turn[q.first][q.second] = turn + 1;
                que.emplace(turn+1, Pii(q.first, q.second));
            }
        }
    }

    for(int i=0;i<H;++i){
        for(int j=0;j<W;++j) {
            opening_turn[i][j] = (opening_turn[i][j] + K - 1) / K;
        }
    }

}

