int search_s(vector<string>& A){
    for(int i=0; i<A.size(); i++){
        for(int j=0; j<A[i].size(); j++){
            if(A[i][j] == 'S') return i*A[i].size() + j;
        }
    }
    return -1;
}

bool vacant(vector<string>& A, Vvec<int>& d, int x, int y){
    const int H = A.size(), W = A[0].size();
    return (x>=0) && (x<H) && (y>=0) && (y<=W) && (A[x][y]=='.') && (d[x][y] == -1); 
}

Vvec<int> bfs(vector<string>& A, int s){
    const int H = A.size();
    const int W = A[0].size();
    queue<Pii> q;
    q.push(Pii(s, 0));
    Vvec<int> dist(H, vector<int>(W, -1));
    dist[s/W][s%W] = 0;

    const vector<int> dx{-1, 0, 0, 1};
    const vector<int> dy{0, -1, 1, 0};
    while(!q.empty()){
        int i = q.front().first / W;
        int j = q.front().first % W;
        int d = q.front().second;
        q.pop();

        for(int k=0; k<4; k++){
            int x = i+dx[k];
            int y = j+dy[k];
            if(vacant(A, dist, x, y)){
                dist[x][y] = d+1;
                q.push(Pii(x*W+y, d+1));
            }
        }
    }

    return dist;
}

int calc_ans(Vvec<int>& dist, int K){
    const int H = dist.size();
    const int W = dist[0].size();
    int ret = 1e9;

    for(int i=0; i<H; i++){
        for(int j=0; j<W; j++){
            if(dist[i][j]>=0 && dist[i][j]<=K){
                int t = min({i, j, H-1-i, W-1-j});
                ret = (t==0) ? 1 : min(ret, (t-1)/K+2);
            }
        }
    }

    return ret;
}

int main()
{
    int H, W, K;
    cin >> H >> W >> K;
    vector<string> A(H);
    for(auto& s: A) cin >> s;

    int s = search_s(A);
    Vvec<int> dist = bfs(A, s);
    int ans = calc_ans(dist, K);

    cout << ans << endl;
}

