	fill(dp[0], dp[H], INF);

	pii sp;
	REP(i, H) REP(j, W) if (maps[i][j] == 'S') sp = pii(i, j);

	queue<pii> que;
	que.push(sp);
	dp[sp.first][sp.second] = 0;

	int dx[4] = {1,0,-1,0}, dy[4] = {0,1,0,-1};

	while (!que.empty()) {
		int y = que.front().first;
		int x = que.front().second;
		que.pop();

		REP(i, 4) {
			int nx = x + dx[i];
			int ny = y + dy[i];
			if (!(nx >= 0 && nx < W && ny >= 0 && ny < H)) continue;
			if (maps[ny][nx] == '#') continue;

			if (dp[ny][nx] <= dp[y][x]) continue;

			dp[ny][nx] = dp[y][x] + 1;
			que.push(pii(ny, nx));
		}
	}

	dp[sp.first][sp.second] = K;
	REP(i, H) REP(j, W) if (dp[i][j] != INF)
		dp[i][j] = (dp[i][j] + K - 1) / K * K;

	REP(i, H) REP(j, W) if (dp[i][j] != INF)
		que.push(pii(i, j));

	while (!que.empty()) {
		int y = que.front().first;
		int x = que.front().second;
		que.pop();

		REP(i, 4) {
			int nx = x + dx[i];
			int ny = y + dy[i];
			if (!(nx >= 0 && nx < W && ny >= 0 && ny < H)) continue;

			if (dp[ny][nx] <= dp[y][x] + 1) continue;

			dp[ny][nx] = dp[y][x] + 1;
			que.push(pii(ny, nx));
		}
	}

	int ans = INF;

	REP(i, H) {
		chmin(ans, dp[i][0]);
		chmin(ans, dp[i][W - 1]);
	}

	REP(i, W) {
		chmin(ans, dp[0][i]);
		chmin(ans, dp[H - 1][i]);
	}

	cout << (ans + K - 1) / K << endl;

	return 0;
}

