				q.push(make_pair(make_pair(nx, ny), d+1));
				used[nx][ny]=1;
			}
		}
	}
	int ans=2147483647;
	for (int i=1; i<n-1; i++) {
		for (int j=1; j<m-1; j++) {
			if (used[i][j]) {
				ans=min(ans, (min(min(i, j), min(n-i-1, n-j-1))+k-1)/k);
			}
		}
	}
	if (ans+1<1)
		for(;;);
	cout<<ans+1<<endl;
	return 0;
}

