int H, W, K;
int sx, sy;
vector<string> board;

bool inBoard(int x, int y) {
	return x >= 0 && x < W && y >= 0 && y < H;
}

bool isEdge(int x, int y) {
	return x == 0 || x == W - 1 || y == 0 || y == H - 1;
}

class Info {
public:
	int x, y;
	int used;

	Info() {}
	Info(int x, int y, int used) {
		this->x = x;
		this->y = y;
		this->used = used;
	}
};

class Point {
public:
	int x, y;
	Point() {}
	Point(int x, int y) {
		this->x = x;
		this->y = y;
	}
};

int connected() {
	bool visit[810][810];
	memset(visit, false, sizeof(visit));
	queue<Point> q;
	q.push(Point(sx, sy));
	int dist = 0;
	while (!q.empty()) {
		queue<Point> nq;
		while (!q.empty()) {
			Point p = q.front(); q.pop();
			if (isEdge(p.x, p.y)) {
				return dist;
			}
			rep(dir, 4) {
				int nx = p.x + dx[dir];
				int ny = p.y + dy[dir];
				if (!inBoard(nx, ny)) continue;
				if (board[ny][nx] == '#') continue;
				if (visit[ny][nx]) continue;
				visit[ny][nx] = true;
				nq.push(Point(nx, ny));
			}
		}
		dist++;
		q = nq;
	}
	return -1;
}

int memo[810][810];

signed main() {
	cin >> H >> W >> K;

	inputVector(board, H);

	rep(y, H) rep(x, W) {
		if (board[y][x] == 'S') {
			sx = x;
			sy = y;
			break;
		}
	}

	int con = connected();
	if (con != -1 && con <= K) {
		cout << 1 << endl;
		return 0;
	}

	int minDist = min(sx, W - sx);
	minDist = min(sy, minDist);
	minDist = min(H - sy, minDist);
	if (minDist <= K) {
		cout << 2 << endl;
		return 0;
	}

	rep(y, H) rep(x, W) {
		memo[y][x] = -1;
	}

	bool flag = true;
	int cnt = 0;
	queue<Info> q;
	q.push(Info(sx, sy, 0));
	while (flag) {
		cnt++;
		queue<Info> nq;
		while (!q.empty()) {
			Info nowinfo = q.front(); q.pop();
			//cerr << cnt << ":" << "(" << nowinfo.x << ", " << nowinfo.y << ")" << endl;
			if (isEdge(nowinfo.x, nowinfo.y)) {
				cout << cnt - 1 << endl;
				flag = false;
				break;
			}
			queue<Info> tmpq;
			tmpq.push(nowinfo);
			int left = K;
			while (left-- && !tmpq.empty()) {
				queue<Info> ntmpq;
				while (!tmpq.empty()) {
					Info nowinfo2 = tmpq.front(); tmpq.pop();
					rep(dir, 4) {
						int nx = nowinfo2.x + dx[dir];
						int ny = nowinfo2.y + dy[dir];
						if (!inBoard(nx, ny)) continue;
						int used = nowinfo2.used + (board[ny][nx] == '#');
						if (used > (cnt - 1) * K) continue;
						if (used <= memo[ny][nx]) continue;
						memo[ny][nx] = used;
						ntmpq.push(Info(nx, ny, used));
						nq.push(Info(nx, ny, used));
					}
				}
				tmpq = ntmpq;
			}
		}
		if (cnt == 1) {
			nq.push(Info(sx, sy, 0));
		}
		q = nq;
	}

    return 0;
}

