const int N = 800;

int dy[] = {-1,1,0,0};
int dx[] = {0,0,-1,1};
pii st;
int r,c,k;
string M[N + 5];
bool vis[N + 5][N + 5];

bool inRange(int y, int x){
	return y >= 0 && y < r && x >= 0 && x < c;
}

int solve(){
	priority_queue < pair < int, pair < pii , pii > > > q;
	while(!q.empty()) q.pop();
	q.push(MP(0, MP(st, MP(0,0))));
	int y,x,yy,xx,step,move,del;
	while(!q.empty()){
		y = q.top().SE.FI.FI;
		x = q.top().SE.FI.SE;
		step = -q.top().FI;
		move = q.top().SE.SE.FI;
		del = q.top().SE.SE.SE;
		q.pop();
		if(vis[y][x]) continue;
		if(y == 0 || y == r-1 || x == 0 || x == c-1) return step;
		vis[y][x] = true;
		if(move == 0){
			move = k;
			del += k;
			step++;
		}
		FOR(i,4){
			yy = y + dy[i];
			xx = x + dx[i];
			if(inRange(yy,xx) && !vis[yy][xx]){
				if(M[yy][xx] == '#'){
					if(del > k) q.push(MP(-step, MP(MP(yy,xx), MP(move-1,del-1))));
					else q.push(MP(-(step+1), MP(MP(yy,xx), MP(k-1,k+del-1))));
				}
				else{
					q.push(MP(-step, MP(MP(yy,xx), MP(move-1,del))));
				}
			}
		}
	}
	return 0;
}

