                if (s[j] == 'S') {
                    start = {i, j};
                }
            }
        }
    }

    ll dist[801][801];
    for (ll i = 0; i < H; i++) {
        for (ll j = 0; j < W; j++) {
            dist[i][j] = L_INF;
        }
    }

    constexpr Pos step[] = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    using Tup = tuple<ll, ll, ll>;

    queue<Tup> q;
    q.emplace(start.x, start.y, 0);
    dist[start.x][start.y] = 0;
    while (!q.empty()) {
        auto [x, y, d] = q.front();
        q.pop();
        if (d + 1 <= K) {
            for (ll i = 0; i < 4; i++) {
                ll xn = x + step[i].x;
                ll yn = y + step[i].y;
                if (!(xn >= 0 && xn < H && yn >= 0 && yn < W)) continue;
                if (cell[xn][yn] == 1) continue;
                if (dist[xn][yn] != L_INF) continue;
                q.emplace(xn, yn, d + 1);
                dist[xn][yn] = d + 1;
            }
        }
    }

    ll ans = L_INF;
    for (ll i = 0; i < H; i++) {
        for (ll j = 0; j < W; j++) {
            if (dist[i][j] == L_INF) continue;
            ans = min(ans, (i + K - 1) / K + 1);
            ans = min(ans, (H - 1 - i + K - 1) / K + 1);
            ans = min(ans, (j + K - 1) / K + 1);
            ans = min(ans, (W - 1 - j + K - 1) / K + 1);
        }
    }

    cout << ans << "\n";
}

