      ll nx = x + dx[j], ny = y + dy[j];
      P temp = P(a, d+1);
      if (d + 1 > k || (a == 1 && s[nx][ny] == '#')) temp = P(a+1, 1);
      if (used[nx][ny] <= temp) continue;
      used[ny][nx] = temp;
      que.push(Q(temp, P(nx, ny)));
    }
  }
}

