void fill_room(P start, int turn) {
	set<P> poses{ start };
	REP(k, K) {
		set<P> new_poses;
        for (auto& pos: poses) {
            auto w = pos.first;
            auto h = pos.second;
            new_poses.insert(P(w,h));
            REP(d, 4) {
