int dist[810][810] = {0};

int calc_dist(int i, int j, int H, int W){

  return min(min(i, H-1-i), min(j, W-1-j));

}

int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  int H, W, K;
  cin >> H >> W >> K;
  vector<vector<bool>> is_ok(H);
  string s;

  int si, sj;
  for(int i = 0; i < H; i++){
    cin >> s;
    for(int j = 0; j < W; j++){
      if(s[j] == '#'){
        is_ok[i].push_back(false);
      }else if(s[j] == '.'){
        is_ok[i].push_back(true);
      }else{
        is_ok[i].push_back(true);
        si = i;
        sj = j;
      }
    }
  }

  for(int i = 0; i < H; i++){
    for(int j = 0; j < W; j++){
      dist[i][j] = -1;    
    }
  }

  dist[si][sj] = calc_dist(si, sj, H, W);
  int min_dist = dist[si][sj];
  queue<pair<int, int>> q;
  q.push(make_pair(si, sj));

  while(!q.empty()){

    pair<int, int> next = q.front();
    int ci = next.first;
    int cj = next.second;
    q.pop();

    if(ci-1 >= 0  && is_ok[ci-1][cj]){
      if(dist[ci-1][cj] >= 0) continue;
      dist[ci-1][cj] = calc_dist(ci-1, cj, H, W);
      chmin(min_dist, dist[ci-1][cj]);
      q.push(make_pair(ci-1, cj));
    }

    if(ci+1 < H && is_ok[ci+1][cj]){
      if(dist[ci+1][cj] >= 0) continue;
      dist[ci+1][cj] = calc_dist(ci+1, cj, H, W);
      chmin(min_dist, dist[ci+1][cj]);
      q.push(make_pair(ci+1, cj));
    }

    if(cj-1 >= 0  && is_ok[ci][cj-1]){
      if(dist[ci][cj-1] >= 0) continue;
      dist[ci][cj-1] = calc_dist(ci, cj-1, H, W);
      chmin(min_dist, dist[ci][cj-1]);
      q.push(make_pair(ci, cj-1));
    }

    if(cj+1 < W && is_ok[ci][cj+1]){
      if(dist[ci][cj+1] >= 0) continue;
      dist[ci][cj+1] = calc_dist(ci, cj+1, H, W);
      chmin(min_dist, dist[ci][cj+1]);
      q.push(make_pair(ci, cj+1));
    }
  }

  cout << 1 + (min_dist + K - 1) / K << endl; 

  return 0;
}

