const int MAX_N = 8e2 + 10;

int N, M, K; char Mp[MAX_N][MAX_N];
bool Vis[MAX_N][MAX_N];
int main() {
	cin >> N >> M >> K;
	for(int i=0; i<N; i++) scanf("%s", Mp[i]);

	pi st;
	for(int i=0; i<N; i++) for(int j=0; j<M; j++) 
		if(Mp[i][j] == 'S') st = mp(i, j);
	/*
	N = M = 800; K = 1;
	for(int i=0; i<N; i++) for(int j=0; j<M; j++) Mp[i][j] = '#';
	st = mp(N/2, M/2);
	//*/

	int ans = 0; bool finish = false;
	vector<ppi> next; next.push_back(mp(mp(0, 0), st));
	while(1) {
		ans++;

		priority_queue<ppi, vector<ppi>, greater<ppi>> Q;
		for(ppi &e : next) Q.push(e);
		next.clear();
		while(!Q.empty()) {
			ppi val = Q.top(); Q.pop();
			pi temp[2]; tie(temp[0], temp[1]) = val;
			int c, m, x, y; tie(c, m) = temp[0], tie(x, y) = temp[1];
//			printf("ans %d : %d %d %d %d [(%d %d) %d]\n", ans, c, m, x, y, N, M, finish);
			if(x == 0 || y == 0 || x == (N-1) || y == (M-1)) {finish = true; break;}
			if(m == (ans * K)) { next.push_back(val); continue; }
			if(Vis[x][y] == true) continue; Vis[x][y] = true;

			bool needTonext = false;
			for(int k=0; k<4; k++) {
				int nx = x + "1012"[k] - '1', ny = y + "0121"[k] - '1';
				if(nx < 0 || ny < 0 || nx >= N || ny >= M) continue;
				if(Vis[nx][ny]) continue;
				pi ns = mp(nx, ny), nv = mp(c + (Mp[nx][ny] == '#'), m+1);
//				printf("[%d %d (%d %d)]\n", ns.first, ns.second, nv.first, nv.second);
				if(nv.first > ((ans-1) * K)) {
					needTonext = true;
					continue;
				}
				Q.push(mp(nv, ns));
			}
			if(needTonext) {Vis[x][y] = false; next.push_back(val);}
		}
		for(ppi &e : next) e.first.second = ans * K;
//		printf("finish : %d\n", finish);
		if(finish) break;
	}
	printf("%d\n", ans);
	return 0;
}

