			} else if (A[j] == '#') {
				board[i][j] = true;
			}
		}
	}
	auto calc = [H, W](const pair<int, int>& p) {
		int x = min(p.first, abs(p.first - (H - 1)));
		int y = min(p.second, abs(p.second - (W - 1)));
		return min(x, y);
	};
	vector<vector<bool>> done(H, vector<bool>(W));
	typedef tuple<int, pair<int, int>> t;
	priority_queue<t> q;
	int score = calc(S);
	q.emplace(0, S);
	while (!q.empty()) {
		pair<int, int> pos;
		int K1;
		tie(K1, pos) = q.top(); q.pop();
		int tmp = calc(pos);
		if (score > tmp) {
			S = pos;
			score = tmp;
		}
		done[pos.first][pos.second] = true;
		if (pos.first == 0 || pos.first == H - 1 || pos.second == 0 || pos.second == W - 1) {
			break;
		}
		if (K1 == K)
			break;
		static const int dx[4] = { 0, 1, 0, -1 };
		static const int dy[4] = { 1, 0, -1, 0 };
		for (int d = 0; d < 4; d++) {
			auto p2 = pos;
			p2.first += dx[d];
			p2.second += dy[d];
			if (!board[p2.first][p2.second] && !done[p2.first][p2.second]) {
				q.emplace(K1 + 1, p2);
			}
		}
	}
	int ans = 1;
	ans += (calc(S) + K - 1) / K;
	cout << ans << endl;
	return 0;
}

