int main()
{
    ll H, W, K;
    cin >> H >> W >> K;
    vector<string> grid = getGrid(H, W);
    P start;
    rep(i, H) rep(j, W) if (grid[i][j] == 'S') start = {i, j};

    queue<pair<P, int>> que;
    que.push({start, 0});

    ll dx[4] = {1, 0, -1, 0};
    ll dy[4] = {0, 1, 0, -1};
    ll nowx = start.first, nowy = start.second;

    ll ans = min({devc(nowx, K), devc(nowy, K), devc(H - 1 - nowx, K), devc(W - 1 - nowy, K)}) + 1;

    vec2 visited(H, vec(W, 0));

    while(!que.empty()){
        pair<P, int> now = que.front();
        que.pop();
        visited[now.first.first][now.first.second] = 1;

        if(now.second == K){
            ll x = now.first.first, y = now.first.second;
            ll magic = min({devc(x, K), devc(y, K), devc(H - 1 - x, K), devc(W - 1 - y, K)}) + 1;
            chmin(ans, magic);
            continue;
        } 

        rep(i, 4){
            P next = {now.first.first + dx[i], now.first.second + dy[i]};
            ll x = next.first, y = next.second;
            if(grid[x][y] == '#') continue;
            if(visited[x][y]) continue;
            if(x <= 0 or y <= 0 or x >= H - 1 or y >= W - 1) drop(1);
            que.push({next, now.second + 1});
        }
    }

    print(ans);

    return 0;
}

