int h, w, k;
char g[1010][1010];
int d[1010][1010];

const int INF = 1e9;
using pii = pair<int, int>;

void bfs(int si, int sj) {
    auto is_valid = [&](int i, int j) {
        if (i < 0 || i >= h || j < 0 || j >= w) return false;
        if (g[i][j] == '#') return false;
        return true;
    };

    auto get_next = [&](int ci, int cj) {
        static const pii dir[] = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
        vector<pii> res;
        for (auto &d : dir) {
            int ni = ci + d.first;
            int nj = cj + d.second;
            if (is_valid(ni, nj)) res.emplace_back(ni, nj);
        }
        return res;
    };

    queue<pii> q;
    rep(i, h) rep(j, w) d[i][j] = INF;
    d[si][sj] = 0;
    q.emplace(si, sj);
    while (q.size()) {
        int ci, cj;
        tie(ci, cj) = q.front();
        q.pop();
        const vector<pii> next = get_next(ci, cj);
        for (auto &nx : next) {
            int ni, nj;
            tie(ni, nj) = nx;
            int nd = d[ci][cj] + 1;
            if (d[ni][nj] > nd) {
                d[ni][nj] = nd;
                q.emplace(ni, nj);
            }
        }
    }
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(0);
    while (cin >> h >> w >> k) {
        rep(i, h) cin >> g[i];
        int si = -1, sj = -1;
        rep(i, h) rep(j, w) if (g[i][j] == 'S') {
            si = i, sj = j;
        }
        bfs(si, sj);
        int ans = INF;
        rep(i, h) rep(j, w) {
            if (d[i][j] <= k) {
                int cd = INF;
                cd = min(cd, i);
                cd = min(cd, w - j - 1);
                cd = min(cd, j);
                cd = min(cd, h - i - 1);
                ans = min(ans, (cd + k - 1) / k);
            }
        }
        cout << ans + 1 << endl;
    }
}

