int dist[1005][1005];

int bfs(int x,int y){
	queue<node> q;
	q.push({x,y});
	dist[x][y]=0;

	while(!q.empty()){
		node temp=q.front(); q.pop();
		int tempx=temp.x;
		int tempy=temp.y;
		for(int i=0;i<4;i++){
			int tx=tempx+xx[i];
			int ty=tempy+yy[i];

			if(tx<0||tx>n||ty<0||ty>m||input[tx][ty]=='#') continue;

			else if(dist[tempx][tempy]+1<dist[tx][ty]){
				q.push({tx,ty}); 
				dist[tx][ty]=dist[tempx][tempy]+1;
			}
		}
	}

	int ans=INF;
	for(int i=0;i<n;i++){
		for(int j=0;j<m;j++){
			if(dist[i][j]!=INF&&dist[i][j]<=k){
				ans=min(ans,min(i,min(n-i-1,min(j,m-j-1))));
			}
		}
	}

	if(ans%k!=0) ans/=k,ans++;
	else ans/=k;
	ans++;
	return ans;
}

