    ll start_y = -1;
    rep (i, h) rep (j, w) if (grid[i][j] == 'S') {
        start_x = i;
        start_y = j;
        break;
    }

    queue<t3> q;
    S bool checked[803][803];
    memset(checked, 0, sizeof(checked));

    q.push(t3(start_x, start_y, 0LL));
    checked[start_x][start_y] = true;

    while (!q.empty()) {
        auto item = q.front(); q.pop();
        ll x = get<0>(item);
        ll y = get<1>(item);
        ll walked = get<2>(item);

        if (walked == k) continue;
        walked++;

        if (x > 0 && !checked[x-1][y] && grid[x-1][y] == '.') {
            q.push(t3(x-1, y, walked));
            checked[x-1][y] = true;
        }
        if (x < h-1 && !checked[x+1][y] && grid[x+1][y] == '.') {
            q.push(t3(x+1, y, walked));
            checked[x+1][y] = true;
        }
        if (y > 0 && !checked[x][y-1] && grid[x][y-1] == '.') {
            q.push(t3(x, y-1, walked));
            checked[x][y-1] = true;
        }
        if (y < w-1 && !checked[x][y+1] && grid[x][y+1] == '.') {
            q.push(t3(x, y+1, walked));
            checked[x][y+1] = true;
        }
    }

    ll ans = 1e18;

    rep (x, h) {
        rep (y, w) {
            if (!checked[x][y]) continue;
            ll distance = 1e18;
            distance = min(distance, x);
            distance = min(distance, h-1-x);
            distance = min(distance, y);
            distance = min(distance, w-1-y);
            ll magic_cnt = ((distance % k) ? (distance / k + 1LL) : (distance / k));
            magic_cnt++;
            debug_printf("x=%lld y=%lld distance=%lld magic_cnt=%lld\n",
                         x, y, distance, magic_cnt);
            ans = min(ans, magic_cnt);
        }
    }

    cout << ans << endl;
}

