using namespace std;

struct TPoint {int x, y;};

const int dx[4] = {0, 0, 1, -1};
const int dy[4] = {1, -1, 0, 0};

const int N = 805;
const int INF = 1e9;

int n, m, k, d[N][N];
char a[N][N];

bool Valid(int x, int y) {return 1 <= x && x <= n && 1 <= y && y <= m;}
bool HasExit(int x, int y) {return x == 1 || x == n || y == 1 || y == m;}

void Solve()
{
    TPoint s;
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= m; ++j)
            if (a[i][j] == 'S') s = {i, j};

    for (int i = 1; i <= n; ++i) fill(d[i]+1, d[i]+1+m, -1);

    int res = INF;
    queue<TPoint> q;
    q.push(s);
    d[s.x][s.y] = 0;
    while (!q.empty())
    {
        TPoint u = q.front(); q.pop();
        if (d[u.x][u.y] <= k)
        {
            if (HasExit(u.x, u.y)) res = 1;
            else res = min(res, (min(min(u.x - 1, n - u.x), min(u.y - 1, m - u.y)) - 1) / k + 2);
        }
        else continue;
        for (int dir = 0; dir < 4; ++dir)
        {
            TPoint v {u.x + dx[dir], u.y + dy[dir]};
            if (Valid(v.x, v.y) && a[v.x][v.y] != '#' && d[v.x][v.y] == -1) q.push(v), d[v.x][v.y] = d[u.x][u.y] + 1;
        }
    }
    printf("%d",res);
}

int main()
{
    scanf("%d%d%d",&n,&m,&k);
    for (int i = 1; i <= n; ++i) scanf("%s",a[i]+1);
    Solve();
    return 0;
}

