int dx[] = {1,-1,0,0};
int dy[] = {0,0,1,-1};

bool check(int x, int y){
  return 0 <= x && x < W && 0 <= y && y < H;
}

int main(void){
  string str[1024];

  cin >> H >> W >> K;
  rep(i,H)cin >> str[i];

  rep(i,H)rep(j,W)
    if(str[i][j] == 'S'){
      q.push(MP(j,i));
