    int si = mv.size();
    rep(j,si){
      PII pos = mv.front();mv.pop();
      if(memo[pos.Y][pos.X] == 1)continue;
      memo[pos.Y][pos.X] = 1;
      rep(k,4){
        int nx = pos.X + dx[k];
        int ny = pos.Y + dy[k];
        if(!check(nx, ny))continue;
        if(str[ny][nx] == '#') continue;
        mv.push(MP(nx, ny));
        q.push(MP(nx,ny));
      }
    }
