    resY = (H-1-t.Y)%K;
    if(resX>0)resX = 1;
    if(resY>0)resY = 1;

    ans = min(ans, (W-1-t.X)/K + resX + 1);
    ans = min(ans, (H-1-t.Y)/K + resY + 1);
  }

  cout << ans << endl;
  return 0;
}

