{
	n=read();m=read();K=read();
	for(int i=1;i<=n;++i)scanf("%s",g[i]+1);
	for(int i=1;i<=n;++i)
		for(int j=1;j<=m;++j)
			if(g[i][j]=='S')sx=i,sy=j;
	BFS(sx,sy);
	printf("%d\n",ans+1);
	return 0;
}

