void solve() {
  int n, m, k;
  cin >> n >> m >> k;
  vector<vector<char> > a(n + 2, vector<char>(m + 2, '#'));

  int si(0), sj(0);

  for (int i = 1; i <= n; ++i) {
    for (int j = 1; j <= m; ++j) {
      cin >> a[i][j];
      if (a[i][j] == 'S') {
        si = i;
        sj = j;
      }
    }
  }

  vector<vector<int> >dist(n + 2, vector<int> (m + 2, inf));

  queue<pii> f;
  f.push(make_pair(si, sj));
  dist[si][sj] = 0;
  while (!f.empty()) {
    pii v = f.front();
