    vector<vb> grid (H, vb (W));

    int sx, sy;
    F0R(i, H) {
        F0R(j, W) {
            char c; cin >> c;
            grid[i][j] = (c == '#');
            if (c == 'S') {sx = j; sy = i;}
        }
    }
    vector<vector<piii>> dist (H, vector<piii> (W, {H*W+2, 0, 0}));
    dist[sy][sx] = {0, 0, 0};
    priority_queue<pair<piii, pii>, vector<pair<piii, pii>>, greater<pair<piii, pii>>> q;
    q.push({{dist[sy][sx]}, {sx, sy}});
    while (!q.empty()) {
        piii d = q.top().first;
        pii pos = q.top().second;
        q.pop();

        int px, py; tie(px, py) = pos;
