bool solve() {
    int h, w, k; cin >> h >> w >> k;
    string bd[h];
    rep (i, h) cin >> bd[i];
    int sx = 0, sy = 0;
    rep (i, h) {
        rep (j, w) {
            if (bd[i][j] == 'S') sx = i, sy = j;
        }
    }
    queue<int> X, Y; X.push(sx), Y.push(sy);
    vector<vector<int>> cst(h, vector(w, INF));
    cst[sx][sy] = 0;
    while (X.size()) {
        int x = X.front(); y = Y.front(); X.pop(), Y.pop();
        rep (i, 4) {
            int nx = x + dx[i], ny = y + dy[i];
            if (cst[nx][ny] > cst[x][y] + 1) {
                cst[nx][ny] = cst[x][y] + 1;
                X.push(nx), Y.push(ny);
            }
        }
    }
    int ans = INF;
    rep (i, h) {
        rep (j, w) {
            if (cst[i][j] > k) continue;
            int add = min({i, h-i-1, j, w-j-1});
            chmin(ans, (cst[i][j] + add - 1) / k + 1);
        }
    }
    cout << ans << endl;
}

signed main() {
    cin.tie(0);
