  ios::sync_with_stdio(false);
  int H, W, K;
  cin >> H >> W >> K;
  vector<string> A(H);
  rep(i, H) cin >> A[i];
  G = vector<vector<edge>>(H*W);
  int dx[] = {0, -1, 0, 1};
  int dy[] = {-1, 0, 1, 0};
  int s = -1;
  rep(i, H) rep(j, W) {
    if(A[i][j] == 'S') s = i*W+j;
    rep(k, 4) {
      int nx = i+dx[k];
      int ny = j+dy[k];
      if(nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
      G[i*W+j].push_back({nx*W+ny, (A[nx][ny] == '#')});
    }
  }
  bellman_ford(H*W, s);

  auto bsearch = [&]() {
    auto test = [&](int k) {
      rep(i, H) if(dist[i*W] <= K*(k-1) || dist[i*W+W-1] <= K*(k-1)) return true;
      rep(j, W) if(dist[j] <= K*(k-1) || dist[(H-1)*W+j] <= K*(k-1)) return true;
      return false;
    };
    ll ok = H*W+1, ng = -1;
    while(ok-ng>1) {
      ll mid = (ok+ng)/2;
      (test(mid) ? ok : ng) = mid;
    }
    return ok;
  };
