const ll INF = 1ll<<29;
const ll MOD = 1000000007;
const double EPS  = 1e-10;

int H, W, K;
int dp[801][801];
string maps[800];

int main() {
	cin >> H >> W >> K;
	REP(i, H) cin >> maps[i];

	fill(dp[0], dp[H], INF);

	pii sp;
	REP(i, H) REP(j, W) if (maps[i][j] == 'S') sp = pii(i, j);

	priority_queue<P> pq;
	pq.push(P(0, sp));

	int dx[4] = {1,0,-1,0}, dy[4] = {0,1,0,-1};

	while (!pq.empty()) {
		P now = pq.top(); pq.pop();

		int y = now.second.first;
		int x = now.second.second;

		int d = now.first;

		if (!chmin(dp[y][x], d)) continue;

		REP(i, 4) {
			int nx = x + dx[i];
			int ny = y + dy[i];
			if (!(nx >= 0 && nx < W && ny >= 0 && ny < H)) continue;
			if (maps[ny][nx] == '#') continue;
			pq.push(P(d, pii(ny, nx)));
		}
	}

	REP(i, H) REP(j, W) if (dp[i][j] == 0) {
		pq.push(P(dp[i][j], pii(i, j)));
		dp[i][j] = INF;
	}

	int ans = INF;

	while (!pq.empty()) {
		P now = pq.top(); pq.pop();

		int y = now.second.first;
		int x = now.second.second;

		int d = now.first;

		if (!chmin(dp[y][x], d)) continue;

		REP(i, 4) {
			int nx = x + dx[i];
			int ny = y + dy[i];
			if (!(nx >= 0 && nx < W && ny >= 0 && ny < H)) continue;
			pq.push(P(d + 1, pii(ny, nx)));
		}
	}

	REP(i, H) {
		chmin(ans, dp[i][0]);
		chmin(ans, dp[i][W - 1]);
	}

	REP(i, W) {
		chmin(ans, dp[0][i]);
		chmin(ans, dp[H - 1][i]);
	}

	cout << (ans + K - 1) / K + 1 << endl;

	return 0;
}

