template <typename T, typename U>
class IntervalSegTree : public SegTree<T, U> {
protected:
    using SegTree<T, U>::n;
    using SegTree<T, U>::rank;
    using SegTree<T, U>::node;
    using SegTree<T, U>::nodef;
    using SegTree<T, U>::nodee;
    std::vector<U> lazy;
    std::vector<bool> lazyflag;
    std::vector<int> width;
    virtual void lazyf(U &, const U &) = 0;
    virtual void updf(T &, const U &, const unsigned int &) = 0;
    void eval(int k) {
        for (int i = rank; i > 0; i--) {
            int nk = k >> i;
            if (lazyflag[nk]) {
                updf(node[2 * nk], lazy[nk], width[2 * nk]);
                updf(node[2 * nk + 1], lazy[nk], width[2 * nk + 1]);
                if (lazyflag[2 * nk])
                    lazyf(lazy[2 * nk], lazy[nk]);
                else
                    lazy[2 * nk] = lazy[nk];
                if (lazyflag[2 * nk + 1])
                    lazyf(lazy[2 * nk + 1], lazy[nk]);
                else
                    lazy[2 * nk + 1] = lazy[nk];
                lazyflag[2 * nk] = lazyflag[2 * nk + 1] = true;
                lazyflag[nk] = false;
            }
        }
    }

public:
    IntervalSegTree(unsigned int m, T init, T nodee) : SegTree<T, U>(m, init, nodee) {
        lazy.resize(2 * n);
        lazyflag.resize(2 * n);
        width.resize(2 * n);
        width[1] = n;
        for (unsigned int i = 2; i < 2 * n; i++) {
            width[i] = width[i >> 1] >> 1;
        }
    }
    IntervalSegTree(T nodee, const std::vector<T> &initvec) : SegTree<T, U>(initvec, nodee) {
        lazy.resize(2 * n);
        lazyflag.resize(2 * n);
        width.resize(2 * n);
        width[1] = n;
        for (unsigned int i = 2; i < 2 * n; i++) {
            width[i] = width[i >> 1] >> 1;
        }
    }
    void update(int i, U x) {
        i += n;
        eval(i);
        updf(node[i], x, width[i]);
        if (lazyflag[i])
            lazyf(lazy[i], x);
        else {
            lazyflag[i] = true;
            lazy[i] = x;
        }
        while (i /= 2)
            node[i] = nodef(node[2 * i], node[2 * i + 1]);
    }
    void update(int l, int r, U x) {
        l += n;
        r += n;
        int nl = l, nr = r;
        while (!(nl & 1))
            nl >>= 1;
        while (!(nr & 1))
            nr >>= 1;
        nr--;
        eval(nl);
        eval(nr);
        while (l < r) {
            if (l & 1) {
                updf(node[l], x, width[l]);
                if (lazyflag[l])
                    lazyf(lazy[l], x);
                else {
                    lazyflag[l] = true;
                    lazy[l] = x;
                }
                l++;
            }
            if (r & 1) {
                r--;
                updf(node[r], x, width[r]);
                if (lazyflag[r])
                    lazyf(lazy[r], x);
                else {
                    lazyflag[r] = true;
                    lazy[r] = x;
                }
            }
            l >>= 1;
            r >>= 1;
        }
        while (nl >>= 1)
            node[nl] = nodef(node[2 * nl], node[2 * nl + 1]);
        while (nr >>= 1)
            node[nr] = nodef(node[2 * nr], node[2 * nr + 1]);
    }
    T query(int l, int r) {
        l += n;
        r += n;
        eval(l);
        eval(r - 1);
        int ls = nodee, rs = nodee;
        while (l < r) {
            if (l & 1) {
                ls = nodef(ls, node[l]);
                l++;
            }
            if (r & 1) {
                r--;
                rs = nodef(node[r], rs);
            }
            l >>= 1;
            r >>= 1;
        }
        return nodef(ls, rs);
    }
    T operator[](const int &x) {
        eval(n + x);
        return node[n + x];
    }
    T queryForAll() {
        return node[1];
    }
};
