    RUQRMaQ(const std::vector<int> &initvec) : IntervalSegTree<int, int>(-inf, initvec) {
        for (int i = n - 1; i > 0; i--)
            node[i] = nodef(node[2 * i], node[2 * i + 1]);
    }
};

