int bfs(int X, int Y, int n) {
	queue<P>que;
	REP(i, 1000) {
		REP(j, 1000) {
			dist[i][j] = INF;
		}
	}
	int res= min({ X,H - X - 1,Y,W - Y - 1 });
	que.push({ X,Y });
	dist[X][Y] = 0;
