      if(dp[newx][newy] <= dp[x][y] + (used == k - 1)) continue;
      dp[newx][newy] = dp[x][y] + (used == k - 1);
      q.push(lol(newx, newy, (used + 1) % k));
    }
  }

  for(i = 0; i < n; ++i) rs = min({rs, dp[i][0], dp[i][m - 1]});
  for(i = 0; i < m; ++i) rs = min({rs, dp[0][i], dp[n - 1][i]});

  for(i = 0; i < n && 0; ++i)
    for(j = 0; j < m; ++j)
      cout << dp[i][j] << " \n"[j == m - 1];

  cout << rs << '\n';

  return 0;
}

