template<class T>bool chmax(T &a, const T &b) { if (a<b) { a=b; return 1; } return 0; }
template<class T>bool chmin(T &a, const T &b) { if (b<a) { a=b; return 1; } return 0; }
const ll MOD = 1e9+7;

bool X[810][810];
pair<ll, ll> isvisit[810][810];
ll H, W, K;

typedef queue<pair<ll, ll>> Q;

bool dfs(Q& que, ll y, ll x, int num, int move){
    if(y >= H) return false;
    if(x >= W) return false;
    if(y < 0) return false;
    if(x < 0) return false;

    if(!X[y][x]) {
        if(num > 0)
            num--;
        else{
            que.push(mp(y, x));
            return false;
        }
    }

    //if(isvisit[y][x] >= num) return false;
    auto p = isvisit[y][x];
    if(p.first >= num && p.second >= move) return false;

    //isvisit[y][x] = num;
    isvisit[y][x] = mp(num, move);
    if(y == 0) return true;
    if(x == 0) return true;
    if(y == H-1) return true;
    if(x == W-1) return true;

    bool ret = false;
    chmax(ret, dfs(que, y+1, x, num, move-1));
    chmax(ret, dfs(que, y-1, x, num, move-1));
    chmax(ret, dfs(que, y, x+1, num, move-1));
    chmax(ret, dfs(que, y, x-1, num, move-1));

    return ret;
}

ll solve(pair<ll, ll> s){
    // (y, x, num)

    REP(i,H){
        REP(j,W){
            isvisit[i][j] = mp(-1, -1);
        }
    }
    Q tmp;
    if(dfs(tmp, s.first, s.second, 0, K))
        return 1;

    REP(i,H){
        REP(j,W){
            isvisit[i][j] = mp(-1, -1);
        }
    }
    Q que[2];
    int num = 1;
    que[0].push(s);
    int idx = 0;
    while(1){
        num++;
        while(!que[idx%2].empty()){
            auto p = que[idx%2].front();
            que[idx%2].pop();
            bool end = dfs(que[(idx+1)%2], p.first, p.second, K, K);
            if(end) return num;
        }
        idx++;
    }
}

int main(){
    cin >> H >> W >> K;

    pair<ll, ll> S;
    REP(i,H){
        REP(j,W){
            char c;
            cin >> c;
            if(c == 'S'){
                S = mp(i, j);
                X[i][j] = true;
            }
            else if(c == '.')
                X[i][j] = true;
        }
    }

    ll ans = solve(S);
    cout << ans << endl;
    return 0;
}

