bool bfs(){
	int x, y, d;
	while (!q.empty()){
		x = q.front().x; y = q.front().y; d = q.front().d; q.pop();
		if (x == 1 || x == h || y == 1 || y == w) return true;
		if (d == k) continue;
		if (x > 1 && !used[x - 1][y] && s[x - 1][y] == '.'){
			q.push((Node){x - 1, y, d + 1});
			used[x - 1][y] = 1;
		}
		if (x < h && !used[x + 1][y] && s[x + 1][y] == '.'){
			q.push((Node){x + 1, y, d + 1});
			used[x + 1][y] = 1;
		}
		if (y > 1 && !used[x][y - 1] && s[x][y - 1] == '.'){
			q.push((Node){x, y - 1, d + 1});
			used[x][y - 1] = 1;
		}
		if (y < w && !used[x][y + 1] && s[x][y + 1] == '.'){
			q.push((Node){x, y + 1, d + 1});
			used[x][y + 1] = 1;
		}
	}
	return false;
}

