const int dx[8] = { +1,+0,-1,+0,+1,+1,-1,-1 };
const int dy[8] = { +0,-1,+0,+1,-1,+1,-1,+1 };
const int mod = 1e9 + 7;
const int INF = 1e9;

typedef tuple<int,int,int,int> F;
int vis[801][801];

signed main() {

	int h, w, k;
	cin >> h >> w >> k;

	int sy, sx;

	vector<string> s(h);
	rep(y, h){
		cin >> s[y];
		rep(x, w){
			if(s[y][x] == 'S'){
				sy = y;sx = x;
			}
		}
	}


	auto ok = [&](int m){
		vector<string> t = s;
		clr(vis);

		priority_queue<F, vector<F>, greater<F>> q;
		q.push(F(0, 0, sy, sx));
		rep(i, w)rep(j, h){
			vis[j][i] = INF;
		}
		vis[sy][sx] = 0;

		while(q.size()){
			auto now = q.top();
			q.pop();

			int mv = get<0>(now);
			int us = get<1>(now);
			int y = get<2>(now);
			int x = get<3>(now);

			if(mv > m * k)continue;
			if(mv && mv % k == 0) us += k;
			if(x == 0 || y == 0 || x == w - 1 || y == h - 1){
				return true;
			}

			rep(i, 4){
				int tx = x + dx[i], ty = y + dy[i];
				if(check(tx, ty, w, h) && vis[ty][tx] > mv + 1){
					if(s[ty][tx] == '#'){
						if(us){
							q.push(F(mv + 1, us - 1, ty, tx));
						}else continue;
					}else{
						q.push(F(mv + 1, us, ty, tx));
					}
					vis[ty][tx] = mv + 1;
				}
			}

			bool ok = false;
			rep(i, 4){
				int tx = x + dx[i], ty = y + dy[i];
				if(check(tx, ty, w, h) && vis[ty][tx] == INF){
					ok = true;
				}
			}
			if(ok){
				q.push(F((mv / k + 1) * k, us, y, x));
			}

		}

		return false;
	};

	int l = 0, r = INF;
	rep(i, 100) {
		int m = (r + l) / 2.0;
		if (ok(m)) {
			r = m;
		}
		else {
			l = m;
		}
	}

	cout << r << endl;

	return 0;
}

