template<class T> inline bool chmax(T& a, T b) { if (a < b) { a = b; return true; } return false; }
template<class T> inline bool chmin(T& a, T b) { if (a > b) { a = b; return true; } return false; }

void Main(){
    int H,W,K;
    cin >> H >> W >> K;
    char a[H][W]; REP(i,H)REP(j,W) cin >> a[i][j];

    int sx, sy;
    REP(i,H)REP(j,W) if(a[i][j] == 'S'){sx=i; sy=j;}

    int d[H][W]; REP(i,H)REP(j,W) d[i][j] = INF;

    vector<P> v{P(1,0),P(-1,0),P(0,1),P(0,-1)};
    int ans = INF;
    queue<tpl> q; q.emplace(sx,sy,0);
    while(!q.empty()){
        int i,j,cost; tie(i,j,cost) = q.front(); q.pop();

        if(cost >= K) continue;
        if(a[i][j]=='#' || d[i][j]<INF) continue;
        if(i==0 || j==0 || i==H-1 || j==W-1){
            ans = 1;
            break;
        }

        d[i][j] = cost;
        int mn = (min({i,j,H-1-i,W-1-j}) + K-1) / K;
        chmin(ans, 1+mn);

        for(auto &p : v){
            int x = i+p.first, y = j+p.second;
            q.emplace(x,y,cost+1);
        }
    }

    cout << ans << en;
    return;
}

