inline bool pc(int x,int y){
	if(x==n||y==m||x<0||y<0||dt[x][y]=='#'||dis[x][y]!=-1) return 0;
	return 1;
}
queue<pii> q;
int fx[4]={1,-1,0,0},fy[4]={0,0,1,-1};
