void dfs(ll x,ll y,ll d){
  if(d>=k) return;
  for(int i=0;i<4;i++){
    ll nx=x+dx[i],ny=y+dy[i];
    if(0<nx&&nx<=h&&0<ny&&ny<=w){
      if(!cando[nx][ny]&&!block[nx][ny]){
        cando[nx][ny]=true;
        dfs(nx,ny,d+1);
      }
    }
  }
}
ll dis(ll x,ll y){
  ll d1=x-1,d2=h-x,d3=y-1,d4=w-y;
