//ifstream cin("x.in"); ofstream cout("x.out");

int n, m;

const int nmax = 800;
const int inf = 1 << 30;
const int dl[ 4 ] = {-1, 0, 0, 1};
const int dc[ 4 ] = {0, -1, 1, 0};

int viz[nmax + 1][nmax + 1];
queue <pair<int, int>> q;
string s[nmax + 1];

inline int mndst (int x, int y) {
    int dist = min(x - 1, y - 1);
    return min(dist, min(n - x, m - y));
}

int main() {
    int k;
    cin >> n >> m >> k;

    int x, y;
    for (int i = 1; i <= n; ++ i) {
        cin >> s[ i ];
        for (int j = 1; j <= m; ++ j) {
            if (s[ i ][j - 1] == 'S') {
                x = i, y = j;
            }
        }
        s[ i ] = "#" + s[ i ];
    }

    viz[ x ][ y ] = 1;
    q.push(make_pair(x, y));
    int ans = inf;

    while (!q.empty()) {
        pair<int, int> shp = q.front(); q.pop();

        ans = min(ans, mndst(shp.first, shp.second));
        if (viz[ shp.first ][ shp.second ] == k + 1) continue;

        for (int dir = 0; dir < 4; ++ dir) {
            int a, b;
            a = shp.first + dl[ dir ], b = shp.second + dc[ dir ];

            if (a < 1 || b < 1 || a > n || b > m) continue;
            if (viz[ a ][ b ] != 0 || s[ a ][ b ] == '#') continue;

            viz[ a ][ b ] = viz[ shp.first ][ shp.second ] + 1;
            q.push(make_pair(a, b));
        }
    }

    if (ans <= 0) ans = 0;
    else ans = (ans - 1) / k + 1;

    if (x == 1 || y == 1 || x == n || y == m) ans = -1;
    cout << ans + 1;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int N = 800 + 10;
int n, m, k, dx[] = {1, -1, 0, 0}, dy[] = {0, 0, 1, -1}, mark[N][N], dis[N][N], ans = N + 1;
string s[N];
pair<int, int> st;
bool isval(int x, int y) {
	if (x < n && x >= 0 && y < m && y >= 0 && s[x][y] == '.')
		return true;
	return false;
}
void bfs(int sx, int sy) {
	mark[sx][sy] = 1;
	queue<pair<int, int> > q;
	q.push({sx, sy});
	dis[sx][sy] = 0;
	while (!q.empty()) {
		auto p = q.front();
		q.pop();
		int x = p.first, y = p.second;
		for (int i = 0; i < 4; i++) {
			int xx = x + dx[i], yy = y + dy[i];
			if (isval(xx, yy) && !mark[xx][yy]) {
				mark[xx][yy] = 1;
				dis[xx][yy] = dis[x][y] + 1;
				q.push({xx, yy});
			}
		}
	}
}
int main() {
	cin >> n >> m >> k;
	for (int i = 0; i < n; i++) {
		cin >> s[i];
		for (int j = 0; j < m; j++)
			if (s[i][j] == 'S')
				st = {i, j};
	}
	memset(dis, 127, sizeof(dis));
	bfs(st.first, st.second);
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			if (dis[i][j] <= k) {
				ans = min({ans, (i + k - 1) / k, (j + k - 1) / k, (n - i - 1 + k - 1) / k, (m - j - 1 + k - 1) / k});
			}	
		}
	}
	cout << ans + 1;
	return 0;
}

#include <bits/stdc++.h>

using namespace std;

typedef long long int ll;
typedef pair<int,int> ii;

const int N = 8e3 + 5;

int n,m,k;
ii st;
bool vis[N][N];
char c[N][N];
int wx[4] = {0,0,-1,1};
int wy[4] = {1,-1,0,0};
queue <pair<int,ii> > Q;

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(NULL); cout.tie(NULL);
  cin >> n >> m >> k;
  for (int i = 1 ; i <= n ; i++)
    for (int j = 1 ; j <= m ; j++) {
      cin >> c[i][j];
      if (c[i][j] == 'S')
        st = {i,j};
    }
  int t = 1;
  for (int i = 0 ; i < 4 ; i++)
    if (c[st.first + wx[i]][st.second + wy[i]] != '#')
      t = 0;
  Q.push({0,st});
  while(Q.empty() == false) {
    auto temp = Q.front();
    Q.pop();
    int cost = temp.first,x = temp.second.first, y = temp.second.second;
    if (x == 1 || x == n || y == 1 || y == m) {
      cout << cost / k + (cost % k != 0) + t;
      return 0;
    }
    if (vis[x][y] == true)
      continue;
    vis[x][y] = true;
    for (int i = 0 ; i < 4 ; i++)
      Q.push({cost + 1,{x + wx[i],y + wy[i]}}); 
  }
}

