using namespace std;

#define MAXN 800

int movesi [4] = {-1, 0, 0, 1};
int movesj [4] = {0, -1, 1, 0};

int h, w, k;
pair<int, int> memo[MAXN+5][MAXN+5];
int maze[MAXN+5][MAXN+5];

void BFS (int i, int j) {

	queue <pair<int, pair<int, int> > > q;
	memo[i][j].first = 1;
	memo[i][j].second = 0;

	q.push(make_pair(i, make_pair(j, 0)));

	while (!q.empty()) {

		int x = q.front().first;
		int y = q.front().second.first;
		int closed = q.front().second.second;
		q.pop();

		for (i=0; i<4; i++) {

			int nx = x+movesi[i];
			int ny = y+movesj[i];
			int c = closed;

			if ((nx>=0 && nx<h) && (ny>=0 && ny<w)) {

				if (memo[nx][ny].first == 0) {
					memo[nx][ny].first = memo[x][y].first+1;
					if (maze[nx][ny] == 1) c++;
					memo[nx][ny].second = c;
					q.push(make_pair(nx, make_pair(ny, c)));
				}

			}

		}

	}

}

