			if (res.second%k != 0) r++;
		}

		else {
			r += res.second/k;
			if (res.second%k != 0) r++;

			res.first = ((res.first%k == 0)?0:1)+(res.first/k);
			res.first -= r;
			r += res.first;
		}
	}

	cout << r << endl;

	return 0;
}

