using namespace std;
typedef long long ll;
const int MAX = static_cast<int>(1e9);

int main()
{
	int H, W, K;
	cin >> H >> W >> K;
	vector<vector<bool>> board(H, vector<bool>(W));
	pair<int, int> S;
	for (int i = 0; i < H; i++) {
		string A;
		cin >> A;
		for (int j = 0; j < W; j++) {
			if (A[j] == 'S') {
				S = make_pair(i, j);
			} else if (A[j] == '#') {
				board[i][j] = true;
			}
		}
	}
	auto calc_score = [H, W](const pair<int, int>& p) {
		return min({ p.first, (H - 1) - p.first, p.second, (W - 1) - p.second });
	};
	auto calc_ans = [K](int score) {
		return ((score + K - 1) / K) + 1;
	};
	vector<vector<int>> step(H, vector<int>(W, MAX));
	typedef pair<int, int> t;
	queue<t> q;
	q.push(S);
	step[S.first][S.second] = 0;
	int ans = MAX;
	while (!q.empty()) {
		pair<int, int> pos;
		pos = q.front(); q.pop();
		int score = calc_score(pos);
		ans = min(ans, calc_ans(score));
		if (score == 0) {
			break;
		}
		if (step[pos.first][pos.second] >= K)
			continue;
		static const int dx[4] = { 1, 0, -1, 0 };
		static const int dy[4] = { 0, 1, 0, -1 };
		for (int d = 0; d < 4; d++) {
			auto p2 = pos;
			p2.first += dy[d];
			p2.second += dx[d];
			if (!board[p2.first][p2.second] && step[p2.first][p2.second] == MAX) {
				q.push(p2);
				step[p2.first][p2.second] = step[pos.first][pos.second] + 1;
			}
		}
	}
	cout << ans << endl;
	return 0;
}

