		}
	}
	assert(y >= 0 && x >= 0);
	int ans = magic(y, x);
	stack<pint> st;
	st.push(mp(y,x));
	for (int i = 0; i < K + 1; i++) {
		stack<pint> st2;
		while (! st.empty()) {
			pint p = st.top();
			st.pop();
			v[p.first][p.second] = 1;
			ans = min(ans, magic(p.first, p.second));
			for (int dy = -1; dy <= 1; dy++) {
				for (int dx = -1; dx <= 1; dx++) {
					if (dy * dx == 0 && v[p.first + dy][p.second + dx] == 0) {
						st2.push(mp(p.first + dy, p.second + dx));
					}
				}
			}
		}
		st = st2;
	}
	cout << ans + 1 << endl;
	return 0;
}

