int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);
    cin >> H >> W >> K;

    field.resize(H);
    for(int i=0; i<H; i++)
        field[i].resize(W, 0);

    cnt.resize(H);
    for(int i=0; i<H; i++)
        cnt[i].resize(W, -1);

    for(int i=0; i<H; i++){
        for(int j=0; j<W; j++){
            char ch;
            cin >> ch;
            if(ch == '#') field[i][j] = 1;
            else if(ch == 'S'){
                x = j;
                y = i;
            }
        }
    }

    cnt[y][x] = 0;
    queue<pair<int, int>> que;
    que.push(make_pair(x, y));
    while(!que.empty()){
        pair<int, int> xy = que.front();
        que.pop();
        int xx = xy.first;
        int yy = xy.second;
        int num = cnt[yy][xx];
        for(int i=0; i<4; i++){
            int xxx = xx + dx[i];
            int yyy = yy + dy[i];
            if(xxx < 0 || W <= xxx || yyy < 0 || H <= yyy) continue;
            if(field[yyy][xxx] == 1 || cnt[yyy][xxx] != -1) continue;
            cnt[yyy][xxx] = num + 1;
            que.push(make_pair(xxx, yyy));
        }
    }

    int ans = 1 << 30;
    for(int i=0; i<H; i++){
        for(int j=0; j<W; j++){
            if(cnt[i][j] == -1 || cnt[i][j] > K) continue;
            if(i == 0 || i == H-1 || j == 0 || j == W-1){
                cout << 1 << endl;
                return 0;
            }
            int tmp1 = min(i, H-1-i);
            int tmp2 = min(j, W-1-j);
            int tmp = min(tmp1, tmp2);
            if(tmp % K == 0){
                ans = min(ans, 1 + tmp / K);
            }else{
                ans = min(ans, 2 + tmp / K);
