bool onedge(int x,int y){
  return x == 0 || x == h - 1 || y == 0 || y == w - 1;
}
bool inner(int x,int y){
  return x >= 0 && x < h && y >= 0 && y < w;
}
void dfs(int x,int y,int d){

  dist[x][y] = d;
  q.emplace(x,y);

  REP(i,4){
    int nx = x + dx[i];
    int ny = y + dy[i];
    if(inner(nx,ny) && g[nx][ny] == '.' && dist[nx][ny] > dist[x][y] + 1 && d < k){
      dfs(nx,ny,d+1);
    }
  }

}
void bfs(){
  while(q.size()){
    int x = q.front().first;
    int y = q.front().second;
    q.pop();

    REP(i,4){
      int nx = x + dx[i];
      int ny = y + dy[i];

      if(inner(nx,ny) && dist[nx][ny] == inf){
        dist[nx][ny] = dist[x][y] + 1;
        q.emplace(nx,ny);
      }
    }
  }
}

