char s[Maxn+5][Maxn+5];
queue<pair<int,int> > q;
int mn(int a,int b){
	return a<b?a:b;
}
int Get(int i,int j){
	int tmp=(i+k-2)/k;
	tmp=min(tmp,(j+k-2)/k);
	tmp=min(tmp,(h-i+k-1)/k);
	tmp=min(tmp,(w-j+k-1)/k);
	return tmp;
}
int main(){
	ans=Inf;
	scanf("%d%d%d",&h,&w,&k);
	for(int i=1;i<=h;i++){
		scanf("%s",s[i]+1);
	}
	for(int i=1;i<=h&&!sx;i++){
		for(int j=1;j<=w&&!sx;j++){
			if(s[i][j]=='S'){
				sx=i;
				sy=j;
			}
		}
	}
	memset(dist,0x3f,sizeof(dist));
	dist[sx][sy]=0;
	q.push(make_pair(sx,sy));
	while(!q.empty()){
		int x=q.front().first,y=q.front().second;
		q.pop();
		if(dist[x][y]==k){
			continue;
		}
		for(int i=1;i<=4;i++){
			int cx=x+d[i-1],cy=y+d[i];
			if(cx<1||cy<1||cx>h||cy>w||dist[x][y]+1>=dist[cx][cy]||s[cx][cy]=='#'){
				continue;
			}
			dist[cx][cy]=dist[x][y]+1;
			q.push(make_pair(cx,cy));
		}
	}
	for(int i=1;i<=h;i++){
		for(int j=1;j<=w;j++){
			if(dist[i][j]<Inf){
				ans=mn(ans,Get(i,j)+1);
			}
		}
	}
	printf("%d\n",ans);
	return 0;
}

