const int N = 810, inf = 1e6;

void bfs(int i, int j, int h, int w);

char a[N][N];
bool seen[N][N] = {0};
int dist[N][N], dx[4] = {-1, 0, 1, 0}, dy[4] = {0, -1, 0, 1};

int main()
{
	int h, w, k;
	cin >> h >> w >> k;
	for (int i = 1; i <= h; ++i)
		cin >> (a[i] + 1);

	int x, y;
	for (int i = 1; i <= h; ++i)
	{
		for (int j = 1; j <= w; ++j)
		{
			if (a[i][j] == 'S')
			{
				x = i;
				y = j;
				break;
			}
		}
	}

	for (int i = 1; i <= h; ++i)
		for (int j = 1; j <= w; ++j)
			dist[i][j] = inf;

	bfs(x, y, h, w);
	int ans = inf;
	for (int i = 1; i <= h; ++i)
	{
		for (int j = 1; j <= w; ++j)
		{
			if (dist[i][j] <= k)
			{
				int temp = min(min(i - 1, h - i), min(j - 1, w - j));
				temp = (temp / k) + ((temp % k) ? 1 : 0) + 1;
				ans = min(ans, temp);
			}
		}
	}

	cout << ans << endl;
}

void bfs(int i, int j, int h, int w)
{
	seen[i][j] = true;
	dist[i][j] = 0;
	queue <pii> q;
	q.push({i, j});
	while (!q.empty())
	{
		pii cur = q.front();
		q.pop();

		for (int k = 0; k < 4; ++k)
		{
			int x = cur.first + dx[k], y = cur.second + dy[k];
			if (1 <= x and x <= h and 1 <= y and y <= w and !seen[x][y] and a[x][y] == '.')
			{
				seen[x][y] = true;
				dist[x][y] = 1 + dist[cur.first][cur.second];
				q.push({x, y});
			}
		}
	}
}

