int bfs() {
	queue<P>que;
	rep(i, H)
		rep(j, W)d[i][j] = INF;
	que.push(P(S_i, S_j));
	d[S_i][S_j] = 0;
	while (que.size()) {
		P p = que.front();
		que.pop();
		if (p.first == G_i&&p.second == G_j)break;
