int go (int price) { // return (벽부수기, 이동횟수)
  static int dst[805][805];
  static int moves[805][805];
  priority_queue< tuple<int, int, int>, vector< tuple<int, int, int> >, greater< tuple<int, int, int> > > pq;
  for(int i = 1; i <= H; i++) for(int j = 1; j <= W; j++) dst[i][j] = moves[i][j] = 1e9;
  dst[si][sj] = 0;
  moves[si][sj] = 0;
  pq.push(make_tuple(0, si, sj));
  int rep = 0;
  while(!pq.empty()) {
    int c, x, y; tie(c, x, y) = pq.top(); pq.pop();
    rep += 1;
    if(dst[x][y] != c) continue;
    if(x == 1 || y == 1 || x == H || y == W) {
      assert(((dst[x][y] - moves[x][y]) / price) * price + moves[x][y] == dst[x][y]);
      int a = (dst[x][y] - moves[x][y]) / price;
      int b = moves[x][y];
      return max((a + K - 1) / K, (b + K - 1) / K);
    }
    for(pii d : {make_pair(-1, 0), make_pair(1, 0), make_pair(0, -1), make_pair(0, 1)}) {
      int nx = x + d.first;
      int ny = y + d.second;
      int nc = c + ((D[nx][ny] == '#' ? price : 0) + 1);
      if(1 <= nx && nx <= H && 1 <= ny && ny <= W && dst[nx][ny] > nc) {
        dst[nx][ny] = nc;
        moves[nx][ny] = moves[x][y] + 1;
        pq.push(make_tuple(nc, nx, ny));
      }
    }
  }
  return 1e9;
  //return pii(1e9, 1e9);
}

