using namespace std;

const int MAXN = 800 + 100;
const int INF = 0x1f1f1f1f;
const int dx[] = {-1, 1, 0, 0};
const int dy[] = {0, 0, -1, 1};

typedef pair<int, int> pii;

int n, m, k, sx, sy;
int ans = INF;
char s[MAXN][MAXN];
int dis[MAXN][MAXN], step[MAXN][MAXN];


void bfs1()
{
	queue<pii> que;
	dis[sx][sy] = 0, step[sx][sy] = 0, que.push(make_pair(sx, sy));
	while(!que.empty())
	{
		int x = que.front().first, y = que.front().second;
		que.pop();
		for(int i = 0; i < 4; i++)
		{
			int xx = x + dx[i], yy = y + dy[i];
			if(xx < 1 || xx > n || yy < 1 || yy > m) continue;
			if(dis[xx][yy] >= 0) continue;
			if(s[xx][yy] == '#') continue;
			if(dis[x][y] + 1 > k) continue;
			dis[xx][yy] = dis[x][y] + 1, step[xx][yy] = 1;
			que.push(make_pair(xx, yy));
		}
	}
}

void bfs2()
{
	queue<pii> que;
	for(int i = 1; i <= n; i++)
		for(int j = 1; j <= m; j++)
			if(dis[i][j] >= 0)
				dis[i][j] = k, que.push(make_pair(i, j));
	while(!que.empty())
	{
		int x = que.front().first, y = que.front().second;
		que.pop();
		for(int i = 0; i < 4; i++)
		{
			int xx = x + dx[i], yy = y + dy[i];
			if(xx < 1 || xx > n || yy < 1 || yy > m) continue;
			if(dis[xx][yy] >= 0) continue;
			dis[xx][yy] = dis[x][y] + 1, step[xx][yy] = (dis[xx][yy] + k - 1) / k;
			que.push(make_pair(xx, yy));
		}
	}
}

int main()
{
	ios::sync_with_stdio(false);
	// freopen("1.in", "r", stdin);
	// freopen("1.out", "w", stdout);

	cin >> n >> m >> k;
	for(int i = 1; i <= n; i++)
		cin >> (s[i] + 1);
	for(int i = 1; i <= n; i++)
		for(int j = 1; j <= m; j++)
			if(s[i][j] == 'S')
				sx = i, sy = j;
	memset(dis, -1, sizeof(dis));
	bfs1();
	bfs2();
	for(int j = 1; j <= m; j++)
		ans = min(ans, step[1][j]), ans = min(ans, step[n][j]);
	for(int i = 1; i <= n; i++)
		ans = min(ans, step[i][1]), ans = min(ans, step[i][m]);
	cout << ans << endl;

	return 0;
}

