const int inf = 1e9+7;
const ll longinf = 1LL<<60;
const ll mod = 1e9+7;

vector<ll> dist;
bool bellman_ford(int n, int s, vector<vector<ll>>& cost) {
  dist = vector<ll>(n, longinf);
  dist[s] = 0;
  rep(i, n) {
    rep(j, n) {
      rep(k, n) {
        if(j != k && dist[j] != longinf && dist[k] > dist[j] + cost[j][k]) {
          dist[k] = dist[j] + cost[j][k];
          if(i == n-1) return true;
        }
      }
    }
  }
  return false;
}

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  int H, W, K;
  cin >> H >> W >> K;
  vector<string> A(H);
  rep(i, H) cin >> A[i];
  vector<vector<ll>> cost(H*W, vector<ll>(H*W, longinf));
  int dx[] = {0, -1, 0, 1};
  int dy[] = {-1, 0, 1, 0};
  int s = -1;
  rep(i, H) rep(j, W) {
    if(A[i][j] == 'S') s = i*W+j;
    rep(k, 4) {
      int nx = i+dx[k];
      int ny = j+dy[k];
      if(nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
      cost[i*W+j][nx*W+ny] = (A[nx][ny] == '#');
    }
  }
  bellman_ford(H*W, s, cost);

  auto bsearch = [&]() {
    auto test = [&](int k) {
      rep(i, H) if(dist[i*W] <= K*(k-1) || dist[i*W+W-1] <= K*(k-1)) return true;
      rep(j, W) if(dist[j] <= K*(k-1) || dist[(H-1)*W+j] <= K*(k-1)) return true;
      return false;
    };
    ll ok = H*W+1, ng = -1;
    while(ok-ng>1) {
      ll mid = (ok+ng)/2;
      (test(mid) ? ok : ng) = mid;
    }
    return ok;
  };
  cout << bsearch() << "\n";
  return 0;
}

