    }
    int res=INF;
    for(int i=1;i<=h;i++){
        for(int j=1;j<=w;j++){
            if(v[i][j]==0&&a[i][j]!='S')continue;
            int d1=(v[i][j]+k-1)/k;
            int d2=min(min(i-1,j-1),min(h-i,w-i));
            res=min(res,max(1,d1+(d2-1+k)/k));
        }
    }
    cout<<res<<endl;
