int dist(int x, int y){
	std::queue<std::pair<int, int>> qu; qu.push({x, y});
	std::vector<std::vector<int>> min_cost(h, std::vector<int>(w, 1e9));
	min_cost[x][y] = 0;

	while(!qu.empty()){
		auto p = qu.front(); qu.pop();

		for(int i = 0; i < 4; i++){
			int nx = p.first + vy[i], ny = p.second + vx[i];
			if(nx<0||ny<0||nx>=h||ny>=w) continue;
			if(min_cost[p.first][p.second] + 1 >= min_cost[nx][ny]) continue;
			min_cost[nx][ny] = min_cost[p.first][p.second] + 1;
			qu.push({nx, ny});
		}
	}

	int ret = 1e9;
	for(int i = 0; i < w; i++){
		ret = std::min(ret, min_cost[0][i]);
		ret = std::min(ret, min_cost[h - 1][i]);
	}

	for(int i = 0; i < h; i++){
		ret = std::min(ret, min_cost[i][0]);
		ret = std::min(ret, min_cost[i][w - 1]);
	}

	return (ret + k - 1) / k;
}

