			if(0<=nx&&nx<w&&0<=ny&&ny<h&&dist[ny][nx]==inf){
				dist[ny][nx]=d+1;
				q.push(pi(nx,ny));
			}
		}
	}
	int ans=inf;
	REP(i,h)chmin(ans,dist[i][0]/k+!!(dist[i][0]%k));
	REP(i,h)chmin(ans,dist[i][w-1]/k+!!(dist[i][w-1]%k));
	REP(j,w)chmin(ans,dist[0][j]/k+!!(dist[0][j]%k));
	REP(j,w)chmin(ans,dist[h-1][j]/k+!!(dist[h-1][j]%k));
	cout<<ans<<endl;
}

#include <iostream>
