	int k = a[0].k;
	int w = a[0].w;
	int h = a[0].h;
	int kk = a[0].kk;
	a.erase(a.begin());
	if (x == 0 || x == w - 1 || y == 0 || y == h - 1) {
		ans = 1;
		return;
	}
	if (b[y][x] > k) {
		return;
	}
	b[y][x] = k;
	if (ans > check(x, y, kk, w, h)) {
		ans = check(x, y, kk, w, h);
	}
	if (k < 0) {
		return;
	}
	if (mp[y][x - 1] == '.') {
