			hoge.h = h;
			hoge.kk = kk;
			a.push_back(hoge);
		}
	}
	if (mp[y][x + 1] == '.') {
		if (x + 1 >= w - 1) {
			ans = 1;
			return;
		}
		if (b[y][x+1] > k - 1) {
		}
		else {
		A hoge;
		hoge.x = x+1;
		hoge.y = y;
		hoge.k = k-1;
		hoge.w = w;
		hoge.h = h;
		hoge.kk = kk;
		a.push_back(hoge);
	}
	}
	if (mp[y - 1][x] == '.') {
		if (y - 1 <= 0) {
			ans = 1;
			return;
		}
		if (b[y-1][x] > k - 1) {
		}
		else {
		A hoge;
		hoge.x = x;
		hoge.y = y-1;
		hoge.k = k-1;
		hoge.w = w;
		hoge.h = h;
		hoge.kk = kk;
		a.push_back(hoge);
	}
	}
	if (mp[y + 1][x] == '.') {
		if (y + 1 >= h - 1) {
			ans = 1;
			return;
		}
		if (b[y+1][x] > k - 1) {
		}
		else {
		A hoge;
		hoge.x = x;
		hoge.y = y+1;
		hoge.k = k-1;
		hoge.w = w;
		hoge.h = h;
		hoge.kk = kk;
		a.push_back(hoge);
	}
	}
}

