			}

	ans = w*h;
	A hoge;
	hoge.x = x;
	hoge.y = y;
	hoge.k = k;
	hoge.w = w;
	hoge.h = h;
	hoge.kk = k;
	a.push_back(hoge);
	int K = k;
	while(true) {
