bool within(int x, int min, int max) {
	return min <= x && x <= max;
}

int main(void) {
	int H, W, K;
	cin >> H >> W >> K;
	vector<vector<char>> f(H);
	REP(i, H) f[i].resize(W);
	int start = 0;
	int start_row = 0, start_col = 0;
	REP(i, H) REP(j, W) {
		cin >> f[i][j];
		if (f[i][j] == 'S') {
			start = i * W + j;
			start_row = i;
			start_col = j;
		}
	}
	int n = W * H;
	int dx[] = { 0,0,1,-1 };
	int dy[] = { 1,-1,0,0 };
	struct info {
		int row, col;
		int depth;
	};
	stack<info> s;
	vector<vector<bool>> v(H);
	REP(i, H) v[i].resize(W, false);
	v[start_row][start_col] = true;
	s.push({ start_row, start_col, 0 });
	while(!s.empty()) {
		int row = s.top().row, col = s.top().col, depth = s.top().depth;
		s.pop();
		if (depth >= K) continue;
		REP(i, 4) {
			int nrow = row + dy[i], ncol = col + dx[i];
			if (!within(nrow, 0, H - 1) | !within(ncol, 0, W - 1)) continue;
			if (!v[nrow][ncol] && f[nrow][ncol] == '.') {
				v[nrow][ncol] = true;
				s.push({ nrow, ncol, depth + 1 });
			}
		}
	}
	int ans = 800 * 800 * 2;
	REP(i, H) REP(j, W) {
		if (!v[i][j]) continue;
		ans = min(ans, (abs((int)j) + K - 1) / K + 1);
		ans = min(ans, (abs((int)i) + K - 1) / K + 1);
		ans = min(ans, (abs((int)j - W - 1) + K - 1) / K + 1);
		ans = min(ans, (abs((int)i - H - 1) + K - 1) / K + 1);
	}
	cout << ans << endl;

	return 0;
}

