long dx[] = {1, 0, -1, 0};
long dy[] = {0, 1, 0, -1};


struct Solver {
  long h, w, k;
  std::vector<std::string> xss;
  Solver() {
    S002 reader;
    reader >= h >= w >= k >h>= xss;
  }
  bool visited[1024][1024];
  long sx, sy;
  long dfs(long x, long y, long d) {
    const long inf = 1000000;
    if( d > k ) return inf;
    if( not ( 0 <= x and x < w ) ) return inf;
    if( not ( 0 <= y and y < h ) ) return inf;
    if( xss[y][x] == '#' ) return inf;
    if( visited[y][x] ) return inf;
    visited[y][x] = true;
    long res = std::min(std::min(std::min((x+k-1)/k, ((w-1)-x+k-1)/k), (y+k-1)/k), ((h-1)-y+k-1)/k);
    for(long i = 0; i < 4; ++i) {
      long nx = x + dx[i];
      long ny = y + dy[i];
      res = std::min(res, dfs(nx, ny, d + 1));
    }
    return res;
  }
  void init() {
    for(long i = 0; i < 1024; ++i) {
      for(long j = 0; j < 1024; ++j) {
        visited[i][j] = false;
      }
    }
    for(long i = 0; i < h; ++i) {
      for(long j = 0; j < w; ++j) {
        if( xss[i][j] == 'S' ) {
          sy = i;
          sx = j;
        }
      }
    }
  }
  void solve() {
    init();
    long res = dfs(sx, sy, 0);
    printf("%ld\n", res + 1);
  }
  ~Solver() { fprintf(stderr, "--end--\n"); }
};

int main() {
  loop std::unique_ptr<Solver>(new Solver())->solve();
  return 0;
}

