	cin >> H >> W >> K;
	vector<vector<char>> f(H);
	REP(i, H) f[i].resize(W);
	int start = 0;
	int start_row = 0, start_col = 0;
	REP(i, H) REP(j, W) {
		cin >> f[i][j];
		if (f[i][j] == 'S') {
			start_row = i;
			start_col = j;
		}
	}
	int dx[] = { 0,0,1,-1 };
	int dy[] = { 1,-1,0,0 };
