bool in(ll y, ll x, ll h, ll w){
	return 0 <= y && y < h && 0 <= x && x < w;
}

int main(){
	ll h,w,k; cin >> h >> w >> k;
	vs s(h); rep(i,h) cin >> s[i];
	vvl d(h,vl(w,inf));
	queue<pair<P,ll>> q, que;
	rep(i,h){
		rep(j,w){
			if(s[i][j]=='S'){
				q.emplace(P(i,j),k);
				que.emplace(P(i,j),0);
				d[i][j] = 1;
			}
		}
	}
	while(!q.empty()){
		auto p = q.front(); q.pop();
		if(p.second == 0) continue;
		ll y = p.first.first;
		ll x = p.first.second;
		rep(i,4){
			ll ny = y + dy[i];
			ll nx = x + dx[i];
			if(in(ny,nx,h,w)){
				if(s[ny][nx] == '#') continue;
				if(d[ny][nx] == 1) continue;
				d[ny][nx] = 1;
				q.emplace(P(ny,nx),p.second-1);
				que.emplace(P(ny,nx),0);
			}
		}
	}
	while(!que.empty()){
		auto p = que.front(); que.pop();
		ll y = p.first.first;
		ll x = p.first.second;
		rep(i,4){
			ll ny = y + dy[i];
			ll nx = x + dx[i];
			if(in(ny,nx,h,w)){
				if(d[ny][nx] != inf) continue;
				ll c = 0, K;
				if(p.second == 0){
					c++;
					K = k - 1;
				}else{
					K = p.second - 1;
				}
				d[ny][nx] = d[y][x] + c;
				que.emplace(P(ny,nx),K);
			}
		}
	}
	ll ans = inf;
	rep(j,w) chmin(ans, min(d[0][j], d[h-1][j]));
	rep(i,h){
		chmin(ans, min(d[i][0], d[i][w-1]));
	}
	cout << ans << endl;
}

#include <bits/stdc++.h>
#define N 1005
#define INF 0x3f3f3f3f
using namespace std;
int X,Y,k;
const int dx[]={-1,0,1,0};
const int dy[]={0,1,0,-1};
bool In(int x,int y)
{
	return x>=0 and x<X and y>=0 and y<Y;
}
char s[N][N];
int sx,sy;
int dist[N][N];
struct Node
{
	int x,y,dis;
	Node(){}
	Node(int a,int b,int c)
	{
		x=a;
		y=b;
		dis=c;
	}
};
void Init()
{
	scanf("%d%d%d",&X,&Y,&k);
	for(int i=0;i<X;i++)
	{
		scanf("%s",s[i]);
	}
	for(int i=0;i<X;i++)
	{
		for(int j=0;j<Y;j++)
		{
			if(s[i][j]=='S')
			{
				sx=i;
				sy=j;
				s[i][j]='.';
			}
		}
	}
}
queue <Node> q;
void Solve()
{
	memset(dist,0x3f,sizeof(dist));
	q.push(Node(sx,sy,0));
	while(not q.empty())
	{
		Node t=q.front();
		q.pop();
		if(dist[t.x][t.y]>t.dis)
		{
			dist[t.x][t.y]=t.dis;
			for(int i=0;i<4;i++)
			{
				int xx=t.x+dx[i];
				int yy=t.y+dy[i];
				if(not In(xx,yy))continue;
				if(s[xx][yy]=='#')continue;
				q.push(Node(xx,yy,t.dis+1));
			}
		}
	}
	int res=INF;
	for(int i=0;i<X;i++)
	{
		for(int j=0;j<Y;j++)
		{
			if(s[i][j]=='.' and i>0 and i<X-1 and j>0 and j<Y-1)
			{
				res=min(res,(dist[i][j]-1)/k+1+(min(min(i,j),min(X-1-i,Y-1-j))-1)/k+1);
			}
			else if(s[i][j]=='.')
			{
				res=min(res,(dist[i][j]-1)/k+1);
			}
		}
	}
	printf("%d\n",res);
	/*puts("Debug:");
	for(int i=0;i<X;i++)
	{
		printf("%s\n",s[i]);
	}
	puts("End Debug");*/
}
int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    Init();
    Solve();
	return 0;
}

