char c[880][880];
int n,m,k,stx,sty;
int ans=BINF;
bool used[886][886];
inline int dist(int x,int y){
	int ans=min(min(n-x-1,m-y-1),min(x,y));
	if(ans%k) return ans/k+1;
	else return ans/k;
}
inline bool inr(int x,int y){
	return x>=0 && x<n && y>=0 && y<m;
}
inline bool win(int x,int y){
	return x==0 || y==0 || x==n-1 || y==m-1; 
}
int main(){
	cin>>n>>m>>k;
	rep(i,n){
		scanf("%s",&c[i]);
		rep(j,m)
			if(c[i][j]=='S')
				stx=i,sty=j;
	}
	queue<pair<int,int> > q;
	used[stx][sty]=true;
	q.push(mp(stx,sty));
	int I_Hate_Atcoder=1;
	while(!q.empty() && I_Hate_Atcoder<=k){
		int x=q.front().F,y=q.front().S;
		q.pop();
		rep(i,4){
			int nx=x+dx[i];
			int ny=y+dy[i];
			if(!inr(nx,ny) || used[nx][ny] || c[nx][ny]=='#') continue;
			used[nx][ny]=true;
			if(win(x,y)) END(1)
			q.push(mp(nx,ny));
		}
		I_Hate_Atcoder++;
	}
	//rep(i,n){rep(j,m) cout<<used[i][j]; cout<<endl;}
	int mn=BINF;
	rep(i,n) rep(j,m){
		if(used[i][j]) mn=min(mn,dist(i,j));
	}
	cout<<mn+1<<endl;
	return 0;
}

