// 処理内容
int main() {

    ios::sync_with_stdio(false);
    cin.tie(0);

    ll h, w, k; cin >> h >> w >> k;
    vector<string> a(h);
    REP(i, h) cin >> a[i];

    ll si, sj;
    REP(i, h) {
        REP(j, w) {
            if (a[i][j] == 'S') {
                si = i;
                sj = j;
            }
        }
    }

    vector<vector<ll>> d(h, vector<ll>(w, INF));
    using pl4 = pair<ll, ll>;
    using tl6 = tuple<ll, ll, ll>;
    auto comp = [&](tl6 i, tl6 j) -> bool {
        return get<2>(i) > get<2>(j);
    };
    priority_queue<tl6, vector<tl6>, decltype(comp)> q(comp);

    d[si][sj] = 0;
    q.push(tl6(si, sj, 0));

    vector<pl4> dx = {
        {-1,  0},
        {+1,  0},
        { 0, -1},
        { 0, +1}
    };

    while (q.size()) {

        ll i = get<0>(q.top());
        ll j = get<1>(q.top());
        ll dij = get<2>(q.top());
        q.pop();
        if (dij != d[i][j]) continue;

        vector<pl4> kimbo; kimbo.reserve(4);
        for (pl4 &v : dx) {
            ll i2 = i + v.first;
            ll j2 = j + v.second;
            if (0 <= i2 && i2 < h && 0 <= j2 && j2 < w) {
                kimbo.emplace_back(i2, j2);
            }
        }

        for (pair<ll, ll> &u : kimbo) {
            ll i2 = u.first;
            ll j2 = u.second;
            ll cand;
            if ((a[i2][j2] == '#') == (a[i][j] == '#')) {
                cand = d[i][j] + 1;
            } else if (a[i][j] != '#') {
                cand = (d[i][j] / k + 1) * k;
            }
            if (chmin(d[i2][j2], cand)) {
                q.push(tl6(i2, j2, cand));
            }
        }

    }

    // cerr << "\n";
    // REP(i, h) REP(j, w) {
    //     cerr << setw(5) << d[i][j] << " \n"[j==w-1];
    // }
    // cerr << "\n";

    ll ans = INF;
    REP(i, h) {
        chmin(ans, d[i][0]);
        chmin(ans, d[i][w-1]);
    }
    REP(j, w) {
        chmin(ans, d[0][j]);
        chmin(ans, d[h-1][j]);
    }
    cout << ans / k + 1 << endl;

}

