const int N = 800;

int dx[4] = {-1,0,0,+1};
int dy[4] = {0,-1,+1,0};

string s[N];
int n,m,k;
int ans;

void dfs(int x, int y, int t) {
  if(x < 0 || x >= n || y < 0 || y >= m) return;
  if(s[x][y] == '#') return;
  if(!t) return;
  int cur = min(x, y);
  cur = min(cur, n - 1 - x);
  cur = min(cur, m - 1 - y);

  ans = min(ans, (cur + k - 1) / k + 1);
  rep(i,0,4) {
    dfs(x + dx[i], y + dy[i], t - 1);
  }
}

