int H, W, K;
char board[802][802];
int dist[802][802];

int dr[] = { 0, 0, 1, -1 };
int dc[] = { 1, -1, 0, 0 };

int main()
{
	scanf("%d %d %d", &H, &W, &K);
	for (int i = 0; i < H; i++) scanf("%s", board[i]);

	PII start = PII(-1, -1);
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (board[i][j] == 'S') {
				start = PII(i, j);
				board[i][j] = '.';
			}
		}
	}

	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			dist[i][j] = -1;
		}
	}

	dist[start.first][start.second] = 0;
	queue<PII> Q;
	Q.push(start);
	while (!Q.empty()) {
		PII u = Q.front();
		Q.pop();
		if (dist[u.first][u.second] == K) continue;

		for (int d = 0; d < 4; d++) {
			PII end;
			end.first = u.first + dr[d];
			end.second = u.second + dc[d];
			if (!(IN(end.first, 0, H - 1) && IN(end.second, 0, W - 1))) continue;
			if (board[end.first][end.second] == '#') continue;
			if (dist[end.first][end.second] == -1) {
				dist[end.first][end.second] = dist[u.first][u.second] + 1;
				Q.push(end);
			}
		}
	}

	int ans = 0;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (i == 0 || i == H - 1 || j == 0 || j == W - 1) {
				if (dist[i][j] != -1) {
					ans = 1;
				}
			}
		}
	}

	if (ans) {
		printf("1\n");
		return 0;
	}

	ans = 1000000000;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			if (dist[i][j] == -1) continue;
			int d = MIN(i, j);
			d = MIN(d, H - 1 - i);
			d = MIN(d, W - 1 - j);
			int now = (d + K - 1) / K;
			ans = MIN(ans, now + 1);
		}
	}

	printf("%d\n", ans);
	return 0;
}

