  if(dist[i][j] <= K) return;
  if(A[i][j] == '#') return;
  dist[i][j] = d;

  bfs(i-1,j, d+1);
  bfs(i+1,j,d+1);
  bfs(i,j-1,d+1);
  bfs(i,j+1,d+1);
}


