#include<bits/stdc++.h>
using namespace std;

long long H, W, K;

long long A[805][805];
long long WORK[805][805];

#define OPEN INT_MAX
#define CLOSED LONG_MAX/3


bool valid(long long h, long long w){
	return (h >= 0) && (h < H) && (w >= 0) && (w < W);
}

void move(long long h, long long w, long long cost){
	A[h][w] = cost;
	if(valid(h-1, w) == true && A[h-1][w] != CLOSED || cost < K || A[h-1][w] > cost){
		move(h-1, w, cost+1);
	}
	if(valid(h+1, w) == true && A[h+1][w] != CLOSED || cost < K || A[h+1][w] > cost){
		move(h+1, w, cost+1);
	}
	if(valid(h, w-1) == true && A[h][w-1] != CLOSED || cost < K || A[h][w-1] > cost){
		move(h, w-1, cost+1);
	}
	if(valid(h, w+1) == true && A[h][w+1] != CLOSED || cost < K || A[h][w+1] > cost){
		move(h, w+1, cost+1);
	}
}

void firstmove(){
	for(long long h = 0; h < H; h++){
		for(long long w = 0; w < W; w++){
			if(A[h][w] == 1){
				move(h, w, (long long)0);
				return;
			}
		}
	}
}


