int main() {
    //ifstream cin("C.in");

    int n, m, k; cin >> n >> m >> k;

    vector<string> a(n);

    pair<int, int> start;

    for(int i = 0; i < n; ++i) {
        cin >> a[i];
        for(int j = 0; j < m; ++j)
            if(a[i][j] == 'S')
                start = make_pair(i, j);
    }

    vector<vector<int>> d(n, vector<int> (m, 1e9));

    queue<pair<int, int>> Q;
    Q.push(start);

    d[start.first][start.second] = 0;

