struct XY {
  int x, y;
  XY&operator+=(const XY&d) { x += d.x; y += d.y; return *this; }
  XY operator+(const XY&d)const { return XY(*this) += d; }
  bool operator==(const XY&d)const { return x == d.x && y == d.y; }
  bool check(int w, int h)const { return 0 <= x && x < w && 0 <= y && y < h; }
};
const XY d4[] = { { -1,0 }, { 1,0 }, { 0,-1 }, { 0,1 }, };
template<class T> auto get(T& a, XY d)->decltype(a[d.y][d.x]) { return a[d.y][d.x]; }
ostream& operator<<(ostream& os, XY d) { return os << '(' << d.x << ',' << d.y << ')'; }



void Calc() {

  var(int, h, w, k);

  auto s = in.Array<string>(h);
  XY start;
  rep(i, h)rep(j, w)if (s[i][j] == 'S') {
    start = { j, i };
    break;
  }

  vector<XY> p;
  p.push_back(start);
  queue<pair<int, XY>> q;
  q.push({ 0, start });

  while (q.size()) {
    auto pp = q.front(); q.pop();
    auto t = pp.second;
    if (get(s, t) == 'A')continue;
    p.push_back(t);
    get(s, t) = 'A';
    if (pp.first == k)continue;
    for (auto& i : d4) {
      auto next = i + t;
      if (next.check(w, h) && get(s, next) == '.') {
        q.push({pp.first + 1, next});
      }
    }
  }

  err(s);
  const int INF = 1e9 - 1;

  int ans = INF;
  for (auto& i : p) {
    auto mini = min({ i.x, i.y, w - i.x - 1, h - i.y - 1 });
    amin(ans, (mini + k - 1) / k + 1);
  }

  cout << (ans) << endl;


}

