		for (int j = 0; j < w; j++)
			if (mp[i][j] == 'S') {
				x = j;
				y = i;
			}

	ans = w*h;
	DFS(x, y, k, w, h, k);
	cout << ans << endl;
	//cin >> k;
	return 0;
}

