void recur(vector<string>& A, int x, int y, int n, int& ans)
{
    A[y][x] = '$';
    if (n > 0) {
        int vx[] = {-1, +1, 0, 0};
        int vy[] = {0, 0, -1, +1};
        for (int i = 0; i < 4; i++) {
            int newx = x + vx[i];
            int newy = y + vy[i];
            if (0 <= newx && newx < W && 0 <= newy && newy < H && A[newy][newx] == '.') {
                recur(A, newx, newy, n-1, ans);
            }
        }
    }
    ans = min({
        ans,
        (abs(x) + K - 1) / K + 1,
        (abs(x - (W - 1)) + K - 1) / K + 1,
        (abs(y) + K - 1) / K + 1,
        (abs(y - (H - 1)) + K - 1) / K + 1,
    });
}
int main()
{
    cin >> H >> W >> K;
    vector<string> A(H);
    for (auto& a : A) cin >> a;
    int sx = 0, sy = 0;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (A[i][j] == 'S') {
                sy = i, sx = j;
            }
        }
    }
    int ans = 1e9;
    recur(A, sx, sy, K, ans);
    cout << ans << endl;
    return 0;
}

