		{
			printf("0\n");
			continue;
		}
		for(int i=1;i<=h;i++)
		{
			for(int j=1;j<=w;j++)
			{
				if(dist[i][j]==-1)	continue;
				int d=min(min(i-1,h-i),min(j-1,w-j));
				ans=min(ans,(d+k-1)/k+1);
			}
		}
		printf("%d\n",ans); 
	}
	return 0;
}

