bool check(int allowed, int moves) {
	V<V<int>> vis(R, V<int>(C));
	queue<tuple<int, int, int, int>> Q;
	Q.emplace(sr, sc, 0, 0);
	vis[sr][sc] = 1;
	while (Q.size()) {
		int r, c, seen, dist;
		tie(r, c, seen, dist) = Q.front();
		// cout << r << " " << c << endl;
		Q.pop();
		if (r == 0 || c == 0)
			return 1;
		for (const auto& dir : dirs) {
			int cr = r+dir[0], cc = c+dir[1];
			// cout << " " << cr << " " << cc << endl;
			if (cr < 0 || cr >= R || cc < 0 || cc >= C)
				continue;
			if (vis[cr][cc])
				continue;
			if (seen + (G[cr][cc]=='#') > allowed)
				continue;
			if (dist+1 > moves)
				continue;
			Q.emplace(cr, cc, seen + (G[cr][cc]=='#'), dist+1);
			vis[cr][cc] = 1;
		}
	}
	return 0;
}

int solve_fast() {
	int lo = 1, hi = R*C+100;
	while (lo < hi) {
		int mid = (lo+hi)/2;
		int64_t num = int64_t(mid-1)*int64_t(K);
		if (num > R*C)
			num = R*C;
		// cout << mid << " " << num << " " << check(num) << endl;
		if (check(num, num+K)) {
			hi = mid;
		} else {
			lo = mid+1;
		}
	}
	return lo;
}

