int h, w, k;
char r[810][810];
bool vis[810][810];
int s, t;
int ans;
int dx[] = { 0, 0, 1, -1 },
	dy[] = { 1, -1, 0, 0 };

int Calc(int c) {
	return (c + k - 1) / k;
}

void Bfs() {
	queue<Node> q;
	q.push((Node){ 0, s, t });
	vis[s][t] = true;
	ans = 0x3f3f3f3f;
	while (!q.empty()) {
		Node f = q.front(); q.pop();
		vis[f.x][f.y] = true;
		int delta = 0;
		if (f.x == s && f.y == t) {
			delta = 1;
		}
		ans = min(ans, min(Calc(f.x - 1), min(Calc(f.y - 1), min(Calc(h - f.x), Calc(w - f.y)))) + f.step + delta);
		for (int i = 0; i < 4; ++i) {
			int xx = f.x + dx[i],
				yy = f.y + dy[i];
			if (xx < 1 || xx > h || yy < 1 || yy > w || vis[xx][yy] || r[xx][yy] == '#') continue;
			q.push((Node){ f.step + 1, xx, yy });
		}
	}
}

