typedef pair<int, int>P;
const int INF = -1;
int H, W, K;
char A[800][800];
int S_i, S_j;
int G_i, G_j;
int d[800][800];
int dx[4] = { 1, 0, -1, 0 };
int dy[4] = { 0, 1, 0, -1 };
void bfs() {
	queue<P>que;
	rep(i, H)
		rep(j, W)d[i][j] = INF;
		que.push(P(S_i, S_j));
	d[S_i][S_j] = 0;
	while (que.size()) {
		P p = que.front();
		que.pop();
		rep(i, 4) {
			int nx = p.first + dx[i], ny = p.second + dy[i];
			if (0 <= nx&&nx < H && 0 <= ny&&ny < W&&A[nx][ny] != '#'&&d[nx][ny] == INF) {
				que.push(P(nx, ny));
				d[nx][ny] = d[p.first][p.second] + 1;
			}
		}
	}
	return;
}

int main() {
	cin.sync_with_stdio(false);

	cin >> H >> W >> K;


	rep(i, H) {
		rep(j, W) {
			cin >> A[i][j];
			if (A[i][j] == 'S') {
				S_i = i;
				S_j = j;
			}
		}
	}
	int min_d = min(min(S_i, H - 1 - S_i), min(S_j, W - 1 - S_j));
	int ans = 0;
	G_i = S_i;
	G_j = S_j;
	bfs();
	rep(i, H) {
		rep(j, W) {
			if (A[i][j] == '.') {
				int min_d2 = min(min(i, H - 1 - i), min(j, W - 1 - j));
				if (min_d > min_d2&&d[i][j] >= 0&&d[i][j]<=K) {
					min_d = min_d2;
					G_i = i;
					G_j = j;
				}
			}
		}
	}
	ans += d[G_i][G_j] / K;
		if (G_i == S_i && G_j == S_j)ans = 1;
		int dis = min(min(G_i, H - 1 - G_i), min(G_j, W - 1 - G_j))+d[G_i][G_j]%K;
		ans += dis / K;
		if (dis % K)ans++;

		cout << ans << endl;
		return 0;


	return 0;
}

