const int N = int(1e3) + 9, M = N;

char A[N][M]; int d[N][M];
int n, m, k;


int qx[N*M], qy[N*M], cz, op;
bool bfs0(){
    cz = 0, op = 1;
    REP(i, n) REP(j, m){
        if (A[i][j] == 'S'){
            qx[0] = i, qy[0] = j;
            break;
        }
    }

    while (cz < op){
        int x = qx[cz] , y = qx[cz];
        if(d[x][y]>k) return 0;
        if (x == 0 || y == 0 || x == n-1 || y == m-1) return 1;

        REP(i, 4){
            int xx = x + dx[i], yy = y + dy[i];
            if (xx < 0 || yy < 0 || xx > n || yy > m) continue;
            if (A[xx][yy] != '.') continue;
            if (d[xx][yy] != 0) continue;

            d[xx][yy] = d[x][y] + 1;
            qx[op] = xx; qy[op] = yy;
            ++op;
        }
        ++cz;
    }
    return 0;
}

int bfs1(){
    cz = 0, op = 1;
    REP(i, n) REP(j, m){
        if (d[i][j] || A[i][j] == 'S'){
            d[i][j] = 1;
            qx[op] = i, qy[op] = j;
            ++op;
        }
    }
    while (cz < op){
        int x = qx[cz] , y = qx[cz];
      //  cout << x << " " << y << endl;
        if (x == 0 || y == 0 || x == n-1 || y == m-1){
            d[x][y] -= 1;
            if (d[x][y] % k == 0) return 1 + d[x][y]/k;

            return 2+(d[x][y]/k);
        }
        REP(i, 4){
            int xx = x + dx[i], yy = y + dy[i];
            if (xx < 0 || yy < 0 || xx > n || yy > m) continue;
            if (d[xx][yy] != 0) continue;

            d[xx][yy] = d[x][y] + 1;
            qx[op] = xx; qy[op] = yy;
            ++op;
        }
        ++cz;
    }
    return -1;
}


