using namespace std;
using pii = pair<int, int>;

typedef long long llint;

const int MAXN = 810;
const int DR[] = {-1, 1, 0, 0};
const int DC[] = {0, 0, 1, -1};
const int INF = 1e9;

int h, w, k, sol = INF;
char a[MAXN][MAXN];
queue<pii> q;
int dist[MAXN][MAXN], dist2[MAXN][MAXN];

bool in(int r, int c) {
  return r >= 0 && c >= 0 && r < h && c < w;
}

void solve(int sr, int sc) {
  memset(dist, -1, sizeof(dist));
  memset(dist2, -1, sizeof(dist2));

  REP(r, h) REP(c, w)
    if (r == 0 || c == 0 || r == h - 1 || c == w - 1) {
      dist[r][c] = 0;
      q.push({r, c});
    }

  while (!q.empty()) {
    pii x = q.front();
    q.pop();

    REP(i, 4) {
      int nr = x.r + DR[i];
      int nc = x.c + DC[i];

      if (!in(nr,nc)) continue;
      if (dist[nr][nc] == -1) {
	dist[nr][nc] = dist[x.r][x.c] + 1;
	q.push({nr, nc});
      }
    }
  }

  q.push({sr, sc});
  dist2[sr][sc] = 0;

  while (!q.empty()) {
    pii x = q.front();
    q.pop();

    if (dist2[x.r][x.c] > k) break;
    sol = min(sol, 1 + (dist[x.r][x.c] + k - 1) / k);

    REP(i, 4) {
      int nr = x.r + DR[i];
      int nc = x.c + DC[i];

      if (!in(nr,nc) || a[nr][nc] == '#') continue;
      if (dist2[nr][nc] == -1) {
	dist2[nr][nc] = dist2[x.r][x.c] + 1;
	q.push({nr, nc});
      }
    }
  }
}


int main(void) {
  scanf("%d %d %d",&h,&w,&k);
  REP(i, h) scanf("%s",a[i]);

  REP(r, h) REP(c, w)
    if (a[r][c] == 'S')
      solve(r,c);

  printf("%d\n",sol);
  return 0;
}

