    if (sw!=W-1&&A[sh][sw+1]!='#'&&!ok[sh][sw+1]) dfs(sh,sw+1,k);
    if (sw!=0&&A[sh][sw-1]!='#'&&!ok[sh][sw-1]) dfs(sh,sw-1,k);
  }
}

