                bfs b1(b.x-1, b.y, b.dist+1);
                que.push(b1);
            }
            if(check[b.x][b.y+1] == false && A[b.x][b.y+1] != 0 && b.y+1<H){
                bfs b1(b.x, b.y+1, b.dist+1);
                que.push(b1);
            }
            if(check[b.x][b.y-1] == false && A[b.x][b.y-1] != 0 && b.y-1>-1){
                bfs b1(b.x, b.y+1, b.dist+1);
                que.push(b1);
            }
        }
    }
    cout << (res==0 ? 1 : 2 + (res-1)/K) << endl;
    return 0;
}

