int v[4][2]={0,1,1,0,0,-1,-1,0};
bool ok[810][810];
int n,m,k;
int nx,ny;
bool vis[810][810];
int ans=1e9;
void bfs()
{
	queue<pair< pair<int,int > ,int > >q;
	q.push(make_pair(make_pair(nx,ny),0));
	vis[nx][ny]=true;
	while(!q.empty())
	{
		int x=q.front().first.first,y=q.front().first.second,w=q.front().second;
		q.pop();
		int res=x-1;
		res=min(res,n-x);
		res=min(res,y-1);
		res=min(res,m-y);
		if((res+k-1)/k+1<ans)ans=(res+k-1)/k+1;
		if(w==k)continue;
		for(int i=0;i<4;i++)
		{
			int xx=x+v[i][0],yy=y+v[i][1];
			if(xx>0 && xx<=n && yy>0 && yy<=m && ok[xx][yy] && !vis[xx][yy])
			{
				vis[xx][yy]=true;
				q.push(make_pair(make_pair(xx,yy),w+1));
			}
		}
	}
}
int main()
{
	scanf("%d%d%d",&n,&m,&k);
	for(int i=1;i<=n;i++)
	{
		for(int j=1;j<=m;j++)
		{
			char x;
			cin>>x;
			if(x=='.' || x=='S')ok[i][j]=true;
			if(x=='S')
			{
				nx=i;ny=j;
			} 
		}
	}
	bfs();
	printf("%d",ans);
	return 0;
}

