	return max (C (dist), C (blocked));
}

char c[maxn][maxn];

pii dis[maxn][maxn];

struct PII
{
	int dist, blocked, x, y;
	PII (int dist, int blocked, int x, int y) : dist(dist), blocked(blocked), x(x), y(y) {}
};

bool operator < (PII A, PII B)
{
	return (cost (A.dist, A.blocked) < cost(B.dist, B.blocked));
}

bool mrk[maxn][maxn];

int dx[] = {0, 0, -1, 1};
int dy[] = {-1, 1, 0, 0};

void solve (int xini, int yini)
{
	for (int i = 1; i <= n; ++i)
		for (int j = 1; j <= m; ++j)
			dis[i][j] = pii (INF, INF);

	dis[xini][yini] = pii (0, 0);

	multiset <PII> Set;

	Set.insert (PII (0, 0, xini, yini));

	while (!Set.empty())
	{
		int x = Set.begin()->x;
		int y = Set.begin()->y;

		int dist = Set.begin()->dist;
		int blocked = Set.begin()->blocked;

		Set.erase (Set.begin());

		if (mrk[x][y])
			continue;

		mrk[x][y] = true;

		for (int it = 0; it < 4; ++it)
		{
			int X = x + dx[it];
			int Y = y + dy[it];

			if (X <= 0 || Y <= 0 || X > n || Y > m)
				continue;

			if (c[X][Y] == '#')
			{
				debug ("(%d,%d) dist(%d) blocked(%d) %d %d\n", X, Y, dist, blocked, C(blocked + 1), C(dist));
				if (C (blocked + 1) > C (dist))
				{
					debug ("(%d,%d) -> (%d,%d)\n", x, y, X, Y);
					if (cost (dis[X][Y].first, dis[X][Y].second) > cost ((C (blocked + 1) + 1) * k, blocked + 1))
					{
						dis[X][Y] = pii ((C (blocked + 1) + 1) * k, blocked + 1);
						Set.insert (PII ((C (blocked + 1) + 1) * k, blocked + 1, X, Y));
					}
				}
				else
				{
					if (cost (dis[X][Y].first, dis[X][Y].second) > cost (dist + 1, blocked + 1))
					{
						dis[X][Y] = pii (dist + 1, blocked + 1);
						Set.insert (PII (dist + 1, blocked + 1, X, Y));
					}
				}
			}
			else
			{
				if (cost (dis[X][Y].first, dis[X][Y].second) > cost (dist + 1, blocked))
				{
					dis[X][Y] = pii (dist + 1, blocked);
					Set.insert (PII (dist + 1, blocked, X, Y));
				}
			}
		}
	}
}

int ans = INF;

void get ()
{
	for (int i = 1; i <= n; ++i)
	{
		for (int j = 1; j <= m; ++j)
			debug ("(%d,%d) %d", dis[i][j].first, dis[i][j].second, cost (dis[i][j].first, dis[i][j].second));
		debug ("\n");
	}

	for (int i = 1; i <= n; ++i)
	{
		ans = min (ans, cost (dis[i][1].first, dis[i][1].second));
		ans = min (ans, cost (dis[i][m].first, dis[i][m].second));
	}

	for (int j = 1; j <= m; ++j)
	{
		ans = min (ans, cost (dis[1][j].first, dis[1][j].second));
		ans = min (ans, cost (dis[n][j].first, dis[n][j].second));
	}
}

