    if (lock_h(y-(((y-1)%k)+1),y-1,x)) tmp++;
    res=min(res,tmp);
    int yy=w-1-y;
    tmp=(yy-1)/k+1;
    if (lock_h(y+1,y+((yy-1)%k)+1,x)) tmp++;
    res=min(res,tmp);
