using ll = long long;
using P = std::pair<ll, ll>;

const ll di[4] = { 0, 1, 0, -1 }, dj[4] = { 1, 0, -1, 0 };
const ll INF = 1ll<<60;

ll H, W, K;
std::string A[1000];
std::queue<P> que;
ll dist[1000][1000];
ll ans = INF;
ll gi, gj;

void bfs( bool all )
{
  while( !que.empty() )
  {
    P st = que.front();
    ll i = st.first, j = st.second;

    que.pop();

    if( !i || !j || i == H-1 || j == W-1 )
    {
      gi = i;
      gj = j;

      break;
    }

    if( !all && dist[i][j] == K )
      continue;

    rep( d, 4 )
    {
      ll ni = i+di[d], nj = j+dj[d];

      if( ni >= 0 && ni < H && nj >= 0 && nj < W && (all || A[ni][nj] != '#') && dist[ni][nj] > dist[i][j]+1 )
      {
        dist[ni][nj] = dist[i][j]+1;
        que.push( P( ni, nj ) );
      }
    }
  }

  return;
}

ll si, sj;

int main()
{
  std::cin >> H >> W >> K;

  rep( i, H )
  {
    std::cin >> A[i];

    rep( j, W ) if( A[i][j] == 'S' )
      si = i, sj = j;
  }

  que.push( P( si, sj ) );

  rep( i, H ) rep( j, W )
    dist[i][j] = INF;

  dist[si][sj] = 0;

  bfs( false );

  rep( i, H ) rep( j, W )
  {
    if( dist[i][j] != INF )
    {
      dist[i][j] = K;

      que.push( P( i, j ) );
    }
  }

  bfs( true );

  std::cout << (dist[gi][gj]+K-1)/K << std::endl;

  return 0;
}

