const int INF = 1e9;
bool contain(int y, int x){
    return (0 <= y && y < h && 0 <= x && x < w);
}

signed main(){
    cin >> h >> w >> k;
    rep(i, 0, h) cin >> s[i];
    rep(i, 0, h) rep(j, 0, w){
        if(s[i][j] == 'S'){
            sy = i; sx = j; break;
        }
    }
    rep(i, 0, h){
        rep(j, 0, w){
            int tmp = min(i, min(j, min(h - i, w - j)));
            d[i][j] = tmp;
        }
    }
    int MIN = (d[sy][sx] + k - 1) / k + 1;
    int kd = k - (d[sy][sx] % k);
    queue<P> q;
    q.push(P(sy, sx));
    rep(i, 0, h) rep(j, 0, w) dist[i][j] = INF;
    dist[sy][sx] = 0;
    // cout << sy << " " << sx << endl;
    while(!q.empty()){
        P p = q.front(); q.pop();
        int y = p.first;
