            // cout << ny << " " << nx << " " << d[ny][nx] << " " << dist[ny][nx] << endl;
            if(dist[ny][nx] == kd) MIN = min(MIN, (dist[ny][nx] + k - 1) / k + 1);
            if(s[ny][nx] == '#') MIN = min(MIN, (dist[ny][nx] + k - 1) / k + 1);
            else if(d[ny][nx] == 0) MIN = min(MIN, (int)1);
            // MIN = min(MIN, (d[ny][nx] + dist[ny][nx] + k - 1) / k + (s[ny][nx] == '#' ? 1 : 0));  
            if(s[ny][nx] == '#') continue;
            q.push(P(ny, nx));
        }
    }
    cout << MIN << endl;
}

