string s;



// k が条件を満たすかどうか
bool isOK(int k) {
    int L = (int)s.length();
    int freedom = L - k;
    int left = freedom, right = L - freedom;
    char cmp = s[left];
    for (int i = left; i < right; i++) {
        if (cmp != s[i]) {
            return false;
        }
    }

    return true;
}

// 汎用的な二分探索のテンプレ(めぐる式)
int binary_search() {
    int ng = (int)s.length() + 1; 
    int ok = 1; 

    /* ok と ng のどちらが大きいかわからないことを考慮 */
    while (abs(ok - ng) > 1) {
        int mid = (ok + ng) / 2;

        if (isOK(mid)) ok = mid;
        else ng = mid;
    }
    return ok;
}

