int H, W, K;
int ans = LL_HALFMAX;

char mapData[1000][1000];
int visited[1000][1000];
int dist[1000][1000];

class Node {
public:
    int x, y, dest;
    Node(int inX, int inY, int dst) {
        x = inX;
        y = inY;
        dest = dst;
    }
};


signed main() {

    cin >> H >> W >> K;

    int sx, sy;

    rep(i, H) {
        rep(j, W) {
            cin >> mapData[i][j];
            int xAxis = min(j, W - 1 - j);
            int yAxis = min(i, H - 1 - i);
            dist[i][j] = min(xAxis, yAxis);
            if (mapData[i][j] == 'S') {
                sx = j;
                sy = i;
            }
        }
    }
    queue<Node> q;
    Node init(sx, sy, 0);
    q.push(init);
    while (!q.empty()) {
        Node open = q.front();
        q.pop();
        if (open.x < 0) continue;
        if (open.y < 0) continue;
        if (open.x >= W) continue;
        if (open.y >= H) continue;
        if (visited[open.y][open.x]) continue;
        if (mapData[open.y][open.x] == '#') continue;
        visited[open.y][open.x] = 1;

        int dst = open.dest;
        if (dst <= K) {
            ans = min(ans, dist[open.y][open.x]);
        }
        q.push(Node(open.x + 1, open.y, dst + 1));
        q.push(Node(open.x - 1, open.y, dst + 1));
        q.push(Node(open.x, open.y + 1, dst + 1));
        q.push(Node(open.x, open.y - 1, dst + 1));
    }


    ans = ans % K == 0 ? ans / K : ans / K + 1;
    cout << ans + 1 << "\n";

    return 0;
}

