int main(){
	int h, w, k;
	scanf("%d %d %d", &h, &w, &k);
	int sx, sy;
	bool fie[h][w];
	getchar();
	rep(i, 0, h){
		rep(j, 0, w){
			char c = getchar();
			if(c=='S') sx=i, sy=j;
			fie[i][j] = (c=='#');
		}
