		ll d = que.front().fi;
		P p = que.front().se;
		que.pop();
		if(fie[p.fi][p.se]) continue;
		fie[p.fi][p.se] = true;
		ll cost = std::min({p.fi, h-p.fi-1, p.se, w-p.se-1});
		ans = std::min(ans, std::max(1l,(d+k-1)/k) + (cost+k-1)/k);
