		rep(i, 0, 4){
			ll nx = p.fi+dx[i], ny = p.se+dy[i];
			if(!fie[nx][ny]) que.emplace(d+1, P(nx, ny));
		}
	}
	printf("%ld\n", ans);
	return 0;
}

