  bfs(i+1,j,d+1);
  bfs(i,j-1,d+1);
  bfs(i,j+1,d+1);
  return;
}


int main() {


  cout<<fixed<<setprecision(10);

  cin>>H>>W>>K;

  rep(i,H)rep(j,W) cin>>A[i][j];
  rep(i,H)rep(j,W) dist[i][j] = K+1;

  ll si, sj;
  si = -1;
  sj = -1;
  rep(i,H)rep(j,W){
    if(A[i][j] == 'S'){
      si = i; sj = j;
      break;
    }
  }

  assert(!(si == -1 && sj == -1));

  bfs(si, sj, 0);

  // rep(i,H){
