  //   }
  //   cout<<endl;
  // }

  ll dmin = H*W;

  repf(i,1,H-1){
    // down
    ll cnt = 0;
    ll j = 0;
    while( (j <= W-1) && (dist[i][j] > K) ){
      cnt++;
      j++;
    }
    chmin(dmin, cnt);

    // up
    cnt = 0;
    j = W-1;
    while( (j >= 0) && (dist[i][j] > K) ){
      cnt++;
      j--;
    }

    chmin(dmin, cnt);
  }

  repf(j,1,W-1){
    // right
    ll cnt = 0;
    ll i = 0;
    while( (i <= H-1) && (dist[i][j] > K) ){
      cnt++;
      i++;
    }
    chmin(dmin, cnt);

    // left
    cnt = 0;
    i = H-1;
    while( (i >= 0) && (dist[i][j] > K) ){
      cnt++;
      i--;
    }

    chmin(dmin, cnt);
  }

  ll ans = 1 + (dmin + K - 1)/K;
  cout<<ans<<endl;
}




