			if(s[a][b] == '#')	continue;
			if(vis[a][b] != -1)	continue;
			vis[a][b] = vis[p.first][p.second] + 1;
			Q.push(make_pair(a, b));
		}
    }

    for(int i=0; i<n; i++){
		for(int j=0; j<m; j++){
			if(vis[i][j] != -1){
				vis[i][j] = K;
				Q.push(make_pair(i, j));
			}
		}
    }

    while(!Q.empty()){
		pii p = Q.front(); Q.pop();
		if(ok(p.first, p.second)){
			int ans = vis[p.first][p.second];
			if(ans % K == 0){
				return ans / K;
			} else {
				return ans / K + 1;
			}
		}
		for(int i=0; i<4; i++){
			int a = p.first + xl[i];
			int b = p.second + yl[i];
			if(a<0 || a>=n || b<0 || b>=m)	continue;
			if(vis[a][b] != -1)	continue;
			vis[a][b] = vis[p.first][p.second] + 1;
			Q.push(make_pair(a, b));
		}
    }
}

