			if(g[at.fi+dx[i]][at.se+dy[i]]=='.'&&dist[at.fi+dx[i]][at.se+dy[i]]>dist[at.fi][at.se]+1) {
				dist[at.fi+dx[i]][at.se+dy[i]]=dist[at.fi][at.se]+1;
				bfs.push({at.fi+dx[i],at.se+dy[i]});
			}
		}
	}
	fr(i,1,n) {
		fr(j,1,m) {
			if(dist[i][j]<=k) {
				ans=min(ans,1+(i+k-1)/k);
				ans=min(ans,1+(j+k-1)/k);
				ans=min(ans,1+(n-i+k-1)/k);
				ans=min(ans,1+(m-j+k-1)/k);
			}
		}
	}
	cout<<ans<<endl;
}
