        scanner >> A[i];
        repeat(j, W) {
            if (A[i][j] == 'S') {
                start.y = i;
                start.x = j;
                A[i][j] = '.';
                break;
            }
        }
    }

    fill(dp[0], dp[H], int(1e9));

    dp[start.y][start.x] = 0;

    queue<P> que;
    que.emplace(start);

    int best = 1e9;

    while (!que.empty()) {
        P p = que.front();
        que.pop();

        if (p.y == 0 || p.x == 0 || p.y == H - 1 || p.x == W - 1) {
            break;
        }

        int currcost = dp[p.y][p.x];

        for (auto mv : FourMoving) {
            P p2 = p + mv;
            int c = currcost + 1;
            if (A[p2.y][p2.x] == '#') continue;

            if (dp[p2.y][p2.x] > c) {
                dp[p2.y][p2.x] = c;
