				if (i > 1 && pat[i-1][j] != '#') {
					AddEdge(id(i,j), id(i-1,j));
				}
				if (j > 1 && pat[i][j-1] != '#') {
					AddEdge(id(i,j), id(i,j-1));
				}
			} 
			if (pat[i][j] == 'S') {
				S = id(i, j);		
			}
		}
	} 
	Dijkstra();
	int ans = INF;
