		return 0;
	return 1;	
}
int t[6][4]={{0,1},{0,-1},{1,0},{-1,0}};
void bfs(int x,int y){
	vis[x][y]=1;
	q.push(Mkp(x,y));
	while(!q.empty()){
		pii newq=q.front();
		q.pop();
		if(dist[newq.first][newq.second]==k)
			break;
		for(int i=0;i<4;i++){
			int xx=newq.first+t[i][0];
			int yy=newq.second+t[i][1];
			if(allow(xx,yy)==0)
				continue;
			vis[xx][yy]=1;
			dist[xx][yy]=dist[newq.first][newq.second]+1;
			q.push(Mkp(xx,yy));
		}
	}
}
int mindist(int x,int y){
	return min(min((x+k-2)/k,(y+k-2)/k),min((h-x+k-1)/k,(w-y+k-1)/k));	
}
