void bfs(vector<pair<int , int> > src)
{
    for(int i = 0; i < n; i++)
        for(int j = 0; j < m; j++)
        {
            d[i][j] = -1;
        }
    h = t = 0;
    for(auto x : src)
        d[x.first][x.second] = 0 , q[h++] = {x.first , x.second};
    while(t < h)
    {
        int x = q[t].first , y = q[t++].second;
        if(is(x + 1 , y))
        {
            if(d[x + 1][y] == -1)
            {
                d[x + 1][y] = d[x][y] + 1;
                q[h++] = {x + 1 , y};
            }
        }
        if(is(x - 1 , y))
        {
            if(d[x - 1][y] == -1)
            {
                d[x - 1][y] = d[x][y] + 1;
                q[h++] = {x - 1 , y};
            }
        }
        if(is(x , y + 1))
        {
            if(d[x][y + 1] == -1)
            {
                d[x][y + 1] = d[x][y] + 1;
                q[h++] = {x , y + 1};
            }
        }
        if(is(x , y - 1))
        {
            if(d[x][y - 1] == -1)
            {
                d[x][y - 1] = d[x][y] + 1;
                q[h++] = {x , y - 1};
            }
        }
    }
}
void bffs(int x , int y)
{
    for(int i = 0; i < n; i++)
        for(int j = 0; j < m; j++)
            d[i][j] = -1;
    d[x][y] = 0;
    q[h++] = {x , y};
    while(t < h)
    {
        int x = q[t].first , y = q[t++].second;
        if(is(x + 1 , y , 1))
        {
            if(d[x + 1][y] == -1)
            {
                d[x + 1][y] = d[x][y] + 1;
                q[h++] = {x + 1 , y};
            }
        }
        if(is(x - 1 , y , 1))
        {
            if(d[x - 1][y] == -1)
            {
                d[x - 1][y] = d[x][y] + 1;
                q[h++] = {x - 1 , y};
            }
        }
        if(is(x , y + 1 , 1))
        {
            if(d[x][y + 1] == -1)
            {
                d[x][y + 1] = d[x][y] + 1;
                q[h++] = {x , y + 1};
            }
        }
        if(is(x , y - 1 , 1))
        {
            if(d[x][y - 1] == -1)
            {
                d[x][y - 1] = d[x][y] + 1;
