const int INF = 1<<29;

int dx[4]={1,0,-1,0};
int dy[4]={0,1,0,-1};

void solve(void){
	int H, W, K;
	cin >> H >> W >> K;
	vector <vector <char>> maze(H, vector <char> (W));
	vector <vector <int>> step(H, vector <int> (W, INF));
	intP s;
	rep(H, i) rep(W, j) {
		cin >> maze[i][j];
		if (maze[i][j] == 'S') {
			s.fst = i, s.snd = j;
		}
	}
	queue <intP> q;
	step[s.fst][s.snd] = 0;
	q.push(s);
	while (!q.empty()) {
		intP n = q.front(); q.pop();
		rep(4, d) {
			int y = n.fst + dy[d], x = n.snd + dx[d];
			if (0 <= x && x < W && 0 <= y && y < H) {
				if (maze[y][x] == '.' && step[y][x] == INF) {
					step[y][x] = step[n.fst][n.snd] + 1;
					q.push(intP(y, x));
				}
			}
		}
	}
	int ans = INF;
	rep(H, i) rep(W, j) {
		if (step[i][j] == INF) continue;
		int cost = max((step[i][j] - 1) / K, 0);
		if (i == 0 || j == 0 || i == H - 1 || j == W - 1) {
			ans = min(ans, cost + 1);
			continue;
		}
		cost += (min(min(i, j), min(H - i - 1, W - j - 1)) + K - 1) / K;
		ans = min(ans, cost + 1);
	}
	cout << ans << endl;

}

int main(void){
	solve();
	//cout << "yui(*-v・)yui" << endl;
	return 0;
}

