int main () {
	bool check = true;
	cin >> M >> N >> K;
	for (int i = 0; i < M; i++) {
		cin >> rooms[i];
		if (check) {
			for (int j = 0; j < N; j++) {
				if (rooms[i][j] == 'S') {
					bx = i;
					by = j;
					rooms[i][j] == '.';
					check = false;
				}
			}
		}
	}
