const int dx[4] = {1, 0, -1, 0};
const int dy[4] = {0, 1, 0, -1};
int H, W;

class Coord {
    public:
        int y, x, k;
        vector<Coord> nextCoord;

        Coord(int i, int j, int _k) {
            y = i;
            x = j;
            k = _k;
        }
        void setNextCoord() {
            for (int i=0; i<4; i++) {
                if (y+dy[i] < 0 || H <= y+dy[i]) continue;
                if (x+dx[i] < 0 || W <= x+dx[i]) continue;
                nextCoord.push_back(Coord(y+dy[i], x+dx[i], k+1));
            }
        }
        int hash() { return y*W + x; }
        int length() { return min(min(y, H-y), min(x, W-x)); }
};

int main() {
    int K; cin >> H >> W >> K;
    vector<vector<char> > A(H, vector<char>(W, '#'));

    set<int> st;
    queue<Coord> que;
    for (int i=0; i<H; i++) {
        for (int j=0; j<W; j++) {
            cin >> A[i][j];
            if (A[i][j] == 'S') que.push(Coord(i, j, 0));
        }
    }

    int minLength = 801;
    while (!que.empty()) {
        Coord c = que.front(); que.pop();
        st.insert(c.hash());
        c.setNextCoord();
        minLength = c.length() < minLength ? c.length() : minLength;

        for (Coord nc : c.nextCoord) {
            if (st.find(nc.hash()) != st.end()) continue;
            if (nc.k > K) continue;
            if (A[nc.y][nc.x] == '#') continue;
            que.push(nc);
        }
    }

    cout << 1 + (minLength+K-1)/K << endl;
    return 0;
}

