struct XY {
  int x, y;
  XY&operator+=(const XY&d) { x += d.x; y += d.y; return *this; }
  XY operator+(const XY&d)const { return XY(*this) += d; }
  bool operator==(const XY&d)const { return x == d.x && y == d.y; }
  bool check(int w, int h)const { return 0 <= x && x < w && 0 <= y && y < h; }
};
const XY d4[] = { { -1,0 },{ 1,0 },{ 0,-1 },{ 0,1 }, };
template<class T> auto get(T& a, XY d)->decltype(a[d.y][d.x]) { return a[d.y][d.x]; }
ostream& operator<<(ostream& os, XY d) { return os << '(' << d.x << ',' << d.y << ')'; }


const int INF = 1e9 - 1;
auto v = nvec(0, 0);
auto a = nvec<string>(0);
int h, w, k;
int dfs(queue<pair<XY, int>>& q, XY pos, int cost, int k) {
  int res = INF;
  if (k < 0)return res;
  for (auto& i : d4) {
    auto n = i + pos;
    if (n.check(w, h)) {
      if (v[n.y][n.x] > cost) {
        if (a[n.y][n.x] != '#') {
          v[n.y][n.x] = cost;
          q.push({ n, cost });
          amin(res, dfs(q, n, cost, k - 1));
        }
        else {
          q.push({ pos, cost });
        }
        a[n.y][n.x] = 'A';
      }
    }
    else {
      return cost;
    }
  }
  return res;
}
void Calc() {
  in, h, w, k;
  a = in.Array<string>(h);

  v = nvec(h, w, Init(INF));

  queue<pair<XY, int>> q;
  {
    XY pos;
    rep(i, h)rep(j, w)if (a[i][j] == 'S') {
      pos.x = j;
      pos.y = i;
      break;
    }

    q.push({ pos,0 });
  }
  int mini = INF;
  while (q.size()) {
    auto p = q.front();
    q.pop();
    auto pos = p.first;
    auto cost = p.second;
    amin(mini, dfs(q, pos, cost + 1, k));
  }
  cout << (mini) << endl;


  err(a);
}

