void check(int x,int y)
{
	ans = min(ans,1 + min((x + k - 1) / k,(H - x + k - 1) / k));
	ans = min(ans,1 + min((y + k - 1) / k,(W - y + k - 1) / k));
}

void bfs(int x,int y,int z)
{
	if (z > k) return;
	check(x,y);
	dis[x][y] = z;
	int xx,yy;
	for (int i = 0;i < 4; ++i)
		{
			xx = x + dx[i];
			yy = y + dy[i];
			if (xx >= 1&&xx <= H&&yy >= 1&&yy <= W)
				if (dis[xx][yy] == inf&&s[xx][yy] !='#')
					bfs(xx,yy,z + 1);
		}
}

