void  bfs(int x, int y, int d) {
  if(d > k) return; 
  used[y][x] = true;
  for(int i = 0; i < 4; i++) {
    int nx = x + dx[i], ny = y + dy[i];

    if(!used[ny][nx] && nx >= 0 && nx < w && ny >= 0 && ny < h && maze[ny][nx] != '#') {
      bfs(nx,ny,d+1);
      check(nx,ny);
      // cout << nx <<"   " << ny <<endl;
    }
  }
  return;
}


