char g[MAXN][MAXN];
int dist[MAXN][MAXN];
struct State
{
    int x,y;
    State(int x=0,int y=0):x(x),y(y){}
};
bool inRange(int x,int y)
{
    return (x>=0&&y>=0&&x<n&&y<m);
}
void bfs(int bx,int by)
{
    queue<State> q;
    while(!q.empty()) q.pop();
    q.push(State(bx,by));
    dist[bx][by]=0;
    while(!q.empty())
    {
        State u=q.front();
        q.pop();
        for (int i=0;i<4;i++)
        {
            int tx=u.x+dir[i][0],ty=u.y+dir[i][1];
            if (inRange(tx,ty)&&dist[tx][ty]==-1&&g[tx][ty]=='.')
            {
                dist[tx][ty]=dist[u.x][u.y]+1;
                q.push(State(tx,ty));
            }
        }
    }
}
int main()
{
    cin >> n >> m >> k;
    int bx=0,by=0,ans=INT_MAX;
    for (int i=0;i<n;i++)
    {
        for (int j=0;j<m;j++)
        {
            cin >> g[i][j];
            if (g[i][j]=='S')
            {
                bx=i;
                by=j;
                g[i][j]='.';
            }
        }
    }
