const int MAXN = 800 + 50;
char f[MAXN + 1][MAXN + 1];
int d[MAXN + 1][MAXN + 1], n, m, k, mv[4][2] = { { -1, 0 }, { 1, 0 }, { 0, -1 }, { 0, 1 } }, calc, used[MAXN + 1][MAXN + 1];

bool valid(int x, int y) {
    return 1 <= x && x <= n && 1 <= y && y <= m;
}

bool win(int x, int y) {
    return (x == 1) || (x == n) || (y == 1) || (y == m);
}

void go(vector<pair<int, int> >& v) {
    deque<pair<int, int> > q;
    vector<vector<int> > dist(n + 1);
    for(int i = 1; i <= n; i++)
        dist[i].assign(m + 1, -1);
    for(auto it: v) {
        q.push_back(it);
        dist[it.first][it.second] = 0;
    }
    while(!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        if(dist[x][y] == k)
            break;
        q.pop_front();
        for(int i = 0; i < 4; i++) {
            int dx = x + mv[i][0];
            int dy = y + mv[i][1];
            if(valid(dx, dy) && d[dx][dy] == -1 && dist[dx][dy] == -1) {
                dist[dx][dy] = dist[x][y];
                int ok = 0;
                if(f[dx][dy] == '#')
                    f[dx][dy] = '.', ok = 1;
                dist[dx][dy] += ok;
                if(!ok)
                    q.push_front({ dx, dy });
                else
                    q.push_back({ dx, dy });
            }
        }
    }
}

