    for(int i = 1; i <= n; i++) {
        for(int j = 1; j <= m; j++) {
            cin >> f[i][j];
            if (f[i][j] == 'S')
                a = i, b = j;
            d[i][j] = -1;
        }
    }
    queue<pair<int, int> > q;
    q.push({ a, b });
    d[a][b] = 0;
    int cur = k, ans = 1;
    vector<pair<int, int> > was;
    while(!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        if(win(x, y)) {
            cout << ans << "\n";
            return 0;
        }
        was.push_back({ x, y });
        q.pop();
        if(d[x][y] == cur) {
            go(was);
            cur += k;
            ans++;
            for(auto it: was)
                q.push(it);
            was.clear();
        }
        for(int i = 0; i < 4; i++) {
            int dx = x + mv[i][0];
            int dy = y + mv[i][1];
