		int y = cur.first;
		if(d[y][x] == k) continue;
		rep(i, 0, 4){
			int nx = x + dx[i];
			int ny = y + dy[i];
			if(canMove(ny, nx) && !was[ny][nx]){
				d[ny][nx] = 1 + d[y][x];
				was[ny][nx] = 1;
				q.pb(mp(ny, nx));
			}
		}
	}

	int ans = INF;

	rep(i, 0, h) rep(j, 0, w) if(was[i][j]){
		ans = min(ans, 1 + calc(i, j));
	}

	cout << ans << endl;

}

