void dfs1(pii croom, int lefts) {
	if (lefts == 0) return;
//	cout << "\n\n" << lefts;
//	dsp();
	if (vis[croom.first][croom.second]) {
		return;
	} else {
		vis[croom.first][croom.second] = true;
		steps[croom.first][croom.second] = 1;
		Q.push(croom);
	}
	for (int i = 0; i < 4; i++) {
		pii nroom = croom;
		nroom.first += dx[i];
		nroom.second += dy[i];
		if (brd[nroom.first][nroom.second]) {
			dfs1(nroom, lefts - 1);
		}
	}
}

void dfs2(pii croom, int lefts, int val) {
	if (lefts == 0) return;
//	dsp();
	for (int i = 0; i < 4; i++) {
		pii nroom = croom;
		nroom.first += dx[i];
		nroom.second += dy[i];
		if (nroom.first < 0 || nroom.first >= H || nroom.second < 0 || nroom.second >= W) continue;
//		if (vis[nroom.first][nroom.second]) continue;
//		vis[nroom.first][nroom.second] = true;
		if (steps[nroom.first][nroom.second] < val) continue;
		steps[nroom.first][nroom.second] = val;
		Q.push(nroom);
		dfs2(nroom, lefts - 1, val);
	}
}

