		if(nowy==0 or nowx==0 or nowy==H-1 or nowx==W-1) return (K-1+minium[nowy][nowx])/K;
		if(minium[nowy][nowx]==K+1) continue;
		REP(i,4){
			int ny=nowy+dy[i],nx=nowx+dx[i];
			if(maps[ny][nx]==0) minium[ny][nx]=K+1;
			else if(minium[ny][nx]>minium[nowy][nowx]+1){
				minium[ny][nx]=minium[nowy][nowx]+1;
				qu.push(pr(ny,nx));
			}
		}

	}
	REP(i,H) REP(j,W){
		if(minium[i][j]==K+1) qu.push(pr(i,j));
	}
	while(!qu.empty()){
		int nowx=qu.front().second,nowy=qu.front().first;
		qu.pop();
