using namespace std;

#define MAX 810
int H,W,K;
string A[MAX];
int mini[MAX][MAX];
int dx[] = {0,1,0,-1};
int dy[] = {1,0,-1,0};

bool isValid(int x,int y) { return 0 <= x && x < W && 0 <= y && y < H; }

struct Data {
  int x,y,v;
  bool operator < ( const Data &data ) const {
    if( v != data.v ) return v > data.v;
    if( x != data.x ) return x > data.x;
    return y > data.y;
  }
};

void compute() {
  priority_queue<Data> Q;
  rep(i,H) rep(j,W) mini[i][j] = INT_MAX;
  {
    int sx=-1,sy;
    rep(i,H) rep(j,W) if( A[i][j] == 'S' ) {
      A[i][j] = '.';
      sx = j, sy = i;
      mini[i][j] = 0;
      goto Skip;
    }
  Skip:
    assert( sx != -1 );
    Q.push((Data){sx,sy,0});
  }
  while( !Q.empty() ) {
    Data data = Q.top(); Q.pop();
    rep(i,4) {
      int nx = data.x + dx[i];
      int ny = data.y + dy[i];
      if( !isValid(nx,ny) ) continue;
      int nv = data.v;
      if( A[ny][nx] == '#' ) ++nv;
      if( mini[ny][nx] > nv ) {
	mini[ny][nx] = nv;
	Q.push((Data){nx,ny,nv});
      }
    }
  }
  int ans = INT_MAX;
  rep(i,H) {
    int cost = ceil(mini[i][0]/(double)K)+1;
    ans = min(ans,cost);
    cost = ceil(mini[i][W-1]/(double)K)+1;
    ans = min(ans,cost);
  }
  rep(i,W) {
    int cost = ceil(mini[0][i]/(double)K)+1;
    ans = min(ans,cost);
    cost = ceil(mini[H-1][i]/(double)K)+1;
    ans = min(ans,cost);
  }
  cout << ans << endl;
}

int main() {
  cin >> H >> W >> K;
  rep(i,H) cin >> A[i];
  compute();
  return 0;
}

