void bfs(ll h,ll w, ll count) {
	queue<tuple<ll,ll,ll>> Q;
	Q.push(mt(h,w,count));
	D[h][w] = 0;
	tuple<ll,ll,ll> u;
	while (!Q.empty()) {
		u = Q.front();
		Q.pop();
		ll p = get<0>(u);
		ll q = get<1>(u);
		ll c = get<2>(u);
		if (p == 0 || p == H-1) ans = min(ans, (D[p][q]-1)/K+1+magic);
		else if (q == 0 || q == W-1) ans = min(ans, (D[p][q] - 1) / K + 1+magic);
		else {
			ll np, nq;
			np = p + 1; nq = q;
			if (D[p][q] + 1 < D[np][nq]) {
				if (A[np][nq] == '.') {
					Q.push(mt(np, nq, c)); D[np][nq] = D[p][q]++;
				}
				else if (c + 1 <= magic * K) {
					Q.push(mt(np, nq, c + 1)); D[np][nq] = D[p][q]++;
				}
			}
			np = p - 1; nq = q;
			if (D[p][q] + 1 < D[np][nq]) {
				if (A[np][nq] == '.') {
					Q.push(mt(np, nq, c)); D[np][nq] = D[p][q]++;
				}
				else if (c + 1 <= magic * K) {
					Q.push(mt(np, nq, c + 1)); D[np][nq] = D[p][q]++;
				}
			}
			np = p; nq = q+1;
			if (D[p][q] + 1 < D[np][nq]) {
				if (A[np][nq] == '.') {
					Q.push(mt(np, nq, c)); D[np][nq] = D[p][q]++;
				}
				else if (c + 1 <= magic * K) {
					Q.push(mt(np, nq, c + 1)); D[np][nq] = D[p][q]++;
				}
			}
			np = p; nq = q-1;
			if (D[p][q] + 1 < D[np][nq]) {
				if (A[np][nq] == '.') {
					Q.push(mt(np, nq, c)); D[np][nq] = D[p][q]++;
				}
				else if (c + 1 <= magic * K) {
					Q.push(mt(np, nq, c + 1)); D[np][nq] = D[p][q]++;
				}
			}
		}
	}
}
