	ok[h][w] = true;
	int dist = K - (std::abs(w - sx) + std::abs(h - sy)) - 1;
	func(h - 1, w, dist);
	func(h + 1, w, dist);
	func(h, w - 1, dist);
	func(h, w + 1, dist);
}

