		REP(j,M)
		{
			if(dis[i][j] > K) continue;
			int res = 1e9;
			minn(res,nceil(i,K));
			minn(res,nceil(j,K));
			minn(res,nceil(N-i-1,K));
			minn(res,nceil(M-j-1,K));
			minn(ans,res+1);
		}

	cout << ans << endl;

	return 0;
}

