const ll MAX_V = 801 * 801;

class dijkstra {
public:

    struct edge {
        ll to;
        ll cost;
    };

    vector<edge> E[MAX_V];
    ll d[MAX_V];

    void calc(ll s) {
        priority_queue <pll, vector<pll>, greater<pll> > que;
        rep(i, MAX_V) d[i] = LINF; //INF
        que.emplace(0LL, s);
        d[s] = 0LL;
        while (!que.empty()) {
            pll p = que.top();
            que.pop();
            ll v = p.second;
            if (d[v] < p.first) continue;

            for (auto&& e : E[v]) {
                if (d[e.to] > d[v] + e.cost) {
                    d[e.to] = d[v] + e.cost;
                    que.emplace(d[e.to], e.to);
                }
            }
        }
    }
};

inline ll CEIL(ll a, ll b) {
    return (a + b - 1) / b;
}

