            ds.E[i * h + j].push_back({i * h + j + 1, 1});
            ds.E[i * h + j + 1].push_back({i * h + j, 1});
        }
    }

    rep(i, h - 1) rep(j, w) {
        if ((a[i][j] == '.' || a[i][j] == 'S')
                && (a[i + 1][j] == '.' || a[i + 1][j] == 'S')) {
            ds.E[i * h + j].push_back({(i + 1) * h + j, 1});
            ds.E[(i + 1) * h + j].push_back({i * h + j, 1});
