	pll S;
	for (i = 0; i < H; i++){
		string row;
		cin >> row;
		for (j = 0; j < W; j++){
			if (row[j] == 'S'){
				S.first = i;
				S.second = j;
			}
		}
		A.push_back(row);
	}
	vector<vector<ll>> M;
	vll tmp(W, INF);
	for (i = 0; i < H; i++){
		M.push_back(tmp);
	}
