	for (k = 0; k < K; k++){
		vector<pll> nexts(0);
		while (!nows.empty()){
			pll now = nows.back();
			nows.pop_back();
			if (now.second - 1 >= 0){
				if (A[now.first][now.second - 1] != '#' && M[now.first][now.second-1]==INF){
					M[now.first][now.second - 1] = step;
					pll next(now.first, now.second - 1);
					nexts.push_back(next);
