	ll min_dist = H + W;
	for (i = 0; i < H; i++){
		for (j = 0; j < W; j++){
			if (M[i][j] < INF){
				min_dist = min(min_dist, min(min(i, j), min(H - i - 1, W - j - 1)));
			}
		}
	}
	if (min_dist == 0){
		cout << 1 << endl;
	}
