    int x,y,dis;
};

void bfs(int x,int y,int dis) {
    vis[x][y]=true;
    ans=min(ans,foo(x,y));
    queue<node> q;
    q.push({x,y,0});
    while (!q.empty()) {
        node cur=q.front();
        q.pop();
        if (vis[cur.x][cur.y]) continue;
        vis[cur.x][cur.y]=1;
        if (cur.dis>0) ans=min(ans,foo(cur.x,cur.y)+1);
        for (int i=-1;i<=1;i++) {
