template <typename Checker>
std::vector<std::vector<int>> bfs_grid(const int H, const int W,
                                       const std::vector<Point> &start_points,
                                       const std::vector<Point> &dir,
                                       const Checker &check_passable)
{
  std::vector<std::vector<int>> dist(H, std::vector<int>(W, -1));
  std::vector<std::vector<bool>> visited(H, std::vector<bool>(W));

  std::queue<Point> q;
  for(auto &p : start_points){
    dist[p.x][p.y] = 0;
    q.push(p);
  }

  while(not q.empty()){
    auto cur = q.front(); q.pop();

    if(visited[cur.x][cur.y]) continue;
    visited[cur.x][cur.y] = true;

    for(auto &d : dir){
      auto nxt = cur + d;

      if(nxt.x < 0 or nxt.x >= H or nxt.y < 0 or nxt.y >= W or not check_passable(nxt)) continue;

      if(dist[nxt.x][nxt.y] == -1){
        dist[nxt.x][nxt.y] = dist[cur.x][cur.y] + 1;
        q.push(nxt);
      }else{
        if(dist[nxt.x][nxt.y] > dist[cur.x][cur.y] + 1){
          dist[nxt.x][nxt.y] = dist[cur.x][cur.y] + 1;
          q.push(nxt);
        }
      }
    }
  }

  return dist;
}

template <typename T, typename Func>
vector<Point> find(const vector<T> &a, const Func &f){
  vector<Point> ret;

  int H = a.size();
  int W = a[0].size();

  REP(i,H){
    REP(j,W){
      if(f(a[i][j])){
        ret.emplace_back(i, j);
      }
    }
  }

  return ret;
}



int main(){
  int H, W, K;
  while(cin >> H >> W >> K){
    vector<string> A(H); cin >> A;

    auto dist = bfs_grid(H, W, find(A, [](char c){return c == 'S';}), grid::dir4, [&](const auto &p){return A[p.x][p.y] != '#';});

    int ans = INT_MAX;

    REP(i,H){
      REP(j,W){
        if(dist[i][j] >= 0 and dist[i][j] <= K){
          chmin(ans, 1 + (i+K-1) / K);
          chmin(ans, 1 + (j+K-1) / K);
          chmin(ans, 1 + (H-1-i+K-1) / K);
          chmin(ans, 1 + (W-1-j+K-1) / K);
        }
      }
    }

    cout << ans << endl;
  }

  return 0;
}

