            qx[0] = i, qy[0] = j;
            break;
        }
    }

    while (cz < op){
        int x = qx[cz] , y = qy[cz];

        if (x == 0 || y == 0 || x == n-1 || y == m-1) return 1;
        if(d[x][y]==k){
            ++cz;
