        }

        REP(i, 4){
            int xx = x + dx[i], yy = y + dy[i];
            if (xx < 0 || yy < 0 || xx > n || yy > m) continue;
            if (A[xx][yy] != '.') continue;
            if (d[xx][yy] != 0) continue;

            d[xx][yy] = d[x][y] + 1;
            qx[op] = xx; qy[op] = yy;
            ++op;
        }
        ++cz;
    }
    return 0;
}

int bfs1(){
