int dx[] = {1, -1, 0, 0};
int dy[] = {0 , 0, -1, 1};

bool ok (int x, int y) {
	return !(x < 0 || y < 0 || x >= n || y >= m);
}

void bfs(int x, int y)
{
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++)
			dist[i][j] = n * m;
	}
	dist[x][y] = 0;
	queue <pii> q;
	q.push({x, y});
	while(!q.empty()) {
		pii e = q.front();
		q.pop();
		x = e.first, y = e.second;
		for (int i = 0; i < 4; i++) {
			int nx = x + dx[i], ny = y + dy[i];
			if(ok(nx, ny) && dist[nx][ny] == inf)	{
				dist[nx][ny] = dist[x][y] + 1;
				q.push({nx, ny});
			}
		}
	}
}

