ll h, w, k;
ll const MAX = 808;
ll grid[MAX][MAX];
ll dist[MAX][MAX];
struct point {
	ll x; ll y;
};

ll f(point p) {
	ll x = p.x, y = p.y;
	ll x1, x2, y1, y2;
	x1 = (x - 1) / k + (0 < (x - 1) % k);
	x2 = (h - x) / k + (0 < (h - x) % k);
	y1 = (y - 1) / k + (0 < (y - 1) % k);
	y2 = (w - y) / k + (0 < (w - y) % k);
	ll ans = min({ x1,x2,y1,y2 });
	return ans;
}

int main() {
	cin >> h >> w >> k;
	REP(i, 0, MAX - 1) {
		REP(j, 0, MAX - 1) {
			dist[i][j] = -1;
		}
	}
	point start;
	REP(i, 0, h+1) {
		REP(j, 0, w+1) {
			if (i == 0 || i == h + 1 || j == 0 || j == w + 1) {
				grid[i][j] = 1;
			}
			else {
				char c;
				cin >> c;
				if (c == '.') {
					grid[i][j] = 0;
				}
				else if (c == '#') {
					grid[i][j] = 1;
				}
				else {
					grid[i][j] = 0;
					start = { i,j };
					dist[i][j] = 0;
				}
			}
		}
	}
	ll dx[4] = { 1,0,-1,0 };
	ll dy[4] = { 0,1,0,-1 };
	queue<point> qu;
	qu.push(start);
	ll ans = f(start);
	while (!qu.empty()) {
		point cur = qu.front();
		ll cur_dist = dist[cur.x][cur.y];
		qu.pop();
		REP(dir, 0, 3) {
			point next = { cur.x + dx[dir], cur.y + dy[dir] };
			if (grid[next.x][next.y] == 0 && dist[next.x][next.y] == -1 && cur_dist <= k) {
				dist[next.x][next.y] = cur_dist + 1;
				qu.push(next);
				ans = min(ans, f(next));
			}
		}
	}
	cout << ans+1 << endl;

}

