bool within(int x, int min, int max) {
	return min <= x && x <= max;
}

int main(void) {
	int H, W, K;
	cin >> H >> W >> K;
	vector<vector<char>> f(H);
	REP(i, H) f[i].resize(W);
	int start = 0;
	int start_row = 0, start_col = 0;
	REP(i, H) REP(j, W) {
		cin >> f[i][j];
		if (f[i][j] == 'S') {
			start_row = i;
			start_col = j;
		}
	}
	int dx[] = { 0,0,1,-1 };
	int dy[] = { 1,-1,0,0 };
	struct info {
		int row, col;
		int depth;
	};
	stack<info> s;
	vector<vector<bool>> v(H);
	REP(i, H) v[i].resize(W, false);
	v[start_row][start_col] = true;
	function<void(int, int, int)> walk = [&](int row, int col, int depth) {
		if (depth >= K) return;
		REP(i, 4) {
			int nrow = row + dy[i];
			int ncol = col + dx[i];
			if (!within(nrow, 0, H - 1) || !within(ncol, 0, W - 1)) continue;
