				v[nrow][ncol] = true;
				walk(nrow, ncol, depth + 1);
			}
		}
	};
	walk(start_row, start_col, 0);
	int ans = 800 * 800 * 2;
	REP(i, H) REP(j, W) {
		if (!v[i][j]) continue;
		ans = min(ans, (abs((int)j) + K - 1) / K + 1);
		ans = min(ans, (abs((int)i) + K - 1) / K + 1);
		ans = min(ans, (abs(W - 1 - (int)j) + K - 1) / K + 1);
		ans = min(ans, (abs(H - 1 - (int)i) + K - 1) / K + 1);
	}
	cout << ans << endl;

	return 0;
}

