vector<vector<int>> bfs(char start, const vector<string> &g) {
    const int INF = 1000000000;
    using pii = pair<int, int>;

    int h = g.size(), w = g[0].size();
    static const auto is_valid = [&](int i, int j) {
        if (i < 0 || i >= h || j < 0 || j >= w) return false;
        if (g[i][j] == '#') return false;
        return true;
    };

    static const pii dir[] = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};
    queue<pii> q;
    vector<vector<int>> d(h, vector<int>(w, INF));
    rep(i, h) rep(j, w) {
        if (g[i][j] == start) {
            d[i][j] = 0;
            q.emplace(i, j);
        }
    }

    while (q.size()) {
        int ci, cj;
        tie(ci, cj) = q.front();
        q.pop();
        for (auto &v : dir) {
            int ni = ci + v.first;
            int nj = cj + v.second;
            if (is_valid(ni, nj)) {
                int nd = d[ci][cj] + 1;
                if (d[ni][nj] > nd) {
                    d[ni][nj] = nd;
                    q.emplace(ni, nj);
                }
            }
        }
    }

    return d;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(0);
    int h, w, k;
    while (cin >> h >> w >> k) {
        vector<string> g(h);
        rep(i, h) cin >> g[i];
        auto d = bfs('S', g);
        int ans = 1e9;
        rep(i, h) rep(j, w) {
            if (d[i][j] <= k) {
                int cd = 1e9;
                cd = min(cd, i);
                cd = min(cd, w - j - 1);
                cd = min(cd, j);
                cd = min(cd, h - i - 1);
                ans = min(ans, (cd + k - 1) / k);
            }
        }
        cout << ans + 1 << endl;
    }
}

