using Pii = pair<int, int>;

constexpr int H_MAX = 800;
constexpr int W_MAX = 800;
constexpr int dyx[4][2] = {
    { 0, 1}, {-1, 0}, {0,-1}, {1, 0}
};

int H, W, K;
Pii start = {-1, -1};
vector<string> a(H_MAX);
vector<vector<int>> opening_turn(H_MAX, vector<int>(W_MAX, 1<<30));
vector<vector<int>> shortest_turn(H_MAX, vector<int>(W_MAX, 1<<30));

inline void calc_opening_turn() {
    priority_queue<pair<int, Pii>, vector<pair<int, Pii>>, greater<pair<int, Pii>>> que;
    for(int i=0;i<H;++i){
        for(int j=0;j<W;++j) {
            if(opening_turn[i][j] == 0) {
                que.emplace(0, Pii(i, j));
            }
        }
    }

    int turn;
    Pii p;
    while(!que.empty()) {
        tie(turn, p) = que.top(); que.pop();
        if(opening_turn[p.first][p.second] < turn) continue;
        for(int k=0;k<4;++k) {
            Pii q = {p.first + dyx[k][0], p.second + dyx[k][1]};
            if(q.first < 0 || H <= q.first || q.second < 0 || W <= q.second) continue;
            if(opening_turn[q.first][q.second] > turn + 1) {
                opening_turn[q.first][q.second] = turn + 1;
                que.emplace(turn+1, Pii(q.first, q.second));
            }
        }
    }

    for(int i=0;i<H;++i){
        for(int j=0;j<W;++j) {
            opening_turn[i][j] = (opening_turn[i][j] + K - 1) / K;
            cerr << opening_turn[i][j];
        }
        cerr << endl;
    }

}

inline int calc_shortest_turn() {
    priority_queue<pair<int, Pii>, vector<pair<int, Pii>>, greater<pair<int, Pii>>> que;
    que.emplace(0, start);
    shortest_turn[start.first][start.second] = 0;

    int turn;
    Pii p;
    while(!que.empty()) {
        tie(turn, p) = que.top(); que.pop();
        if(shortest_turn[p.first][p.second] < turn) continue;
        if(p.first == 0 || p.first == H-1 || p.second == 0 || p.second == W-1) {
            return shortest_turn[p.first][p.second];
        }
        for(int di=0;di<=K;++di) {
            for(int dj=0;dj<=K-di;++dj) {
                for(int d=0;d<4;++d) {
                    Pii q = {
                        p.first + di * (d/2?1:-1), 
                        p.second + dj * (d&1?1:-1)
                    };
                    if(q.first < 0 || H <= q.first || q.second < 0 || W <= q.second) continue;
                    // cerr << turn << " " << q.first << " " << q.second << endl;
                    if(shortest_turn[q.first][q.second] > max(opening_turn[q.first][q.second], turn) + 1) {
                        shortest_turn[q.first][q.second] = max(opening_turn[q.first][q.second], turn) + 1;
                        que.emplace(shortest_turn[q.first][q.second], Pii(q.first, q.second));
                    }
                }
            }
        }
    }

    for(int i=0;i<H;++i){
        for(int j=0;j<W;++j) {
            cerr << ((shortest_turn[i][j] == 1<<30)?9:shortest_turn[i][j]);
        }
        cerr << endl;
    }

    return -1;
}

int main() {
    std::ios::sync_with_stdio(false); cin.tie(nullptr);
    cin >> H >> W >> K;
    for(int i=0;i<H;++i){
        cin >> a[i];
        for(int j=0;j<W;++j) {
            if(a[i][j] != '#') {
                if(a[i][j] == 'S') {
                    start = {i, j};
                }
                opening_turn[i][j] = 0;
            }
        }
    }

    calc_opening_turn();

    cout << calc_shortest_turn() << endl;

}

