    if (i == 0 || i == h - 1 || j == 0 || j == w - 1) { //最初のk歩でゴールできるなら1ターン
      cout << 1 << endl;
      return;
    }
    int height = min(abs(h - 1 - i), i); //一番近い壁(上下で)
    int width = min(abs(w - 1 - j), j); //一番近い壁(左右で)
    int d = min(height, width); //ゴールまでの最短経路の長さ
