            return 0;
        }
    }
    for(int i = 0; i < w; ++i){
        if(range[0][i] <= k){
            cout << 1 << endl;
            return 0;
        }
        if(range[h - 1][i] <= k){
            cout << 1 << endl;
            return 0;
        }
    }

    for(int i = 0; i < h; ++i)
        for(int j = 0; j < w; ++j)
            if(range[i][j] != MOD){
                que.emplace(0, ptoi(i, j));
                range[i][j] = 0;
            }

    while(!que.empty()){
        int x, y, dist;
        dist = que.top().first;
        tie(x, y) = itop(que.top().second);
        que.pop();
        if(range[x][y] != dist)
            continue;
        for(int d = 0; d < 4; ++d){
            int nx = x + dx[d];
            int ny = y + dy[d];
            if(nx < 0 || ny < 0 || nx >= h || ny >= w)
                continue;
            if(range[nx][ny] > range[x][y] + 1){
                range[nx][ny] = range[x][y] + 1;
                que.emplace(range[nx][ny], ptoi(nx, ny));
            }
        }
    }

