        }
    }

    using type = pair<pnt, pnt>;
    priority_queue<type, vector<type>, greater<type>> pq;
    vector<vector<pnt>> cost(h, vector<pnt>(w, { LINF, 0 }));
    pq.emplace(pnt(0, 0), s);
    while (!pq.empty()) {
        auto [c, now] = pq.top();
        pq.pop();
        if (now[cost] <= c) continue;
        DMP(c, now);
        chmin(now[cost], c);

        vector<int> dx{ 1,-1,0,0 };
