}

int n, m, K;

int go(pii L) {
	int x = L.F;
	int y = L.S;
	int mn = x - 1;
	mn = min(mn, y - 1);
	mn = min(mn, n - x);	
	mn = min(mn, m - y);
	return (mn + K - 1) / K;
}

