      ll nrest = min(p.f.s * K, 409);
      dist[p.s.f][p.s.s][nrest] = (p.f.f / K + 1) * K;
      pque.push({{dist[p.s.f][p.s.s][nrest], nrest}, {p.s.f, p.s.s}});
