int dc[] = {1, 0, -1, 0};

bool valid(int r, int c)
{
	return r >= 0 && c >= 0 && r < n && c < m && s[r][c] != '#';
}

void bfs(int sr, int sc)
{
	memset(dis, 63, sizeof dis);
	int h = 0, t = 0;
	dis[sr][sc] = 0;
	q[t++] = {sr, sc};
	while (h < t)
	{
		int r = q[h].first;
		int c = q[h].second;
		h++;
		for (int i=0; i<4; i++)
		{
			int R = r + dr[i];
			int C = c + dc[i];
			if (valid(R, C) && dis[R][C] > dis[r][c] + 1)
			{
				dis[R][C] = dis[r][c] + 1;
				q[t++] = {R, C};
			}
		}
	}
}

int best(int r, int c)
{
	int A = min(r, n-1-r);
	int B = min(c, m-1-c);
	return (min(A, B) + k - 1) / k;
}

