int pr[4] = {1, 0, -1, 0};
int ps[4] = {0, 1, 0, -1};
int brred, brstup;

int vani(int r, int c) {
  return r < 0 || c < 0 || r >= brred || c >= brstup;
}

void bfs(int r, int c) {
  REP(i, MAX) REP(j, MAX) bio[i][j] = 1e9;

  queue <P> Q;
  Q.push(P(r, c));
  bio[r][c] = 0;

  for (; !Q.empty(); ) {
    P tmp = Q.front(); Q.pop();
    REP(i, 4) {
      int nr = tmp.X + pr[i];
      int nc = tmp.Y + ps[i];
      if (!vani(nr, nc) && s[nr][nc] != '#' && bio[nr][nc] > bio[tmp.X][tmp.Y] + 1) {
	bio[nr][nc] = bio[tmp.X][tmp.Y] + 1;
	Q.push(P(nr, nc));
      }
    }
  }
}

int main()
{
  int K;
  scanf("%d%d%d", &brred, &brstup, &K);

  P poc = P(-1, -1);
  REP(i, brred) {
    scanf(" %s", s[i]);
    REP(j, brstup)
      if (s[i][j] == 'S')
	poc = P(i, j);
  }

  assert(poc.X != -1);
  bfs(poc.X, poc.Y);

  int rje = 1e9;
  REP(i, brred) {
    REP(j, brstup) {
      if (bio[i][j] <= K) {
	int mn = min(min(i, j), min(brred-i-1, brstup-j-1));
	int jos = (mn + K - 1) / K;
	rje = min(rje, 1 + jos);
      }
    }
  }

  printf("%d\n", rje);

  return 0;
}

