using namespace std;
using ll = long long;

const int N = 800;

int h, w, k;
string f[N];
int sx, sy;
int gone[N * N];
using P = pair<int, int>;

int calc(int y, int x) {
  int res = x;
  res = min(res, w-1-x);
  res = min(res, y);
  res = min(res, h-1-y);
  return res;
}

int dx[] = {1, 0, -1, 0};
int dy[] = {0, -1, 0, 1};

int main() {
  ios::sync_with_stdio(false), cin.tie(0);
  cin >> h >> w >> k;
  for(int i = 0; i < h; i++) {
    cin >> f[i];
    for(int j = 0; j < w; j++) if(f[i][j] == 'S') sy = i, sx = j;
  }
  int m = calc(sy, sx);
  int ans = (m + k - 1) / k + 1;

  // BFS
  queue<P> q;
  // coordinate, steps 
  q.emplace(sy * N + sx, 0);
  gone[sy * N + sx] = 0;
  while(q.size()) {
    int c = q.front().first, d = q.front().second;
    q.pop();
    int y = c / N, x = c % N;
    if(d >= k) continue;
    for(int i = 0; i < 4; i++) {
      int nx = x + dx[i], ny = y + dy[i];
      if(nx < 0 || w <= nx || ny < 0 || h <= ny) continue;
      if(f[ny][nx] == '#') continue;
      if(gone[ny * N + nx]) continue;
      if(d + 1 > k) continue;
      gone[ny * N + nx] = 1;
      ans = min(ans, (calc(ny, nx) + k - 1) / k + 1);
      q.emplace(ny * N + nx, d + 1);
    }
  }
  cout << ans << endl;
}

