using namespace std;

template <typename T>
using Matrix = vector<vector<T>>;

template <typename T>
Matrix<T> matrix(const int R, const int C, const T x = T()) { return Matrix<T>(R, vector<T>(C, x)); }

int main()
{
    int H, W, K; cin >> H >> W >> K;

    auto grid = vector<string>(H);
    for (auto& row : grid) cin >> row;

    struct Point { int row, column; };

    Point start;
    for (auto row = 0; row < H; row++) for (auto column = 0; column < W; column++)
        if (grid[row][column] == 'S') start = {row, column};

    const auto straight_line_solution = [&](const Point p)
    {
        const auto d = min({p.row, H-1-p.row, p.column, W-1-p.column});
        return (d + (K-1)) / K;
    };

    auto seen = matrix<bool>(H, W);
    struct State { Point p; int distance; };
    auto queue = std::queue<State>();

    seen[start.row][start.column] = true;
    queue.push({start, 0});

    auto result = numeric_limits<int>::max();
    while (!queue.empty())
    {
        const auto s = queue.front(); queue.pop();

        result = min(result, 1 + straight_line_solution(s.p));

        if (s.distance == K) continue;

        const auto dr = array<int, 4>{-1, 0, 1, 0};
        const auto dc = array<int, 4>{0, 1, 0, -1};
        for (auto i = 0; i < 4; i++)
        {
            const auto row = s.p.row + dr[i], column = s.p.column + dc[i];
            if (0 <= row && row < H && 0 <= column && column < W && grid[row][column] != '#' && !seen[row][column])
            {
                seen[row][column] = true;
                queue.push({{row, column}, s.distance+1});
            }
        }
    }

    cout << result << endl;
}

