		int D = min(p.fs, p.sc);
		D = min(D, W - p.sc - 1);
		D = min(D, H - p.fs - 1);
		M = min(M, D);


		rep(i, 4) {
			int x = p.sc + dx[i];
			int y = p.fs + dy[i];
			if (x < 0) continue;
			if (y < 0) continue;
			if (x >= W) continue;
			if (y >= H) continue;
			if (m[y][x] != '.')continue;
			if (f[y][x] != -1)continue;

			Q.push({ y,x });


		}
	}

	cerr << M << endl;

	if (M == 0) {
		cout << 1 << endl;
	} else {
		cout << (M - 1) / K + 2 << endl;

	}

}
