        REP(i, 4){
            int ny = y + DY[i];
            int nx = x + DX[i];
            if (ny < 0 || h <= ny || nx < 0 || w <= nx) continue;

            state ns = memo[y][x].next(maze[y][x], maze[ny][nx]);
            if (ns < memo[ny][nx]){
                if (ny == 0 || ny == h - 1 || nx == 0 || nx == w - 1){

#ifdef D
