#include <bits/stdc++.h>
#include <array>
using namespace std;
using ULL = unsigned long long;
using UL = unsigned;
using LL = long long;
#define rep(i, n) for(UL i = 0; i < (n); i++)

struct Problem {

	int opt[800][800];

	void Solve() {
		UL H, W; cin >> H >> W;
		UL K; cin >> K;
		UL sx, sy;
		rep(y, H) rep(x, W) {
			char c; cin >> c;
			if (c == '#') opt[x][y] = -1;
			if (c == '.') opt[x][y] = 0;
			if (c == 'S') { opt[x][y] = 0; sx = x; sy = y; }
		}
		queue<pair<pair<UL, UL>, UL>> q;
		q.push({ {sx, sy}, K });
		UL ans = 10000;
		while (q.size()) {
			auto p = q.front(); q.pop();
			UL x = p.first.first, y = p.first.second;
			UL k = p.second;
			if (opt[x][y] != 0) continue;
			opt[x][y] = k;
			UL ansbuf = min(min(x, y), min(W - 1 - x, H - 1 - y));
			ans = min(ans, (ansbuf + K - 1) / K);
			if (k == 0) continue;
			if (x != 0) q.push({ {x - 1, y}, k - 1 });
			if (y != 0) q.push({ {x, y - 1}, k - 1 });
			if (x != W - 1) q.push({ {x + 1, y}, k - 1 });
			if (y != H - 1) q.push({ {x, y + 1}, k - 1 });
		}
		cout << (ans + 1) << endl;
	}


	Problem();
};
int main() {
	unique_ptr<Problem> p(new Problem());
	p->Solve();
	return 0;
}
Problem::Problem() {
	cout << fixed << setprecision(10);
}

#include <iostream>
