const int maxn = 805;
int n, m, k;
char c[maxn][maxn];

int read() {
  if (scanf("%d%d%d", &n, &m, &k) < 3) {
    return false;
  }
  for (int i = 0; i < n; i++) {
    scanf("%s", c[i]);
  }
  return true;
}

int d[maxn][maxn];
vector< pair<int, int> > q;

const int gox[] = {1, 0, -1, 0};
const int goy[] = {0, 1, 0, -1};

bool inside(int x, int y) {
  return 0 <= x && x < n && 0 <= y && y < m;
}

void solve() {
  int sx = -1, sy = -1;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (c[i][j] == 'S') {
        assert(sx == -1);
        sx = i;
        sy = j;
        c[i][j] = '.';
      }
    }
  }
  assert(sx != -1);
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      d[i][j] = inf;
    }
  }
  d[sx][sy] = 0;
  q.clear();
  q.push_back(make_pair(sx, sy));
  for (int ql = 0; ql < sz(q); ql++) {
    int x = q[ql].first, y = q[ql].second;
    if (d[x][y] >= k) {
      break;
    }
    for (int dir = 0; dir < 4; dir++) {
      int nx = x + gox[dir], ny = y + goy[dir];
      if (!inside(nx, ny) || c[nx][ny] == '#' || d[nx][ny] < inf) {
        continue;
      }
      d[nx][ny] = d[x][y] + 1;
      q.push_back(make_pair(nx, ny));
    }
  }
  int res = inf;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (d[i][j] >= inf) {
        continue;
      }
      int dist = min(min(i, n - i - 1), min(j, m - j - 1));
      res = min(res, (dist + k - 1) / k + 1);
    }
  }
  printf("%d\n", res);
}

