	int res = INF;
	while (!Q.empty())
	{
		int x = Q.front().Y.X, y = Q.front().Y.Y, k = Q.front().X; Q.pop();
		if (x == 1 || x == n || y == 1 || y == m) res = 1;
		res = min(res, Ceil(min(min(n - x, x), min(m - y, y)), K) + 1);
