void solve (int h)
{
    int w, k;
    cin >> w >> k;

    int sx = -1, sy = -1;
    vector<string> grid(h);
    forn (i, h)
    {
        cin >> grid[i];
        int pos = find(all(grid[i]), 'S') - grid[i].begin();
        if (pos != w)
            sx = i, sy = pos;
    }

    queue<pii> q;
    q.push(mp(sx, sy));
    vvi dist(h, vi(w, -1));
    dist[sx][sy] = 0;

    int dx[] = {-1, 1, 0, 0};
    int dy[] = {0, 0, -1, 1};

    while (!q.empty())
    {
        int cx = q.front().fst, cy = q.front().snd;
        q.pop();
        if (dist[cx][cy] == k)
            break;

        forn (d, 4)
        {
            int nx = cx + dx[d], ny = cy + dy[d];
            if (0 <= nx && nx < h && 0 <= ny && ny < w
                && grid[nx][ny] != '#' && dist[nx][ny] == -1)
            {
                q.push(mp(nx, ny));
                dist[nx][ny] = dist[cx][cy] + 1;
            }
        }
    }

    const int inf = (int)1e9;
    int ans = inf;
    forn (i, h) forn (j, w)
    {
        if (dist[i][j] == -1)
            continue;
        int brd = min({i, h - 1 - i, j, w - 1 - j});
        int cur = 1 + (brd + k - 1) / k;
        ans = min(ans, cur);
    }

    assert(ans != inf);
    cout << ans << endl;
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    while (cin >> n)
        solve(n);
}

