using namespace std;

int dx[] = {0, 0, 1, -1};
int dy[] = {1, -1, 0, 0};

signed main() {
  int H, W, K;
  cin >> H >> W >> K;

  vector<string> s(H);
  REP(i, H) cin >> s[i];

  pair<int, int> start;
  REP(i, H) REP(j, W) if(s[i][j] == 'S') start = make_pair(i, j);


  queue<pair<int, int>> q;
  vector<vector<int>> dist(H, vector<int>(W, INF));
  dist[start.first][start.second] = 0;
  q.push(start);

  while(!q.empty()){
    auto p = q.front(); q.pop();

    REP(i, 4){
      int x = p.first+dx[i];
      int y = p.second+dy[i];
      if(OUT(0, x, H) || OUT(0, y, W)) continue;
      if(s[x][y] == '#') continue;

      int d = dist[p.first][p.second];
      if(dist[x][y] <= d) continue;
      dist[x][y] = d;
      q.push(make_pair(x, y));
    }
  }

  int ans = INF;
  REP(i, H){
    REP(j, W){
      if(dist[i][j] != 0) continue;
      int MIN = min(min(i, j), min(H-i-1, W-j-1));
      if(MIN == 0) ans = 1;
      chmin(ans, (MIN+K-1)/K+1);
    }
  }

  cout << ans << endl;

  return 0;
}

