#include <bits/stdc++.h>
using namespace std;
const int maxn = 888;
int w, h, k, ans = maxn;
int sx, sy;
char s[maxn][maxn];
int step[maxn][maxn];
const int dx[4] = {1, 0, -1, 0};
const int dy[4] = {0, 1, 0, -1};
struct Item {
    int x, y;
};
vector<Item> reach;
int cal (int x) {
    if (x == 0) return 0;
    else return (x-1)/k+1;
}
int main () {
    scanf ("%d%d%d", &w, &h, &k);
    memset (step, -1, sizeof (step));
    for (int i = 1; i <= w; i++) {
        //printf ("%d\n", i);
        scanf ("%s", s[i]+1);
    }
    for (int i = 1; i <= w; i++) for (int j = 1; j <= h; j++) {
        //printf ("%c", s[i][j]);
        if (s[i][j]=='S') {
            sx = i; sy = j;
        }
    }
    step[sx][sy] = 0;
    queue<Item> q;
    q.push ({sx, sy});
    while (!q.empty()) {
        Item u = q.front(); q.pop();
        //printf ("%d %d\n", u.x, u.y);
        reach.push_back ({u.x, u.y});
        if (step[u.x][u.y] == k) continue;
        for (int i = 0; i < 4; i++) {
            int nx = u.x + dx[i], ny = u.y + dy[i];
            if (step[nx][ny] == -1 && s[nx][ny] == '.') {
                step[nx][ny] = step[u.x][u.y]+1;
                q.push ({nx, ny});
            }
        }
    }
    //printf ("%d\n", -1/3+1);
    for (int i = 0; i < reach.size(); i++) {
        Item u = reach[i];
        //printf ("%d %d\n", u.x, u.y);
        ans = min (ans, cal(u.x-1));
        ans = min (ans, cal(w-u.x));
        ans = min (ans, cal(u.y-1));
        ans = min (ans, cal(h-u.y));
    }
    printf ("%d\n", ans+1);
}

