queue<int> dp;
char getopt()
{
	char ch=getchar();
	while (ch!='#'&&ch!='.'&&ch!='S') ch=getchar();
	return ch;
}
int calc(int x,int y)
{
	if (min(min(x-1,n-x),min(y-1,m-y))==0) return 0;
	return (min(min(x-1,n-x),min(y-1,m-y))-1)/k+1;
}
void bfs(int x,int y,int deep)
{
	q.push(make_pair(x,y));
	vis[x][y]=1;
	dp.push(0);
	while (!q.empty())
	{
		PII tmp=q.front();
		q.pop();
		int h=dp.front();
		dp.pop();
		if (h>k) continue;
		ans=min(ans,calc(tmp.first,tmp.second));
		for (int i=0;i<4;i++)
		{
			int newx=tmp.first+dir[i][0];
			int newy=tmp.second+dir[i][1];
			if (newx>=1&&newx<=n&&newy>=1&&newy<=m&&mp[newx][newy]=='.'&&!vis[newx][newy])
			{
				vis[newx][newy]=1;
				q.push(make_pair(newx,newy));
				dp.push(h+1);
			}
		}
	}
}
