		for (int j=1;j<=m;j++)
		{
			mp[i][j]=getopt();
			if (mp[i][j]=='S')
				x=i,y=j;
		}
	ans=INF;
	bfs(x,y,0);
	printf("%d",ans+1);
	return 0;
}

