int h,w,k;
int sx,sy;
//vector<pii> stat;
pii stat[800*800];
int sn;

bool used[800][800];

char s[800][800];

int go(int gx,int gy){
    int ret = INF;
    for(int i=0;i<sn;i++){
        pii st =stat[i];
        int x = st.first;
        int y = st.second;
        int gdist = abs(gx-x)+abs(gy-y);
        int cnt = gdist/k;
        if(gdist%k>0) cnt++;
        ret = min(ret,cnt);
    }
    return ret;
}

int main(){
    cin >> h >> w >> k;
    //vector<string> s(h);
    //rep(i,h) cin>>s[i];
    rep(i,h) scanf("%s",&s[i]);

    rep(i,h) rep(j,w){
        if(s[i][j]=='S'){
            sx = i;
            sy = j;
            break;
        }
    }

    // 1回の魔法で行ける場所
    used[sx][sy]=true;
    queue<pii> que;
    que.push(pii(sx,sy));

    while(!que.empty()){
        auto p = que.front();
        que.pop();
        int x = p.first;
        int y = p.second;
        if(abs(x-sx)+abs(y-sy)>=k) continue;

        for(int i=0;i<4;i++){
            int nx=x+dx[i];
            int ny=y+dy[i];
            if(nx<0 or ny<0 or nx>h-1 or ny>w-1) continue;
            if(used[nx][ny] or s[nx][ny]=='#') continue;
            used[nx][ny]=true;
            que.push(pii(nx,ny));
        }
    }


    rep(i,h) rep(j,w){
        if(abs(i-sx)+abs(j-sy)<=k && s[i][j]=='.' && used[i][j]){
            s[i][j]='S';
            stat[sn++] = make_pair(i,j);
        }
    }
    stat[sn++] = make_pair(sx,sy);

    //rep(i,h) rep(j,w)  if(s[i][j]=='S') stat[idx++] = make_pair(i,j);

    int ans = INF;
    for(int i=0;i<h;i++) ans = min(ans,go(i,0));
    for(int i=0;i<h;i++) ans = min(ans,go(i,w-1));
    for(int i=0;i<w;i++) ans = min(ans,go(0,i));
    for(int i=0;i<w;i++) ans = min(ans,go(h-1,i));
    cout << ans+1 << endl;
}

