        for (int dd = 0; dd < 4; dd++) {
            int nx = x + dx[dd], ny = y + dy[dd];
            if (nx >= 0 && nx < n && ny >= 0 && ny < m && d[nx][ny] > d[x][y] + 1 && s[nx][ny] != '#') {
                d[nx][ny] = d[x][y] + 1;
