const int dj[] = {-1, 1, 0, 0};

int si, sj;
pii Q[MAXN * MAXN];
int dist[MAXN][MAXN];
int head = 0;

int valid(const pii& pt) {
	return (pt.first >= 0 && pt.second >= 0 && pt.first < H && pt.second < W);
}

void clear() {
	head = 0;

	for(int i = 0; i < H; ++i) {
		for(int j = 0; j < W; ++j) {
			dist[i][j] = INT_INF;
		}
	}
}

int find() {
	clear();
	dist[si][sj] = 0;
	Q[head++] = make_pair(si, sj);

	for(int ptr = 0; ptr < head; ++ptr) {
		pii cur = Q[ptr];

		for(int dir = 0; dir < DIRS; ++dir) {
			pii nxt = make_pair(cur.first + di[dir], cur.second + dj[dir]);

			if(valid(nxt) && A[nxt.first][nxt.second] == '.' && dist[nxt.first][nxt.second] > dist[cur.first][cur.second] + 1) {
				dist[nxt.first][nxt.second] = dist[cur.first][cur.second] + 1;
				Q[head++] = nxt;
			}
		}
	}

	head = 0;

	for(int i = 0; i < H; ++i) {
		for(int j = 0; j < W; ++j) {
			if(dist[i][j] > K) {
				dist[i][j] = INT_INF;
			} else {
				dist[i][j] = 0;
				Q[head++] = make_pair(i, j);
			}
		}
	}

	for(int ptr = 0; ptr < head; ++ptr) {
		pii cur = Q[ptr];

		for(int dir = 0; dir < DIRS; ++dir) {
			pii nxt = make_pair(cur.first + di[dir], cur.second + dj[dir]);

			if(valid(nxt) && dist[nxt.first][nxt.second] > dist[cur.first][cur.second] + 1) {
				dist[nxt.first][nxt.second] = dist[cur.first][cur.second] + 1;
				Q[head++] = nxt;
			}
		}
	}

	int rez = INT_INF;

	for(int i = 0; i < H; ++i) {
		for(int j = 0; j < W; ++j) {
			if(i == 0 || j == 0 || i == H - 1 || j == W - 1) {
				rez = min(rez, 1 + (dist[i][j] + K - 1) / K);
			}
		}
	}

	return rez;
}

void solve() {
	cin >> H >> W >> K;

	for(int i = 0; i < H; ++i) {
		auto line = fetch<string>();

		for(int j = 0; j < W; ++j) {
			A[i][j] = line[j];

			if(A[i][j] == 'S') {
				si = i;
				sj = j;
				A[i][j] = '.';
			}
		}
	}

	cout << find() << '\n';
}

