    sc(n, m, k);
    pii p;
    fr(i, 1, n) {
        fr(j, 1, m) {
            sc(a[i][j]);
            if(a[i][j] == 'S') p = {i, j};
            dist[i][j] = 1e9;
        }
    }
    dist[p.fi][p.se] = 0;
    queue<pii> q;
    q.push(p);
    while(!q.empty()) {
        pii u = q.front();
        q.pop();
        if(dist[u.fi][u.se] == k) {
            break;
        }
        fr(kk, 0, 3) {
            pii v = {u.fi + dx[kk], u.se + dy[kk]};
            if(v.fi >= 1 && v.fi <= n && v.se >= 1 && v.se <= m) {
                if(dist[v.fi][v.se] > dist[u.fi][u.se] + 1 && a[v.fi][v.se] != '#') {
                    dist[v.fi][v.se] = dist[u.fi][u.se] + 1;
                    q.push(v);
                }
            }
        }
