const int MaxN = 800;
int n, m, K, head, tail;
int a[MaxN + 5][MaxN + 5];
int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, 1, 0, -1};
struct Node {
	int x, y, step;
	void make(int tx, int ty, int tstep) {
		x = tx; y = ty; step = tstep;
	}
}S, seq[MaxN * MaxN * 2 + 5];
bool Inseq[MaxN + 5][MaxN + 5];


void Init()
{
	for (int i = 1; i <= n; i++) {
		string s;
		cin >> s;
		for (int j = 0; j < m; j++) 
			if (s[j] == '.') a[i][j + 1] = 0;
				else if (s[j] == '#') a[i][j + 1] = 1;
					else a[i][j + 1] = 2, S.x = i, S.y = j + 1;
	}
}

bool Check(int x, int y, bool flag)
{
	if (x < 1) return false;	
	if (x > n) return false;
	if (y < 1) return false;
	if (y > m) return false;
	if (Inseq[x][y]) return false;
	if (!flag && a[x][y] == 1) return false;
	return true;
}

void Bfs1()
{
	head = 1, tail = 0;
	memset(Inseq, 0, sizeof(Inseq));
	S.step = 0;
	seq[++tail] = S;
	Inseq[S.x][S.y] = true;
	while (head <= tail) {
		Node now = seq[head];	
		if (now.step >= K) {head++; continue;}
		for (int i = 0; i < 4; i++) {
			int nx = now.x + dx[i];
			int ny = now.y + dy[i];
			if (Check(nx, ny, 0)) {
				Node t;	t.make(nx, ny, now.step + 1);
				seq[++tail] = t;
				Inseq[nx][ny] = true;
			}
		}
		head++;
	}
}

void Bfs2()
{
	for (int i = 1; i <= tail; i++) seq[i].step = 0;
	head = 1;
	//printf("%d %d\n", head, tail);
	while (head <= tail) {
		Node now = seq[head];
		for (int i = 0; i < 4; i++) {
			int nx = now.x + dx[i];
			int ny = now.y + dy[i];
			if (Check(nx, ny, 1)) {
				Node t; t.make(nx, ny, now.step + 1);
				seq[++tail] = t;
				Inseq[nx][ny] = true;
			}
		}
		head++;
	}
	int ans = 1 << 30;
	for (int i = 1; i <= tail; i++) {
		if (seq[i].x == 1 || seq[i].x == n || seq[i].y == 1 || seq[i].y == m)
			ans = min(ans, (seq[i].step + K - 1) / K + 1);
	}
	printf("%d\n", ans);
}

int main()
{
	while (~scanf("%d%d%d", &n, &m, &K)) {
		Init();
		Bfs1();
		Bfs2();
	}
	return 0;
}

