    queue<pair<P, int>> que;
    que.push({start, 0});

    ll dx[4] = {1, 0, -1, 0};
    ll dy[4] = {0, 1, 0, -1};
    ll nowx = start.first, nowy = start.second;
    ll ans = min({devc(nowx, K), devc(nowy, K), devc(H - 1 - nowx, K), devc(W - 1 - nowy, K)}) + 1;

