    chmin(ans, (dist[i][0] + k - 1) / k + 1);
    chmin(ans, (dist[i][w-1] + k - 1) / k + 1);
  }
  REP(j,w){
    chmin(ans, (dist[0][j] + k - 1) / k + 1);
    chmin(ans, (dist[h-1][j] + k - 1) / k + 1);

  }
  ANS(ans);
  return 0;
}

