	for (int i = 0; i <= H; ++i) mi = min({ mi, ans[i][0], ans[i][W + 1] });
	for (int i = 0; i <= W; ++i) mi = min({ mi, ans[0][i] = ans[H + 1][i] });
	cout << mi << endl;
	return 0;
}

