void dfs(int x, int y, int dep) {
	if (dep >= K) return;
	v[x][y] = true;
	for (int i = 0; i != 4; ++i) {
		int tx = x + dx[i], ty = y + dy[i];
		if (!v[tx][ty] && m[tx][ty] != '#')
			dfs(tx, ty, dep + 1);
	}
	if (ceil((double)(x - 1) / K) < mini) mini = ceil((double)(x - 1) / K);
	if (ceil((double)(y - 1) / K) < mini) mini = ceil((double)(y - 1) / K);
	if (ceil((double)(H - x) / K) < mini) mini = ceil((double)(H - x) / K);
	if (ceil((double)(W - y) / K) < mini) mini = ceil((double)(W - y) / K);
}

