void DFS(int x, int y, int now) {
    if (now > K) return;
    if (vis[x][y] <= now && vis[x][y] != 0) return;
    vis[x][y] = now;
    if (x == 1 || y == 1 || x == H || y == W) ans = min(ans, now);
