int main(const int argc, char * argv [])
{
  ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);

  size_t n, m, k;
  cin >> n >> m >> k;

  vector<string> a(n);
  cin >> a;

  // typedef pair<size_t, size_t> value_t;
  const size_t inf = n * m + 100;

  typedef pair<pair<size_t, size_t>, size_t> value_t;

  const auto comp = [](const value_t & a, const value_t & b) {
    return b.second < a.second;
  };

  priority_queue<value_t, vector<value_t>, decltype(comp)> heap(comp);
  vector<vector<size_t>> dist(n, vector<size_t>(m, inf));

  for(size_t i = 0; i < n && heap.empty(); ++i)
    for(size_t j = 0; j < m && heap.empty(); ++j)
      if(a[i][j] == 'S')
      {
        a[i][j] = '.';
        dist[i][j] = 0;
        heap.push({{i, j}, 0});
      }

  size_t out = inf;

  while(!heap.empty())
  {
    const auto pr = heap.top();
    heap.pop();

    const size_t i = pr.first.first;
    const size_t j = pr.first.second;
    const size_t d = pr.second;
    if(d != dist[i][j]) continue;

    out = min(out, 1 + (i + k - 1) / k);
    out = min(out, 1 + (j + k - 1) / k);

    out = min(out, 1 + (n + k - i - 2) / k);
    out = min(out, 1 + (m + k - j - 2) / k);

    if(d == k) continue;

    if(0 < i && a[i - 1][j] == '.' && d + 1 < dist[i - 1][j])
      heap.push({{i - 1, j}, dist[i - 1][j] = d + 1});

    if(i + 1 < n && a[i + 1][j] == '.' && d + 1 < dist[i + 1][j])
      heap.push({{i + 1, j}, dist[i + 1][j] = d + 1});

    if(0 < j && a[i][j - 1] == '.' && d + 1 < dist[i][j - 1])
      heap.push({{i, j - 1}, dist[i][j - 1] = d + 1});

    if(j + 1 < m && a[i][j + 1] == '.' && d + 1 < dist[i][j + 1])
      heap.push({{i, j + 1}, dist[i][j + 1] = d + 1});
  }

  cout << out;
  return EXIT_SUCCESS;
}

