            if(S[i][j]=='S') st={i,j};
        }
    }
    vector<vector<int>> dist(H,vector<int>(W,INF));
    queue<pii> q;
    q.push(st);
    dist[st.first][st.second]=0;
    int ans=INF;
    while(!q.empty()) {
        int y=q.front().first;
        int x=q.front().second; q.pop();
        if(S[y][x]=='#') {
            int l1=dist[y][x]-1;
            int l2=min(min(y,x),min(H-y,W-x)-1);
            if(l1>=K) {
                chmin(ans,(l1+l2+K-1)/K);
            } else {
                chmin(ans,1+(l2+K-1)/K);
            }
            continue;
        }
        REP(dir,4) {
            int yy=y+DY[dir];
            int xx=x+DX[dir];
            if(OUTOFRANGE(yy,xx,H,W)) continue;
            if(chmin(dist[yy][xx],dist[y][x]+1)) {
                q.push({yy,xx});
            }
        }
    }
    cout<<ans<<endl;
    return 0;
}

