void bfs(pair<int,int> start){
    for(int i=0;i<H;i++){
        for(int j=0;j<W;j++){
            dist[i][j]=MOD;
        }
    }
    dist[start.first][start.second]=0;
    queue<pair<int,int>> Q;
    Q.push(start);
    while(Q.size()){
        pair<int,int> now=Q.front();
        Q.pop();
        int x=now.first;
        int y=now.second;
        ans=min(ans,(x+K-1)/K);
        ans=min(ans,(y+K-1)/K);
        ans=min(ans,(H-1-x+K-1)/K);
        ans=min(ans,(W-1-y+K-1)/K);
