using namespace std;
const int Max_HW(805);
const int dx[] = {+1, -1, +0, +0};
const int dy[] = {+0, +0, +1, -1};

struct node
{
	node(int _x, int _y) : x(_x), y(_y) {}
	int x, y;
};

int H, W, K, Dist[Max_HW][Max_HW];
char A[Max_HW][Max_HW];

inline bool test(int x, int y)
{
	return 1 <= x && x <= H && 1 <= y && y <= W && A[x][y] == '.';
}

inline int get(int x)
{
	return (x - 1) / K + 1;
}

int main()
{
	queue<node> Q;
	scanf("%d%d%d", &H, &W, &K);
	for (int i = 1;i <= H;++i)
	{
		scanf("%s", A[i] + 1);
		for (int j = 1;j <= W;++j)
			if (A[i][j] == 'S')
				Dist[i][j] = 1, Q.push(node(i, j));
	}
	for (int ux, uy;Q.empty() == false;)
	{
		ux = Q.front().x, uy = Q.front().y, Q.pop();
		for (int k = 0, vx, vy;k != 4;++k)
			if (test(vx = ux + dx[k], vy = uy + dy[k]) && !Dist[vx][vy])
				Dist[vx][vy] = Dist[ux][uy] + 1, Q.push(node(vx, vy));
	}
	int Ans = 0X3F3F3F3F;
	for (int x = 1;x <= H;++x)
		for (int y = 1;y <= W;++y)
		{
			if (Dist[x][y] == 0 || (--Dist[x][y]) > K)
				continue;
			if (x == 1 || x == H || y == 1 || y == W)
				Ans = min(Ans, 1);
			else
			{
				Ans = min(Ans, 1 + get(x - 1));
				Ans = min(Ans, 1 + get(H - x));
				Ans = min(Ans, 1 + get(y - 1));
				Ans = min(Ans, 1 + get(W - y));
			}
		}
	printf("%d", Ans);
	return 0;
}

