}
int main(){
	int64_t H,W,K;
	cin>>H>>W>>K;
	vector<vector<char> > map;
	read_2d(map,H,W);
	bool used[H][W];
	for(int64_t i1=0;i1<H;i1++){
		for(int64_t i2=0;i2<W;i2++){
			used[i1][i2]=false;
		}
	}
	int64_t x1,y1;
	for(int64_t i1=0;i1<H;i1++){
		for(int64_t i2=0;i2<W;i2++){
			if(map[i1][i2]=='S'){
