				y1=i2;
				break;
			}
		}
	}
	priority_queue<Point> que;
	int64_t ans=INF;
	que.push(Point{x1,y1,0});

	while(!que.empty()){
		Point p=que.top();
		que.pop();
		if(used[p.x][p.y]){
			continue;
		}

		if(p.x==0||p.x==H-1||p.y==0||p.y==W-1){
			ans=0;
			break;
