#define MAX_H   (800)                  // 10^5
#define MAX_N   (100000)                  // 10^5
#define BASE    (1000000000 + 7)          // 10^9 + 7
#define INFI    (1000000000 + 7)          // 10^9 + 7
#define INFL    (1000000000000000000 + 7) // 10^18 + 7

ll H, W, K;
string MAP[MAX_H];
int DIST[MAX_H][MAX_H];

bool is_inside(int i, int j) {
  return 0 <= i && i < H && 0 <= j && j < W;
}

bool is_edge(int i, int j) {
  return i == 0 || i == H - 1 || j == 0 || j == W - 1;
}

ll min_turn() {
  int dir[4][2] = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};

  queue<Pi> que;
  vector<Pi> cell;
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      DIST[i][j] = INFI;
      if (MAP[i][j] == 'S') {
        if (is_edge(i, j)) return 0;
        que.push(Pi(i, j));
        cell.push_back(Pi(i, j));
        DIST[i][j] = 0;
      }
    }
  }

  while (!que.empty()) {
    Pi p = que.front(); que.pop();
    int r = p.FST, c = p.SND;
    for (int i = 0; i < 4; i++) {
      int rx = r + dir[i][0], cx = c + dir[i][1];
      if (is_inside(rx, cx)) {
        int dist = DIST[r][c] + 1;
        if (MAP[rx][cx] == '.' && dist < DIST[rx][cx] && dist <= K) {
          DIST[rx][cx] = dist;
          que.push(Pi(rx, cx));
          cell.push_back(Pi(rx, cx));
        }
      }
    }
  }

  ll mn = INFI;
  for (auto p : cell) {
    int r = p.FST, c = p.SND;
    ll vals[4] = {r, c, W - 1 - r, H - 1 - c};
    for (int i = 0; i < 4; i++) mn = min(mn, vals[i]);
  }
  return (mn + K) / K + 1;
}

void solve() {
  ll ans = min_turn();
  cout << ans << endl;
}

int main() {
  cin >> H >> W >> K;

  for (int i = 0; i < H; i++) cin >> MAP[i];

  solve();

  return 0;
}

