vector<Point> bfs(int h, int w, Point p, int k){
	int dis[N][N];
	queue<Point> q;
	rep(i,N) rep(j,N) dis[i][j] = INF;

	dis[p.y][p.x] = 0;
	q.push(p);

	Point u;
	vector<Point> res;
	while(not q.empty()){
		u = q.front(); q.pop();
		res.emplace_back(u);
		rep(i,4){
			Point next;
			next.x = u.x + dx[i];
			next.y = u.y + dy[i];
			if(next.x < 0 || next.x >= w || next.y < 0 || next.y >= h) continue;
			if(dis[next.y][next.x] == INF && c[next.y][next.x] == '.' && dis[u.y][u.x] + 1 <= k){
				dis[next.y][next.x] = dis[u.y][u.x] + 1;
				q.push(next);
			}
		}
	}
	return res;
}

int bfs(int h, int w, Point p, vector<Point> s){
	int dis[N][N];
	queue<Point> q;
	rep(i,N) rep(j,N) dis[i][j] = INF;

	for(auto i : s){
		dis[i.y][i.x] = 0;
		q.push(i);
	}

	Point u;
	while(not q.empty()){
		u = q.front(); q.pop();
		rep(i,4){
			Point next;
			next.x = u.x + dx[i];
			next.y = u.y + dy[i];
			if(next.x < 0 || next.x >= w || next.y < 0 || next.y >= h) continue;
			if(dis[next.y][next.x] == INF){
				dis[next.y][next.x] = dis[u.y][u.x] + 1;
				q.push(next);
			}
		}
	}

	int ans = INF;
	rep(i,h) ans = min(ans, min(dis[i][0], dis[i][w - 1]));
	rep(i,w) ans = min(ans, min(dis[0][i], dis[h - 1][i]));

	return (ans + 3) / 4;
}


