int main() {
    scanf("%d%d%d", &H, &W, &K);

    int sx = -1, sy = -1;
    for(int i=0; i<H; i++) {
        for(int j=0; j<W; j++) {
            scanf(" %c", &board[i][j]);

            if(board[i][j] == 'S') {
                sx = i, sy = j;
            }
        }
    }

    queue< Elem > que;
    que.push( Elem{sx, sy, K} );

    set< pair<int, int> > init_vs;
    fill(visited[0], visited[810], INF);
    visited[sx][sy] = 0;

    while(que.size()) {
        Elem cur = que.front(); que.pop();
        init_vs.insert(make_pair(cur.x, cur.y));
        // printf("insert: x = %d, y = %d, cost = %d\n", cur.x, cur.y, visited[cur.x][cur.y]);
        if(cur.rest == 0) continue;

        for(int k=0; k<4; k++) {
            int nx = cur.x + dx[k], ny = cur.y + dy[k];
            if(nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
            if(board[nx][ny] == '#') continue;

            if(visited[nx][ny] != INF) continue;
            visited[nx][ny] = visited[cur.x][cur.y] + 1;
            que.push(Elem{nx, ny, cur.rest - 1});
        }
    }

    for(auto x : init_vs) {
        visited[x.first][x.second] = 0;
        que.push(Elem{x.first, x.second, 0});
    }
    while(que.size()) {
        Elem cur = que.front(); que.pop();

        for(int k=0; k<4; k++) {
            int nx = cur.x + dx[k], ny = cur.y + dy[k];
            if(nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
            if(visited[nx][ny] != INF) continue;
            visited[nx][ny] = visited[cur.x][cur.y] + 1;
            que.push(Elem{nx, ny, 0});
        }
    }

    int ans = INF;
    for(int i=0; i<W; i++) {
        // printf("pat a: val_l = %d, val_r = %d\n", visited[0][i], visited[H-1][i]);
        ans = min(ans, (visited[0  ][i] + K - 1) / K + 1);
        ans = min(ans, (visited[H-1][i] + K - 1) / K + 1);
    }
    for(int i=0; i<H; i++) {
        // printf("pat b: val_l = %d, val_r = %d\n", visited[i][0], visited[i][W-1]);
        ans = min(ans, (visited[i][0  ] + K - 1) / K + 1);
        ans = min(ans, (visited[i][W-1] + K - 1) / K + 1);
    }
    cout << ans << endl;
    return 0;
}

