        if((kc%k)==0) ans = (kc/k) + 1;
        else ans = (kc/k) + 2;
        for(pair <int, int> &den:cua1){
            int u = den.first, v = den.second;
            int dist = abs(e.first - u) + abs(e.second - v);
            if(kc%k==0){
                int y = kc/k;
                double x = double(dist)/k;
                --y;
                ans = min(ans, y + 2);
                int xx = int(x);
                if(xx <= y) ans = min(ans, y + 1);
            }
            else{
                int x = kc/k; ++x;
                ans = min(ans, x + 1);
                int y = dist/k;
                if(y < x) ans = min(ans, x);
            }
        }
        res = min(res, ans);
    }
    cout << res;
}

