int G_i, G_j;
int d[800][800];
int dx[4] = { 1, 0, -1, 0 };
int dy[4] = { 0, 1, 0, -1 };

int bfs() {
	queue<P>que;
	rep(i, H)
		rep(j, W)d[i][j] = INF;
	que.push(P(S_i, S_j));
	d[S_i][S_j] = 0;
	while (que.size()) {
		P p = que.front();
		que.pop();
		if (p.first == G_i&&p.second == G_j)break;
		rep(i, 4) {
			int nx = p.first + dx[i], ny = p.second + dy[i];
			if (0 <= nx&&nx < H && 0 <= ny&&ny < W&&A[nx][ny] != '#'&&d[nx][ny] == INF) {
				que.push(P(nx, ny));
				d[nx][ny] = d[p.first][p.second] + 1;
			}
		}
	}
	return d[G_i][G_j];
}


