	cin >> H >> W >> K;


	rep(i, H) {
		rep(j, W) {
			cin >> A[i][j];
			if (A[i][j] == 'S') {
				S_i = i;
				S_j = j;
			}
		}
	}
	int min_d = min(min(S_i - 1, H - 1 - S_i), min(S_j - 1, W - 1 - S_j));
	int ans = 0;
	int open = 0;
	G_i = S_i;
	G_j = S_j;
	while (1) {
