ll ans = INT_MAX;

ll movey[4] = {0, 0, -1, 1};
ll movex[4] = {-1, 1, 0, 0};

ll magic(ll y, ll x) {

	queue< vector<ll> > wow;
	wow.push({y, x, 0});

	while(!wow.empty()) {

		ll nowy = wow.front()[0];
		ll nowx = wow.front()[1];
		ll nowsteps = wow.front()[2];
		wow.pop();

		if(vis[nowy][nowx] || grid[nowy][nowx] == '#') continue;
		vis[nowy][nowx] = 1;

		ll add = 1;
		if(nowy == 0 || nowx == 0 || nowy == h-1 || nowx == w-1) add = 0;
		ans = min(ans, add + nowsteps / k + (nowsteps % k > 0));

		for(ll i=0;i<4;i++) {
			ll targety = nowy + movey[i];
			ll targetx = nowx + movex[i];
			if(targety < 0 || targetx < 0 || targety > h-1 || targetx > w-1) continue;
			if(vis[targety][targetx] || grid[targety][targetx] == '#') continue;
			wow.push({targety, targetx, nowsteps+1});
		}

	}

	return INT_MAX;

}

