int bfs()
{
    int dmin = INF;

    vector<deque<bool>> visited(H, deque<bool>(W, false));
    queue<tuple<int,int,int>> que;
    que.emplace(SX,SY,K);
    visited[SY][SX] = true;

    while(!que.empty()) {
        int x,y,n; tie(x,y,n) = POP(que);

        chmin(dmin, dist(x,y));
        if(n == 0) continue;

        for(const auto& p : neighbor4(x,y)) {
            int xx,yy; tie(xx,yy) = p;
            if(!in_bounds_wh(xx, yy, W, H)) continue;
            if(M[yy][xx] == '#') continue;
            if(visited[yy][xx]) continue;

            que.emplace(xx,yy,n-1);
            visited[yy][xx] = true;
        }
    }

    return dmin;
}

