  rep(i, H) cin >> A[i];
  int s = -1;
  rep(i, H) rep(j, W) if(A[i][j] == 'S') s = i*W+j;
  int dx[] = {0, -1, 0, 1};
  int dy[] = {-1, 0, 1, 0};
  vector<int> dist(H*W);
  auto bfs = [&](int s) {
    queue<int> q;
    q.push(s);
    vector<int> vis(H*W);
    while(!q.empty()) {
      int cur = q.front();
      q.pop();
      if(vis[cur]) continue;
      vis[cur] = true;
      int x = cur/W;
      int y = cur%W;
      rep(k, 4) {
        int nx = x+dx[k];
        int ny = y+dy[k];
        int ne = nx*W+ny;
        if(nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
        if(vis[ne]) continue;
        dist[ne] = dist[cur] + (A[nx][ny] == '#');
        q.push(ne);
      }
    }
  };
  auto bsearch = [&](int s) {
    auto test = [&](int k) {
      rep(i, H) if(dist[i*W]-dist[s] <= K*(k-1) ||
                   dist[i*W+W-1]-dist[s] <= K*(k-1)) return true;
      rep(j, W) if(dist[j]-dist[s] <= K*(k-1) ||
                   dist[(H-1)*W+j]-dist[s] <= K*(k-1)) return true;
      return false;
    };
    ll ok = H*W+1, ng = -1;
    while(ok-ng>1) {
      ll mid = (ok+ng)/2;
      (test(mid) ? ok : ng) = mid;
    }
    return ok;
  };
  ll ans = longinf;
  function<void(int, int, int)> dfs = [&](int cur, int par, int d) {
    if(d > K) return;
    ans = min(bsearch(cur), ans);
    int i = cur/W;
    int j = cur%W;
    rep(k, 4) {
      int nx = i+dx[k];
      int ny = j+dy[k];
      if(nx < 0 || nx >= H || ny < 0 || ny >= W) continue;
      if(nx*W+ny == par) continue;
      if(A[nx][ny] == '.') dfs(nx*W+ny, cur, d+1);
    }
  };
  bfs(s);
  dfs(s, -1, 0);
  cout << ans << "\n";
  return 0;
}

