priority_queue <pq> cari;
bool masuk(int bar,int kol){
	return (1<=bar&&bar<=baris&&1<=kol&&kol<=kolom);
}
bool pinggir(int bar,int kol){
	return (bar==1||bar==baris||kol==1||kol==kolom);
}
bool masuk(pii pos){
	return masuk(pos.fi,pos.se);
}
bool pinggir(pii pos){
	return pinggir(pos.fi,pos.se);
}
