      cin >> a;
      if(a == 'S') {
        sh = i;
        sw = j;
      }

      buil[i][j] = a;
    }
  }

  mini = min(min(sh, h - sh), min(sw, w - sw));

  if(!tansaku(sh, sw, 0)) {
    out(1);
    return 0;
  }

  out(mini / k + (mini % k == 0 ? 1 : 2));
}

