	for (i=0; i<h; i++) {
		cin >> s;
		for (j=0; j<w; j++) {
			if (s[j] == '#') maze[i][j] = 1;
			else if (s[j] == 'S') {ini=i; fin=j;}
		}
	}

	BFS(ini, fin);

	pair <int, int> res;
	res.first = res.second = INT_MAX;

	for (i=0; i<h; i++) res = min(res, memo[0][i]); // cout << memo[0][i].first-1 << " " << memo[0][i].second << " | "; cout << endl;
	for (i=0; i<h; i++) res = min(res, memo[w-1][i]); //cout << memo[w-1][i].first-1 << " " << memo[w-1][i].second << " | "; cout << endl;
	for (i=0; i<w; i++) res = min(res, memo[i][0]); //cout << memo[i][0].first-1 << " " << memo[i][0].second << " | "; cout << endl;
	for (i=0; i<w; i++) res = min(res, memo[i][h-1]);//cout << memo[i][h-1].first-1 << " " << memo[i][h-1].second << " | "; cout << endl;

	//cout << res.first << " " << res.second << endl;

	int r = 0;

	if (res.second == 0) {
		r = res.first/k;
		if (res.first%k != 0) r++;
	}
	else {

		res.first -= 1;

		if (res.first == res.second) {
			r=1;
			r += res.second/k;
			if (res.second%k != 0) r++;
		}

		else {
			r += res.second/k;
			if (res.second%k != 0) r++;

			res .first -= (r*k);
			res.first = ((res.first%k == 0)?0:1)+(res.first/k);
			r += res.first;
		}
	}

	cout << r << endl;

