void Dfs(int x, int y, int t, int dep) {
	if(dep > k) return;
	vis[x][y] = 1;
	for(int i = 1; i <= 4; i++) {
		int px = x + dx[i], py = y + dy[i];
		if(Check(px, py) && a[px][py] != '#') {
			Node r; r.x = px; r.y = py; r.t = t + 1;
			seq[++tail] = r;
			dis[r.x][r.y] = r.t;
			Dfs(px, py, t, dep + 1);
		}
	}
}

void Dfs1(int x, int y, int t, int dep) {
	if(dep > k) return;
	vis[x][y] = 1;
	for(int i = 1; i <= 4; i++) {
		int px = x + dx[i], py = y + dy[i];
		if(Check(px, py)) {
			Node r; r.x = px; r.y = py; r.t = t + 1;
			seq[++tail] = r;
			dis[r.x][r.y] = r.t;
			Dfs1(px, py, t, dep + 1);
		}
	}
}

void Bfs(Node s) {
	memset(dis, 60, sizeof(dis));
	memset(vis, 0, sizeof(vis));
	dis[s.x][s.y] = 1; s.t = 1; 
	head = 1; tail = 0;
	seq[++tail] = s; vis[s.x][s.y] = 1;
	for(int i = 1; i <= 4; i++) {
		int px = s.x + dx[i], py = s.y + dy[i];
		if(Check(px, py) && a[px][py] != '#') {
			Node r; r.x = px; r.y = py; r.t = s.t;
			seq[++tail] = r;
			dis[r.x][r.y] = r.t;
			Dfs(px, py, s.t - 1, 1);
		}
	}
	while(head <= tail) {
		Node now = seq[head];
		for(int i = 1; i <= 4; i++) {
			int px = now.x + dx[i], py = now.y + dy[i];
			if(Check(px, py)) {
				Node r; r.x = px; r.y = py; r.t = now.t + 1;
				seq[++tail] = r;
				dis[r.x][r.y] = r.t;
				Dfs1(px, py, now.t, 1);
			}
		}
		head++;
	}
}

