int dx[] = {-1, 0, 1, 0};
int dy[] = {0, -1, 0, 1};

void solve() {
  int h, w, k;
  cin >> h >> w >> k;
  vstr a(h);
  cin >> a;
  int sx, sy;
  rep(i, h) rep(j, w) if (a[i][j] == 'S') {
    sx = i, sy = j;
  }
  vector<vi32> dp(h, vi32(w, 1e9));
  using T = tuple<int, int, int, int>;
  queue<T> q;
  q.emplace(sx, sy, 1, k);
  while (sz(q)) {
    int x, y, c, s;
    tie(x, y, c, s) = q.front();
    q.pop();
    if (dp[x][y] != 1e9) continue;
    dp[x][y] = c;
    if (s == 0) continue;
    rep(i, 4) {
      int nx = x + dx[i];
      int ny = y + dy[i];
      if (nx < 0 || nx >= h || ny < 0 || ny >= w) continue;
      if (a[nx][ny] == '#') continue;
      q.emplace(nx, ny, c, s - 1);
    }
  }
  rep(i, h) rep(j, w) if (dp[i][j] != 1e9) {
    rep(i, 4) {
      int nx = i + dx[i];
      int ny = j + dy[i];
      if (nx < 0 || nx >= h || ny < 0 || ny >= w) continue;
      if (dp[nx][ny] != 1e9) continue;
      q.emplace(nx, ny, 2, k - 1);
    }
  }
  while (sz(q)) {
    int x, y, c, s;
    tie(x, y, c, s) = q.front();
    q.pop();
    if (dp[x][y] != 1e9) continue;
    dp[x][y] = c;
    if (s == 0) {
      c += 1;
      s = k;
    }
    rep(i, 4) {
      int nx = x + dx[i];
      int ny = y + dy[i];
      if (nx < 0 || nx >= h || ny < 0 || ny >= w) continue;
      q.emplace(nx, ny, c, s - 1);
    }
  }
  int ans = 1e9;
  rep(i, h) {
    amin(ans, dp[i][0]);
    amin(ans, dp[i][w - 1]);
  }
  rep(j, w) {
    amin(ans, dp[0][j]);
    amin(ans, dp[h - 1][j]);
  }
  cout << ans << endl;
}

