  vector<string> A(M); read(A);
  dout << "============================================================" << endl;
  dout << db(K) << endl; for (auto& a : A) dout << a << endl;

  int iStart = -1, jStart = -1;
  Loop(i, M) Loop(j, N) if (A[i][j] == 'S') {
    assert(iStart == -1);
    A[i][j] = '.', iStart = i, jStart = j;
  }

  vector<Vi> dist(M, Vi(N, INT_MAX));
  queue<Pii> q;
  push(q, {iStart, jStart});
  dist[iStart][jStart] = 0;
  while (!q.empty()) {
    int i, j; tie(i, j) = pop(q);
