    assert(dist[i][j] < INT_MAX);
    Loop(d, 4) {
      int u = i + DI[d], v = j + DJ[d];
      if (Bounded(u, 0, M-1) && Bounded(v, 0, N-1) && A[u][v] != '#' && dist[u][v] == INT_MAX) {
        dist[u][v] = 1 + dist[i][j];
        push(q, {u, v});
        dout << db(i) << db(j) << db(u) << db(v) << endl;
