const int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};
const int INF = 1e8;

struct point {
  int x, y;
};

void solve(int H, int W, int K, std::vector<std::string> A) {
  int sx, sy;
  rep(i, 0, H) {
    rep(j, 0, W) {
      if (A[i][j] == 'S') {
        sx = i;
        sy = j;
      }
    }
  }

  // 移動できるところに移動
  vector<vi> dp(H, vi(W, INF));
  queue<pair<point, int>> q;

  dp[sx][sy] = 1;
  q.push(mp((point){sx, sy}, 0));

  while (!q.empty()) {
    point p = q.front().first;
    int c = q.front().second;
    q.pop();

    rep(k, 0, 4) {
      int nx = p.x + dx[k];
      int ny = p.y + dy[k];

      if (nx >= 0 && nx < H && ny >= 0 && ny < W && A[nx][ny] == '.' &&
          dp[nx][ny] > c + 1) {
        dp[nx][ny] = c + 1;
        q.push(mp((point){nx, ny}, c + 1));
      }
    }
  }

  // そこから端までの最小距離を求める
  int ans = INF;
  rep(i, 0, H) {
    rep(j, 0, W) {
      if (dp[i][j] <= K) {
        chmin(ans, i);
        chmin(ans, j);
        chmin(ans, W - j - 1);
        chmin(ans, H - i - 1);
      }
    }
  }
  print((ans + K - 1) / K + 1);
}

