	FOR(i, 0, n) {
		scanf("%s", a[i]);
	}
	int x = -1;
	int y = -1;
	FOR(i, 0, n) {
		FOR(j, 0, m) {
			if (a[i][j] == 'S') {
				x = i;
				y = j;
			}
		}
	}
	MEMS(d, -1);
	d[x][y] = 0;
	p[0][0] = x;
	p[0][1] = y;
	int l = 0;
	int r = 0;
	while (l <= r) {
		int x = p[l][0];
		int y = p[l++][1];
		FOR(k, 0, 4) {
			int nx = x + dx[k];
			int ny = y + dy[k];
			if ((nx >= 0) && (nx < n) && (ny >= 0) && (ny < m) && (a[nx][ny] == '.') && (d[nx][ny] == -1)) {
				r++;
				p[r][0] = nx;
				p[r][1] = ny;
				d[nx][ny] = d[x][y] + 1;
			}
		}
	}
	int res = 100500;
	FOR(i, 0, n) {
		FOR(j, 0, m) {
			if ((d[i][j] != -1) && (d[i][j] <= k)) {
				relax(res, i, k);
				relax(res, j, k);
				relax(res, n - i - 1, k);
				relax(res, m - j - 1, k);
			}
		}
	}
	cout << res + 1 << endl;

#ifdef Fcdkbear
	double end = clock();
	fprintf(stderr, "*** Total time = %.3lf ***\n", (end - beg) / CLOCKS_PER_SEC);
