    if(p.first >= 0 && p.first < H && p.second >= 0 && p.second < W) return true;
    else return false;
}

void bfs(int d, int h, int w){
    dist[h][w] = 0;
    queue<P> que;
    que.push(P(h, w));
    used[h][w] = true;
    while(!que.empty()){
        P top = que.front();
        int y = top.first;
        int x = top.second;
        que.pop();
        if(dist[y][x] == K) continue;

        if(isValid(P(y-1, x)) && A[y-1][x] == '.' && !used[y-1][x]) {
            que.push(P(y-1, x));
            dist[y-1][x] = dist[y][x]+1;
            used[y-1][x] = true;
        }
        if(isValid(P(y+1, x)) && A[y+1][x] == '.' && !used[y+1][x]) {
            que.push(P(y+1, x));
            dist[y+1][x] = dist[y][x]+1;
            used[y+1][x] = true;
        }
        if(isValid(P(y, x-1)) && A[y][x-1] == '.' && !used[y][x-1]) {
            que.push(P(y, x-1));
            dist[y][x-1] = dist[y][x]+1;
            used[y][x-1] = true;
        }
        if(isValid(P(y, x+1)) && A[y][x+1] == '.' && !used[y][x+1]) {
            que.push(P(y, x+1));
            dist[y][x+1] = dist[y][x]+1;
            used[y][x+1] = true;
