int res;

void EnQueue(int x)
{
	q[tail] = x;
	tail ++;
}

int DeQueue()
{
	int r = q[front];
	front ++;
	return r;
}

void solve()
{
	int i, j;
	for(i=0; i<H; i++){
		for(j=0; j<W; j++)
			vis[i][j] = 0;
	}
	for(i=0; i<H; i++){
		for(j=0; j<W; j++){
			if(A[i][j] == 'S'){
				si = i, sj = j;
				break;
			}
		}
	}
	front = tail = 0;
	EnQueue(si);
	EnQueue(sj);
	EnQueue(0);
	vis[si][sj] = 1;
	int ui, uj, ul;
	int vi, vj, vl;
	int ok = 0;
	while(front != tail){
		ui = DeQueue();
		uj = DeQueue();
		ul = DeQueue();
		if(ui==0 || ui==H-1 || uj==0 || uj == W-1){
			ok = 1;
			break;
		}
		if(ul == K)
			break;
		for(i=0; i<4; i++){
			vi = ui + step[i][0];
			vj = uj + step[i][1];
			vl = ul + 1;
			if(A[vi][vj] == '.' && vis[vi][vj] == 0){
				EnQueue(vi);
				EnQueue(vj);
				EnQueue(vl);
				vis[vi][vj] = 1;
			}
		}
	}
	if(ok == 1){
