		return ;
	}
	front = tail = 0;
	for(i=0; i<H; i++){
		for(j=0; j<W; j++){
			if(vis[i][j] == 1){
				EnQueue(i);
				EnQueue(j);
				EnQueue(0);
			}
		}
	}
	while(front != tail){
		ui = DeQueue();
		uj = DeQueue();
		ul = DeQueue();
		if(ui==0 || ui==H-1 || uj==0 || uj == W-1){
			ok = 1;
			break;
		}
		for(i=0; i<4; i++){
			vi = ui + step[i][0];
			vj = uj + step[i][1];
			vl = ul + 1;
			if(vis[vi][vj] == 0){
				EnQueue(vi);
				EnQueue(vj);
				EnQueue(vl);
				vis[vi][vj] = 1;
			}
		}
	}
	res = (ul-1)/K + 1 + 1;
	printf("%d\n", res);
}

