lint dp[800][800];
lint canvisit[800][800];
char mp[800][800];
lint H, W, K, sy, sx;
int main() {
	cin >> H >> W >> K;
	REP(i, H) {
		REP(j, W) {
			cin >> mp[i][j];
			if (mp[i][j] == 'S') sy = i, sx = j;
			canvisit[i][j] = INF;
			dp[i][j] = INF;
		}
	}
	queue<plint> que;
	que.push({ sy, sx });
	canvisit[sy][sx] = 0;
	lint dy[4] = { 0, 1, 0, -1 }, dx[4] = { 1, 0, -1, 0 };
	while (!que.empty()) {
		plint curr = que.front(); que.pop();
		REP(k, 4) {
			lint ny = curr.first + dy[k], nx = curr.second + dx[k];
			if (ny < 0 || ny >= H || nx < 0 || nx >= W) continue;
			lint s = (mp[ny][nx] == '#' ? 1 : 0);
			if (canvisit[curr.first][curr.second] + s < canvisit[ny][nx]) {
				canvisit[ny][nx] = canvisit[curr.first][curr.second] + s;
				que.push({ ny, nx });
			}
		}
	}

	dp[sy][sx] = 0;
	que.push({ sy, sx });
	while (!que.empty()) {
		plint curr = que.front(); que.pop();
		REP(k, 4) {
			lint ny = curr.first + dy[k], nx = curr.second + dx[k];
			if (ny < 0 || ny >= H || nx < 0 || nx >= W) continue;
			if (dp[ny][nx] > dp[curr.first][curr.second] + 1) {
				dp[ny][nx] = dp[curr.first][curr.second] + 1;
				que.push({ ny, nx });
			}
		}
	}

	lint minv = 800 * 800;
	REP(i, H) {
		REP(j, W) {
			dp[i][j] = max((canvisit[i][j] - 1) / K + 2, (dp[i][j] - 1) / K + 1);
		}
	}
	REP(i, W) {
		chmin(minv, dp[0][i]);
		chmin(minv, dp[H - 1][i]);
	}
	REP(i, H) {
		chmin(minv, dp[i][0]);
		chmin(minv, dp[i][W - 1]);
	}
	cout << minv << endl;
}

