typedef pair<int,int> pii;
const int dx[4]={1,-1,0,0};
const int dy[4]={0,0,1,-1};
bool b[805][805],vis[805][805];
int dist[805][805];
char t;
int n,m,k,ans=INT_MAX,sx,sy;
void swap_int(int &a,int &b)
{
	a^=b;
	b^=a;
	a^=b;
}
bool inrange(int x,int y)
{
	return x>0&&x<=n&&y>0&&y<=m;
}
queue<pii> q;
int main(int argv,char *argc[])
{
	cin>>n>>m>>k;
	for(int i=1;i<=n;i++)
	{
		for(int j=1;j<=m;j++)
		{
			t=getchar();
			while(t!='#'&&t!='S'&&t!='.')
			{
				t=getchar();
			}
			b[i][j]=(t=='#');
			if(t=='S')
			{
				sx=i,sy=j;
			}
		}
	}
	q.push(make_pair(sx,sy));
	vis[sx][sy]=1;
	while(!q.empty())
	{
		pii fr=q.front();
		q.pop();
		int x=fr.first,y=fr.second;
		if(dist[x][y]==k)
		{
			continue;
		}
		for(int dir=0;dir<4;dir++)
		{
			int nx=x+dx[dir],ny=y+dy[dir];
			if(inrange(nx,ny))
			{
				if(!vis[nx][ny]&&!b[nx][ny])
				{
					vis[nx][ny]=1;
					dist[nx][ny]=dist[x][y]+1;
					q.push(make_pair(nx,ny));
				}
			}
		}
	}
	for(int i=1;i<=n;i++)
	{
		for(int j=1;j<=m;j++)
		{
			if(vis[i][j])
			{
				int dis=min(i-1,min(j-1,min(n-i,m-j)));
				ans=min(ans,(dis%k==0?(dis/k):(dis/k+1)));
			}
		}
	}
	ans++;
	cout<<ans;
	return 0;
}

