int H;
int W;

int K;

int SX;
int SY;

vector<string> M;

int dist(int x, int y)
{
    int d1 = x;
    int d2 = W-1 - x;
    int d3 = y;
    int d4 = H-1 - y;

    return min({ d1, d2, d3, d4 });
}

int dmin = INF;
vector<deque<bool>> visited;

void dfs(int x, int y, int n)
{
    chmin(dmin, dist(x,y));
    visited[y][x] = true;

    if(n == 0) return;

    for(const auto& p : neighbor4(x,y)) {
        int xx,yy; tie(xx,yy) = p;
        if(!in_bounds_wh(xx, yy, W, H)) continue;
        if(M[yy][xx] == '#') continue;
        if(visited[yy][xx]) continue;

        dfs(xx, yy, n-1);
    }
}

void solve()
{
    visited.assign(H, deque<bool>(W, false));
    dfs(SX, SY, K);

#ifdef DEBUG
    DBG(dmin);
#endif

    int ans = 1 + div_ceil(dmin, K);

    PRINTLN(ans);
}

