            if(c == 'S') {
                SX = x;
                SY = y;
            }
        }
        M.emplace_back(s);
    }

#ifdef DEBUG
    DBG(SX);
    DBG(SY);
    DBG(M);
#endif

    solve();

    EXIT();
}

