char g[kN][kN]; bool vis[kN][kN];
std::queue <pii> que;

void Bfs() {
	memset(vis, false, sizeof(vis));
	que.push(mkp(stx, sty));
	while(!que.empty()) {
		pii cur = que.front(); que.pop();
	//	printf("VIS: %d %d\n", cur.fi, cur.se);
		for(int i = 0; i < 4; ++i) {
			int nx = cur.fi + step[i][0], ny = cur.se + step[i][1], nd;
			if(nx <= 0 || ny <= 0 || nx > H || ny > W) continue;
			nd = d[cur.fi][cur.se] + 1;
			if(g[nx][ny] != '.') continue;
			if(!vis[nx][ny]) {
				d[nx][ny] = nd; vis[nx][ny] = true;
				que.push(mkp(nx, ny));
			}
		}
	}
}
void Bfs2() {
	for(int i = 1; i <= H; ++i)
		for(int j = 1; j <= W; ++j)
			if(d[i][j] <= K) que.push(mkp(i, j));
	while(!que.empty()) {
		pii cur = que.front(); que.pop();
	//	printf("VIS: %d %d\n", cur.fi, cur.se);
		for(int i = 0; i < 4; ++i) {
			int nx = cur.fi + step[i][0], ny = cur.se + step[i][1], nd;
			if(nx <= 0 || ny <= 0 || nx > H || ny > W) continue;
			nd = d2[cur.fi][cur.se] + 1;
			if(!vis[nx][ny]) {
				d2[nx][ny] = nd; vis[nx][ny] = true;
				que.push(mkp(nx, ny));
			}
		}
	}
}

