		for(int j = 1; j <= W; ++j)
			if(g[i][j] == 'S') {
				g[i][j] = '.';
				stx = i; sty = j;
			}
	Bfs(); Bfs2();
	int ans = 0;
	for(int i = 1; i <= H; ++i)
		for(int j = 1; j <= W; ++j) {
			if(i == 1 || j == 1 || i == H || j == W) {
				ans = std::max(ans, (d2[i][j] - 1) / K + 1);
			}
