    if (sh!=H-1) dfs(sh+1,sw,K);
    if (sh!=0) dfs(sh-1,sw,K);
    if (sw!=W-1) dfs(sh,sw+1,K);
    if (sw!=0) dfs(sh,sw-1,K);
  }
}

