using namespace std;

typedef pair<int, int> P;

int H, W, K;
char A[800][800];
bool used[800][800];
int dist[800][800];

bool isValid(P p){
    if(p.first >= 0 && p.first < H && p.second >= 0 && p.second < W) return true;
    else return false;
}

void bfs(int d, int h, int w){
    dist[h][w] = 0;
    queue<P> que;
    que.push(P(h, w));
    used[h][w] = true;
    while(!que.empty()){
        P top = que.front();
        int y = top.first;
        int x = top.second;
        que.pop();
        if(dist[y][x] == K) continue;

        if(isValid(P(y-1, x)) && A[y-1][x] == '.' && !used[y-1][x]) {
            que.push(P(y-1, x));
            dist[y-1][x] = dist[y][x]+1;
            used[y-1][x] = true;
        }
        if(isValid(P(y+1, x)) && A[y+1][x] == '.' && !used[y+1][x]) {
            que.push(P(y+1, x));
            dist[y+1][x] = dist[y][x]+1;
            used[y+1][x] = true;
        }
        if(isValid(P(y, x-1)) && A[y][x-1] == '.' && !used[y][x-1]) {
            que.push(P(h, w-1));
            dist[y][x-1] = dist[y][x]+1;
            used[y][x-1] = true;
        }
        if(isValid(P(y, x+1)) && A[y][x+1] == '.' && !used[y][x+1]) {
            que.push(P(y, x-1));
            dist[y][x+1] = dist[y][x]+1;
            used[y][x+1] = true;
        }
    }
}

int main(){
    cin >> H >> W >> K;
    P s;
    for(int i = 0; i < H; i++){
        for(int j = 0; j < W; j++){
            cin >> A[i][j];
            if(A[i][j] == 'S') s = P(i, j);
            used[i][j] = false;
        }
    }
    bfs(0, s.first, s.second);
    int min_dist = 800;
     for(int i = 0; i < H; i++){
        for(int j = 0; j < W; j++){
            if(used[i][j]){
                min_dist = min(min_dist, min({i, j, H-i-1, W-j-1}));
            }
        }
    }
    cout << 1+((min_dist+K-1)/K) << endl;
}

#include<bits/stdc++.h>
using namespace std;

long long H, W, K;

long long A[805][805];
long long WORK[805][805];

#define OPEN INT_MAX
#define CLOSED LONG_MAX/3


bool valid(long long h, long long w){
	return (h >= 0) && (h < H) && (w >= 0) && (w < W);
}

void move(long long h, long long w, long long cost){
	if(valid(h, w) == false || A[h][w] == CLOSED || cost > K || A[h][w] <= cost){
		return;
	}
	A[h][w] = cost;
	move(h-1, w, cost+1);
	move(h+1, w, cost+1);
	move(h, w-1, cost+1);
	move(h, w+1, cost+1);
}

void firstmove(){
	for(long long h = 0; h < H; h++){
		for(long long w = 0; w < W; w++){
			if(A[h][w] == 1){
				move(h, w, (long long)0);
				return;
			}
		}
	}
}


int main(){
	cin >> H >> W >> K;

	for(long long h = 0; h < H; h++){
		string S;
		cin >> S;
		for(long long w = 0; w < W; w++){
			if(S[w] == '.'){
				A[h][w] = OPEN;
			}else if(S[w] == 'S'){
				A[h][w] = 1;
			}else{
				A[h][w] = CLOSED;
			}
		}
	}

	firstmove();
	cout << 0 << endl;
	return 0;

	long long ans = INT_MAX;
	for(long long h = 0; h < H; h++){
		for(long long w = 0; w < W; w++){
			if(A[h][w] != OPEN && A[h][w] != CLOSED){
				long long tmp;
				tmp = h;
				tmp = min(tmp, w);
				tmp = min(tmp, H - h - 1);
				tmp = min(tmp, W - w - 1);
				if(tmp % K == 0){
					ans = min(ans, tmp/K);
				}else{
					ans = min(ans, tmp/K + 1);
				}
			}
		}
	}
	cout << ans + 1 << endl;
}

