const int MAXN = 800;

int n, m, K;

char a[MAXN + 5][MAXN + 5];

inline void input()
{
	n = read<int>(), m = read<int>(), K = read<int>();
	for(int i = 1; i <= n; ++i)
		for(int j = 1; j <= m; ++j)
			a[i][j] = safe_getc();
}

struct node
{
	int x, y;

	node() { }
	node(int _x, int _y): x(_x), y(_y) { }
};

int d[MAXN + 5][MAXN + 5];

inline void BFS()
{
	static queue<node> q;
	memset(d, -1, sizeof d);

	for(int i = 1; i <= m; ++i)
	{
		d[1][i] = 0, q.emplace(1, i);
		d[n][i] = 0, q.emplace(n, i);
	}
	for(int i = 1; i <= n; ++i)
	{
		d[i][1] = 0, q.emplace(i, 1);
		d[i][m] = 0, q.emplace(i, m);
	}

	while(!q.empty())
	{
		node u = q.front();
		q.pop();

		static const int D[4][2] = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
		for(int i = 0; i < 4; ++i)
		{
			node v(u.x + D[i][0], u.y + D[i][1]);
			if(v.x < 1 || v.y < 1 || v.x > n || v.y > m || d[v.x][v.y] != -1) continue;
			d[v.x][v.y] = d[u.x][u.y] + 1, q.push(v);
		}
	}
}

inline void solve()
{
	BFS();

	static int d0[MAXN + 5][MAXN + 5];

	static queue<node> q;
	memset(d0, -1, sizeof d0);

	for(int i = 1; i <= n; ++i)
		for(int j = 1; j <= m; ++j)
			if(a[i][j] == 'S') d0[i][j] = 0, q.emplace(i, j);

	while(!q.empty())
	{
		node u = q.front();
		q.pop();

		static const int D[4][2] = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
		for(int i = 0; i < 4; ++i)
		{
			node v(u.x + D[i][0], u.y + D[i][1]);
			if(v.x < 1 || v.y < 1 || v.x > n || v.y > m || d0[v.x][v.y] != -1 || a[v.x][v.y] == '#') continue;
			d0[v.x][v.y] = d0[u.x][u.y] + 1, q.push(v);
		}
	}

	int ans = INT_MAX;
	for(int i = 1; i <= n; ++i)
		for(int j = 1; j <= m; ++j)
			if(d0[i][j] != -1 && d0[i][j] <= K) chkmin(ans, (d[i][j] + K - 1) / K + 1);
	printf("%d\n", ans);
}

int main()
{
#ifdef K_ON
	freopen("C.in", "r", stdin);
	freopen("C.out", "w", stdout);
#endif

	input();
	solve();

	return 0;
}

