i64 gcd(i64 n, i64 m) {return (m == 0? n : gcd(m, n % m));}
i64 lcm(i64 n, i64 m) {return (n / gcd(n, m) * m);}
int dx[] = {0, -1, 0, 1, 1, 1, -1, -1};
int dy[] = {-1, 0, 1, 0, 1, -1, 1, -1};

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);

  int h, w, k;
  cin >> h >> w >> k;

  int sx, sy;
  vvt<bool> grid(h + 2, vt<bool>(w + 2, false));
  rep(i, 0, h) {
    string s;
    cin >> s;

    rep(j, 0, w) {
      if(s[j] == 'S') {
        sx = j + 1;
        sy = i + 1;
        grid[sy][sx] = true;
      }
      else if(s[j] == '.') grid[i + 1][j + 1] = true;
    }
  }

  vvt<int> dist(h + 2, vt<int>(w + 2, INF));
  dist[sy][sx] = 0;
  queue<pi> que;
  que.push({sx, sy});
  while(!que.empty()) {
    int x = que.front().first, y = que.front().second;
    que.pop();

    rep(i, 0, 4) {
      int nx = x + dx[i], ny = y + dy[i];
      if(!grid[ny][nx] || dist[y][x] + 1 >= dist[ny][nx]) continue;
      dist[ny][nx] = dist[y][x] + 1;
      que.push({nx, ny});
    }
  }

  int ans = INF;
  rep(i, 1, h + 1) {
    rep(j, 1, w + 1) {
      if(dist[i][j] > k) continue;

      int cost = min({h - i, w - j, i - 1, j - 1});
      ans = min(ans, cost / k + !!(cost % k));
    }
  }
  cout << ans + 1 << endl;
}

