int A[1000][1000];
int D[1000][1000];
bool check[1000][1000];

struct bfs{
    int x, y, dist;
    bfs(int x, int y, int dist): x(x), y(y), dist(dist) {}
};

int main(){
    int H, W, K, si, sj;
    cin >> H >> W >> K;
    REP(i, H){
        string s;
        cin >> s;
        REP(j, W){
            check[i][j] = false;
            int tate = min(i, H-i);
            int yoko = min(j, W-j);
            D[i][j] = min(tate, yoko);
            if(s[j]=='#'){
                A[i][j] = 0;
            }else if(s[j]=='.'){
                A[i][j] = 1;
            }else{
                A[i][j] = 2;
                si = i;
                sj = j;
            }
        }
    }
    int res = INT_MAX/3;
    queue<bfs> que;
    bfs s(si, sj, 0);
    que.push(s);
    while(!que.empty()){
        bfs b = que.front();que.pop();
        //cout << b.x << " " << b.y << " " << b.dist << endl;
        check[b.x][b.y] = true;
        res = min(res, D[b.x][b.y]);
        if(b.dist < K){
            if(check[b.x+1][b.y] == false && A[b.x+1][b.y] != 0 && b.x+1<W){
                //cout << 1 << endl;
                bfs b1(b.x+1, b.y, b.dist+1);
                que.push(b1);
            }
            if(check[b.x-1][b.y] == false && A[b.x-1][b.y] != 0 && b.x-1>-1){
                //cout << 2 << endl;
                bfs b1(b.x-1, b.y, b.dist+1);
                que.push(b1);
            }
            if(check[b.x][b.y+1] == false && A[b.x][b.y+1] != 0 && b.y+1<H){
                //cout << 3 << endl;
                bfs b1(b.x, b.y+1, b.dist+1);
                que.push(b1);
            }
            if(check[b.x][b.y-1] == false && A[b.x][b.y-1] != 0 && b.y-1>-1){
                //cout << 4 << endl;
                bfs b1(b.x, b.y-1, b.dist+1);
                que.push(b1);
            }
        }
    }
    cout << (res==0 ? 1 : 2 + (res-1)/K) << endl;
    return 0;
}

#include <bits/stdc++.h>
using std::cout;
using std::endl;
using std::cin;
constexpr int vx[] = {1, 0, -1, 0}, vy[] = {0, 1, 0, -1};

std::vector<std::string> s;
int h, w, k, sx, sy;

int dist(int x, int y){
	int A = std::min({abs(x - (h - 1)), x, abs(y - (w - 1)), y});
	assert(A >= 0);

	return (A + k - 1) / k;
}

int main(){
	cin >> h >> w >> k; s.resize(h);
	for(int i = 0; i < h; i++){
		cin >> s[i];

		for(int j = 0; j < w; j++){
			if(s[i][j] != 'S') continue;
			sx = i; sy = j;
			break;
		}
	}

	int mi = dist(sx, sy) + 1;
	std::queue<std::pair<int, int>> qu; qu.push({sx, sy});
	std::vector<std::vector<int>> min_cost(h, std::vector<int>(w, 1e9));
	min_cost[sx][sy] = 0;
	while(!qu.empty()){
		auto p = qu.front(); qu.pop();

		for(int i = 0; i < 4; i++){
			int nx = p.first + vy[i], ny = p.second + vx[i];
			if(nx<0||ny<0||nx>=h||ny>=w||s[nx][ny] == '#') continue;
			if(min_cost[p.first][p.second] + 1 >= min_cost[nx][ny]) continue;
			min_cost[nx][ny] = min_cost[p.first][p.second] + 1;
			mi = std::min(mi, dist(nx, ny) + 1);
			qu.push({nx, ny});
		}
	}

	cout << mi << endl;
	return 0;
}

