typedef long long ll;
typedef long double ld;
typedef pair<int,int>pii;
const int INF = 1e9 + 10;
const int MN = 850;

pii q[MN*MN];
bool mk[MN][MN];
int l , r , R , C;
string s[MN];
int n , m , k;
int dist[MN][MN];

int dx[4] = {-1 , 0 , 0 , 1};
int dy[4] = {0 , -1 , 1 , 0};

bool valid(int tr,int tc){
	if(tr < 0 || tc < 0 || tr >= n || tc >= m) return false;
	return true;
}

void bfs()
{
	for(int i=0;i<MN;++i) fill(dist[i] , dist[i] + MN , INF);
	mk[R][C] = true , dist[R][C] = 0;
	q[r++] = {R , C};
	while(l < r){
		pii v = q[l++];
		for(int d=0;d<4;++d){
			int tr = v.first + dx[d] , tc = v.second + dy[d];
			if(valid(tr , tc) && s[tr][tc] != '#'&& !mk[tr][tc]){
				mk[tr][tc] = true;
				dist[tr][tc] = dist[v.first][v.second]+1;
				q[R++] = {tr , tc};
			}
		}
	}	
}

int F(int a){
	return (a+k-1)/k;
}

int main()
{
	ios_base :: sync_with_stdio(false) ,cin.tie(0) , cout.tie(0);
	cin >> n >> m >> k;
	for(int i=0;i<n;++i) cin >> s[i];
	for(int i=0;i<n;++i)
		for(int j=0;j<m;++j)
			if(s[i][j] == 'S')
				R = i , C = j;
	int Ans = INF;
	bfs();
	for(int i=0;i<n;++i)
		for(int j=0;j<m;++j) if(dist[i][j] <= k){
			int V = min(min(i , n-1-i) , min(j , m-1-j)); 
			Ans = min(Ans , 1 + F(V));
		}
	cout << Ans << '\n';
