    int ans=min(ans,a/k+(a%k>0));
    ans=min(ans,b/k+(b%k>0));
    ans=min(ans,(n-a-1)/k+((n-a-1)%k>0));
    ans=min(ans,(m-b-1)/k+((m-b-1)%k>0));
    return ans;
}
