using namespace std;

void minDist(const vector<string>& plane, char wall, int y0, int x0, vector<vector<int> >& dist)
{
    int dy[] = {0, 0, -1, 1};
    int dx[] = {-1, 1, 0, 0};

    int h = plane.size();
    int w = plane[0].size();
    dist.assign(h, vector<int>(w, -1));

    queue<pair<int, int> > q;
    q.push(make_pair(y0, x0));
    dist[y0][x0] = 0;
    int n = 1;
    while(!q.empty()){
        queue<pair<int, int> > q1;
        while(!q.empty()){
            int y = q.front().first;
            int x = q.front().second;
            q.pop();
            for(int i=0; i<4; ++i){
                int y1 = y + dy[i];
                int x1 = x + dx[i];
                if(0 <= y1 && y1 < h && 0 <= x1 && x1 < w && plane[y1][x1] != wall && dist[y1][x1] == -1){
                    q1.push(make_pair(y1, x1));
                    dist[y1][x1] = n;
                }
            }
        }
        ++ n;
        q = q1;
    }
}

int main()
{
    int h, w, k;
    cin >> h >> w >> k;
    vector<string> s(h, string(w, ' '));
    int sy, sx;
    for(int y=0; y<h; ++y){
        for(int x=0; x<w; ++x){
            cin >> s[y][x];
            if(s[y][x] == 'S'){
                sy = y;
                sx = x;
            }
        }
    }

    vector<vector<int> > dist;
    minDist(s, '#', sy, sx, dist);
    int ans = INT_MAX;
    for(int y=0; y<h; ++y){
        for(int x=0; x<w; ++x){
            if(dist[y][x] == -1 || dist[y][x] > k)
                continue;
            int d = min({ y, h-1-y, x, w-1-x });
            ans = min(ans, 1 + (d + k - 1) / k);
        }
    }
    cout << ans << endl;

    return 0;
}

