template<typename T> T read(T &x)
{
    int f = 1;
    char ch = getchar();
    for (; !isdigit(ch); ch = getchar())
        f = (ch == '-' ? -1 : 1);
    for (x = 0; isdigit(ch); ch = getchar())
        x = 10 * x + ch - '0';
    return x *= f;
}
template<typename T> void write(T x)
{
    if (x == 0) {
        putchar('0');
        return;
    }
    if (x < 0) {
        putchar('-');
        x = -x;
    }
    static char s[20];
    int top = 0;
    for (; x; x /= 10)
        s[++top] = x % 10 + '0';
    while (top)
        putchar(s[top--]);
}
// EOT

const int MAXN = 805;

int N, M, K;
char A[MAXN][MAXN];

void input()
{
    read(N); read(M); read(K);
    for (int i = 1; i <= N; ++i) {
        scanf("%s", A[i] + 1);
    }
}

const int DX[4] = {-1, 0, 0, +1};
const int DY[4] = {0, -1, +1, 0};

void solve()
{
    Pii s;
    for (int i = 1; i <= N; ++i) {
        for (int j = 1; j <= M; ++j) {
            if (A[i][j] == 'S') {
                s = MP(i, j);
                break;
            }
        }
    }

    static int dis[MAXN][MAXN];
    static Pii q[MAXN * MAXN];
    int front = 0, rear = 0;

    memset(dis, +oo, sizeof(dis));
    dis[s.x][s.y] = 0;
    q[rear++] = s;
    while (front != rear) {
        Pii u = q[front++];
        if (u.x == 1 || u.x == N || u.y == 1 || u.y == M) {
            puts("1");
            return;
        }
        if (dis[u.x][u.y] == K)
            break;
        for (int i = 0; i < 4; ++i) {
            Pii v(u.x + DX[i], u.y + DY[i]);
            if (A[v.x][v.y] != '#' && chkmin(dis[v.x][v.y], dis[u.x][u.y] + 1))
                q[rear++] = v;
        }
    }

    int min = +oo;
    for (int i = 0; i < rear; ++i) {
        Pii u = q[i];
        chkmin(min, std::min(std::min(u.x - 1, N - u.x), std::min(u.y - 1, M - u.y)));
    }
    int ans = 1 + min / K + !!(min % K);

    printf("%d\n", ans);
}

int main()
{
#ifdef __DEBUG
    freopen("C.in", "r", stdin);
    freopen("C.out", "w", stdout);
#endif

    input();
    solve();

    return 0;
}

