using namespace std;

const int dy[4] = {1, 0, -1, 0};
const int dx[4] = {0, 1, 0, -1};
int H, W, K;

class Coord {
    public:
        int y, x, k;

        Coord(int i, int j, int _k) {
            y = i; x = j; k = _k;
        }
        void setNextCoord(vector<Coord>& v) {
            for (int i=0; i<4; i++) {
                if (k+1 > K) continue;
                v.push_back(Coord(y+dy[i], x+dx[i], k+1));
            }
        }
        int hash() { return y*W + x; }
        int remain() { return min(min(y, H-y-1), min(x, W-x-1)); }
};

int main() {
    cin >> H >> W >> K;
    vector<vector<char> > A(H, vector<char>(W, '#'));

    unordered_set<int> st;
    queue<Coord> que;
    for (int i=0; i<H; i++) {
        for (int j=0; j<W; j++) {
            cin >> A[i][j];
            if (A[i][j] == 'S') que.push(Coord(i, j, 0));
        }
    }

    int minRemain = 801;
    vector<Coord> nextCoord;
    while (!que.empty()) {
        Coord c = que.front(); que.pop();
        st.insert(c.hash());

        minRemain = c.remain() < minRemain ? c.remain() : minRemain;
        if (minRemain == 0) break;

        nextCoord.clear();
        c.setNextCoord(nextCoord);

        for (Coord nc : nextCoord) {
            if (st.find(nc.hash()) != st.end()) continue;
            if (A[nc.y][nc.x] == '#') continue;
            que.push(nc);
        }
    }

    cout << 1 + (minRemain+K-1)/K << endl;
    return 0;
}

#include <iostream>
#include <queue>

using namespace std;
typedef pair<int,int> pii;


int H,W,K;
char grid[805][805];
int dist[805][805];
int x0,y0;

int main() {
	cin >> H >> W >> K;
	for (int i=0; i<H; i++) {
		for (int j=0; j<W; j++) {
			cin >> grid[i][j];
			if (grid[i][j] == 'S') {
				x0 = i;
				y0 = j;
			}
			dist[i][j] = -1;
		}
	}

	int mind = H*W;
	queue<pii> q;
	q.push(pii(x0,y0));
	while (q.size() > 0) {
		pii cur = q.front();
		q.pop();
		int x=cur.first, y=cur.second;
		if (x < 0 || x >= H || y < 0 || y >= W) continue;
		if (dist[x][y] >= 0 || grid[x][y] == '#') continue;
		dist[x][y] = min(min(x,y),min(H-x-1,W-y-1));
		mind = min(mind,dist[x][y]);
		q.push(pii(x-1,y));
		q.push(pii(x+1,y));
		q.push(pii(x,y-1));
		q.push(pii(x,y+1));
	}

	//cout << mind << endl;

	if ((mind+K-1)/K < (dist[x0][y0]+K-1)/K)
		cout << (dist[x0][y0]+K-1)/K << "\n";
	else
		cout << (dist[x0][y0]+K-1)/K + 1 << "\n";
}

#include <bits/stdc++.h>

using namespace std;
typedef long long ll;

#define MAX 802

char A[MAX][MAX];
int dp[MAX][MAX];
int dx[4] = {1,0,-1,0};
int dy[4] = {0,1,0,-1};

int main(void) {
    int i, j, H, W, K, sx, sy;
    scanf("%d%d%d", &H, &W, &K);
    for(i=0; i<H; i++) scanf("%s", &A[i]);
    for(i=0; i<H; i++) for(j=0; j<W; j++) {
        if(A[i][j] == 'S') {
            sx = j;
            sy = i;
        }
    }
    for(i=0; i<H; i++) for(j=0; j<W; j++) {
        dp[i][j] = -1;
    } 
    dp[sy][sx] = 0;
    queue<pair<int, int> > P;
    P.push(make_pair(sx, sy));
    while(!P.empty()) {
        int x = P.front().first;
        int y = P.front().second;
        P.pop();
        for(i=0; i<4; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];
            if(nx < 0 || nx >= W || ny < 0 || ny >= H) {
                if(dp[y][x] <= K) return !printf("1\n");
                continue;
            }
            if(~dp[ny][nx] || A[ny][nx] == '#') continue;
            dp[ny][nx] = dp[y][x] + 1;
            P.push(make_pair(nx, ny));
        }
    }

    int ret = 1e9;
    for(i=0; i<H; i++) for(j=0; j<H; j++) {
        if(~dp[i][j] && dp[i][j] <= K) {
            int d = min(min(i, j), min(H-i-1, W-j-1));
            ret = min(ret, (d+K-1) / K);
        }
    }

    return !printf("%d\n", ret+1);
}

