  reached[start_y][start_x] = true;
  while (!stk.empty()) {
    auto u = stk.front();
    stk.pop_front();
    rep (i, 4) {
      int y = u.first + dy[i];
      int x = u.second + dx[i];
      if (x < 0 || w <= x || y < 0 || h <= y) { continue; }
      if (board[y][x] == -1) { continue; }
      if (reached[y][x]) { continue; }
      cost[y][x] = min(cost[y][x], cost[u.first][u.second] + 1);
      reached[y][x] = true;
      stk.push_back((pii){y, x});
    }
  }

  int min_cost = 1e9;

  rep (i, h) {
    rep (j, w) {
      if (cost[i][j] <= k) {
        min_cost = min(min_cost, min_distance(i, j));
      }
    }
  }

  int ans = 1 + (min_cost + k - 1) / k;
  printf("%d\n", ans);


  return 0;
}

