        for (int i = 0; i < qu.size(); ++i) {
            int x = qu[i].first;
            int y = qu[i].second;
            if (dist[x][y] == k) {
                continue;
            }
            for (int j = 0; j < 4; ++j) {
                int xx = x + dx[j];
                int yy = y + dy[j];
                if (in_board(xx, yy)) {
                    if (opened[xx][yy]) {
                        if (dist[xx][yy] > dist[x][y] + 1) {
                            dist[xx][yy] = dist[x][y] + 1;
                            reached[xx][yy] = true;
                            qu.push_back({xx, yy});
                        }
                    }
                }
            }
        }
        qu.clear();
        vector<vector<int>> dist1(h, vector<int>(w, inf));
        for (int i = 0; i < h; ++i) {
            for (int j = 0; j < w; ++j) {
                if (reached[i][j]) {
                    dist1[i][j] = 0;
                    qu.push_back({i, j});
                }
            }
        }
        for (int i = 0; i < qu.size(); ++i) {
            int x = qu[i].first;
            int y = qu[i].second;
            if (dist1[x][y] == k) {
                continue;
            }
            for (int j = 0; j < 4; ++j) {
                int xx = x + dx[j];
                int yy = y + dy[j];
                if (in_board(xx, yy) && !opened[xx][yy]) {
                     if (dist1[xx][yy] > dist1[x][y] + 1) {
                        dist1[xx][yy] = dist1[x][y] + 1;
                        opened[xx][yy] = true;
                        qu.push_back({xx, yy});
                    }
                }
            }
        }
        for (int i = 0; i < h; ++i) {
            if (reached[i][0] || reached[i][w - 1]) {
                printf("%d\n", iter);
                return;
            }
        }
        for (int i = 0; i < w; ++i) {
            if (reached[0][i] || reached[h - 1][i]) {
                printf("%d\n", iter);
                return;
            }
        }
    }
}

