void bfs(){
	while(q.size()>0){
		int s=q.front().first, t=q.front().second;
		q.pop();
		if(dist[s][t]>=K) break;
		if(s>0){
			if(dist[s-1][t]==dinf && A[s-1][t]=='.'){
				dist[s-1][t]=dist[s][t]+1;
				q.push(make_pair(s-1, t));
			}
		}
		if(s+1<H){
			if(dist[s+1][t]==dinf && A[s+1][t]=='.'){
				dist[s+1][t]=dist[s][t]+1;
				q.push(make_pair(s+1, t));
			}
		}
		if(t>0){
			if(dist[s][t-1]==dinf && A[s][t-1]=='.'){
				dist[s][t-1]=dist[s][t]+1;
				q.push(make_pair(s, t-1));
			}
		}
		if(t+1<W){
			if(dist[s][t+1]==dinf && A[s][t+1]=='.'){
				dist[s][t+1]=dist[s][t]+1;
				q.push(make_pair(s, t+1));
			}
		}
	}
}

