int main(){
    int h=in(),w=in(),k=in(),sh=-1,sw=-1;
    vector<vec> a(h,vec(w));
    rep(i,h){
        string s=stin();
        rep(j,w){
            a[i][j]=s[j]=='#'?1:0;
            if(s[j]=='S'){
                sh=i;
                sw=j;
            }
        }
    }
    vector<vector<bool>> done(h,vector<bool>(w,false));
    priority_queue<pair<int,pii>,vector<pair<int,pii>>,greater<pair<int,pii>>> q;
    q.push(mp(0,mp(sh,sw)));
    int min_cost=200000;
    while(!q.empty()){
        int s=q.top().second.first,t=q.top().second.second,cost=q.top().first;
        q.pop();
        done[s][t]=true;
        if(s==0||s==h-1||t==0||t==w-1){
            min_cost=cost;
            break;
        }
        if(!done[s+1][t]){
            if(a[s+1][t]==0)q.push(mp(cost,mp(s+1,t)));
            else q.push(mp(cost+1,mp(s+1,t)));
        }
        if(!done[s-1][t]){
            if(a[s-1][t]==0)q.push(mp(cost,mp(s-1,t)));
            else q.push(mp(cost+1,mp(s-1,t)));
        }
        if(!done[s][t+1]){
            if(a[s][t+1]==0)q.push(mp(cost,mp(s,t+1)));
            else q.push(mp(cost+1,mp(s,t+1)));
        }
        if(!done[s][t-1]){
            if(a[s][t-1]==0)q.push(mp(cost,mp(s,t-1)));
            else q.push(mp(cost+1,mp(s,t-1)));
        }
    }
    cout<<(min_cost+k-1)/k+1<<endl;
}

