int H,W,K;
char A[1000][1000];

int sx,sy;
bool used[1000][1000];
int cnt[1000][1000];

int dx[4] = {0,1,0,-1};
int dy[4] = {1,0,-1,0};

void bfs() {
    queue< pair<Point,int> > que;
    que.push(make_pair(Point(sx,sy),K));
    while(que.size() > 0) {
        Point p = que.front().first;
        int dep = que.front().second-1;
        que.pop();
        if(p.x<0 || p.y<0 || p.x>=W || p.y>=H) continue;
        if(used[p.y][p.x]) continue;
        if(cnt[p.y][p.x] < 0) continue;
        if(A[p.y][p.x] == '#') continue;
        used[p.y][p.x] = true;
        cnt[p.y][p.x] = dep;
        REP(i,4) {
            que.push(make_pair(Point(dx[i]+p.x,dy[i]+p.y),dep));
        }
    }
}

int main() {

    cin >> H >> W >> K;
    REP(i,H) scanf("%s",A[i]);

    sx = sy = -1;
    REP(i,H)REP(j,W) {
        if(A[i][j] == 'S') {
            sy = i;
            sx = j;
        }
    }

    REP(i,1000)REP(j,1000) used[i][j] = false;
    REP(i,1000)REP(j,1000) cnt[i][j] = 1e9;
    bfs();

    REP(i,H) {
        if(cnt[i][W-1] < K || cnt[i][0] < K) {
            cout << 1 << endl;
            return 0;
        }
    }

    REP(i,W) {
        if(cnt[H-1][i] < K || cnt[0][i] < K) {
            cout << 1 << endl;
            return 0;
        }
    }

    int ans = 1e9;
    REP(i,H)REP(j,W) {
        if(cnt[i][j] >= 0) {
            ans = min(ans,(i+1)/K+2);
            ans = min(ans,(j+1)/K+2);
            ans = min(ans,(H-i)/K+2);
            ans = min(ans,(W-j)/K+2);
        }
    }

    cout << ans << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 8e2 + 7;

int n, m, k;
char tbl[N][N];
int dp[N][N][N];
int g[5][2];
deque < pair <int, int> > d[N];

void chk(int x, int y, int l, int f) {
	if (x >= 1 && y >= 1 && x <= n && y <= m && dp[x][y][l] == 0)
		d[l].push_back({x, y}), dp[x][y][l] = f;	
}

void bfs(int xs, int ys) {
	int pnt = 0;
	d[0].push_back({xs, ys});
	dp[xs][ys][0] = 1;
	while (pnt * 2 - 2 < N) {
		while (d[pnt].size()) {
			int x = d[pnt].front().first, y = d[pnt].front().second;
			d[pnt].pop_front();
			for (int i = 1; i <= 4; i++)
				chk(x + g[i][0], y + g[i][1], (tbl[x + g[i][0]][y + g[i][1]] == '#') + pnt, dp[x][y][pnt] + 1);
		}
		pnt++;
	}
}
int res = N * N;
int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	cout.tie(0);
	g[1][0] = g[2][1] = 1;
	g[3][0] = g[4][1] = -1;
	cin >> n >> m >> k;
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= m; j++)
			cin >> tbl[i][j];
	for (int i = 1; i <= n; i++)
		for (int j = 1; j <= m; j++)
			if (tbl[i][j] == 'S')
				bfs(i, j);
	for (int h = 0; h * 2 - 2 <= n; h++) {
		for (int i = 1; i <= n; i++) {
			for (int j = 1; j <= m; j++) {
				dp[i][j][h]--;
				if ((i == 1 || i == n || j == 1 || j == m) && dp[i][j][h] >= 0) {
					res = min(res, (h + k - 1) / k + (dp[i][j][h] + k - 1) / k);
				}
			}
		}
	}
	cout << res;
	return 0;
}

