void bfs(ll h,ll w,ll count) {
	queue < tuple < ll, ll, ll >> Q;
	Q.push(mt(h,w,0));
	D[h][w] = 1;
	tuple<ll,ll,ll> u;
	while (!Q.empty()) {
		u = Q.front();
		Q.pop();
		ll p = get<0>(u);
		ll q = get<1>(u);
		ll c = get<2>(u);
