				Q.push(mt(np, nq, c+1)); D[np][nq] = 1;
			}
			np = p; nq = q-1;
			if ((ans > 1 || A[np][nq] == '.') && !D[np][nq]) {
				Q.push(mt(np, nq, c+1)); D[np][nq] = 1;
