const double eps = 1e-9;
char a[N][N];
int h, w, k, dp[N][N];
int dx[4] = {0, 1, 0, -1};
int dy[4] = {1, 0, -1, 0};

int in(int x, int y) {
  return 1 <= x && x <= h && 1 <= y && y <= w && a[x][y] != '#';
}

int main() {
  scanf("%d %d %d", &h, &w, &k);
  pii s;
  for (int i = 1; i <= h; i++) {
    scanf("%s", a[i]+1);
    for (int j = 1; j <= w; j++) {
      if (a[i][j] == 'S')
        s = {i, j};
      dp[i][j] = inf;
    }
  }
  deque<pii> pq;
  pq.pb(s);
  dp[s.st][s.nd] = 0;
  while (!pq.empty()) {
    auto it = pq.front(); pq.pop_front();
    if (dp[it.st][it.nd] == k)
      continue;
    for (int i = 0; i < 4; i++) {
      int nx = it.st + dx[i], ny = it.nd + dy[i];
      if (!in(nx, ny) || dp[nx][ny] <= dp[it.st][it.nd] + 1)
        continue;
      dp[nx][ny] = dp[it.st][it.nd] + 1;
      pq.pb({nx, ny});
    }
  }
  int ans = inf;
  for (int i = 1; i <= h; i++)
    for (int j = 1; j <= w; j++) if (dp[i][j] != inf) {
      ans = min(ans, (min({i-1, j-1, h-i, w-j}) + k - 1) / k + (dp[i][j]+k-1) / k);
    }
  printf("%d\n", ans);
  return 0;
}

