int bfs(int sx, int sy){
	int b = 0, e = 0;
	vis[sx][sy] = true;
	memset(dist, -1, sizeof(dist));
	dist[sx][sy] = 0;
	que[b++] = {sx, sy};
	while(e < b){
		auto cur = que[e++];
		if(cur.first == 1 or cur.second == W or cur.second == 1 or cur.first == H){
			return dist[cur.first][cur.second];
		}
