			if(mat[ncur.first][ncur.second] == '#')continue;
			que[b++] = ncur;
			vis[ncur.first][ncur.second] = true;
			dist[ncur.first][ncur.second] =dist[cur.first][cur.second] + 1;
		}
	}

	for(int i = 0; i < b; i++)dist[que[i].first][que[i].second] = K;

	e = 0;
	while(e < b){
		auto cur = que[e++];
		if(cur.first == 1 or cur.second == W or cur.second == 1 or cur.first == H){
			return dist[cur.first][cur.second];
		}

		for(int i = 0; i < 4; i++){
			pair<int, int> ncur;
