			if(ncur.first < 1 or ncur.first > H or ncur.second < 1 or ncur.second > W)continue;
			if(vis[ncur.first][ncur.second])continue;
			//if(dist[cur.first][cur.second] < K and mat[ncur.first][ncur.second] == '#')continue;
			que[b++] = ncur;
			vis[ncur.first][ncur.second] = true;
			dist[ncur.first][ncur.second] =dist[cur.first][cur.second] + 1;
		}
	}
	assert(1 == 0);
	return 0;
}
