void dfs(LL x,LL y,LL dep){
	if(!x || !y || x > n || y > m) return;
	if(dep < 0) return; if(ch[x][y] == '#') return;
	vis[x][y] = 1;
	ans = min(ans,min(min(x - 1,y - 1),min(n - x,m - y)));
	if(!vis[x - 1][y]) dfs(x - 1,y,dep - 1);
	if(!vis[x][y - 1]) dfs(x,y - 1,dep - 1);
	if(!vis[x + 1][y]) dfs(x + 1,y,dep - 1);
	if(!vis[x][y + 1]) dfs(x,y + 1,dep - 1);
}

