void dijkstra(){
	priority_queue<pair<ll,pii>, vector<pair<ll,pii> >, greater<pair<ll,pii> > > vertices;
	vertices.push(make_pair(0,start));
	while(!vertices.empty()){
		pii x=(vertices.top()).second;
		vertices.pop();
		if(!visited[x.F][x.S]){
			for(auto it=adj[x.F][x.S].begin();it!=adj[x.F][x.S].end();it++){
				ll w1;
				w1=(*it).first;
				pii other =(*it).second;
				if(dist[x.F][x.S]+w1<dist[other.F][other.S]){
					dist[other.F][other.S]=dist[x.F][x.S]+w1;
					vertices.push(make_pair(dist[other.F][other.S],other));
				}
			}
		}
		visited[x.F][x.S]=1;
	}
}

