int h[N][N];
int H, W, k;

bool ck(int x, int y)
{
	return (x >= 1 && y >= 1 && x <= H && y <= W && ar[x][y] == '.' && h[x][y] <= k && vis[x][y] == false);
}
int getans(int x, int y)
{
	int res = min(min(H - x, x - 1), min(W - y, y - 1));
	if(res % k == 0)
		return res/k;
	else
		return res/k + 1;
}

queue <pii> q;

int bfs(int x, int y)
{
	int res = H*W;
	q.push({x, y});
	vis[x][y] = true;
	while(q.size() > 0)
	{
		int a = q.front().fi,
			b = q.front().se;

		vis[a][b] = true;
		res = min(res, getans(a, b) + 1);

		q.pop();
		for(int i=0;i<4;i++)
		{
			int na = a + Tx[i],
				nb = b + Ty[i];
			h[na][nb] = h[a][b] + 1;
			if(ck(na, nb) == true)
			{
				q.push({na, nb});
				h[na][nb] = h[a][b] + 1;
				vis[na][nb] = true;
			}
		}
	}

	return res;
}
