int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int H, W, K;
    cin >> H >> W >> K;
    vector<string> A;
    rep(i, 0, H) {
        string s;
        cin >> s;
        A.push_back(s);
    }

    int sx, sy;
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            if (A[i][j] == 'S') {
                sx = i;
                sy = j;
            }
        }
    }

    using Pxy = pair<int, int>; //座標
    using V = pair<Pxy, int>; //あるへん


    set<Pxy> grids; //最初に行ける座標たち
    set<Pxy> used; // 使用済み
    queue<V> que;
    que.push(V(Pxy(sx, sy), 0));
    used.emplace(sx, sy);

    while (!que.empty()) {
        V top = que.front();
        que.pop();
        if (top.second <= K) {
            grids.insert(top.first);
            int dx[] = {-1, 0, 1, 0};
            int dy[] = {0, -1, 0, 1};
            for (int k = 0; k < 4; ++k) {
                int h = top.first.first + dx[k];
                int w = top.first.second + dy[k];

                if (h >= 0 && h < H && w >= 0 && w < W) {
                    if (A[h][w] == '.' && !used.count(Pxy(h, w))) {
                        que.push(V(Pxy(h, w), top.second + 1));
                        used.insert(Pxy(h, w));
                    }
                }
            }

        }
    }

    int ans = INF;
    for (auto e : grids) {
        int h = e.first;
        int w = e.second;

        vector<int> kouho;
        kouho.push_back(h);
        kouho.push_back(H - 1 - h);
        kouho.push_back(w);
        kouho.push_back(W - 1 - w);
        sort(all(kouho));
        int dist = kouho[0] / K + (kouho[0] % K != 0) + 1;

        chmin(ans, dist);
    }

    cout << ans << endl;

    return 0;
}

