ll H, W, K;
const ll inf = 5e15;

ll dist_to_outside(ll h, ll w) {
    return var_min(h, (H - 1) - h,
                   w, (W - 1) - w);
}

ll rest_magic(ll h, ll w) {
    ll dist = dist_to_outside(h, w);
    return dist / K + !!(dist % K);
}

int main() {
    cin >> H >> W >> K;
    V<string> A(H);
    for(auto &&s : A) cin >> s;
    ll sh, sw;
    for(ll i = 0; i < H; i++) for(ll j = 0; j < W; j++) if(A[i][j] == 'S') {
        sh = i;
        sw = j;
        break;
    }

    ll ans = inf;
    queue<pair<PLL, ll>> que;
    que.emplace(PLL(sh, sw), 0);
    VV<ll> dists = make_v<ll>(inf, H, W);
    dists[sh][sw] = 0;
    ll dh[] = { 1, 0, -1, 0 };
    ll dw[] = { 0, 1, 0, -1 };

    while(que.size()) {
        ll h, w, d;
        tie(h, w) = que.front().first;
        d = que.front().second;
        que.pop();
        if(dists[h][w] < d) continue;
        if(d == K) continue;
        chmin(ans, rest_magic(h, w));
        for(ll i = 0; i < 4; i++) {
            ll nh = h + dh[i];
            ll nw = w + dw[i];
            ll nd = d + 1;
            if(!(0 <= nh && nh < H &&
                 0 <= nw && nw < W)) continue;
            if(dists[nh][nw] <= nd) continue;
            if(A[nh][nw] != '.') continue;
            DEBUG(make_tuple(nh, nw));
            dists[nh][nw] = nd;
            que.emplace(PLL(nh, nw), nd);
        }
    }
    cout << ans + 1 << endl;
    return 0;
}

