                for (int i = 0; i < 4; i++) {
                        int ny = y + dy[i], nx = x + dx[i];
                        if (ny < 0 || nx < 0 || H <= ny || W <= nx || A[ny][nx] == '#' || mc[ny][nx] != INF) continue;
                        mc[ny][nx] = mc[y][x] + 1;
                        que.emplace(ny, nx);
                }
        }

        int minv = INF;
        for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                        if (A[i][j] != '#') {
                                int dist = min(min(H - 1 - i, i), min(W - 1 - j, j));
                                chmin(minv, mc[i][j] / K + (dist + K - 1) / K + 1);
                        }
                }
        }
        cout << minv << endl;
        return (0);
}

