	{
		for (int j = 0; j < m; j++)
		{
			if (s[i][j] == 'S')
			{
				x1 = i, y1 = j;
				s[i][j] = '.';
			}
		}
	}
	dp[x1][y1] = 0;
	int d = 0;
	vector < pair < int, int > > v;
