				if (good(tx, ty)  && dp[i][j] >= bool(s[tx][ty] == '#'))
				{
					int ndp = dp[i][j] - bool(s[tx][ty] == '#') + k * bool((d + 1) % k == 0);
					if (!used[tx][ty])
						v.pb({tx, ty}), used[tx][ty] = true;
					nw[tx][ty] = max(nw[tx][ty], ndp);
				}
			}
			nw[i][j] = max(nw[i][j], dp[i][j] + bool((d + 1) % k == 0) * k);   
		}
		for (int i = 0; i < n; i++)
		{
			for (int j = 0; j < m; j++)
			{
				dp[i][j] = nw[i][j];
