      int nhakai = hakai;
      int ncost = cost;
      int npower = power;
      if(mas[ny][nx] == '#'){
        nhakai--;
        if(nhakai == -1){
          ncost++;
          nhakai = k;
          npower = k;
        }
      }
      npower--;
      if(npower == -1){
        ncost++;
        nhakai += k;
        npower = k;
      }
