#define MAXN 1000

int mat[MAXN][MAXN];
int memo [MAXN][MAXN];
int x, y, n, m;

void BFS () {

	queue <pair<int, int> > q;
	q.push(make_pair(x, y));

	memo[x][y] = 1;

	while (!q.empty()) {
		x = q.front().first;
		y = q.front().second;
		q.pop();

		if (x+1 < n) {
			if (memo[x+1][y] == 0 && mat[x+1][y] == 1) {
				memo[x+1][y] = memo[x][y]+1;
				q.push(make_pair(x+1, y));
			}
		}

		if (x-1 >= 0) {
			if (memo[x-1][y] == 0 && mat[x-1][y] == 1) {
				memo[x-1][y] = memo[x][y]+1;
				q.push(make_pair(x-1, y));
			}
		}

		if (y+1 < m) {
			if (memo[x][y+1] == 0 && mat[x][y+1] == 1) {
				memo[x][y+1] = memo[x][y]+1;
				q.push(make_pair(x, y+1));
			}
		}

		if (y-1 >= 0) {
			if (memo[x][y-1] == 0 && mat[x][y-1] == 1) {
				memo[x][y-1] = memo[x][y]+1;
				q.push(make_pair(x, y-1));
			}
		}
	}

}

