			break;
		}
	}

	step = INT_MAX;

	if (flag == 1) {

		//cout << "in0" << endl;

		if (memo[0][i] != 0) step = min(step, memo[0][i]);
		if (memo[n-1][i] != 0) step = min(step, memo[n-1][i]);

		step--;
