void f(vector<vector<int> >& v, int y, int x, int nl, int l)
{
  if (v[y][x] >= l){
    v[y][x] = l;
    if (nl == l)
      return;
    if (y != 0 && v[y-1][x] != -1){
      f(v, y-1, x, nl, l+1);
    }
    if (y != v.size()-1 && v[y+1][x] != -1){
      f(v, y+1, x, nl, l+1);
    }
    if (x != 0 && v[y][x-1] != -1){
      f(v, y, x-1, nl, l+1);
    }
    if (x != v[0].size()-1 && v[y][x+1] != -1){
      f(v, y, x+1, nl, l+1);
    }
  }
}

