            }
        }
    }

    int ans = INF;
    for (PII p : visitable) {
        int tmp = min({
            calc(p.first),
            calc(p.second),
            calc(W - p.first - 1),
            calc(H - p.second - 1)
        });
        ans = min(ans, tmp);
    }

    cout << ans + 1 << endl;
}

