using namespace std;

typedef pair<int, int> pii;

const int INF = 1e8 + 8;
const int MAXN = 805;
bool vis[MAXN][MAXN];
bool brd[MAXN][MAXN];
int steps[MAXN][MAXN];
int H, W, K, ans;
int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};
pii st;
queue<pii> Q;

void dfs1(pii croom, int lefts) {
	if (lefts == 0) return;
	if (vis[croom.first][croom.second]) {
		return;
	} else {
		vis[croom.first][croom.second] = true;
		steps[croom.first][croom.second] = 1;
		Q.push(croom);
	}
	for (int i = 0; i < 4; i++) {
		pii nroom = croom;
		nroom.first += dx[i];
		nroom.second += dy[i];
		if (brd[nroom.first][nroom.second]) {
			dfs1(nroom, lefts - 1);
		}
	}
}

void dfs2(pii croom, int lefts, int val) {
	if (lefts == 0) return;
	for (int i = 0; i < 4; i++) {
		pii nroom = croom;
		nroom.first += dx[i];
		nroom.second += dy[i];
		if (nroom.first < 0 || nroom.first >= H || nroom.second < 0 || nroom.second >= W) continue;
		if (vis[nroom.first][nroom.second]) continue;
		vis[nroom.first][nroom.second] = true;
		steps[nroom.first][nroom.second] = val;
		Q.push(nroom);
		dfs2(nroom, lefts - 1, val);
	}
}

