	char c;
	for (int i = 0; i < H; i++) {
		for (int j = 0; j < W; j++) {
			cin >> c;
			if (c == '.') {
				brd[i][j] = true;
			} else if (c == '#') {
				brd[i][j] = false;
			} else {
				brd[i][j] = true;
				st.first = i;
				st.second = j;
			}
		}
	}
	dfs1(st, K);
	ans = INF;
	while (!Q.empty()) {
		pii croom = Q.front();
		Q.pop();
		if (croom.first == 0 || croom.first == H - 1 || croom.second == 0 || croom.second == W - 1) {
			ans = min(ans, steps[croom.first][croom.second]);
		} else {
			dfs2(croom, K, steps[croom.first][croom.second] + 1);
		}		
	}
	cout << ans << '\n';
	return 0;
}

