    rep(i, H) rep(j, W) if(A[i][j] == 'S'){
        sh = i; sw = j; i = H; j = W;
    }

    queue<st> q; q.push({{sh, sw}, K, 1});
    vvl cost(H, vl(W, LINF)); cost[sh][sw] = 1;
    while (!q.empty()) {
        PL now = q.front().pos;
        ll rem = q.front().rem, cnt = q.front().cnt;
        q.pop();
        if(rem == 0){
            q.push({now, K, cnt+1});
        }
        else if(cnt == 1){
            bool updated = false;
            rep(i, 4){
                ll nh = now.ff + dh[i], nw = now.ss + dw[i];
                if(bok(nh, nw) && A[nh][nw] == '.' && cost[nh][nw] == LINF){
                    cost[nh][nw] = cnt;
                    q.push({{nh,nw}, rem-1, cnt});
                    updated = true;
                }
            }
            if(!updated) q.push({now, rem-1, cnt});
        }
        else{
            rep(i, 4){
                ll nh = now.ff + dh[i], nw = now.ss + dw[i];
                if(bok(nh, nw) && cost[nh][nw] == LINF){
                    cost[nh][nw] = cnt;
                    ll nx_rem = rem-1;
                    q.push({{nh,nw}, nx_rem, cnt});
                }
            }
        }
    }

    ll ans = LINF;
    rep(i, W){
        chmin(ans, cost[0][i]); chmin(ans, cost[H-1][i]);
    }
    rep(i, H){
        chmin(ans, cost[i][0]); chmin(ans, cost[i][W-1]);
    }
    cout << ans << endstr;
    return 0;
}

