{
	queue<pair<int,int> > Q;
	for (int i = 0;i < n;i++)
		for (int j = 0;j < m;j++)
			dis[i][j] = 1e9;
	dis[X][Y] = 0;
	Q.push(make_pair(X,Y));
	ans = 1e9;
	while (!Q.empty())
	{
		int x = Q.front().first,y = Q.front().second;
		Q.pop();
		ans = min(ans,(min(min(x,n - 1 - x),min(y,m - 1 - y)) + k - 1) / k + 1);
		if (dis[x][y] >= k)
			continue;
		if (x > 0 && dis[x - 1][y] == 1e9 && s[x - 1][y] != '#')
		{
			dis[x - 1][y] = dis[x][y] + 1;
			Q.push(make_pair(x - 1,y));
		}
		if (y > 0 && dis[x][y - 1] == 1e9 && s[x][y - 1] != '#')
		{
			dis[x][y - 1] = dis[x][y] + 1;
			Q.push(make_pair(x,y - 1));
		}
		if (x < n - 1 && dis[x + 1][y] == 1e9 && s[x + 1][y] != '#')
		{
			dis[x + 1][y] = dis[x][y] + 1;
			Q.push(make_pair(x + 1,y));
