int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(20);
  ll h, w, K;
  cin >> h >> w >> K;
  vs s(h);
  rep(i, h){
    cin >> s[i];
  }
  int min_dist = 100100100;
  int di[4] = {1, -1, 0, 0};
  int dj[4] = {0, 0, 1, -1};
  vvi visited(h, vi(w, 0));
  auto bfs = [&](int si, int sj) -> void{
    queue<tuple<int, int, int>> q;
    q.emplace(si, sj, 0);
    visited[si][sj] = 1;
    while(q.size()){
      auto fr = q.front();
      chmin(min_dist, get<0>(fr));
      chmin(min_dist, h-1-get<0>(fr));
      chmin(min_dist, get<1>(fr));
      chmin(min_dist, w-1-get<1>(fr));
      q.pop();
      rep(k, 4){
        int ni = get<0>(fr) + di[k];
        int nj = get<1>(fr) + dj[k];
        if(ni < 0 || ni >= h
        || nj < 0 || nj >= w)
          continue;
        if(s[ni][nj] == '.' && !visited[ni][nj] && get<2>(fr) < K){
          visited[ni][nj] = 1;
          q.emplace(ni, nj, get<2>(fr)+1);
        }
      }
    }
  };
  rep(i, h)rep(j, w){
    if(s[i][j] == 'S') bfs(i, j);
  }
  dump(min_dist);
  print((min_dist+K-1)/K+1);
}

