char g[805][805];
int h,w,k,ans = MAX;
bool vis[805][805];

void dfs(int u,int v,int t)
{
    if(vis[u][v] || g[u][v] == '#' || t > k) return;
    vis[u][v] = 1;
    int d = min(min(u,h - 1 - u),min(v,w - 1 - v));
    if(d == 0) ans = 1;
    else ans = min(ans,d / k + (d % k != 0) + 1);
    if(u > 0) dfs(u - 1,v,t + 1);
    if(u + 1 < h) dfs(u + 1,v,t + 1);
    if(v > 0) dfs(u,v - 1,t + 1);
    if(v + 1 < w) dfs(u,v + 1,t + 1);
}


