struct TnT {
    int x , y , step , flag;
};
bool visit[M][M];
void bfs(TnT sta) {
    memset(step , 0 , sizeof(step));
    step[sta.x][sta.y] = 1;
    memset(visit, false , sizeof(visit));
    visit[sta.x][sta.y] = true;
    queue<TnT>q;
    q.push(sta);
    while(!q.empty()) {
        TnT gg = q.front();
        q.pop();
        for(int i = 0 ; i < 4 ; i++) {
            TnT gl = gg;
            gl.x += dr[i][0];
            gl.y += dr[i][1];
            if(gl.x >= 0 && gl.x < h && gl.y >= 0 && gl.y < w && mmp[gl.x][gl.y] != '#' && !visit[gl.x][gl.y]) {
                gl.step++;
