	static int d[802][802];
	static bool used[802][802];
	static queue<P> que;
	rep(i,802)rep(j,802){
		d[i][j] = INF;
		used[i][j] = false;
	}
	rep1(i,h)rep1(j,w){
		if(a[i][j] == 'S'){
