using namespace std;
using PII = pair<int, int>;

const int inf = 1e8;
const int dx[4] = {1, 0, -1,  0};
const int dy[4] = {0, 1,  0, -1};

int main() {
	int h, w, k;
	cin >> h >> w >> k;

	vector<string> board(h);
	for (int i = 0; i < h; i++) {
		cin >> board[i];
	}

	int sx = -1, sy = -1;
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			if (board[i][j] == 'S') {
				sx = j;
				sy = i;
				break;
			}
		}
		if (sx != -1) {
			break;
		}
	}

	if (sx == 0 || sx == w - 1 || sy == 0 || sy == h) {
		cout << 0 << endl;
		return 0;
	}

	vector<vector<int>> walk(h, vector<int>(w, inf));
	walk[sy][sx] = 0;

	queue<PII> que;
	que.push(make_pair(sx, sy));

	while (!que.empty()) {
		auto p = que.front();
		que.pop();

		int x = p.first;
		int y = p.second;

		if (walk[y][x] >= k) {
			continue;
		}

		for (int i = 0; i < 4; i++) {
			int nx = x + dx[i];
			int ny = y + dy[i];

			if (0 <= nx && nx < w && 0 <= ny && ny < h &&
				board[ny][nx] == '.' && walk[ny][nx] == inf)
			{
				walk[ny][nx] = walk[y][x] + 1;
				que.push(make_pair(nx, ny));
			}
		}
	}

	int min_len = inf;
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			if (walk[i][j] == inf) {
				continue;
			}

			min_len = min({min_len, i, h - 1 - i, j, w - 1 - j});
		}
	}

	int ans = 1 + (min_len + k - 1) / k;

	cout << ans << endl;
	return 0;
}

