			starty--;
			steps--;
			mindist = min(mindist, starty);
		}
		else break;
	}

	// down
	starty = starty2;
	startx = startx2;
	steps = k;
	mindist = min(mindist, h-starty-1);
	while(steps > 0) {
		if(starty < h-1 && grid[starty+1][startx] != '#') {
			starty++;
			steps--;
			mindist = min(mindist, h-starty-1);
		}
		else break;
	}

	// left
	starty = starty2;
	startx = startx2;
	steps = k;
	mindist = min(mindist, startx);
	while(steps > 0) {
		if(startx > 0 && grid[starty][startx-1] != '#') {
			startx--;
			steps--;
			mindist = min(mindist, startx);
		}
		else break;
	}

	// right
	starty = starty2;
	startx = startx2;
	steps = k;
	mindist = min(mindist, w-startx-1);
	while(steps > 0) {
		if(startx < w-1 && grid[starty][startx+1] != '#') {
			startx++;
			steps--;
			mindist = min(mindist, w-startx-1);
		}
		else break;
	}

	// cout<<"mindist: "<<mindist<<endl;

	ll ans = 1;

starty = starty2;
