template<typename T>
vector<T> make_vec_nd(T init, size_t size) {
    return vector<T>(size, init);
}
template<typename T, typename... Args>
auto make_vec_nd(T init, size_t size, Args... rest) {
    auto inner = make_vec_nd(init, rest...);
    return vector<decltype(inner)>(size, inner);
}

int main() {
    ll H, W, K;
    cin >> H >> W >> K;
    auto grid = make_vec_nd('$', W, H);
    pair<ll, ll> start;
    for (ll y = 0; y < H; y++) {
        for (ll x = 0; x < W; x++) {
            char c;
            cin >> c;
            grid[x][y] = c;
            if (c == 'S') {
                start = {x, y};
            }
        }
    }
    if (start.first == 0 || start.first == W-1 || start.second == 0 || start.second == H-1) {
        cout << 0 << endl;
        return 0;
    }
    ll min_cost = numeric_limits<ll>::max();
    auto calc_cost = [W, H](pair<ll, ll> pos) -> ll {
        vector<ll> costs = {pos.first - 0, W - pos.first - 1, pos.second - 0, H - pos.second - 1};
        return *min_element(costs.begin(), costs.end());
    };
    auto distance = make_vec_nd(numeric_limits<ll>::max(), W, H);
    using Pos = pair<ll, ll>;
    deque<Pos> queue;
    queue.push_back(start);
    distance[start.first][start.second] = 0;
    min_cost = min(min_cost, calc_cost(start));
    while (!queue.empty()) {
        Pos pos = queue.front();
        queue.pop_front();
        for (Pos vec : {Pos{-1, 0}, Pos{1, 0}, Pos{0, -1}, Pos{0, 1}}) {
            Pos next = {pos.first + vec.first, pos.second + vec.second};
            if (next.first < 0 || next.first >= W || next.second < 0 || next.second >= H) {
                continue;
            }
            if (grid[next.first][next.second] == '#') {
                continue;
            }
            if (distance[pos.first][pos.second] + 1 < distance[next.first][next.second]) {
                distance[next.first][next.second] = distance[pos.first][pos.second] + 1;
                if (distance[next.first][next.second] <= K) {
                    min_cost = min(min_cost, calc_cost(next));
                    queue.push_back(next);
                }
            }
        }
    }
    ll count = min_cost / K + (min_cost % K != 0) + 1;
    cout << count << endl;
}

