void dene(){
    int x=s.first;  int y=s.second; visit[x][y]=1;
    bool sol=true, sag=true, yukari=true, asagi=true;   ++step; bool islem=false;
    for(int i=1;k>=i;i++){
        if(x+i<n and vec[x+i][y]=='.' and sag and !visit[x+i][y]){
            ans[x+i][y]=step;   q.push({x+i, y});   visit[x+i][y]=1;    islem=true;
        }
        if(y+i<m and vec[x][y+i]=='.' and yukari and !visit[x][y+i]){
            ans[x][y+i]=step;   q.push({x, y+i});   visit[x][y+i]=1;    islem=true;
        }
        if(x-i>=0 and vec[x-i][y]=='.' and sol and !visit[x-i][y]){
            ans[x-i][y]=step;   q.push({x-i, y});   visit[x-i][y]=1;    islem=true;
        }
        if(y-i>=0 and vec[x][y-i]=='.' and asagi and !visit[x][y-i]){
            ans[x][y-i]=step;   q.push({x, y-i});   visit[x][y-i]=1;    islem=true;
        }
        if(x+i<n and vec[x+i][y]=='#'){
            sag=false;
        }
        if(x-i>=0 and vec[x-i][y]=='#'){
            sol=false;
        }
        if(y+i<n and vec[x][y+i]=='#'){
            yukari=false;
        }
        if(y-i>0 and vec[x][y-i]=='#'){
            asagi=false;
        }
    }
    if(islem){
        kir();
    }
    else if(s==bas){
        q.push({x, y}); kir();
    }
}

