        seen[i][j] = true;
        if (rem[i][j] == 0) continue;

        rep(dir, 0, 4) {
            int ni = i + di[dir];
            int nj = j + dj[dir];
            if (!canGo(ni, nj) || seen[ni][nj]) continue;
            seen[ni][nj] = true;
            rem[ni][nj] = rem[i][j] - 1;
            q.push({ni, nj});
        }
    }

    //rep(i, 0, h) {rep(j, 0, w) cout << seen[i][j] << " "; cout << endl;}
    int best = h * w;
    rep(i, 0, h) rep(j, 0, w) {
        if (seen[i][j]) {
            int cur = min(min(i, j), min(h - i - 1, w - j - 1));
            if (cur == 0) {
                cout << 1 << endl;
                return 0;
            }
            cur = (cur - 1) / k + 1;
            best = min(best, cur);
        }
    }
    cout << best + 1 << endl;
}

