		}
		if (cur_pos.w != 0 && A[cur_pos.h][cur_pos.w - 1] == '.' && DP[cur_pos.h][cur_pos.w - 1] > (cur_pos.cost + 1)) {
			queue.emplace(cur_pos.h, cur_pos.w - 1, cur_pos.cost + 1, 0);
			DP[cur_pos.h][cur_pos.w - 1] = cur_pos.cost + 1;
		}
		if (cur_pos.w != W - 1 && A[cur_pos.h][cur_pos.w + 1] == '.' && DP[cur_pos.h][cur_pos.w + 1] > (cur_pos.cost + 1)) {
			queue.emplace(cur_pos.h, cur_pos.w + 1, cur_pos.cost + 1, 0);
			DP[cur_pos.h][cur_pos.w + 1] = cur_pos.cost + 1;
		}
	}
	bool s = false;
	for (int i = 0; i < H; i++) {
		s |= DP[i][0] != 10000000;
		s |= DP[i][W - 1] != 10000000;
	}
	for (int i = 0; i < W; i++) {
		s |= DP[0][i] != 10000000;
		s |= DP[H - 1][i] != 10000000;
	}
	if (s)
		printf("%d\n", 1);
	else {
		int distance = 800;
		for (int i = 0; i < H; i++)
			for (int j = 0; j < W; j++)
				if (DP[i][j] != 10000000)
					distance = std::min(distance, std::min(std::min(i, j), std::min(H - 1 - i, W - 1 - j)));
		printf("%d\n", (distance + K - 1) / K + 1);
	}
}

