		return x + y * W;
	};
	for (int i = 0; i < H * W; i++)
	{
		char m;
		cin >> m;
		if (m == 'S') {
			sx = i % W;
			sy = i / W;
		}
		opened[i] = (m != '#') ? true : false;
		reached[i] = false;
	}

	int MC = 1;

	int sr;
	priority_queue<pair<int, int>  > moveque;
	auto push_move = [&](int range, int x,int y) {
		if (range == 0)return;
		int index = Index(x, y);
		if (!opened[index] || reached[index])return;
		moveque.push({ range ,index });
		reached[index] = true;
		sr = min(sr,min(min(x, W - x - 1), min(y, H - y - 1)));
	};

