typedef pair<ll,ll> P; 
typedef tuple<ll,ll,ll> T;
ll INF = 1e15;

vector<string> area;
ll H,W,K;
ll dx[]={-1,0,1,0};
ll dy[]={0,1,0,-1};


ll bfs(ll sy, ll sx){
	priority_queue<T> que;
	que.push(T(-K,sy,sx));
	vector<vector<ll>> visited(H+2,vector<ll>(W+2, INF));
	ll ans=min(abs(sy - 1), abs(sy - H)) + min(abs(sx - 1), abs(sx - W));
	while(!que.empty()){
		ll y,x,k;
		tie(k,y,x) = que.top();
		if(visited[y][x]==0){
			que.pop();
			continue;
		}
		visited[y][x]=0;
		k=-k;
		que.pop();
		if(k==0)
			continue;
		for(int i=0;i<4;i++){
			if(area[y+dy[i]][x+dx[i]]!='#' && visited[y+dy[i]][x+dx[i]]>k-1){
				que.push(T(-(k-1),y+dy[i], x+dx[i]));
				visited[y+dy[i]][x+dx[i]]=k-1;
				ans = min(ans, min(min(abs(y+dy[i] - 1), abs(y+dy[i] - H)) , min(abs(x+dx[i] - 1), abs(x+dx[i] - W))));
			}
		}
	}
	return ans;
}

int main(){
	cin >> H >> W >> K;
	area.assign(H+2, string(W+2, '#'));
	for(int i=1;i<=H;i++){
		cin >> area[i];
		area[i] = "#" + area[i] + "#";
	}
	for(int y=1;y<=H;y++)
		for(int x=1;x<=W;x++)
			if(area[y][x]=='S'){
				ll ret = bfs(y,x);
				if(ret == 0)
					cout << 1 << endl;
				else
					cout << 1 + (bfs(y,x)+K-1)/K << endl;
				return 0;
				break;
			}
	return 0;
}

