lint h, w, k;
char a[1000][1000];


vec bfs(const vec2& g, lint s)
{
	lint n = g.size();
	vec d(n, inf);

	d[s] = 0;
	queue<lint> q;
	q.push(s);
	while (!q.empty())
	{
		lint pos = q.front();
		q.pop();
		rep(i, g[pos].size())
		{
			if (d[pos] + 1 < d[g[pos][i]])
			{
				d[g[pos][i]] = d[pos] + 1;
				q.push(g[pos][i]);
			}
		}
	}
	return d;
}

int main()
{
	cin >> h >> w >> k;

	rep(i, h)
		cin >> a[i];

	lint sx, sy;
	rep(y,h)
		rep(x,w)
		if (a[y][x] == 'S')
		{
			sx = x; sy = y;
		}

	lint ans = inf;
	lint p = inf;
	repb(x, sx, w - 1)
	{
		if (a[sy][x] == '#')
		{
			p = x;
			break;
		}
	}
	if (p == inf || (p - sx) > k)
		ans = mmin(ans, div2(w - 1 - sx, k));
	else
		ans = mmin(ans, div2(w - 1 - (p - 1), k) + 1);

	p = inf;
	repbr(x, 0, sx)
	{
		if (a[sy][x] == '#')
		{
			p = x;
			break;
		}
	}
	if (p == inf || (sx - p) > k)
		ans = mmin(ans, div2(sx - 0, k));
	else
		ans = mmin(ans, div2((p + 1) - 0, k) + 1);

	p = inf;
	repb(y, sy, h - 1)
	{
		if (a[y][sx] == '#')
		{
			p = y;
			break;
		}
	}
	if (p == inf || (p - sy) > k)
		ans = mmin(ans, div2(h - 1 - sy, k));
	else
		ans = mmin(ans, div2(h - 1 - (p - 1), k) + 1);

	p = inf;
	repbr(y, 0, sy)
	{
		if (a[y][sx] == '#')
		{
			p = y;
			break;
		}
	}
	if (p == inf || (sy - p) > k)
		ans = mmin(ans, div2(sy - 0, k));
	else
		ans = mmin(ans, div2((p + 1) - 0, k) + 1);

	vec2 g(h* w);

	auto f = [](lint x, lint y)
	{
		return x + y * w;
	};

	repi(x, 1, w-1)
		repi(y, 1, h - 1)
	{
		if (a[y][x - 1] != '#')
			g[f(x, y)].push_back(f(x - 1, y));
		if (a[y][x + 1] != '#')
			g[f(x, y)].push_back(f(x + 1, y));
		if (a[y - 1][x] != '#')
			g[f(x, y)].push_back(f(x, y - 1));
		if (a[y + 1][x] != '#')
			g[f(x, y)].push_back(f(x, y + 1));
	}

	auto dd = bfs(g, f(sx, sy));
	rep(x, w)
		ans = mmin(ans, div2(dd[f(x, 0)], k), div2(dd[f(x, h - 1)], k));
	rep(y, h)
		ans = mmin(ans, div2(dd[f(0, y)], k), div2(dd[f(w - 1, y)], k));

	cout << ans << endl;

	return 0;
}

