  rep(i, H) cin >> A[i];
  int s = -1;
  rep(i, H) rep(j, W) if(A[i][j] == 'S') s = i*W+j;
  int dx[] = {0, -1, 0, 1};
  int dy[] = {-1, 0, 1, 0};
  vector<int> dist(H*W);
  vector<int> S;
