				else if (c + 1 <= magic * K) {
					Q.push(mt(np, nq, c + 1)); D[np][nq] = D[p][q]+1;
				}
			}
			np = p; nq = q+1;
			if (D[np][nq] == INF) {
				if (A[np][nq] == '.') {
					Q.push(mt(np, nq, c)); D[np][nq] = D[p][q]+1;
				}
				else if (c + 1 <= magic * K) {
					Q.push(mt(np, nq, c + 1)); D[np][nq] = D[p][q]+1;
				}
			}
			np = p; nq = q-1;
			if (D[np][nq] == INF) {
				if (A[np][nq] == '.') {
					Q.push(mt(np, nq, c)); D[np][nq] = D[p][q]+1;
				}
				else if (c + 1 <= magic * K) {
