vector<pair<int, int> > pt;

void dfs(int x, int y)
{
	pt.push_back(mp(x, y));
	for(int i = 0; i < 4; i ++)
	{
		int u = x + xx[i];
		int v = y + yy[i];
		if(u <= 0) continue;
		if(v <= 0) continue;
		if(u > w) continue;
		if(v > h) continue;
		if(vis[u][v]) continue;
		if(ch[u][v] == '#') continue;
		vis[u][v] = 1;
		dfs(u, v);
	}
}

int main()
{
	cin >> h >> w >> k;
	for(int i = 1; i <= w; i ++)
		scanf("%s", ch[i] + 1);
	int stx, sty;
	for(int i = 1; i <= w; i ++)
		for(int j = 1; j <= h; j ++)
			if(ch[i][j] == 'S')
				{stx = i; sty = j; break;}
	//cout << stx << " " << sty << endl;
	vis[stx][sty] = 1;
	dfs(stx, sty);
	int n = pt.size(), dis = 1e7;
	for(int i = 0; i < n; i ++)
	{
		int x = pt[i].X;
		int y = pt[i].Y;
		dis = min(dis, x - 1);
		dis = min(dis, y - 1);
		dis = min(dis, w - x);
		dis = min(dis, h - y);
	}
	cout << 1 + ceil((double)dis / k);
	return 0;
}

