typedef pair<int, int> PII;
typedef long long LL;

char M[1000][1000];
int D[1000][1000];
int D2[1000][1000];

const int INF = 1e9;

int main() {
  int H, W, K;
  scanf("%d%d%d", &H, &W, &K);
  REP(i,H) scanf("%s", M[i]);
  PII starting;
  REP(i,H)REP(j,W) {
    if (M[i][j] == 'S') {
      M[i][j] = '.';
      starting = {i,j};
    }

    D[i][j] = D2[i][j] = INF;
  }

  queue<PII> Q;
  REP(i,H) D[i][0] = D[i][W-1] = 0;
  REP(j,W) D[0][j] = D[H-1][j] = 0;
  REP(i,H)REP(j,W) if (D[i][j] == 0) Q.push({i,j});

  while (!Q.empty()) {
    PII p = Q.front();
    int d = D[p.st][p.nd];
    Q.pop();
    if (p.st > 0 && D[p.st-1][p.nd] > d + 1) {
      D[p.st-1][p.nd] = d + 1;
      Q.push({p.st - 1, p.nd});
    }
    if (p.st < H - 1 && D[p.st+1][p.nd] > d + 1) {
      D[p.st+1][p.nd] = d + 1;
      Q.push({p.st + 1, p.nd});
    }
    if (p.nd > 0 && D[p.st][p.nd - 1] > d + 1) {
      D[p.st][p.nd - 1] = d + 1;
      Q.push({p.st, p.nd - 1});
    }
    if (p.nd < W - 1 && D[p.st][p.nd + 1] > d + 1) {
      D[p.st][p.nd + 1] = d + 1;
      Q.push({p.st, p.nd + 1});
    }
  }

  D2[starting.st][starting.nd] = 0;
  Q.push(starting);
  while (!Q.empty()) {
    PII p = Q.front();
    int d = D2[p.st][p.nd];
    Q.pop();
    if (M[p.st][p.nd] == '#') continue;

    if (p.st > 0 && D2[p.st-1][p.nd] > d + 1) {
      D2[p.st-1][p.nd] = d + 1;
      Q.push({p.st - 1, p.nd});
    }
    if (p.st < H - 1 && D2[p.st+1][p.nd] > d + 1) {
      D2[p.st+1][p.nd] = d + 1;
      Q.push({p.st + 1, p.nd});
    }
    if (p.nd > 0 && D2[p.st][p.nd - 1] > d + 1) {
      D2[p.st][p.nd - 1] = d + 1;
      Q.push({p.st, p.nd - 1});
    }
    if (p.nd < W - 1 && D2[p.st][p.nd + 1] > d + 1) {
      D2[p.st][p.nd + 1] = d + 1;
      Q.push({p.st, p.nd + 1});
    }
  }

  int result = INF;
  REP(i,H)REP(j,W) {
    if (M[i][j] == '#' || D2[i][j] > K) continue;
    result = min(result, 1 + (D[i][j] + K-1) / K);
  }
  printf("%d\n", result);
}

