struct pnt{
    int y,x,cost,cnt;
};

bool operator< (const pnt &pnt1, const pnt &pnt2){
    if(pnt1.cost<pnt2.cost){
        return true;
    }else if(pnt1.cost>pnt2.cost){
        return false;
    }else{
        return pnt1.cnt<pnt2.cnt;
    }
}
bool operator> (const pnt &pnt1, const pnt &pnt2){
    if(pnt1.cost>pnt2.cost){
        return true;
    }else if(pnt1.cost<pnt2.cost){
        return false;
    }else{
        return pnt1.cnt>pnt2.cnt;
    }
}

vector<vector<int>> mv={{1,0},{-1,0},{0,1},{0,-1}};
vector<vector<int>> dist(800,vector<int>(800,MOD));

int bfs(vector<vector<char>> &grid){
    priority_queue<pnt,vector<pnt>,greater<pnt>> que;
    que.push({sy,sx,1,0});
    while((int)que.size()>0){
        pnt now=que.top();
        que.pop();

        if(dist[now.y][now.x]<MOD){
            if(now.cnt>0){
                continue;
            }
        }else{
            dist[now.y][now.x]=now.cost;
        }
        if(now.y==0 || now.y==H-1 || now.x==0 || now.x==W-1){
            return now.cost;
        }else if(now.cnt==K){
            now.cost++;
            now.cnt=0;
        }

        for(auto &m:mv){
            int nx,ny;
            nx=now.x+m[1];
            ny=now.y+m[0];

            if(grid[ny][nx]=='#' && now.cost==1){
                continue;
            }else{
                que.push({ny,nx,now.cost,now.cnt+1});
            }
        }
        if(now.cost==1){
            que.push({now.y,now.x,now.cost+1,0});
        }
    }
}

