using namespace std;

int solve(const vector<string>& board, int K){
	const int H = board.size();
	const int W = board[0].size();
	queue<pair<int,int>> qu;
	vector<vector<int>> step(H, vector<int>(W, -1));
	for(int i=0;i<H;i++){
		for(int j=0;j<W;j++){
			if(board[i][j] == 'S'){
				qu.emplace(i, j);
				step[i][j] = 0;
			}
		}
	}
	while(!qu.empty()){
		auto p = qu.front(); qu.pop();
		int h = p.first, w = p.second;
		if(h == 0 || h == H-1 || w == 0 || w == W-1) return 1;
		if(step[h][w] == K) continue;
		int dx[] = {-1, 0, 1, 0};
		int dy[] = {0, -1, 0, 1};
		for(int d=0;d<4;d++){
			int nh = h + dx[d], nw = w + dy[d];
			if(nh < 0 || H <= nh || nw < 0 || W <= nw) continue;
			if(board[nh][nw] == '#') continue;
			if(step[nh][nw] != -1) continue;
			step[nh][nw] = step[h][w] + 1;
			qu.emplace(nh, nw);
		}
	}
	int res = 100000000;
	for(int i=0;i<H;i++){
		for(int j=0;j<W;j++){
			if(step[i][j] == -1) continue;
			res = min(res, (i+K-1)/K);
			res = min(res, (j+K-1)/K);
			res = min(res, (H-1-i+K-1)/K);
			res = min(res, (W-1-j+K-1)/K);
		}
	}
	return res + 1;
}

int main(){
	int H, W, K;
	while(cin >> H >> W >> K){
		vector<string> board(H);
		for(auto& s : board) cin >> s;
		cout << solve(board, K) << endl;
	}
}

