using namespace std;
const double PI = 3.14159265358979323846;
const double EPS = 1e-12;
const int INF = numeric_limits<int>::max() / 2;
const int NEG_INF = numeric_limits<int>::min() / 2;
typedef vector<int> VI;
typedef vector<VI> VVI;
typedef vector<string> VS;
typedef pair<int, int> PII;
typedef long long LL;

int H, W, K;
VS table;
const int MAX_H = 800 + 10;
const int MAX_W = 800 + 10;
int cost_mat[MAX_H][MAX_W];

void solve() {
    PII start;
    REP(i, H) {
        REP(j, W) {
            cost_mat[i][j] = INF;
            if (table[i][j] == 'S') {
               start = make_pair(i, j); 
            }
        }
    }
    // startからK回で移動できるところを列挙
    int dx[4] = {-1, 0, 1, 0};
    int dy[4] = {0, -1, 0, 1};
    queue<PII> que;
    que.push(start);
    cost_mat[start.first][start.second] = 0;

    while (!que.empty()) {
        PII pos = que.front(); que.pop();
        if (cost_mat[pos.first][pos.second] < K) {
            REP(d, 4) {
                int ni = pos.first + dx[d];
                int nj = pos.second + dy[d];
                if (0 <= ni and ni < H and 0 <= nj and nj < W and table[ni][nj] != '#') {
                    if (cost_mat[ni][nj] > cost_mat[pos.first][pos.second] + 1) {
                        cost_mat[ni][nj] = cost_mat[pos.first][pos.second] + 1;
                        que.push(make_pair(ni, nj));
                    }
                }
            }
        }

    }

    // 移動できるところから最短距離を求める
    int ans = INF;
    REP(i, H) {
        REP(j, W) {
            if (cost_mat[i][j] != INF) {
                //cout << i << " " << j << endl;
                ans = min(ans, (i + K - 1) / K);
                ans = min(ans, (j + K - 1) / K);
                ans = min(ans, (H - i - 1 + K - 1) / K);
                ans = min(ans, (W - j - 1 + K - 1) / K);
            }
        }
    }
    cout << ans + 1 << endl;



}

int main(int argc, char const* argv[])
{
    cin >> H >> W >> K;
    REP(i, H) {
        string s; cin >> s;
        table.PB(s);
    }
    solve();
    return 0;
}

