  for(int i=1; i<=H; ++i){
    for(int j=1; j<=W; ++j){
      cin>>A[i][j];
      if(A[i][j]=='S'){
        sy=i;
        sx=j;
      }
      D[i][j]=MAX;
      CAN[i][j]=false;
