    while (!q.empty())
    {
        TnT gg = q.front();
        q.pop();
        for (int i = 0 ; i < 4 ; i++)
        {
            TnT gl = gg;
            gl.x += dr[i][0];
            gl.y += dr[i][1];
            if (gl.x >= 0 && gl.x < h && gl.y >= 0 && gl.y < w && mmp[gl.x][gl.y] != '#' && !vis[gl.x][gl.y])
            {
                gl.step++;
                step[gl.x][gl.y] = gl.step;
                vis[gl.x][gl.y] = true;
                q.push(gl);
            }
        }
    }
}
