                {
                    S.x = i;
                    S.y = j;
                    S.step = 1;
                }
            }
        }
        bfs();
        int ans = INF;
        for (i = 0; i < n; ++i)
        {
            for (j = 0; j < m; ++j)
            {
                if (step[i][j])
                {
                    int gg = step[i][j], gl = 0;
                    gl = gg / k + (gg % k != 0);
                    gg = i;
                    ans = min(ans, gl + gg / k + (gg % k != 0));
                    gg = j;
