int dfs(queue<pair<XY, int>>& q, XY pos, int cost, int k) {
  int res = INF;
  if (k < 0)return res;
  for (auto& i : d4) {
    auto n = i + pos;
    if (n.check(w, h)) {
      if (v[n.y][n.x] > cost) {
        q.push({ n, cost });
        v[n.y][n.x] = cost;
        if (a[n.y][n.x] != '#') {
          amin(res, dfs(q, n, cost, k - 1));
        }
        else {
          v[n.y][n.x] = cost + 1;
        }
        a[n.y][n.x] = 'A';
      }
    }
    else {
      return cost;
    }
  }
  return res;
}
