template <typename T> T inf;
template <> constexpr int inf<int> = 1e9;
template <> constexpr ll inf<ll> = 1e18;

constexpr int dx[4] = {0, 1, 0, -1};
constexpr int dy[4] = {1, 0, -1, 0};

int main() {
    int H, W, K;
    cin >> H >> W >> K;
    vector<string> A(H);
    for(int i = 0; i < H; ++i) {
        cin >> A[i];
    }

    queue<pii> que;
    vector<vector<int>> d(H, vector<int>(W, inf<int>));
    for(int i = 0; i < H; ++i) {
        for(int j = 0; j < W; ++j) {
            if(A[i][j] == 'S') {
                que.emplace(i, j);
                d[i][j] = 0;
            }
        }
    }
    while(!que.empty()) {
        int y = que.front().first, x = que.front().second;
        que.pop();
        for(int i = 0; i < 4; ++i) {
            int ny = y + dy[i], nx = x + dx[i];
            if(ny < 0 || H <= ny || nx < 0 || W <= nx || d[ny][nx] != inf<int> || A[ny][nx] == '#') {
                continue;
            }
            d[ny][nx] = d[y][x] + 1;
            if(d[ny][nx] < K) {
                que.emplace(ny, nx);
            }
        }
    }

    int res = inf<int>;
    for(int i = 0; i < H; ++i) {
        for(int j = 0; j < W; ++j) {
            if(d[i][j] == inf<int>) {
                continue;
            }
            int dist_y = min(H - i - 1, i);
            int dist_x = min(j, W - j - 1);
            int dist = min(dist_y, dist_x);
            res = min(res, (dist + K - 1) / K + 1);
        }
    }
    cout << res << endl;
}

