int MinDir(int x,int y)
{
	int a1=x/k;
	if(x%k)
		++a1;
	int a2=(n-x-1)/k;
	if((n-x-1)%k)
		++a2;
	int a3=y/k;
	if(y%k)
		++a3;
	int a4=(m-y-1)/k;
	if((m-y-1)%k)
		++a4;
	return min(a1,min(a2,min(a3,a4))); 
}
