#include<bits/stdc++.h>
#define fi first
#define se second
#define pb push_back
using namespace std;
typedef long long LL;
typedef pair<int, int> pii;

deque<pair<pii, int> > pos;
bool vis[805][805];
int Bvis[805][805];
int N, M, K;
char kotak[805][805];
int x1[4]={0, 1, 0, -1};
int y2[4]={1, 0, -1, 0};
vector<pii> tmp;
bool bfs()
{
    while(!pos.empty()) pos.pop_front();
    for(int z=0;z<tmp.size();z++)
    {
        pos.push_back(pair<pii, int> (tmp[z], K));
        vis[tmp[z].fi][tmp[z].se]=1;
    }
    tmp.clear();
    while(!pos.empty())
    {
        int nowx=pos.front().fi.se, nowy=pos.front().fi.fi, nowcost=pos.front().se;
        pos.pop_front();
        if(nowx==1 || nowy==1 || nowx==M || nowy==N) return 1;
        if(nowcost==0)
        {
            tmp.push_back(pii(nowy, nowx));
            continue;
        }
        bool done=0;
        for(int z=0;z<4;z++)
        {
            int newy=nowy+y2[z], newx=nowx+x1[z];
            if(newy<1 || newx<1 || newy>N || newx>M) continue;
            if(kotak[newy][newx]=='#') continue;
            if(vis[newy][newx]) continue;
            vis[newy][newx]=1;
            pos.push_back(pair<pii, int> (pii(newy, newx), nowcost-1));
            done=1;
        }
        if(!done)
        {
            tmp.push_back(pii(nowy, nowx));
        }
    }
    return 0;
}

void createpath()
{
    while(!pos.empty()) pos.pop_front();
    for(int z=0;z<tmp.size();z++)
    {
        pos.push_back(pair<pii, int> (tmp[z], K));
        Bvis[tmp[z].fi][tmp[z].se]=1;
    }
    queue<pii> STMP;
    while(!pos.empty())
    {
        int nowx=pos.front().fi.se, nowy=pos.front().fi.fi, nowcost=pos.front().se;
        pos.pop_front();
        STMP.push(pii(nowy, nowx));
        if(nowcost==0) continue;
        for(int z=0;z<4;z++)
        {
            int newy=nowy+y2[z], newx=nowx+x1[z], nc=nowcost-(kotak[newy][newx]=='#');
            if(newy<1 || newx<1 || newy>N || newx>M) continue;
            if(Bvis[newy][newx]>=nc) continue;
            Bvis[newy][newx]=nc;
            if(nc==nowcost)
            {
                pos.push_front(pair<pii, int> (pii(newy, newx), nc));
            }
            else
            {
                pos.push_back(pair<pii, int> (pii(newy, newx), nc));
            }
        }
    }
    while(!STMP.empty())
    {
        kotak[STMP.front().fi][STMP.front().se]='.';
        STMP.pop();
    }
}
int main()
{
    ios_base::sync_with_stdio(false);cin.tie(0);cout.tie(0);
    cin>>N>>M>>K;
    memset(Bvis, -1, sizeof(Bvis));
    for(int a=1;a<=N;a++)
    {
        for(int b=1;b<=M;b++)
        {
            cin>>kotak[a][b];
            if(kotak[a][b]=='S')
            {
                tmp.push_back(pii(a, b));
            }
        }
    }
    int cnt=1;
    while(!bfs())
    {
        createpath();
        cnt++;
    }
    cout<<cnt<<endl;
    return 0;
}

