int H, W, K;
constexpr int Hmax = 800;
vector<vector<int>> A, dp;

int main()
{
    cin >> H >> W >> K;
    A.resize(H + 2, vector<int>(W + 2, 1));
    dp.resize(H + 2, vector<int>(W + 2, 0));
    int sx, sy;
    REP(h, H)
    {
        string s;
        cin >> s;
        REP(w, W)
        {
            if (s[w] != '#') A[h + 1][w + 1] = 0;
            if (s[w] == 'S') sx = h + 1, sy = w + 1;
        }
    }

    using tpl = tuple<int, int, int>;
    queue<tpl> q;
    q.push(tpl(sx, sy, K + 1));
    int ans = 100000000;
    while (!q.empty())
    {
        int x, y, Know;
        tie(x, y, Know) = q.front();
        q.pop();
        if (Know <= dp[x][y]) continue;
        dp[x][y] = Know;
        ans = min(ans, (x + K - 2) / K);
        ans = min(ans, (H + 1 - x + K - 2) / K);
        ans = min(ans, (y + K - 2) / K);
        ans = min(ans, (W + 1 - y + K - 2) / K);
        if (!A[x + 1][y] and dp[x + 1][y] < Know - 1) q.push(tpl(x + 1, y, Know - 1));
        if (!A[x - 1][y] and dp[x - 1][y] < Know - 1) q.push(tpl(x - 1, y, Know - 1));
        if (!A[x][y + 1] and dp[x][y + 1] < Know - 1) q.push(tpl(x, y + 1, Know - 1));
        if (!A[x][y - 1] and dp[x][y - 1] < Know - 1) q.push(tpl(x, y - 1, Know - 1));
    }
    dbg(dp);
    cout << ans + 1 << endl;
}

