PII dfs(int i, int j, int x1, int x2) {
	if (i == 0 || i == h - 1 || j == 0 || j == w - 1) {
		return MP(x1, x2);
	}
	if (x1 > k || x2 > k) {
		return MP(INF, INF);
	}
	if (v[i][j]) {
		return MP(c1[i][j], c2[i][j]);
	}
	PII ret = MP(INF, INF);
	FR(k, 4) {
		int ni = i + dx[k], nj = j + dy[k];
		if (g[ni][nj] == '#') {
			PII p = dfs(ni, nj, x1, x2 + 1);
			if (p.first + max(0, p.second - p.first) + p.second < ret.first + max(0, ret.second - ret.first) + ret.second) {
				ret = p;
			}
		} else {
			PII p = dfs(ni, nj, x1 + 1, x2);
			if (p.first + max(0, p.second - p.first) + p.second < ret.first + max(0, ret.second - ret.first) + ret.second) {
				ret = p;
			}
		}
	}
	return ret;
}

