using namespace std;

#define MAX_H 805
#define MAX_W 805
#define MAX_K (MAX_H * MAX_W)

int H, W, K;
char Field[MAX_H][MAX_W];
int Sx, Sy;

int used[MAX_H][MAX_W];

int dx[] = {1,-1,0,0};
int dy[] = {0,0,1,-1};

bool isInField(int x, int y)
{
  return 0 <= x && x < W && 0 <= y && y < H;
}

bool isGoal(int x, int y)
{
  return x == 0 || x == W-1 || 0 == y || y == H-1;
}

int main()
{
  cin >> H >> W >> K;
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      cin >> Field[i][j];
      if(Field[i][j] == 'S'){
        Sx = j; Sy = i;
        Field[i][j] = '.';
      }
    }
  }

  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      used[i][j] = INF;
    }
  }

  using Pos = pair<int, int>;
  queue<Pos> que;
  queue<Pos> ansList;

  que.push(Pos(Sx, Sy));

  used[Sy][Sx] = 0;

  while(que.size()){
    Pos p = que.front();
    que.pop();

    int x = p.first;
    int y = p.second;

    ansList.push(p);

    if(used[y][x] == K){
      continue;
    }

    for (int d = 0; d < 4; d++) {
      int nx = x + dx[d];
      int ny = y + dy[d];
      if(isInField(nx, ny) && used[ny][nx] == INF && Field[ny][nx] == '.'){
        used[ny][nx] = used[y][x]+1;
        que.push(Pos(nx, ny));
      }
    }

  }

  int ans = 1145141919;
  while(ansList.size()){

    Pos p = ansList.front();
    ansList.pop();

    int x = p.first;
    int y = p.second;

    if(isGoal(x, y)){
      cout << 1 << endl;
      return 0;
    }

    //左
    int tmp = x/K + (x % K > 0 ? 1 : 0);
    ans = min(ans, tmp);

    //右
    tmp = (W-x-1)/K + ((W-x-1) % K > 0 ? 1 : 0);
    ans = min(ans, tmp);

    //上
    tmp = y/K + (y % K > 0 ? 1 : 0);
    ans = min(ans, tmp);

    //下
    tmp = (H-1-y)/K + ((H-1-y) % K > 0 ? 1 : 0);
    ans = min(ans, tmp);

  }

  cout << ans + 1 << endl;

  return 0;
}

