//コンビネーション
const int MAXcomb = 200010;
ll fac[MAXcomb], finv[MAXcomb], inv[MAXcomb];
//facはn!,finvは1/n!
//invは逆元
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAXcomb; i++){
        fac[i] = fac[i-1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;
        finv[i] = finv[i-1] * inv[i] % MOD;
    }
}
ll comb(int n, int k){
    if(n < k) return 0;
    if(n < 0 || k < 0) return 0;
    return fac[n] * finv[k] % MOD * finv[n-k] % MOD;
}


int H, W, K;
vector<vector<char>> mp(810, vector<char>(810));
int sy, sx;
int dist[810][810][1200];
typedef pair<pair<int, int>, pair<int, int>> P;


int dijkstra(){
  priority_queue<P, vector<P>, greater<P>> pque;
  //dist, rest, y, x
  dist[sy][sx][0] = 0;
  pque.push({{0, 0}, {sy, sx}});
  while(!pque.empty()){
    P p = pque.top();
    pque.pop();
    if(p.s.f == 0 || p.s.f == H-1){
      return (p.f.f-1) / K + 1;
    }
    if(p.s.s == 0 || p.s.s == W-1){
      return (p.f.f-1) / K + 1;
    }
    if((p.f.f / K + 1) * K < dist[p.s.f][p.s.s][p.f.s + K]){
      dist[p.s.f][p.s.s][p.f.s + K] = (p.f.f / K + 1) * K;
      pque.push({{dist[p.s.f][p.s.s][p.f.s + K], p.f.s + K}, {p.s.f, p.s.s}});
    }
    if(dist[p.s.f][p.s.s][p.f.s] < p.f.f) continue;
    rep(i, 5){
      int ny = p.s.f + dy[i];
      int nx = p.s.s + dx[i];
      if(mp[ny][nx] == '.'){
        if(p.f.f + 1 < dist[ny][nx][p.f.s]){
          dist[ny][nx][p.f.s] = p.f.f + 1;
          pque.push({{dist[ny][nx][p.f.s], p.f.s}, {ny, nx}});
        }
      }else{
        if(p.f.s == 0) continue;
        if(p.f.f + 1 < dist[ny][nx][p.f.s-1]){
          dist[ny][nx][p.f.s-1] = p.f.f + 1;
          pque.push({{dist[ny][nx][p.f.s-1], p.f.s-1}, {ny, nx}});
        }
      }
    }
  }
}

