                dfs(dfs, {ny, nx}, n-1);
            }
        };

        s.insert({si, sj});
        dfs(dfs, {si, sj}, k);
    }

    auto f = [&](pair<long,long> t) {
        long y, x;
        tie(y, x) = t;
        return min(min(x, y), min(w-1-x, h-1-y));
    };

    long r = 1e9;
    for(auto &t: s) {
        long u = (f(t) + k-1) / k;
        r = min(r, u);
    }
    cout << 1+r << endl;
}

