#include<bits/stdc++.h>
using namespace std;

int main() {
    int64_t H, W, K;
    cin >> H >> W >> K;
    vector<string> A(H);
    for (int64_t i = 0; i < H; i++) {
        cin >> A[i];
    }

    int64_t Sx, Sy;
    for (int64_t i = 0; i < H; i++) {
        for (int64_t j = 0; j < W; j++) {
            if (A[i][j] == 'S') {
                Sx = j;
                Sy = i;
                i = H;
                j = W;
            }
        }
    }

    //Sから深さKのDFSでどこに到達できるか調べる
    int64_t dx[] = { 1, 0, -1, 0 };
    int64_t dy[] = { 0, 1, 0, -1 };
    vector<vector<int64_t>> can_reach(H, vector<int64_t>(W, LLONG_MAX));
    queue<pair<int64_t, int64_t>> st;
    can_reach[Sy][Sx] = 0;
    st.push({ Sx, Sy });
    while (!st.empty()) {
        pair<int64_t, int64_t> top = st.front();
        st.pop();

        if (can_reach[top.first][top.second] == K) {
            break;
        }

        for (int64_t i = 0; i < 4; i++) {
            int64_t nx = top.first + dx[i];
            int64_t ny = top.second + dy[i];
            if (nx < 0 || nx >= W || ny < 0 || ny >= H || can_reach[ny][nx] != LLONG_MAX || A[ny][nx] == '#') {
                continue;
            }

            can_reach[ny][nx] = can_reach[top.first][top.second] + 1;
            st.push({ ny, nx });
        }
    }


    int64_t ans = LLONG_MAX;
    for (int64_t i = 0; i < H; i++) {
        for (int64_t j = 0; j < W; j++) {
            if (can_reach[i][j] == LLONG_MAX) {
                continue;
            }

            int64_t min_distance = min({ i, j, H - 1 - i, W - 1 - j });

            ans = min(ans, 1 + (min_distance + K - 1) / K);
        }
    }

    cout << ans << endl;
}

