ll bfs(ll sy, ll sx){
	queue<T> que;
	que.push(T(sy,sx, K));
	vector<vector<ll>> visited(H+2,vector<ll>(W+2, INF));
	ll ans=min(abs(sy - 1), abs(sy - H)) + min(abs(sx - 1), abs(sx - W));
	while(!que.empty()){
		ll y,x,k;
		tie(y,x,k) = que.front();
		que.pop();
		if(k==0)
			continue;
		for(int i=0;i<4;i++){
			if(area[y+dy[i]][x+dx[i]]!='#' && visited[y+dy[i]][x+dx[i]]>=k-1){
				que.push(T(y+dy[i], x+dx[i], k-1));
				visited[y+dy[i]][x+dx[i]]=k-1;
				ans = min(ans, min(abs(y+dy[i] - 1), abs(y+dy[i] - H)) + min(abs(x+dx[i] - 1), abs(x+dx[i] - W)));
			}
		}
	}
	return ans;
}

