void searchNearest( int cx, int cy, int ck )
{
  if( cy < 1 || h < cy || cx < 1 || w < cx)
    return;
  if( map[cy][cx] == '#')
    return;
  if( visited[cy][cx] != 0 )
    return;
  visited[cy][cx] = 1;

  // check distance
  int dy = ( h / 2 > cy )? cy : h - cy;
  int dx = ( w / 2 > cx )? cx : w - cx;
  int md = ( dy < dx )? dy : dx;
  if( md < nd )
    nd = md;

  // check neighber
  if( ck > 0 )
  {
    --ck;
    searchNearest( cx - 1, cy, ck );
    searchNearest( cx + 1, cy, ck );
    searchNearest( cx, cy - 1, ck );
    searchNearest( cx, cy + 1, ck );
  }
}

