bool used[N][N];
int bfs(int y,int x,int sK){

  for(int i=0;i<N;i++)
    for(int j=0;j<N;j++) D[i][j] = PP(1e9,P(1e9,1e9));

  priority_queue<dat>Q;
  Q.push((dat){y,x,sK,0,1});  
  D[y][x] = PP(1,P(-sK,0));

  while(!Q.empty()){
    dat t = Q.top();Q.pop();
    y = t.y;
    x = t.x;
    int K1 = t.K1;
    int K2 = t.K2;
    int cost = t.cost;
    if(used[y][x] )continue;
    used[y][x] = 1;
    if(D[y][x] < PP(cost,P(-K1,-K2)))continue;
    //cout<<y<<" "<<x<<" "<<K1<<" "<<K2<<" "<<cost<<endl;

    for(int i=0;i<4;i++){
      int nx = x+dx[i];
