	cin.tie(0);
    ios::sync_with_stdio(false);

	for(int i = 0; i <= 800; i++) {
		for(int j = 0; j <= 800; j++) {
			visited[i][j] = false;
		}
	}

	int h, w, k;
	cin >> h >> w >> k;
	vector<string> table(h);
	getline(cin, table[0]);
	for(int i = 0; i < h; i++) {
		getline(cin, table[i]);
	}
	int sy, sx;
	tie(sy, sx) = getStart(table);

	int turn, bestY, bestX;
	tie(turn, bestY, bestX) = dfs(table, sy, sx, k);
	cout << ((turn + k - 1) / k + 1) << endl;

	return 0;
}

