int dx[] = {0,0,-1,1};
pii st;
int r,c,k;
string M[N + 5];
bool vis[N + 5][N + 5];

bool inRange(int y, int x){
	return y >= 0 && y < r && x >= 0 && x < c;
}

int solve(){
	queue < pair < pii , int > > q;
	while(!q.empty()) q.pop();
	q.push(MP(st,k));
	int y,x,yy,xx,ret = INF,mn,val,move;
	while(!q.empty()){
		y = q.front().FI.FI;
		x = q.front().FI.SE;
		move = q.front().SE;
		q.pop();
		if(vis[y][x]) continue;
		if(y == 0 || y == r - 1 || x == 0 || x == c-1) return 1;
		vis[y][x] = true;
		mn = min(min(x,c-x-1), min(y, r-y-1));
		val = 0;
		if(mn % k > 0) val = 1;
		val += mn / k;
		ret = min(ret, val+1);
		if(move == 0) continue;
		FOR(i,4){
			yy = y + dy[i];
			xx = x + dx[i];
			if(inRange(yy,xx) && !vis[yy][xx] && M[yy][xx] == '.'){
				q.push(MP(MP(yy,xx),move-1));
			}
		}
	}
	return ret;
}

