template<class Cost> struct Edge{
    int to;Cost cost;
    Edge(int to,Cost cost):to(to),cost(cost){};
    bool operator<(Edge r) const{ return cost<r.cost;}
    bool operator>(Edge r) const{ return cost>r.cost;}
};
template<class Cost> ostream& operator << (ostream& os, const Edge<Cost>& e){ return os<<"(->"<<e.to <<","<<e.cost<<")";}
template<class Cost> using Graph = vector<vector<Edge<Cost>>>;

template<class Cost> vector<Cost> dijkstra(const Graph<Cost>& g,const int s){
    vector<Cost> ds(g.size(),INF<Cost>());ds[s]=0;
    priority_queue<pair<Cost,int>,vector<pair<Cost,int>>,greater<pair<Cost,int>>> que;que.push({0,s});
    while(!que.empty()){
        Cost c;int v;tie(c,v)=que.top();que.pop();
        for(const Edge<Cost>& e:g[v]){
            Cost nxtc= c + e.cost;
            if(nxtc<ds[e.to]){
                ds[e.to]=nxtc;
                que.push({nxtc,e.to});
            }
        }
    }
    return ds;
}


int dx[4] = {1,0,-1,0},dy[4] = {0,1,0,-1};

class Main{
	public:

	void run(){
		int H,W,K;cin >> H >> W >> K;
		vector<string> board(H);cin >> board;

		int Sx,Sy;
		for(int y:range(H))for(int x:range(W))if(board[y][x]=='S') Sy = y,Sx = x;

		// 最初だけ注意
		Graph<ll> gs1(H*W);
		for(int y:range(H))for(int x:range(W)){
			for(int d:range(4)){
				int ny = y + dy[d],nx = x + dx[d];
				if(!IN(0,ny,H) || !IN(0,nx,W))continue;
				if(board[ny][nx] != '#')
					gs1[y*W+x].push_back(Edge<ll>(ny*W+nx,1));
			}
		}
		vector<ll> ds = dijkstra(gs1,Sy*W + Sx);

		int mv = INF<int>();
		for(int y:range(H))for(int x:range(W))if(ds[y*W+x] <= K){
			mv = min(mv,(min(min(y,H-1-y),min(x,W-1-x))+(K-1))/K+1);
		}

		cout << mv << endl;
	}
};

