			if (i == 0 || j == 0 || i == n - 1 || j == m - 1)
			{
				cout << (d + k - 1) / k << endl;
				return 0;
			}
			for (int dir = 0; dir < DIR; dir++)
			{
				int tx = i + X[dir];
				int ty = j + Y[dir];
				if (good(tx, ty)  && dp[i][j] >= bool(s[tx][ty] == '#'))
				{
					int ndp = dp[i][j] - bool(s[tx][ty] == '#') + k * bool((d + 1) % k == 0);
					if (nw[tx][ty] == -1)
						v.pb({tx, ty});
					nw[tx][ty] = max(nw[tx][ty], ndp);
				}
			}
			nw[i][j] = max(nw[i][j], dp[i][j] + bool((d + 1) % k == 0) * k);   
		}
		for (int i = 0; i < n; i++)
		{
			for (int j = 0; j < m; j++)
			{
				dp[i][j] = nw[i][j];
				nw[i][j] = -1;
			}
		}
		d++;
	}

	return 0;
}

