void dfs(int x,int y,int s){
  if(s>k) return ;
  if(x==1||x==n||y==1||y==m) { puts("1"); exit(0); }
  if(vis[x][y]) return ;
  vis[x][y]=1;
  int now=min(min(x-1,n-x),min(y-1,m-y));
  if(now<Min) Min=now;
  if(a[x+1][y]!='#') dfs(x+1,y,s+1);
  if(a[x-1][y]!='#') dfs(x-1,y,s+1);
  if(a[x][y+1]!='#') dfs(x,y+1,s+1);
  if(a[x][y-1]!='#') dfs(x,y-1,s+1);
}

