      if(a[i][j]=='S') bx=i,by=j;
  Min=min(min(bx-1,n-bx),min(by-1,m-by));
  dfs(bx,by,0);
  Ans=1+ceil(Min/(double)k);
  printf("%d\n",Ans);
  return 0;
}

