int H, W, K;
string S[800];
int si, sj;

int Dist(int i,int j) {
	return min({ i, j, H - i - 1, W - j - 1 });
}

int di[] = { 0,1,0,-1 };
int dj[] = { 1,0,-1,0 };

bool visited[800][800];
int DFS(int i, int j) {
	if (S[i][j] == '#' || visited[i][j]) return INF;
	visited[i][j] = true;
	int mn = Dist(i, j);
	REP(k, 0, 4) {
		int p = i + di[k];
		int q = j + dj[k];
		if (!Inside(p, q, H, W)) continue;
		mn = min(mn, DFS(p, q));
	}
	return mn;
}

