const int maxn=855;
int sr=-1,sc=-1;
bool vis[maxn][maxn];
int h,w,k,dis=100000000;
vector<string>v;

queue<int>xq,yq,le;
bool chk(int x , int y , int z) {
	if(x>=0 && x<h && y>=0 && y<w) {
		if(vis[x][y]==0 && v[x][y]!='#') {
			vis[x][y]=1;
			int d=min(min(x,h-x-1),min(y,w-y-1));
			dis=min(dis,d);
			if(z<=k) {
				xq.push(x);
				yq.push(y);
				le.push(z);
			}
			return 1;
		}
	}
	return 0;
}
void bfs(int i , int j) {
	chk(i,j,0);
	while (!xq.empty()) {
		int a=xq.front(),b=yq.front(),c=le.front();
		chk(a-1,b,c+1);
		chk(a+1,b,c+1);
		chk(a,b-1,c+1);
		chk(a,b+1,c+1);
		xq.pop(),yq.pop(),le.pop();
	}
}

