#include<bits/stdc++.h>
using namespace std;
template<class T> void chmin(T& x, T y) {if(x > y) x = y;}
int ans = 1 << 30;
char bld[810][810];
bool came[810][810];
int H, W, K, s, t;
int dx[] = {1, 0, -1, 0};
int dy[] = {0, -1, 0, 1};

struct edge{
    int a, b, cost;
    bool operator < (const edge& e) const {
        return cost < e.cost;
    }

    bool operator > (const edge& e) const {
        return cost > e.cost;
    }
};


int main(){
    cin >> H >> W >> K;
    for(int i = 1; i <= H; i++){
        for(int j = 1; j <= W; j++){
            cin >> bld[i][j];
            if(bld[i][j] == 'S') s = i, t = j;
        }
    }

    priority_queue<edge, vector<edge>, greater<edge>> pq;
    pq.push(edge{s, t, 0});
    while(!pq.empty()){
        edge e = pq.top();
        pq.pop();

        if(came[e.a][e.b]) continue;
        came[e.a][e.b] = true;

        if(e.a == 1 || e.b == 1 || e.a == H || e.b == W){
            ans = 1;
        }

        chmin(ans, ((H - e.a - 1) / K) + 2);
        chmin(ans, ((e.a - 2) / K) + 2);
        chmin(ans, ((W - e.b - 1) / K) + 2);
        chmin(ans, ((e.b - 2) / K) + 2);

        for(int i = 0; i < 4; i++){
            int ux = e.a + dx[i];
            int uy = e.b + dy[i];

            if(bld[ux][uy] == '#') continue;

            if(1 <= ux && ux <= H && 1 <= uy && uy <= W && e.cost < K){
                pq.push(edge{ux, uy, e.cost + 1});
            }
        }

    }
    cout << ans << endl;
    return 0;
}

#include <iostream>
#include <queue>
#include <vector>
using namespace std;
#define p pair<int,int>
#define out(tp) (tp.first < 0 || tp.first >= H || tp.second < 0 || tp.second >= W)

int rs[] = {0,0,1,-1};
int cs[] = {-1,1,0,0};

typedef struct node {
    p tp;
    int r, ml, cl;
} node;
typedef node * Node;

class cmp {
    public: bool operator() (Node a, Node b) { return (b->r < a->r || (b->r == a->r && b->cl > a->cl)); }
};

Node newNode(p tp, int r, int ml, int cl) {
    Node tn = (Node) malloc(sizeof(node));
    tn->tp = tp, tn->r = r, tn->ml = ml, tn->cl = cl;
    return tn;
}

int main() {
    int H, W, K, i, r, c;
    p tp;
    string m[800];
    cin >> H >> W >> K;
    for (r = 0; r < H; r++) {
        cin >> m[r];
        for (c = 0; c < W; c++) {
            if (m[r][c] == 'S') {
                m[r][c] = '.';
                tp = p(r, c);
            }
        }
    }

    // each state
    // - coord
    // - moves so far
    // - rooms to move left
    // - rooms to clear left
    priority_queue<Node, vector<Node>, cmp> q;
    q.push(newNode(tp, 0, K, K));

    int seen[800][800] = {};
    while (!q.empty()) {
        Node t = q.top(); q.pop();

        //printf("at %d %d, r:%d, ml:%d, cl:%d\n", t->tp.first, t->tp.second, t->r, t->ml, t->cl);
        // If you moved out of bounds, game over
        if (out(t->tp)) {
            cout << t->r+1+(t->cl != K) << '\n';
            return 0;
        }

        if (seen[t->tp.first][t->tp.second]) continue;
        seen[t->tp.first][t->tp.second] = 1;

        // Move
        for (i = 0; i < 4; i++) {
            tp = p(t->tp.first+rs[i], t->tp.second+cs[i]);

            if (out(tp) || m[tp.first][tp.second] == '.') {
                // push a node where you've moved there
                Node nn = newNode(tp, t->r, t->ml-1, t->cl);
                if (nn->ml < 0) {
                    nn->ml += K, nn->cl += K, nn->r++;
                }
                q.push(nn);
            }
            else {
                // push a node where you've destroyed it AND moved there
                Node nn = newNode(tp, t->r, t->ml-1, t->cl-1);
                if (nn->ml < 0 || nn->cl < 0) {
                    nn->ml += K, nn->cl += K, nn->r++;
                }
                q.push(nn);

            }
        }
    }
}

