int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int H, W, K;
  cin >> H >> W >> K;
  VS vs(H);
  REP(y,H) cin >> vs[y];
  int sx, sy;
  REP(y,H) REP(x,W) if(vs[y][x] == 'S')
	sx = x, sy = y;
  vs[sy][sx] = '.';

  VVI dist(H, VI(W, INF));
  queue<PII> q;
  q.push(MP(sx,sy));
  dist[sy][sx] = 0;
  while(!q.empty()){
	PII p = q.front();
	q.pop();
	if(p.FF == 0 || p.FF == W-1 || p.SS == 0 || p.SS == H-1 || dist[p.SS][p.FF] == K)
	  continue;
	REP(d,4){
	  int nx = p.FF + dx[d], ny = p.SS + dy[d];
	  if(vs[ny][nx] == '#' || dist[ny][nx] < INF) continue;
	  dist[ny][nx] = dist[p.SS][p.FF] + 1;
	  q.push(MP(nx,ny));
	}
  }

  int ans = INF;
  REP(y,H) REP(x,W)
	if(dist[y][x] < INF){
	  int tmp = min(min(y,H-1-y), min(x, W-1-x));
	  mini(ans, (tmp+K-1)/K);
	}

  cout << 1+ans << endl;

  return 0;
}

