struct dt{
	int r, c, dm, dk;
	dt(int r=0, int c =0, int dm = 0, int dk = 0):r(r),c(c),dm(dm),dk(dk){}
	bool operator< (const dt &rhs) const{
		return dm == rhs.dm ? dk > rhs.dk : dm > rhs.dm;
	}
};
priority_queue<dt> q;
int dr[] = {1,0,-1,0};
int dc[] = {0,1,0,-1};

void dijk(pii st){
	q.emplace(st.fi, st.se, 1, 0);
	memset(d, 0x3f3f3f3f, sizeof(d));
	d[st.fi][st.se] = {1,0};
	while (!q.empty()){
		dt u = q.top(); q.pop();
		pii D = make_pair(u.dm, u.dk);
		if (D < d[u.r][u.c]) continue;
		for (int i = 0; i < 4; i++){
			pii x = {u.r + dr[i], u.c + dc[i]};
			if (!ins(x.fi, x.se)) continue;
			int dm, dk;
			if (g[x.fi][x.se] == g[u.r][u.c]){
				dk = u.dk + 1; dm = u.dm;
				if (dk == k + 1) dm++, dk = 0;
			} else if (g[x.fi][x.se] == '#'){
				dm = u.dm, dk = 1;
			} else {
				dm = u.dm + 1; dk = 1;
			}
			if (make_pair(dm, dk) < d[x.fi][x.se]){
				d[x.fi][x.se] = {dm, dk};
				q.emplace(x.fi, x.se, dm, dk);
			}
		}
	}
}

