char a[N][N];
int dist[N][N];
int dx[4] = {1, -1, 0, 0};
int dy[4] = {0, 0, 1, -1};

void solve() {
	int n, m, k;
    sc(n, m, k);
    pii p;
    fr(i, 1, n) {
        fr(j, 1, m) {
            sc(a[i][j]);
            if(a[i][j] == 'S') p = {i, j};
            dist[i][j] = 1e9;
        }
    }
    dist[p.fi][p.se] = 0;
    queue<pii> q;
    q.push(p);
    while(!q.empty()) {
        pii u = q.front();
        q.pop();
        if(dist[u.fi][u.se] == k) {
            break;
        }
        fr(kk, 0, 3) {
            pii v = {u.fi + dx[kk], u.se + dy[kk]};
            if(v.fi >= 1 && v.fi <= n && v.se >= 1 && v.se <= m) {
                if(dist[v.fi][v.se] > dist[u.fi][u.se] + 1 && a[v.fi][v.se] != '#') {
                    dist[v.fi][v.se] = dist[u.fi][u.se] + 1;
                    q.push(v);
                }
            }
        }
    }
    int ans = 1e9;
    fr(i, 1, n) {
        fr(j, 1, n) {
            if(dist[i][j] <= k) {
                ans = min({ans, 1 + cdiv(min(n - i, i - 1), k), 1 + cdiv(min(m - j, j - 1), k)});
                if(i == 1 || i == n || j == 1 || j == m) ans = 0;
            }
        }
    }
    cout << ans;
}

