#include<bits/stdc++.h>
using namespace std;

long long H, W, K;

long long A[805][805];
long long WORK[805][805];

#define OPEN INT_MAX
#define CLOSED LONG_MAX/3


bool valid(long long h, long long w){
	return (h >= 0) && (h < H) && (w >= 0) && (w < W);
}

void move(long long h, long long w){
	queue<pair<long long, pair<long long, long long> > >Q;
	Q.push(make_pair(0, make_pair(h, w)));
	while(!Q.empty()){
		long long cost = Q.front().first;
		long long curh = Q.front().second.first;
		long long curw = Q.front().second.second;
		Q.pop();
		if(cost > K){
			break;
		}
		if(valid(curh, curw) == false || A[curh][curw] == CLOSED ||  A[curh][curw] <= cost){
			continue;
		}
		A[curh][curw] = cost;
		Q.push(make_pair(cost + 1, make_pair(curh-1, curw)));
		Q.push(make_pair(cost + 1, make_pair(curh+1, curw)));
		Q.push(make_pair(cost + 1, make_pair(curh, curw-1)));
		Q.push(make_pair(cost + 1, make_pair(curh, curw+1)));
	}
}

