int h,w,k,stx,sty,dist[805][805],x[4]={0,0,1,-1},y[4]={1,-1,0,0},mini=1e9;
char g[805][805];

void ff(int a, int b) {
	if(a==1 || a==h || b==1 || b==w || dist[a][b]>=k) {
		return;
	}
	for(int i=0;i<4;i++) {
		if(g[a+x[i]][b+y[i]]=='.' && dist[a][b]<k) {
			if(dist[a+x[i]][b+y[i]]!=-1) {
				dist[a+x[i]][b+y[i]]=min(dist[a+x[i]][b+y[i]],dist[a][b]+1);
				ff(a+x[i],b+y[i]);
			}
			else {
				dist[a+x[i]][b+y[i]]=dist[a][b]+1;
				ff(a+x[i],b+y[i]);
			}
		}
	}
}

