    		if(g[i][j]=='S') {
    			stx=i;
    			sty=j;
    			if(stx==1 || stx==h || sty==1 || sty==w) {
    				cout<<0<<endl;
    				return 0;
				}
			}
		}
	}
	dist[stx][sty]=0;
	ff(stx,sty);
	for(int i=1;i<=h;i++) {
    	for(int j=1;j<=w;j++) {
    		if(dist[i][j]!=-1) {
    			if(i==1 || i==h || j==1 || j==w) {
    				mini=0;
				}
    			mini=min(mini,(max(0,i-1-1))/k+1);
    			mini=min(mini,(max(0,h-i-1))/k+1);
				mini=min(mini,(max(0,j-1-1))/k+1);
				mini=min(mini,(max(0,w-j-1))/k+1);	
			}
		}
	}
	cout<<mini+1<<endl;
}

