typedef pair<int, int> Pi;
typedef pair<ll, ll> Pl;

#define FST first
#define SND second

#define MAX_H   (800)                  // 10^5
#define MAX_N   (100000)                  // 10^5
#define BASE    (1000000000 + 7)          // 10^9 + 7
#define INFI    (1000000000 + 7)          // 10^9 + 7
#define INFL    (1000000000000000000 + 7) // 10^18 + 7

ll H, W, K;
string MAP[MAX_H];
int DIST[MAX_H][MAX_H];

bool is_inside(int i, int j) {
  return 0 <= i && i < H && 0 <= j && j < W;
}

void solve() {
  int dir[4][2] = {{1, 0}, {0, 1}, {-1, 0}, {0, -1}};

  int r0, c0;
  queue<Pi> q1, q2;
  for (int i = 0; i < H; i++) {
    for (int j = 0; j < W; j++) {
      DIST[i][j] = INFI;
      if (MAP[i][j] == 'S') {
        r0 = i; c0 = j;
        q1.push(Pi(i, j));
        q2.push(Pi(i, j));
        DIST[i][j] = 0;
      }
    }
  }

  while (!q1.empty()) {
    Pi p = q1.front(); q1.pop();
    int r = p.FST, c = p.SND;
    for (int i = 0; i < 4; i++) {
      int rx = r + dir[i][0], cx = c + dir[i][1];
      if (is_inside(rx, cx)) {
        int dist = DIST[r][c] + 1;
        if (MAP[rx][cx] == '.' && dist < DIST[rx][cx] && dist <= K) {
          DIST[rx][cx] = dist;
          q1.push(Pi(rx, cx));
          q2.push(Pi(rx, cx));
        }
      }
    }
  }

  ll mn = INFI;
  while (!q2.empty()) {
    Pi p = q2.front(); q2.pop();
    int r = p.FST, c = p.SND;
    ll vals[4] = {r, c, W - 1 -r, H - 1 - c};
    for (int i = 0; i < 4; i++) mn = min(mn, vals[i]);
  }
  ll ans = (mn + K - 1) / K + 1;
  cout << ans << endl;
}

int main() {
  cin >> H >> W >> K;

  for (int i = 0; i < H; i++) cin >> MAP[i];

  solve();

  return 0;
}

