                    tq.emplace(xx, yy, ck-1);
                }
            }
        }

        while (!q.empty()) {
            int cx, cy, cc;
            tie(cx, cy, cc) = q.front();
            q.pop();

            for (int i = 0; i < 4; ++i) {
                int xx = cx + K * dirx[i], yy = cy + K * diry[i];
                if (xx > 0 && xx < H-1 && yy > 0 && yy < W-1) {
                    q.emplace(xx, yy, cc+1);
                } else {
                    out << cc+1 << "\n";
                    return;
                }
            }
        }
        assert(false);
    }
};


