    REP(i, h) {
        REP(j, w) {
            if (a[i][j] == 'S') {
                si = i;
                sj = j;
            }
        }
    }

    vector<vector<ll>> d(h, vector<ll>(w, INF));
    using pl4 = pair<ll, ll>;
    using tl6 = tuple<ll, ll, ll>;
    auto comp = [&](tl6 i, tl6 j) -> bool {
        return get<2>(i) > get<2>(j);
    };
    priority_queue<tl6, vector<tl6>, decltype(comp)> q(comp);

    d[si][sj] = 0;
    q.push(tl6(si, sj, 0));

    vector<pl4> dx = {
        {-1,  0},
        {+1,  0},
        { 0, -1},
        { 0, +1}
    };

    while (q.size()) {

        ll i = get<0>(q.top());
        ll j = get<1>(q.top());
        ll dij = get<2>(q.top());
        q.pop();
        if (dij != d[i][j]) continue;

        vector<pl4> kimbo; kimbo.reserve(4);
        for (pl4 &v : dx) {
            ll i2 = i + v.first;
            ll j2 = j + v.second;
            if (0 <= i2 && i2 < h && 0 <= j2 && j2 < w) {
                kimbo.emplace_back(i2, j2);
