                if (d[i][j] < k) {
                    cand = (d[i][j] / k + 1) * k + 1;
                } else {
                    cand = d[i][j] + 1;
                }
            }
            if (chmin(d[i2][j2], cand)) {
                q.push(tl6(i2, j2, cand));
            }
        }

    }

    cerr << "\n";
    REP(i, h) REP(j, w) {
        cerr << setw(5) << d[i][j] << " \n"[j==w-1];
    }
    cerr << "\n";

