        chmin(ans, d[i][0]);
        chmin(ans, d[i][w-1]);
    }
    REP(j, w) {
        chmin(ans, d[0][j]);
        chmin(ans, d[h-1][j]);
    }
    cout << (ans + k - 1) / k << endl;

