void bfs(short x, short y)
{
    queue< pair<int, int> > Q;
    Q.push({x, y});
    dist[x][y] = 0;
    visit[x][y] = 1;

    while(Q.size())
    {
        pair<int, int> c = Q.front(); Q.pop();
        int x = c.first;
        int y = c.second;

        for(int i=0; i<n; i++)
        {
