               !visit[x+dx[i]][y+dy[i]] &&
               MP[x+dx[i]][y+dy[i]] != '#')
            {
                visit[x+dx[i]][y+dy[i]] = 1;
                Q.push({x+dx[i], y+dy[i]});
                dist[x+dx[i]][y+dy[i]] = dist[x][y] + 1;
            }
        }
    }
}

