bool valid(int x, int y) {
	if(x < 0 || y < 0 || x == w || y == h || visit[y][x]) return 0;
	return 1;
}

void solve(int x, int y, int step, int k_step, int cast) {
	if(step > ans) return;
	if(x == 0 || y == 0) {
		ans = min(ans, step);
		return;
	}

	for(int i=0; i<4; i++) {
		xx = x+dx[i];
		yy = y+dy[i];
		k_nstep = k_step;
		nstep = step;
		ncast = cast;
		if(valid(xx, yy)) {
			visit[yy][xx] = 1;

			if(s[yy][xx] == '#') {
				if(ncast == -1) nstep += 2;
				if(ncast == 0) {
					k_nstep = 0;
					nstep++;
				}

				ncast = 1;
				if(k_nstep == k) {
					nstep++;
					k_nstep = 0;
				}

				k_nstep++;
			}
			else {
				if(ncast == -1) nstep++;
				cast = 0;
				if(k_nstep == k) {
					nstep++;
					k_nstep = 0;
				}
				k_nstep++;
			}

			solve(xx, yy, nstep, k_nstep, ncast);
			visit[yy][xx] = 0;
		}
	}
	visit[y][x] = 0;
}

