        if((j==0?false:room[i][j-1]!='#')) G[i*H+j].push_back(edge{i*N+(j-1), 1});
        if((i==H-1?false:room[i+1][j]!='#')) G[i*H+j].push_back(edge{(i+1)*N+j, 1});
        if((j==W-1?false:room[i][j+1]!='#')) G[i*H+j].push_back(edge{i*N+(j+1), 1});
      }
    }
  }
  dijkstra(Start.first*N+Start.second);
  for(int i=0;i<H;i++){
