      if(d[i*N+j]<=K) {
        dist = min({dist, i, j, W-j-1, H-1-i});
      }
    }
  }
  ans = 1 + dist/K + (dist%K!=0?1:0);
  std::cout << ans << '\n';
  return 0;
}

