bool lock_h(int l,int r,int x) {
    for (int i=l;i<=r;i++) {
        if (grid[x][i]=='#') return true;
    }
    return false;
}

bool lock_v(int u,int d,int y) {
    for (int i=u;i<=d;i++) {
        if (grid[i][y]=='#') return true;
    }
    return false;
}

int foo(int x,int y) {
    if (x==0||x==h-1||y==0||y==w-1) return 0;
    int res=INF;

    int tmp=(x-1)/k+1;
    if (lock_v(x-(((x-1)%k)+1),x-1,y)) tmp++;
    res=min(res,tmp);

    int xx=h-1-x;
    tmp=(xx-1)/k+1;
    if (lock_v(x+1,x+((xx-1)%k)+1,y)) tmp++;
    res=min(res,tmp);

    tmp=(y-1)/k+1;
    if (lock_h(y-(((y-1)%k)+1),y-1,x)) tmp++;
    res=min(res,tmp);

    int yy=w-1-y;
    tmp=(yy-1)/k+1;
    if (lock_h(y+1,y+((yy-1)%k)+1,x)) tmp++;
    res=min(res,tmp);

    return res;
}

