        chmin(ans,1+divup(min(min(H-1-nx,nx),min(W-1-ny,ny)),K));
        if(depth[nx][ny]==K)continue;
        REP(i,4){
            int x=nx+dx[i];
            int y=ny+dy[i];
            if(x<0||x>=H||y>W||y<0||depth[x][y]!=INF)continue;
            if(maze[x][y]=='#')continue;
            if(x==0||x==H-1||y==0||y==W-1){
                cout<<1<<endl;
                return 0;
            }
            q.push({x,y});  
            depth[x][y]=depth[nx][ny]+1;
        }
    }
    cout<<ans<<endl;
}

