	cout << fixed << setprecision(12);

	ll h, w, k; cin >> h >> w >> k;

	vs A_(h); cin >> A_;
	string A = "";
	rep(i, 0, h) A += A_[i];
	ll N = h * w;
	queue<pll> que, que2;
	vll visited(N);
	auto it = A.find('S');
	visited[it] = true;
	que.push({ it, 0 });
	vll DIR = { 1,-1,w,-w };
	auto in = [&](ll n, ll d) {
		if (n % w == 0 && d == -1)
			return false;
		if (n % w == w - 1 && d == 1) 
			return false;
		if (n / w == 0 && d == -w)
			return false;
		if (n / w == h - 1 && d == w)
			return false;
		return true;
	};

	ll res = INF;
	while(que.size()) {
		auto cur = que.front();
		que2.push({ cur.first, 0 });
		que.pop();
		if (cur.second != k) {
			for (auto d : DIR) {
				if (in(cur.first, d)) {
					ll next = cur.first + d;
					if (A[next] == '.' && !visited[next]) {
						que.push({ next, cur.second + 1 });
						visited[next] = true;
					}
				}
				else {
					chmin(res, 1ll);
				}
			}
		}
	}
	while (que2.size()) {
		auto cur = que2.front();
		que2.pop();
		chmin(res, 1 + ((cur.first) % w -1) / k + 1);
		chmin(res, 1 + ((cur.first) / w - 1) / k + 1);
		chmin(res, 1 + (w-1 - (cur.first) % w - 1) / k + 1);
		chmin(res, 1 + (h-1 - (cur.first) / w - 1) / k + 1);
	}
	cout << res << endl;
	return 0;
}

