		if (a[x-1][y]) b[x-1][y]=min(b[x-1][y],b[x][y]+1),q.push(make_pair(x-1,y));
		if (a[x][y+1]) b[x][y+1]=min(b[x][y+1],b[x][y]+1),q.push(make_pair(x,y+1));
		if (a[x][y-1]) b[x][y-1]=min(b[x][y-1],b[x][y]+1),q.push(make_pair(x,y-1));
	}
	for (i=1;i<=n;i++) {
		for (j=1;j<=m;j++) {
			if (!a[i][j]) continue;
			int tt=b[i][j];
			if (b[i][j]<=k) tt=k;
			int w=min(min(i-1,j-1),min(n-i,m-j));
			tt+=w;
			tt=(tt-1)/k+1;
			if (tt<ans) ans=tt;
		}
	}
	printf("%d\n",ans);
	return 0;
}
