void bfs(int r, int c, int walk) {
  REP(i, H) REP(j, W) memo[i][j] = INF;
  memo[r][c] = 0;
  queue<int> q;
  q.push(r); q.push(c);
  while (q.size() > 0) {
    r = q.front(); q.pop();
    c = q.front(); q.pop();
    if (memo[r][c] == walk) break;
    for (int i = 0; i < 4; i++) {
      int nr = r + dr[i];
      int nc = c + dc[i];
      if (0 <= nr && nr < H && 0 <= nc && nc < W && s[nr][nc] == '.' && memo[nr][nc] == INF) {
        memo[nr][nc] = memo[r][c] + 1;
        q.push(nr);
        q.push(nc);
      }
    }
  }
}

int ceil(int r, int x) {
