int f(int r, int c) {
  if (r == 0 || c == 0 || r == H - 1 || c == W - 1) return 0;
  return min({
    ceil(r, K),
    ceil(H - 1 - r, K),
    ceil(c, K),
    ceil(W - 1 - c, K)});
}

