struct point {
  int x, y;
};

void solve(int H, int W, int K, std::vector<std::string> A) {
  vector<vl> dp(H, vl(W, -1));

  queue<point> q;
  rep(i, 0, H) {
    rep(j, 0, W) {
      if (A[i][j] == 'S') {
        q.push((point){i, j});
      }
    }
  }

  // K回までで移動できるところに移動
  vector<point> next;
  int cnt = 1;
  while (!q.empty()) {
    point p = q.front();
    q.pop();

    if (A[p.x][p.y] == '#') {
      continue;
    }

    if (dp[p.x][p.y] == -1) {
      next.push_back(p);
      dp[p.x][p.y] = cnt;

      rep(k, 0, 4) {
        int nx = p.x + dx[k];
        int ny = p.y + dy[k];

        if (nx >= 0 && nx < H && ny >= 0 && ny < W && dp[nx][ny] == -1) {
          q.push((point){nx, ny});
        }
      }
    }
  }

  // そこから端までの最小距離を求める
  int ans = INF;
  rep(i, 0, H) {
    rep(j, 0, W) {
      if (dp[i][j] == 1) {
        chmin(ans, i);
        chmin(ans, j);
        chmin(ans, W - i - 1);
        chmin(ans, H - j - 1);
      }
    }
  }
  print((ans + K - 1) / K + 1);
}

