	const int inf = 1e9;

	vvi D(h, vi (w, inf));

	{
		queue<pii> q;
		D[sy][sx] = 0;
		q.emplace(sy, sx);

		while (!q.empty()) {
			int y, x;
			tie(y, x) = q.front();
			q.pop();

			int nd = D[y][x] + 1;

			rep(dir, 4) {
				int ny = y + DY4[dir];
				int nx = x + DX4[dir];
				if (!inside(ny, nx, h, w)) continue;
				if (M[ny][nx] == '#') continue;
				if (D[ny][nx] > nd) {
					D[ny][nx] = nd;
					q.emplace(ny, nx);
				}
			}
		}
	}

	int ans = inf;

	rep(y, h) rep(x, w) {
		int d = D[y][x];
		if (d <= k) {
			int lef = x;
			int rig = w - x - 1;
			int top = y;
			int bot = h - y - 1;
			int mid = (min({lef, rig, top, bot}) + k - 1) / k;
			amin(ans, mid + 1);

			out(y, x, D[y][x]);
			out(lef, rig, top, bot, mid);
		}
	}
	return ans;
}

