int main(void) {
    REP(i, MAX) REP(j, MAX)REP(k, 2)REP(l, 2) minCost[i][j][k][l] = INF;
    scanf("%d%d%d", &H, &W, &K);
    PII start;
    REP(i, H) {
        A[i] = next();
        assert(A[i].length() == W);
        REP(j, W) {
            if (A[i][j] == 'S') {
                start = MP(i, j);
            }
        }
    }
    priority_queue<tuple<int, PII, int, int>, VT<tuple<int, PII, int, int>>, greater<tuple<int, PII, int, int>>> pq;
    // (cost, point, 動ける数, 開けられる数)
    pq.push(MT(0, start, 0, 0));
    while (!pq.empty()) {
        PII nowPoint;
        int nowCost, canMove, canOpen;
        tie(nowCost, nowPoint, canMove, canOpen) = pq.top(); pq.pop();
        if (minCost[nowPoint.first][nowPoint.second][canMove != 0][canOpen!= 0] <= nowCost) {
            continue;
        }
        //cerr << nowPoint.first << " " << nowPoint.second << " " << nowCost << " " << canMove << " " << canOpen << endl;
        chmin(minCost[nowPoint.first][nowPoint.second][canMove != 0][canOpen!= 0], nowCost);
        REP(i, 4) {
            PII nextPoint = MP(nowPoint.first + dh[i], nowPoint.second + dw[i]);
            if (!inside(nextPoint)) {
                continue;
            }
            if (A[nextPoint.first][nextPoint.second] == '#') {
                if (canOpen == 0) {
                    if (canMove == 0) {
                        pq.push(MT(nowCost + 2, nextPoint, K - 1, K + K - 1));
                    } else {
                        pq.push(MT(nowCost + 1, nextPoint, K - 1, K - 1));
                    }
                } else {
                    if (canMove == 0) {
                        pq.push(MT(nowCost + 1, nextPoint, K - 1, canOpen + K - 1));
                    } else {
                        pq.push(MT(nowCost, nextPoint, canMove - 1, canOpen - 1));
                    }
                }
            } else {
                if (canMove == 0) pq.push(MT(nowCost + 1, nextPoint, K - 1, canOpen + K));
                else pq.push(MT(nowCost, nextPoint, canMove - 1, canOpen));
            }
        }
    }
    int ans = INF;
    REP(i, H) {
        if (i == 0 || i == H - 1) {
            REP(j, W) {
                REP(k, 2)REP(l, 2)chmin(ans, minCost[i][j][k][l]);
            }
        } else {
            REP(k, 2)REP(l, 2) {
                chmin(ans, minCost[i][0][k][l]);
                chmin(ans, minCost[i][W - 1][k][l]);
            }
        }
    }
    // REP(i, H) REP(j, W) {
