            q.push({cnt+1, {K, now}});
        }
        else if(cnt == 1){
            bool updated = false;
            rep(i, 4){
                ll nh = now.ff + dh[i], nw = now.ss + dw[i];
                if(bok(nh, nw) && A[nh][nw] == '.' && cost[nh][nw] == LINF){
                    cost[nh][nw] = cnt;
                    q.push({cnt, {rem-1, {nh,nw}}});
                    updated = true;
                }
            }
            if(!updated) q.push({cnt, {0, now}});
        }
        else{
            rep(i, 4){
                ll nh = now.ff + dh[i], nw = now.ss + dw[i];
                if(bok(nh, nw) && cost[nh][nw] == LINF){
                    cost[nh][nw] = cnt;
                    q.push({cnt, {rem-1, {nh,nw}}});
                }
            }
        }
    }

    ll ans = LINF;
    rep(i, W){
        chmin(ans, cost[0][i]); chmin(ans, cost[H-1][i]);
    }
    rep(i, H){
        chmin(ans, cost[i][0]); chmin(ans, cost[i][W-1]);
    }
    cout << ans << endstr;
    return 0;
}

