int bfs(vector<vector<char>> &grid){
    priority_queue<pnt,vector<pnt>,greater<pnt>> que;
    que.push({sy,sx,1,0});
    while((int)que.size()>0){
        pnt now=que.top();
        que.pop();

        if(dist[now.y][now.x]<MOD){
            if(now.cnt>0){
                continue;
            }
        }else{
            dist[now.y][now.x]=now.cost;
        }
        if(now.y==0 || now.y==H-1 || now.x==0 || now.x==W-1){
            return now.cost;
        }else if(now.cnt==K){
            now.cost++;
            now.cnt=0;
