        for(auto &m:mv){
            int nx,ny;
            nx=now.x+m[1];
            ny=now.y+m[0];

            if(grid[ny][nx]=='#' && now.cost==1){
                continue;
            }else{
                que.push({ny,nx,now.cost,now.cnt+1});
            }
        }
        if(now.cost==1){
            que.push({now.y,now.x,now.cost+1,0});
        }
    }
}

