int n,m,k,dist[NMAX][NMAX], viz[NMAX][NMAX],answer = INF;
int dx[4] = {-1,0,1,0};
int dy[4] = {0,1,0,-1};
pair<int,int> stiva[NMAX * NMAX], start;
char s[NMAX][NMAX];

inline bool outOfMatrix(pair<int, int> poz) {
    return (poz.x < 1 || poz.x > n || poz.y < 1 || poz.y > m);
}

void bfs(pair<int,int> start) {
    int left = 1, right = 0;;

    stiva[right = 1] = start;
    viz[start.x][start.y] = 1;
    for(int i = 1; i <= n; i++)
        for(int j = 1; j <= m; j++)
            dist[i][j] = INF;
    dist[start.x][start.y] = 0;

    while(left <= right) {
        pair<int, int> currPoz = stiva[left];
        for(int dir = 0; dir < 4; dir++) {
            pair<int,int> nextPoz = make_pair(currPoz.x + dx[dir], currPoz.y + dy[dir]);
            if(viz[nextPoz.x][nextPoz.y] || outOfMatrix(nextPoz) || s[nextPoz.x][nextPoz.y] == '#')
                continue;
            viz[nextPoz.x][nextPoz.y] = 1;
            dist[nextPoz.x][nextPoz.y] = dist[currPoz.x][currPoz.y] + 1;
            stiva[++right] = nextPoz;
        }
        left++;
    }
}

int getCost(int px, int py) {
    int D = min(px - 1, min(py - 1, min(n - px, m - py)));
    return D / k + (D % k == 0 ? 0 : 1);
}

