        printf("0\n");
        return 0;
    }

    bfs(start);

    for(int i = 1; i <= n; i++)
        for(int j = 1; j <= m; j++)
            if(dist[i][j] <= k) {
            //    printf("%d %d\n", i,j);
                answer = min(answer, getCost(i,j) + 1);
            }

    printf("%d\n", answer);

    return 0;
}

