bool magic(ll y, ll x, ll steps) {

	if(grid[y][x] == '#') return 0;
	if(y == 0 || x == 0 || y == h-1 || x == w-1) return 1;

	if(vis[y][x]) return 0;
	vis[y][x] = 1;

	if(steps == 0) return 0;

	return magic(y-1, x, steps-1) || magic(y+1, x, steps-1) || magic(y, x-1, steps-1) ||magic(y, x+1, steps-1);

}

