using namespace std;
typedef long long ll;
typedef pair<int,int> P;
typedef pair<int,P> PP;
int h,w;
string mp[N];

struct dat{
  int y,x,K1,K2,cost;
  bool operator < (const dat &A)const{
    if(A.K2!=K2) return K2>A.K2;
    return K1>A.K1;
  }
};

int dx[] ={0,0,1,-1};
int dy[] ={1,-1,0,0};
PP D[N][N];
int bfs(int y,int x,int sK){

  for(int i=0;i<N;i++)
    for(int j=0;j<N;j++) D[i][j] = PP(1e9,P(1e9,1e9));

  priority_queue<dat>Q;
  Q.push((dat){y,x,sK,0,1});  
  D[y][x] = PP(sK,P(0,sK));
  int res = 1e9;
  while(!Q.empty()){
    dat t = Q.top();Q.pop();
    y = t.y;
    x = t.x;
    int K1 = t.K1;
    int K2 = t.K2;
    int cost = t.cost;
    if(D[y][x] < PP(cost,P(K2,K1)))continue;
    // cout<<y<<" "<<x<<" "<<K1<<" "<<K2<<" "<<cost<<endl;

    for(int i=0;i<4;i++){
      int nx = x+dx[i];
      int ny = y+dy[i];
      int nK1 = K1-1;
      int nK2 = K2;
      int ncost = cost;
      if(nx<0||ny<0||nx>=w||ny>=h){return cost-(cost>2);}
      if(nK1 <  0) ncost++,nK1 = sK-1,nK2 += sK;
      if(mp[ny][nx] == '#') nK2--;
      if(nK2<0) nK1 = nK2 = sK-1,ncost+=2;
      PP tmp = PP(ncost,P(nK2,nK1));
      if(D[ny][nx]<= tmp)continue;
      Q.push((dat){ny,nx,nK1,nK2,ncost});
      D[ny][nx] = tmp;
    }      
  }
  if(res>2) res--;
  return res;
}

