void dfs(int a,int b,int len)
{
	int t=min(min(a,b),min(h-a,w-b));
	int res;
	if(t) res=(t-1)/k+1+1;
	else res=len;
	if(res<ans) ans=res;

	if(len==k) return;

	for(int i=0;i<4;i++)
	{
		int x=a+d1[i],y=b+d2[i];
		if(x<0||x>=h||y<0||y>=w) continue; 
		if(mp[x][y]=='#') continue;
		if(visit[x][y]) continue;
		visit[x][y]=1;
		dfs(x,y,len+1); 
	}
} 

