const int N = 800 + 10;
const int DX[4] = {0, 1, 0, -1};
const int DY[4] = {1, 0, -1, 0};
int n, m, k;
char S[N][N];
int d[N][N];

int main() {
#ifdef LOCAL
    freopen("inp", "r", stdin);
    freopen("out", "w", stdout);
#endif
    scanf("%d%d%d", &n, &m, &k);
    for (int i = 1; i <= n; ++i) scanf("%s", S[i] + 1);

    int sx = -1, sy = -1;
    for (int i = 1; i <= n; ++i) for (int j = 1; j <= m; ++j) if (S[i][j] == 'S') {
        sx = i;
        sy = j;
        break;
    }

    queue<II> Q; Q.push(II(sx, sy));
    for (int i = 1; i <= n; ++i)
        for (int j = 1; j <= m; ++j)
            d[i][j] = -1;
    d[sx][sy] = 0;
    while (Q.size()) {
        int x = Q.front().first;
        int y = Q.front().second;
        Q.pop();
        if (x == 1 || x == n || y == 1 || y == m) {
            puts("1");
            return 0;
        }
        if (d[x][y] >= k) continue;
        for (int t = 0; t < 4; ++t) {
            int u = x + DX[t];
            int v = y + DY[t];
            if (1 <= u && u <= n && 1 <= v && v <= m) {
                if (d[u][v] != -1 || S[u][v] == '#') continue;
                d[u][v] = d[x][y] + 1;
                Q.push(II(u, v));
            }
        }
    }

    int ans = 1e9;
    for (int i = 1; i <= n; ++i) for (int j = 1; j <= m; ++j) if (d[i][j] != -1) {
        int f = min(min(i - 1, j - 1), min(n - i, m - j));
        ans = min(ans, (f + k - 1) / k + 1);
    }
    printf("%d", ans);
    return 0;
}

