	int cur_ans=x-1;
	cur_ans=min(cur_ans,y-1);
	cur_ans=min(cur_ans,r-x);
	cur_ans=min(cur_ans,c-y);
	ans=min(ans,cur_ans);
	visited[x][y]=true;
	if (step==k) return;
	int xx,yy,i;
	for (i=1;i<=4;i++)
	{
		xx=x+movee[i][1];yy=y+movee[i][2];
		if (xx<1 || xx>r || yy<1 || yy>c) continue;
		if (a[xx][yy]==1 || visited[xx][yy]) continue;
		dfs(xx,yy,step+1);
	}
}

int main ()
{
	ios::sync_with_stdio(false);
	int i,j;
	movee[1][1]=1;movee[1][2]=0;
	movee[2][1]=0;movee[2][2]=1;
	movee[3][1]=-1;movee[3][2]=0;
	movee[4][1]=0;movee[4][2]=-1;
	cin>>r>>c>>k;
	for (i=1;i<=r;i++)
	{
		cin>>s;
		for (j=1;j<=c;j++)
		{
			if (s[j-1]=='#') a[i][j]=1;
			if (s[j-1]=='.') a[i][j]=2;
			if (s[j-1]=='S')
			{
				sx=i;sy=j;
				a[i][j]=2;
			}
		}
	}
	dfs(sx,sy,0);
	int fans=1+(ans+k-1)/k;
	cout<<fans<<endl;
	return 0;
}

