    std::vector<std::string> board(h);
    std::vector<std::vector<int>> g(h * w);
    constexpr int inf = 1000000000;
    std::vector<int> dist(h * w, inf);
    for (int i = 0; i < h; i++) std::cin >> board[i];

    std::deque<int> q;
    for (int i = 0; i < h; i++) for (int j = 0; j < w; j++) {
        int index = i * w + j;
        if (board[i][j] == 'S') {
            q.push_back(index);
            dist[index] = 0;
        }
        if (i > 0) g[index].push_back((i - 1) * w + j);
        if (i + 1 < h) g[index].push_back((i + 1) * w + j);
        if (j > 0) g[index].push_back(i * w + j - 1);
        if (j + 1 < w) g[index].push_back(i * w + j + 1);
    }

    while (!q.empty()) {
        int v = q.front();
        q.pop_front();
        for (int to : g[v]) {
            if (board[to / w][to % w] == '#') continue;
            if (dist[to] > dist[v] + 1) {
                dist[to] = dist[v] + 1;
                q.push_back(to);
            }
        }
    }

    std::vector<int> d(h * w, inf);
    for (int i = 0; i < h * w; i++) if (dist[i] <= k) {
        d[i] = 0;
        q.push_back(i);
    }

    while (!q.empty()) {
        int v = q.front();
        q.pop_front();
        for (int to : g[v]) {
            if (d[to] > d[v] + 1) {
                d[to] = d[v] + 1;
                q.push_back(to);
            }
        }
    }

    int ret = inf;
    for (int i = 0; i < w; i++) ret = std::min({ ret, d[i], d[h * w - 1 - i] });
    for (int i = 0; i < h; i++) ret = std::min({ ret, d[i * w], d[i * w + w - 1] });

    std::cout << (ret + k - 1) / k + 1 << std::endl;

    return 0;
}

