using namespace std;

#define sz(x) (int)(x.size())
#define rep(i, a, b) for(int i=a;i<b;++i)
#define per(i, a, b) for(int i=b-1;i>=a;--i)
#define pb push_back
#define mp make_pair
typedef long long ll;
typedef pair<ll, ll> pll;
typedef pair<int, int> pii;

////////////////

int const H = 841;
int const W = 841;
int const INF = 1e9 + 41;

int h, w, k;
int ma[H][W], d[H][W], was[H][W], f[H][W];
int sx, sy;
int dx[4] = {0, 1, 0, -1};
int dy[4] = {-1, 0, 1, 0};

deque<pii> q;

bool canMove(int ny, int nx){
	if(ny >= h || ny < 0) return false;
	if(nx >= w || nx < 0) return false;
	if(ma[ny][nx] == 1) return false;
	return true;
}

int calc(int y, int x){
	int ret = min(x, y) / k + (min(x, y) % k != 0 ? 1 : 0);
	return ret;
}

void solve(){
	cin >> h >> w >> k;
	k = min(k, max(h, w));
	rep(i, 0, h){
		string s;
		cin >> s;
		rep(j, 0, w){
			if(s[j] == '.'){
				ma[i][j] = 0;
			}else if(s[j] == '#'){
				ma[i][j] = 1;
			}else{
				sy = i;
				sx = j;
			}
		}
	}

	rep(i, 0, h) rep(j, 0, w) d[i][j] = INF;
	d[sy][sx] = 0;
	q.pb(mp(sy, sx));
	was[sy][sx] = 1;

	while(sz(q)){
		pii cur = q.front();
		q.pop_front();
		int x = cur.second;
		int y = cur.first;
		if(d[y][x] == k) continue;
		rep(i, 0, 4){
			int nx = x + dx[i];
			int ny = y + dy[i];
			if(canMove(ny, nx) && !was[ny][nx]){
				d[ny][nx] = 1 + d[y][x];
				was[ny][nx] = 1;
				q.pb(mp(ny, nx));
			}
		}
	}

	int ans = INF;

	rep(i, 0, h) rep(j, 0, w) if(was[i][j]){
		ans = min(ans, 1 + calc(i, j));
	}

	cout << ans << endl;

}

int main(){
#ifdef _DEBUG
	freopen("input.txt","r",stdin);
	freopen("output.txt","w",stdout);
#endif

	solve();

	return 0;
}

