                        que.push(make_pair(make_pair(abs((xy.first-nx)*k), abs((xy.second-ny)*k)), make_pair(make_pair(turn,k), tile)));
                    else
                        que.push(make_pair(make_pair(nx, ny), make_pair(make_pair(turn,cnt), tile)));
                }
                else {
                    if(field[nx][ny]=='.')
                        que.push(make_pair(make_pair(nx, ny), make_pair(make_pair(turn, cnt+1), tile)));
                }
            }
        }
        if(que.empty()) {
