queue< pair<int, int> > que;

char c[H][W];//入力値保存用の配列('S', '#', '.')が格納される
ll d[H][W];//開始地点からの距離を格納する配列

int main() {
    int h, w;
    ll k, ans;
    scanf("%d %d %d", &h, &w, &k);

    for (int i = 0; i < w; i++) {
        for (int j = 0; j < h; j++) {
            d[i][j] = INF;//距離を無限大に初期化
        }
    }

    for (int i = 0; i < h; i++) {
        scanf("\n");
        for (int j = 0; j < w; j++) {
            scanf("%c", &c[j][i]);
            if (c[j][i]=='S') {
                d[j][i] = 0;
                que.push(pair<int, int>(j, i));//初期位置をキューに追加
            }
        }
    }

    while (!que.empty()) {
        int x, y;
        int x1, y1;
        ll a;
        tie(x, y) = que.front();
        a = d[x][y];
        que.pop();

        for (ll i = 0; i < 4; i++) {//4方向探索
            x1 = x + dx[i];
            y1 = y + dy[i];
            if (x1 >= w | y1 >= h) continue;//端を処理しない
            if (x1 < 0 | y1 < 0) continue;//端を処理しない
            if (k <= a) break;//距離がk以上で探索終了
            if (c[x1][y1] == '.') {
                if (d[x1][y1] == INF) {//初期発見
                    d[x1][y1] = a + 1;//距離を格納
                    que.push(pair<int, int>(x1, y1));//キューに発見個所を追加
                }
            }
        }
    }

    ll dis;//端までの距離
    ll out = INF;//最も端に近い位置
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (d[j][i] != INF) {
                dis = min(min(i, j), min((h-i-1), (w-j-1)));
                if (k >= d[j][i] & out > dis) {
                    out = dis;
                }
            }
        }
    }


    ans = 1;
    while(1) {
        if (out <= 0) {
            printf("%d\n", ans);
            return 0;
        }
        out -= k;//操作をするごとに端までの距離がK縮まる
        ans++ ;
    }
}

