    chmin(D,x);
    chmin(D,W-1-x);
    chmin(D,y);
    chmin(D,H-y-1);
    if(d==K)return;
    if(check==0){
        if(grid[x-1][y]=='.') dfs(x-1,y,d+1,grid,1);
        if(grid[x+1][y]=='.') dfs(x+1,y,d+1,grid,3);
        if(grid[x][y-1]=='.') dfs(x,y-1,d+1,grid,4);
        if(grid[x][y+1]=='.') dfs(x,y+1,d+1,grid,2);
    }else if(check==1){
        if(x-1>=0&&grid[x-1][y]=='.') dfs(x-1,y,d+1,grid,check);
        if(y-1>=0&&grid[x][y-1]=='.') dfs(x,y-1,d+1,grid,check);
    }else if(check==2){
        if(x-1>=0&&grid[x-1][y]=='.') dfs(x-1,y,d+1,grid,check);
        if(y+1<H&&grid[x][y+1]=='.') dfs(x,y+1,d+1,grid,check);
    }else if(check==3){
        if(x+1<W&&grid[x+1][y]=='.') dfs(x+1,y,d+1,grid,check);
        if(y+1<H&&grid[x][y+1]=='.') dfs(x,y+1,d+1,grid,check);
    }else if(check==4){
        if(x+1<W&&grid[x+1][y]=='.') dfs(x+1,y,d+1,grid,check);
        if(y-1>=0&&grid[x][y-1]=='.') dfs(x,y-1,d+1,grid,check);
