      if( ni >= 0 && ni < H && nj >= 0 && nj < W && A[ni][nj] != '#' && !used[ni][nj] )
        que.push( St( P( ni, nj ), dist+1 ) ), upd = true;
    }

    if( !upd )
    {
      que2.push( St2( St( P( i, j ), 0 ), (dist+K-1)/K ) );
    }
  }

  return;
}

void bfs2()
{
  while( !que2.empty() )
  {
    St2 st = que2.front(); que2.pop();
    ll i = st.first.first.first, j = st.first.first.second, dist = st.first.second, org = st.second;

    //std::cout << i << ' ' << j << ' ' << dist << std::endl;

    if( !i || !j || i == H-1 || j == W-1 )
    {
      chmin( ans, org+(dist+K-1)/K );

      break;
    }

    rep( d, 4 )
    {
      ll ni = i+di[d], nj = j+dj[d];

      if( ni >= 0 && ni < H && nj >= 0 && nj < W && !used[ni][nj] )
        que2.push( St2( St( P( ni, nj ), dist+1 ), org ) );
    }
  }

  return;
}

