const ll MOD = 1000000007;

const int dx[] = {0, 1, 0, -1, 0}, dy[] = {0, 0, -1, 0, 1};
int H,W,K;
const int MAX_HW = 810;
const int MAX_K = MAX_HW * MAX_HW;
char board[MAX_HW][MAX_HW];
bool visited[MAX_HW][MAX_HW][MAX_HW / 2];
int sy,sx;
int main() {
  cin >> H >> W >> K;
  for (int i = 0; i < H; i++){
    for (int j = 0; j < W; j++){
      cin >> board[i][j];
      if (board[i][j] == 'S'){
        sy = i;
        sx = j;
      }
    }
  }
  queue<pair<pii, pii>> que;//(py,px),(cnt,rest)
  que.emplace(mp(mp(sy, sx), mp(0, 0)));
  int result = 1 << 30;
  while (not que.empty()){
    auto p = que.front();
    que.pop();
    auto pos = p.first;
    auto state = p.second;
    int py,px;
    py = pos.first;
    px = pos.second;

    int cost,rest;
    cost = state.first;
    rest = state.second;

    if (visited[py][px][rest])continue;
    visited[py][px][rest] = true;
    //goal
    if (py == 0 or py == H - 1 or px == 0 or px == W - 1){
      result = min(result, cost);
      continue;
    }
    int ny,nx;
    for (int i = 0; i < 5; i++){
      ny = py + dy[i];
      nx = px + dx[i];
      int n_rest = rest;
      int n_cost = cost + 1;
      if (board[ny][nx] == '#'){
        n_rest--;
      }
      if (n_rest < 0)continue;
      if (n_cost > 0 and n_cost % K == 0){
        n_rest = n_rest + K;
        n_rest = min(n_rest, MAX_HW / 2);
      }
      que.emplace(mp(mp(ny, nx), mp(n_cost, n_rest)));
    }
    que.emplace(mp(mp(py, px), mp(cost + K, min(rest+K, MAX_HW / 2))));
  }
  cout << (result + K - 1) / K << endl;
  return 0;
}

