ll check(ll y, ll x, ll h, ll w, ll k) {
    ll l = (x + k - 1) / k;
    ll u = (y + k - 1) / k;
    ll r = (w - x - 1 + k - 1) / k;
    ll d = (h - y - 1 + k - 1) / k;

    return min({l, u, r, d});

}

