void dfs(pii croom, int lefts) {
	if (lefts < 0) return;
	if (vis[croom.first][croom.second]) {
		return;
	} else {
		vis[croom.first][croom.second] = true;
		Q.push(croom);
	}
	for (int i = 0; i < 4; i++) {
