    REP (h, H) {
        string a;
        cin >> a;
        REP (w, W) {
            if (a[w] == 'S') {
                sx = w;
                sy = h;
            } else if (a[w] == '#') {
                f[h][w] = true;
            }
        }
    }
    cout << solve() << endl;
}

