int H, W, K;
string S[800];
int si, sj;

int Dist(int i,int j) {
	return min({ i, j, H - i - 1, W - j - 1 });
}

int di[] = { 0,1,0,-1 };
int dj[] = { 1,0,-1,0 };

int dist[800][800];
int BFS(int si, int sj) {
	int ret = Dist(si, sj);

	queue<PP> Q;
	Q.push(PP(si, sj));
	Fill(dist, INF);
	dist[si][sj] = 0;
	while (!Q.empty()) {
		PP p = Q.front(); Q.pop();
		int i = p.first;
		int j = p.second;
		if (S[i][j] == '#') continue;
		if (dist[i][j] > K) continue;
		ret = min(ret, Dist(i, j));

		REP(k, 0, 4) {
			int p = i + di[k];
			int q = j + dj[k];
			if (!Inside(p, q, H, W)) continue;
			if (dist[i][j] + 1 > dist[p][q]) continue;
			dist[p][q] = dist[i][j] + 1;
			Q.push(PP(p, q));
		}
	}
	return ret;
}

int main() {
	cin >> H >> W >> K;
	REP(i, 0, H) {
		cin >> S[i];
		REP(j, 0, W) {
			if (S[i][j] == 'S') {
				si = i;
				sj = j;
			}
		}
	}

	int dist = BFS(si, sj);
	cout << 1 + (dist + K - 1) / K << endl;
	return 0;
}

