            if (s[j] == 'S')start = {i, j};
        }
    }

    queue<pos> que;
    que.push(start), que.push({-1, -1});
    int dis = 1;
    int ret = 1145141919;
    while (dis <= k) {
        pos now = que.front();
        que.pop();
        if (now.x < 0) {
            dis++;
            que.push({-1, -1});
        } else {
            int cost = (calc(now) + k - 1) / k;
            ret = min(ret, 1 + cost);

            for (auto move:moves) {
                pos next = {now.x + move.x, now.y + move.y};
                if (inRange(next) && !isWall[next.x][next.y]) {
                    isWall[next.x][next.y] = true;
                    que.push(next);
                }
            }
        }
    }

    cout << ret << endl;
    return 0;
}

