const int dx[] = {0, 1, 0, -1, 0}, dy[] = {0, 0, -1, 0, 1};
int H,W,K;
const int MAX_HW = 810;
const int MAX_K = MAX_HW * MAX_HW;
char board[MAX_HW][MAX_HW];
bool visited[MAX_HW][MAX_HW][MAX_HW];
int sy,sx;
int main() {
  cin >> H >> W >> K;
  for (int i = 0; i < H; i++){
    for (int j = 0; j < W; j++){
      cin >> board[i][j];
      if (board[i][j] == 'S'){
        sy = i;
        sx = j;
      }
    }
  }
