  int result = 1 << 30;
  while (not que.empty()){
    auto p = que.front();
    que.pop();
    auto pos = p.first;
    auto state = p.second;
    int py,px;
    py = pos.first;
    px = pos.second;

    int cost,rest;
    cost = state.first;
    rest = state.second;

    if (visited[py][px][rest])continue;
    visited[py][px][rest] = true;
    //goal
    if (py == 0 or py == H - 1 or px == 0 or px == W - 1){
      result = min(result, cost);
      continue;
    }
    int ny,nx;
    for (int i = 0; i < 5; i++){
      ny = py + dy[i];
      nx = px + dx[i];
      int n_rest = rest;
      int n_cost = cost + 1;
      if (board[ny][nx] == '#'){
        n_rest--;
      }
      if (n_rest < 0)continue;
      if (n_cost > 0 and n_cost % K == 0){
        n_rest = n_rest + K;
        n_rest = min(n_rest, 800);
      }
      que.emplace(mp(mp(ny, nx), mp(n_cost, n_rest)));
    }
    que.emplace(mp(mp(py, px), mp(cost + K, min(rest+K, 800))));
  }
  cout << (result + K - 1) / K << endl;
  return 0;
}

