private:
    double TIME;

    static const ll INF = static_cast<ll>(1e9) + 7;
    static const int MAXN = static_cast<ll>(1e6) + 17;
    const int MAGIC = 62;

    int n, m, k;
    vector<string> s;

public:
    static bool FLAG;

    solver() {
        TIME = static_cast<double>(clock()) / CLOCKS_PER_SEC;
    }

    bool read() {
        if (!(cin >> n >> m >> k))
            return false;

        s.resize(n);

        forn (i, n)
            cin >> s[i];

        return true;
    }

    bool valid(int i, int j) {
        return 0 <= i && i < n && 0 <= j && j < m;
    }

    void solve() {
        vector< pair<int, int> > dd = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
        int I, J;

        forn (i, n)
            forn (j, m)
                if (s[i][j] == 'S')
                    I = i, J = j;

        int inf = INF;
        vector< vector<int> > D(n, vector<int>(m, inf));
        std::queue< pair<int, int> > Q;
        D[I][J] = 0;
        Q.push(std::make_pair(I, J));

        while (!Q.empty()) {
            I = Q.front().first;
            J = Q.front().second;
            Q.pop();

            for (auto d : dd)
                if (valid(I + d.first, J + d.second)) {
                    int i = I + d.first;
                    int j = J + d.second;

                    if (D[i][j] != inf || s[i][j] == '#')
                        continue;

                    D[i][j] = D[I][J] + 1;
                    Q.push(std::make_pair(i, j));
                }
        }

        int ans = inf;

        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (D[i][j] != inf) {
                    int t = min({i, j, n - i - 1, m - j - 1});
                    ans = min(ans, D[i][j] / k + 1 + (t + k - 1) / k);
                }

        cout << ans << endl;
    }

    ~solver() {
#ifdef SEREZHKA
        if (FLAG)
            cerr << "Time elapsed: " << static_cast<double>(clock()) / CLOCKS_PER_SEC - TIME << endl;
#endif
    }
};

