i32 solve(i32 fx, i32 fy, i32 tx, i32 ty) {
    bool fp[800][800] = {};
    set<tuple<i32, i32, i32>> s;
    vec<pair<i32, i32>> v;
    s.insert(make_tuple(0, fy, fx));
    while (s.size() > 0) {
        i32 d, y, x;
        tie(d, y, x) = *s.begin();
        s.erase(s.begin());
        if (fp[y][x]) {
            continue;
        }
        v.append(make_pair(y, x));
        fp[y][x] = true;
        if (d >= k) {
            continue;
        }
        times(4, i) {
            i32 nx, ny;
            nx = x + ox[i];
            ny = y + oy[i];
            if (0 <= nx && nx < w && 0 <= ny && ny < h) {
                if (a[ny][nx] && !fp[ny][nx]) {
                    s.insert(make_tuple(d+1, ny, nx));
                }
            }
        }
    }
    i32 ans = INT_MAX;
    times(v.size(), i) {
        i32 d = abs(v[i].second - ty) + abs(v[i].first - tx);
        if ((d % k) == 0) {
            ans = min(ans, d / k + 1);
        }
        else {
            ans = min(ans, d / k + 2);
        }
    }
    return ans;
}

