void dfs(int x,int y,int k){
	if(x<=0||y<=0||x>n||y>m||k>K||a[x][y]=='#'||vis[x][y])return;
	vis[x][y]=1;
	dfs(x-1,y,k+1);
	dfs(x+1,y,k+1);
	dfs(x,y-1,k+1);
	dfs(x,y+1,k+1);
}

int Q(int x,int y){
	return min(min(x-1,y-1),min(n-x,m-y));
}

