	if(a>=0&&a<n&&b>=0&&b<m&&c[a][b]!='#'){
		return true;
	}
	return false;
}
int minidis(int a,int b){
	int cnt=a;
	cnt=min(min(b,n-1-a),m-1-b);
	return cnt;
}
