  rep(i, h)cin >> s[i];
  int sx = 0, sy = 0;
  rep(i, h)rep(j, w)if(s[i][j] == 'S')sx = i, sy = j;
  priority_queue<state> pq;
  rep(i, h)rep(j, w)dis[i][j] = inf;
  dis[sx][sy] = 1;
  pq.push(state(sx, sy, 1, 1));
  while(!pq.empty()){
    auto p = pq.top(); pq.pop();
    if(dis[p.i][p.j] < p.m)continue;
    rep(l, 4){
      int nx = p.i + dx[l];
      int ny = p.j + dy[l];
      if(nx >= 0 && nx < h && ny >= 0 && ny < w){
        if(s[nx][ny] != '#'){
          state s = state(nx, ny, p.k + 1, p.m, p.b);
          if(s.k > k){
            s.m++;
            s.k = 1;
            s.b = false;
          }
          if(dis[nx][ny] > s.m){
            pq.push(s);
            dis[nx][ny] = s.m;
          }
        }else{
          state s = state(nx, ny, p.k + 1, p.m, p.b);
          if(!p.b){
            s.k = 1;
            s.m++;
            s.b = true;
          }
          if(s.k > k){
            s.k = 1;
            s.m++;
            s.b = false;
          }
          if(dis[nx][ny] > s.m){
            pq.push(s);
            dis[nx][ny] = s.m;
          }
        }
      }
    }
  }
  int res = inf;
  rep(i, h){
    chmin(res, dis[i][0]);
    chmin(res, dis[i][w-1]);
  }
  rep(j, w){
    chmin(res, dis[0][j]);
    chmin(res, dis[h-1][j]);
  }
  cout << res << endl;
  return 0;
}

