    rep(i,h){
        rep(j,w){
            if(a[i][j] == 'S'){
                sy = i;
                sx = j;
            }
        }
    }
    vector<vector<int>> dist = gridBFS(a, sy, sx);
    int ans = INF;
    rep(i,h){
        rep(j,w){
            if(dist[i][j] <= k){
                ans = min(ans, 1 + min({(i + k - 1) / k, ((h - 1) - i + k - 1) / k, (j + k - 1) / k, ((w - 1) - j + k - 1) / k}));
            }
        }
    }
    cout << ans << endl;
    return 0;
}

