int dx[] = {1, 0, -1, 0};
int dy[] = {0, 1, 0, -1};

int calc(int x, int y){
    int ret = 1e9;
    ret = min(ret, (x + k - 1) / k);
    ret = min(ret, (y + k - 1) / k);
    ret = min(ret, (n - x - 1 + k - 1) / k);
    ret = min(ret, (m - y - 1 + k - 1) / k);
    return ret;
}
int main(){
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cin >> n >> m >> k;
    a.resize(n);
    for(auto &i : a) cin >> i;
    int sx, sy;
    for(int i = 0 ; i < n ; i++){
        for(int j = 0 ; j < m ; j++){
            if(a[i][j] == 'S'){
                sx = i; sy = j;
                break;
            }
        }
    }
    queue <pair <int, int> > q;
    vector <vector <int> > dis(n, vector <int>(m, -1));
    q.push(make_pair(sx, sy));
    dis[sx][sy] = 0;
    int ans = 1e9;
    while(q.size()){
        auto top = q.front();
        q.pop();
        ans = min(ans, 1 + calc(top.first, top.second));
        for(int i = 0 ; i < 4 ; i++){
            int nx = top.first + dx[i];
            int ny = top.second + dy[i];
            if(nx < 0 || nx >= n || ny < 0 || ny >= m || a[nx][ny] == '#') continue;
            if(dis[nx][ny] != -1 || dis[top.first][top.second] + 1 > k) continue;
            dis[nx][ny] = dis[top.first][top.second] + 1;
            q.push(make_pair(nx, ny));
        }
    }
    cout << ans << endl; 
}

