void bfs(int r, int c, int walk) {
  REP(i, H) REP(j, W) memo[i][j] = INF;
  memo[r][c] = 0;
  queue<int> q;
  q.push(r); q.push(c);
  while (q.size() > 0) {
    r = q.front(); q.pop();
    c = q.front(); q.pop();
    if (memo[r][c] == walk) break;
