using namespace std;

typedef pair<int, int> P;

int H, W, K;
char A[800][800];
bool used[800][800];
int dist[800][800];

bool isValid(P p){
    if(p.first >= 0 && p.first < H && p.second >= 0 && p.second < W) return true;
    else return false;
}

void bfs(int d, int h, int w){
    dist[h][w] = 0;
    queue<P> que;
    que.push(P(h, w));
    while(!que.empty()){
        P top = que.front();
        int h_ = top.first;
        int w_ = top.second;
        que.pop();
        if(dist[h_][w_] == K) continue;

        if(isValid(P(h-1, w)) && A[h_-1][w_] == '.' && !used[h_-1][w_]) {
            que.push(P(h_-1, w_));
            dist[h_-1][w_] = dist[h_][w_]+1;
            used[h_-1][w_] = true;
        }
        if(isValid(P(h_+1, w_)) && A[h_+1][w_] == '.' && !used[h_+1][w_]) {
            que.push(P(h_+1, w_));
            dist[h_+1][w_] = dist[h_][w_]+1;
            used[h_+1][w_] = true;
        }
        if(isValid(P(h_, w_-1)) && A[h_][w_-1] == '.' && !used[h_][w_-1]) {
            que.push(P(h, w-1));
            dist[h_][w_-1] = dist[h_][w_]+1;
            used[h_][w_-1] = true;
        }
        if(isValid(P(h_, w_+1)) && A[h_][w_+1] == '.' && !used[h_][w_+1]) {
            que.push(P(h_, w_-1));
            dist[h_][w_+1] = dist[h_][w_]+1;
            used[h_][w_+1] = true;
        }
    }
}

