const int MOVE[4][2] =
{
	1, 0,
	-1, 0,
	0, 1,
	0, -1
};

int n, m, K;
char g[MAXN][MAXN];
int lev[MAXN][MAXN];
PII q[MAXN*MAXN];

void init ();
void input ();
void work ();

int getans ( int x, int y )
{
	return ( ( ( min ( min ( min ( x - 1, y - 1 ), n - x ), m - y ) ) + K - 1 ) / K );
