void init ()
{
	// Init Everything Here

	ios::sync_with_stdio ( false );
}

void input ()
{
	// input method

	scanf ( "%d%d%d", &n, &m, &K );
	lpi ( i, 1, n ) scanf ( "%s", g[i]+1 );
}

void work ()
{
	// main work

	int sx, sy;
	lpi ( i, 1, n ) lpi ( j, 1, m ) if ( g[i][j] == 'S' ) sx = i, sy = j;

	int ans = INF, l = 0, r = 0, nx, ny, vx, vy;
	q[r++] = MP ( sx, sy );
	INIT ( lev, -1 );
	lev[sx][sy] = 0;
	while ( l < r ){
		nx = q[l].FF, ny = q[l].SS, ++l;
		ans = min ( ans, getans ( nx, ny ) );
		if ( !ans ) break;
		if ( lev[nx][ny] ^ K ){
			lp ( d, 0, 4 ){
				vx = nx + MOVE[d][0], vy = ny +  MOVE[d][1];
				if ( g[vx][vy] != '#' && lev[vx][vy] == -1 ){
					lev[vx][vy] = lev[nx][ny] + 1;
					q[r++] = MP ( vx, vy );
				}
			}
		}
	}

	cout << ( ( getans ( sx, sy ) ) ? ( ans + 1 ) : 0 ) << endl;
}

