int mini = ~0u >> 1;

void dfs(int x, int y, int dep) {
	if (dep >= K) return;
	for (int i = 0; i != 4; ++i) {
		int tx = x + dx[i], ty = y + dy[i];
		if (!v[tx][ty] && m[tx][ty] != '#') {
			v[tx][ty] = true;
			dfs(tx, ty, dep + 1);
			v[tx][ty] = false;
		}
	}
	if (ceil((x - 1) / K) < mini) mini = ceil((x - 1) / K);
	if (ceil((y - 1) / K) < mini) mini = ceil((y - 1) / K);
	if (ceil((H - x) / K) < mini) mini = ceil((H - x) / K);
	if (ceil((W - y) / K) < mini) mini = ceil((W - y) / K);
}

