	memset(m, '#', sizeof m);
	scanf("%d%d%lf", &H, &W, &K);
	for (int i = 1; i <= H; ++i)
		for (int j = 1; j <= W; ++j) {
			while (isspace(m[i][j] = getchar()));
			if (m[i][j] == 'S') sx = i, sy = j;
		}
	v[sx][sy] = true;
	dfs(sx, sy, 0);
	printf("%d\n", mini + 1);
}

