int main() {
    init();

    int h, w, k; cin >> h >> w >> k;
    VS s(h); cin >> s;

    int sy, sx;
    FOR(y, 0, h)FOR(x, 0, w) {
        if (s[y][x] == 'S') {
            tie(sy, sx) = tie(y, x);
            goto gotstart;
        }
    }
gotstart:

    auto dis = defvec<int>(INF, h, w);
    dis[sy][sx] = 0;
    queue<pair<int, int>> bfs;
