    int ans = INF;
    FOR(y, 0, h)FOR(x, 0, w) {
        if (dis[y][x] <= k) {
            int m = min({ y,x,h - y - 1,w - x - 1 });
            chmin(ans, (m + k - 1) / k + 1);
        }
    }

    cout << ans << "\n";
}

