using namespace std;
typedef long long LL;
const LL INF = 0x3f3f3f3f3f3f3f3f;

LL vis[805][805] = {0};
char ch[805][805];
LL n,m,k,ans = INF;

void dfs(LL x,LL y,LL dep){
	if(!x || !y || x > n || y > m) return;
	if(!dep) return; if(ch[x][y] == '#') return;
	vis[x][y] = 1;
	ans = min(ans,min(min(x - 1,y - 1),min(n - x,m - y)));
	if(!vis[x - 1][y]) dfs(x - 1,y,dep);
	if(!vis[x][y - 1]) dfs(x,y - 1,dep);
	if(!vis[x + 1][y]) dfs(x + 1,y,dep);
	if(!vis[x][y + 1]) dfs(x,y + 1,dep);
}

int main(){
	ios::sync_with_stdio(false);
	LL sx = 0,sy = 0;
	cin >> n >> m >> k;
	for(LL i = 1;i <= n;i ++){
		for(LL j = 1;j <= m;j ++){
			cin >> ch[i][j];
			if(ch[i][j] == 'S'){ sx = i; sy = j; }
		}
	}
	dfs(sx,sy,k);
//	cout << ans << endl;
	if(ans) cout << (ans - 1) / k + 2 << endl;
	else cout << 1 << endl;
	return 0;
}

