        visited.at(y-1).at(x) = true;
        que.push(make_tuple(x, y-1, rk-1));
      }
      if (y+1<h && amap.at(y+1).at(x) == '.' && !visited.at(y+1).at(x)) {
        visited.at(y+1).at(x) = true;
        que.push(make_tuple(x, y+1, rk-1));
      }
    }
  }
  cout << ans / k + (1 ? ans % k : 0) + 1 << endl;
  return 0;
}

