        if (f.x == 0 || f.x == h - 1 || f.y == 0 || f.y == w - 1) { ans = min(ans, f.step); continue; }
        REP(i, 4) {
            x_t = f.x + dir[i][0]; y_t = f.y + dir[i][1];
            if (vis[x_t][y_t]) { continue; } vis[x_t][y_t] = true;
            if (G[x_t][y_t] == '.' && f.step + 1 <= k) { q.push(Node{x_t, y_t, f.step + 1}); }
            else if (G[x_t][y_t] == '#' && f.step + 2 <= k) { q.push(Node{x_t, y_t, f.step + 2}); }
        }
    }
}

