vi dr = {1, 0, -1, 0};
vi dc = {0, -1, 0, 1};

int solve() {
    int H, W, K;
    cin >> H >> W >> K;
    vector<string> fi(H);
    rep(i, H) {
        cin >> fi[i];
    }

    pii start;
    int nearest = -1;
    rep(r, H) {
        rep(c, W) {
            if(fi[r][c] == 'S') {
                start = mp(r, c);
                nearest = min(min(r, H-r), min(c, W-c));
            }
        }
    }

    if(nearest == 0) {
        return 1;
    }

    priority_queue<pair<int, pii>> que;
    que.push(mp(K-1, start));

    vector<vvb> dp(801, vvb(H, vb(W, false)));

    while(!que.empty()) {
        auto f = que.top(); que.pop();
        int d = f.first;
        int r = f.second.first;
        int c = f.second.second;

        chmin(nearest, min(min(r, H-r), min(c, W-c)));
        dp[d][r][c] = true;

        if(d == 0)
            continue;

        rep(i, 4) {
            int nr = r + dr[i];
            int nc = c + dc[i];

            if(nr < 0 || H <= nr || nc < 0 || W <= nc || fi[nr][nc] == '#' || dp[d-1][nr][nc])
                continue;

            que.push(mp(d-1, mp(nr, nc)));
        }
    }

    return 1 + (int)ceil((double)nearest / K);
}

int main() {
    auto res = solve();	
	cout << res << endl;
    return 0;
}

