int g(int w, int h)
{
	int ret = 1000;
	if(h < ret) ret = h;
	if(w < ret) ret = w;
	if(H - h - 1 < ret) ret = H - h - 1;
	if(W - w - 1 < ret) ret = W - w - 1;
	return (ret + K - 1) / K;
}

int f(int w, int h)
{
	if(w <  0) return 0;
	if(w >= W) return 0;
	if(h <  0) return 0;
	if(h >= H) return 0;
	if(A[h][w] == '.'){
		return 1;
	}
	return 0;
}

int main(void)
{
	cin >> H >> W >> K;
	P p;
	Rep(h, H){
		cin >> A[h];
		Rep(w, W){
			if(A[h][w] == 'S'){
				p.w = w;
				p.h = h;
				a[h][w] = 0;
				A[h][w] = 'T';
			}
		}
	}

	stack<P> st;
	st.push(p);
	while(!st.empty()){
		p = st.top();
		st.pop();
		int w = p.w;
		int h = p.h;
		A[h][w] = 'T';
