		if(f(w, h-1)){a[h-1][w] = a[h][w] + 1; p.w = w; p.h = h-1; P p_ = p; st.push(p_);}
		if(f(w, h+1)){a[h+1][w] = a[h][w] + 1; p.w = w; p.h = h+1; P p_ = p; st.push(p_);}
	}

	int ans = 1000;
	Rep(h, H){
		Rep(w, W){
			if(A[h][w] == 'T'){
				int score = g(w, h);
				if(score < ans) ans = score;
			}
		}
	}
	PrintLn(ans + 1);
	return 0;
}

