		for(int i=0 ; i<w ; i++)
			for(int j=0 ; j<h ; j++){
				if(dp[i][j] >= inf)
					continue;
				dp[i][j] = dp[i][j] - k;
				if(ok(ii(i , j))){
					printf("%d\n" , ans);
					return 0;
				}
			}
	}
}

