        if (x > 0 && board[x - 1][y]) {
            if (d[x - 1][y] > d[x][y] + 1) {
                d[x - 1][y] = d[x][y] + 1;
                q.push({x - 1, y});
            }
        }
        if (x < n - 1 && board[x + 1][y]) {
            if (d[x + 1][y] > d[x][y] + 1) {
                d[x + 1][y] = d[x][y] + 1;
                q.push({x + 1, y});
            }
        }
        if (y > 0 && board[x][y - 1]) {
            if (d[x][y - 1] > d[x][y] + 1) {
                d[x][y - 1] = d[x][y] + 1;
                q.push({x, y - 1});
            }
        }
        if (y < m - 1 && board[x][y + 1]) {
            if (d[x][y] > d[x][y + 1] + 1) {
                d[x][y] = d[x][y + 1] + 1;
                q.push({x, y + 1});
            }
        }
    }
    int res = 1e9;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (d[i][j] <= k) {
                int tmp = min(i, n - 1 - i);
                tmp = min(tmp, min(j, m - 1 - j));
                res = min(res, (tmp + k - 1) / k);
            }
        }
    }
    cout << res + 1 << endl;
    return 0;
}

