char mas[810][810];

int memo[810][810];
int pp[810][810];

int move_x[4] = {1,-1,0,0};
int move_y[4] = {0,0,1,-1};


int main(){
  int h, w, k;
  cin >> h >> w >> k;

  int sx, sy;
  for(int i = 0;i < h;i++){
    cin >> mas[i];
    for(int j = 0;j < w;j++){
      if(mas[i][j] == 'S'){
        mas[i][j] = '.';
        sy = i;
        sx = j;
      }
    }
  }

  memset(memo,-1,sizeof(memo));
  memset(pp,-1,sizeof(pp));

  que.push(make_data(1, k, 0, sx, sy));

  while(!que.empty()){
    int cost = que.top().cost;
    int power = que.top().power;
    int hakai = que.top().hakai;
    int x = que.top().x;
    int y = que.top().y;
    que.pop();

    if(x == 0 || x == w-1 || y == 0 || y == h-1){
      cout << cost << endl;
      return 0;
    }

    if(memo[y][x] != -1 && pp[y][x] <= power) continue;

    memo[y][x] = cost;
    pp[y][x] = power;

    for(int i = 0;i < 4;i++){
      int nx = x + move_x[i];
      int ny = y + move_y[i];
      int nhakai = hakai;
      int ncost = cost;
      int npower = power;
      if(mas[ny][nx] == '#'){
        nhakai--;
        if(nhakai == -1){
          ncost++;
          nhakai = k;
          npower = k;
        }
      }
      npower--;
      if(npower == -1){
        ncost++;
        nhakai += k;
        npower = k;
      }
      que.push(make_data(ncost,npower,nhakai,nx,ny));
    }
  }


  return 0;
}

