void solve(int h, int w, long long k, vector<string> a){
	memset(vis,true,sizeof(vis));
	int x=0,y=0;
	for(int i=0; i<h; ++i) {
		for(int j=0; j<w; ++j) {
			if (a[i][j]=='S') {
				x=i;
