		DFS(x-1, y, k - 1, w, h, kk);
	if (mp[y][x + 1] == '.')
		DFS(x+1, y, k - 1, w, h, kk);
	if (mp[y-1][x] == '.')
		DFS(x, y-1, k - 1, w, h, kk);
	if (mp[y+1][x] == '.')
		DFS(x, y+1, k - 1, w, h, kk);
}

