        }
    }
    while (!q.empty()) {
        std::tie(x, y) = q.front();
        q.pop();

        forn(k, 4) {
            int xx = x + dx[k];
            int yy = y + dy[k];
            if (xx < 0 || xx >= n || yy < 0 || yy >= m) {
                continue;
            }
//            if (s[xx][yy] == '#') continue;
            if (d2[xx][yy] != -1) continue;
            d2[xx][yy] = d2[x][y] + 1;
            q.push({xx, yy});
        }
    }
    int ans = INT_MAX;
    forn(i, n) forn(j, m) {
            if (d1[i][j] != -1 && d1[i][j] <= k) {
                ans = min(ans, (d2[i][j] + k - 1) / k + 1);
            }
        }
    cout << ans << "\n";


}

