int min_to_go(int h, int w){
  int hh = min(H-h-1, h);
  int ww = min(W-w-1, w);
  return min(hh, ww);
}

int bfs(int m){
  if(qh.empty())  return m;
  int h = qh.front(); qh.pop();
  int w = qw.front(); qw.pop();
  int k = qk.front(); qk.pop();
  int mi = min(m, min_to_go(h, w));
  if(k >= K) return bfs(mi);
  for(int i = 0; i < 4; i++){
    int hh = h + vh[i], ww = w + vw[i];
