struct dat{
  int y,x,K1,K2,cost;
  bool operator < (const dat &A)const{
    if(cost!=A.cost) return cost>A.cost;
    if(A.K1!=K1) return K1<A.K1;
    return K2<A.K2;
  }
};

int dx[] ={0,0,1,-1};
int dy[] ={1,-1,0,0};
PP D[N][N];
bool used[N][N];
int bfs(int y,int x,int sK){

  for(int i=0;i<N;i++)
    for(int j=0;j<N;j++) D[i][j] = PP(1e9,P(1e9,1e9));

  priority_queue<dat>Q;
  Q.push((dat){y,x,sK,0,1});  
  D[y][x] = PP(1,P(-sK,0));

  while(!Q.empty()){
    dat t = Q.top();Q.pop();
    y = t.y;
    x = t.x;
    int K1 = t.K1;
    int K2 = t.K2;
    int cost = t.cost;
    if(used[y][x] )continue;
    used[y][x] = 1;
    if(D[y][x] < PP(cost,P(-K1,-K2)))continue;
    //cout<<y<<" "<<x<<" "<<K1<<" "<<K2<<" "<<cost<<endl;

    for(int i=0;i<4;i++){
      int nx = x+dx[i];
      int ny = y+dy[i];
      int nK1 = K1-1;
      int nK2 = K2;
      int ncost = cost;
      if(nx<0||ny<0||nx>=w||ny>=h){return cost;}
      if(nK1 <  0) ncost++,nK1 = sK-1,nK2 += sK;
      if(mp[ny][nx] == '#') nK2--;
      if(nK2<0) nK1 = nK2 = sK-1,ncost+=2 - (cost==1);
      PP tmp = PP(ncost,P(-nK1,-nK2));
      if(D[ny][nx]<= tmp)continue;
      Q.push((dat){ny,nx,nK1,nK2,ncost});
      D[ny][nx] = tmp;
    }      
  }
  assert(0);
}

