#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
#define H 800

int vis[H][H];
char a[H][H];
int h,w,k;
int u,d,l,r;

bool check(int x,int y,int k){
	if(x>=0 && x<h && y>=0 && k>=1 && y<w && a[x][y]!='#' && !vis[x][y])return true;
	return false;
}

int dx[4]={-1,0,1,0},dy[4]={0,-1,0,1};

void dfs(int x,int y,int k){
	queue<pair<int,int>> que;
	queue<int> kque;
	que.push({x,y});
	vis[x][y]=1;
	kque.push(k);
	while(que.size()){
		x=que.front().first;
		y=que.front().second;
		k=kque.front();
		que.pop();
		kque.pop();
		u=min(x,u);
		d=max(x,d);
		l=min(l,y);
		r=max(r,y);
		for (int i = 0; i < 4; i++) {
			if(check(x+dx[i],y+dy[i],k)){
				que.push({x+dx[i],y+dy[i]});
				vis[x+dx[i]][y+dy[i]]=1;
				kque.push(k-1);
			}
		}
	}
}

int main(void)
{
	cin>>h>>w>>k;
	for (int i = 0; i < h; i++) {
		for (int j = 0; j < w; j++) {
			cin>>a[i][j];
			if(a[i][j]=='S'){
				u=d=i;
				l=r=j;
			}
		}
	}
	dfs(u,l,k);
	int dmin=min(u-0,min(h-1-d,min(l-0,w-1-r)));
	cout<<ceil(float(dmin)/k)+1<<endl;
	return 0;
}

#include<cstdio>
#include<cstring>
#include<queue>
#include<algorithm>
using namespace std;
const int MAXN=805;
const int dir[4][2]={{-1,0},{0,1},{1,0},{0,-1}};

int H,W,K;
char maze[MAXN][MAXN];

int step[MAXN][MAXN];
pair<int,int> st;
queue<pair<int,int> > Q;

int main()
{
    scanf("%d%d%d",&H,&W,&K);
    for(int i=1;i<=H;i++)
    {
        scanf("%s",maze[i]+1);
        for(int j=1;j<=W;j++)
            if(maze[i][j]=='S')
                st.first=i,st.second=j;
    }

    memset(step,-1,sizeof step);
    step[st.first][st.second]=0;
    Q.push(st);
    int ans=0x3F3F3F3F;
    while(!Q.empty())
    {
        pair<int,int> u=Q.front();
        Q.pop();

        ans=min(ans,(u.first-1+K-1)/K+1);
        ans=min(ans,(u.second-1+K-1)/K+1);
        ans=min(ans,(H-u.first+K-1)/K+1);
        ans=min(ans,(W-u.second+K-1)/K+1);

        if(step[u.first][u.second]>=K)
            continue;

        for(int d=0;d<4;d++)
        {
            pair<int,int> v=u;
            v.first+=dir[d][0],v.second+=dir[d][1];
            if(step[v.first][v.second]==-1&&maze[v.first][v.second]!='#')
            {
                step[v.first][v.second]=step[u.first][u.second]+1;
                Q.push(v);
            }
        }
    }

    printf("%d\n",ans);

    return 0;
}

