struct State
{
    int x,y,mv,unlck;
    State(int x=0,int y=0,int mv=0,int unlck=0):x(x),y(y),mv(mv),unlck(unlck){}
};
bool inRange(int x,int y)
{
    return (x>=0&&y>=0&&x<n&&y<m);
}
void bfs(int bx,int by)
{
    queue<State> q;
    while(!q.empty()) q.pop();
    q.push(State(bx,by,0,0));
    vis[bx][by]=1;
    while(!q.empty())
    {
        State u=q.front();
        q.pop();
        //cout << u.x << " "<< u.y << endl;
        if (u.x==0||u.y==0||u.x==n-1||u.y==m-1)
        {
            ans=min(ans,max((u.mv+k-1)/k,(u.unlck+k-1)/k));
        }
        for (int i=0;i<4;i++)
        {
            int tx=u.x+dir[i][0],ty=u.y+dir[i][1];
            if (inRange(tx,ty)&&!vis[tx][ty])
            {
                vis[tx][ty]=1;
                if (g[tx][ty]=='.')
