        for (int j=0;j<m;j++)
        {
            cin >> g[i][j];
            if (g[i][j]=='S')
            {
                bx=i;
                by=j;
                g[i][j]='.';
            }
        }
    }
    bfs(bx,by);
    cout << ans << endl;
    return 0;
}

