	int h, w, k, ans;
	scanf("%d %d %d", &h, &w, &k);

	vector< vector<char> > c(h, vector<char> (w));
	vector< vector<int> > d(h, vector<int> (w));

	for (int i = 0; i < w; i++) {
		for (int j = 0; j < h; j++) {
			d[i][j] = INF;
		}
	}

	for (int i = 0; i < h; i++) {
		scanf("\n");
		for (int j = 0; j < w; j++) {
			scanf("%c", &c[j][i]);
			if (c[j][i]=='S') {
				d[j][i] = 0;
				que.push(pair<int, int>(j, i));
			}
		}
	}

	while (!que.empty()) {
		int x, y;
		int x1, y1;
		int a;
		tie(x, y) = que.front();
		a = d[x][y];
		que.pop();
		for (int i = 0; i < 4; i++) {
			x1 = x + dx[i];
			y1 = y + dy[i];
			if (x1 >= w) continue;
			if (y1 >= h) continue;
			if (x1 < 0) continue;
			if (y1 < 0) continue;
			if (c[x1][y1] == '.') {
				if (d[x1][y1] == INF) {
