			dis = min(dis1, dis2);

			if (k >= d[j][i] & min_out > dis) {
				min_out = dis;
			}
		}
	}

	ans = 1;
	while(1) {
		if (min_out <= 0) {
			printf("%d\n", ans);
			return 0;
		}
		min_out -= k;
		ans++ ;
	}

}

