#define MEMS(a,b) memset(a,b,sizeof(a))
#define mp make_pair
template<class T>bool chmax(T &a, const T &b) { if (a<b) { a=b; return 1; } return 0; }
template<class T>bool chmin(T &a, const T &b) { if (b<a) { a=b; return 1; } return 0; }
const ll MOD = 1e9+7;

bool X[810][810];
ll isvisit[810][810];
ll H, W, K;

typedef queue<pair<ll, ll>> Q;

bool dfs(Q& que, ll y, ll x, int num){
    if(y >= H) return false;
    if(x >= W) return false;
    if(y < 0) return false;
    if(x < 0) return false;

    if(isvisit[y][x] >= num) return false;

    if(!X[y][x]) {
        if(num > 0)
            num--;
        else{
            que.push(mp(y, x));
            return false;
        }
    }

    isvisit[y][x] = num;
    if(y == 0) return true;
    if(x == 0) return true;
    if(y == H-1) return true;
    if(x == W-1) return true;

    bool ret = false;
    chmax(ret, dfs(que, y+1, x, num));
    chmax(ret, dfs(que, y-1, x, num));
    chmax(ret, dfs(que, y, x+1, num));
    chmax(ret, dfs(que, y, x-1, num));

    return ret;
}

ll solve(pair<ll, ll> s){
    // (y, x, num)
    Q tmp;
    MEMS(isvisit, -1);
    if(dfs(tmp, s.first, s.second, 0))
        return 1;
    MEMS(isvisit, -1);

    Q que;
    int num = 1;
    que.push(s);
    while(1){
        num++;
        while(!que.empty()){
            auto p = que.front();
            que.pop();
            bool end = dfs(que, p.first, p.second, K);
            if(end) return num;
        }
    }
}

int main(){
    cin >> H >> W >> K;

    pair<ll, ll> S;
    REP(i,H){
        REP(j,W){
            char c;
            cin >> c;
            if(c == 'S'){
                S = mp(i, j);
                X[i][j] = true;
            }
            else if(c == '.')
                X[i][j] = true;
        }
    }

    ll ans = solve(S);
    cout << ans << endl;
    return 0;
}

