template<class T>inline bool chmax(T &a, const T &b) { if (b > a) { a = b; return true; } return false; }
template<class T>inline bool chmin(T &a, const T &b) { if (b < a) { a = b; return true; } return false; }

constexpr int dx[4] = {-1, 0, 0, 1}, dy[4] = {0, -1, 1, 0};
constexpr int INF = 1e9;
constexpr int MOD = 1e9 + 7;
constexpr long long LINF = 1e18;
constexpr double EPS = 1e-10;
constexpr double PI = M_PI;

void solve() {
    int H, W, K;
    cin >> H >> W >> K;
    vector<string> a(H);
    for (int i=0; i<H; ++i) cin >> a[i];

    int si = -1, sj = -1;
    for (int i=0; i<H; ++i) {
        for (int j=0; j<W; ++j) {
            if (a[i][j] == 'S') {
                si = i, sj = j;
                break;
            }
        }
        if (si != -1) break;
    }

    using T = pair<int, int>;
    using P = pair<T, int>;
    vector<vector<T>> dis(H, vector<T>(W, make_pair(INF, INF)));
    priority_queue<P, vector<P>, greater<P>> que;
    dis[si][sj] = make_pair(1, -K);
    que.push(make_pair(dis[si][sj], si*W+sj));
    while (!que.empty()) {
        auto p = que.top(); que.pop();
        int c = p.first.first, r = p.first.second, cx = p.second / W, cy = p.second % W;
        if (dis[cx][cy] < p.first) continue;
        for (int i=0; i<4; ++i) {
            int nx = cx + dx[i], ny = cy + dy[i];
            if (nx < 0 || H <= nx || ny < 0 || W <= ny) continue;
            T n;
            if (r == 0) {
                n = make_pair(c+1, -K+1);
            } else if (c == 1) {
                if (a[nx][ny] == '#') {
                    n = make_pair(c+1, -K+1);
                } else {
                    n = make_pair(c, r+1);
                }
            } else {
                n = make_pair(c, r+1);
            }
            if (n < dis[nx][ny]) {
                dis[nx][ny] = n;
                que.push(make_pair(n, nx*W+ny));
            }
        }
    }

    int res = INF;
    for (int i=0; i<H; ++i) {
        chmin(res, dis[i][0].first);
        chmin(res, dis[i][W-1].first);
    }
    for (int i=0; i<W; ++i) {
        chmin(res, dis[0][i].first);
        chmin(res, dis[H-1][i].first);
    }
    cout << res << '\n';
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(20);

    solve();

    return 0;
}

