    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            if (dist.at(i).at(j) > k) continue;

            if ((i == 0) || (i == h - 1) || (j == 0) || (j == w - 1)) mini = 1;
            else mini = min(mini, (min({i, h - i, j, w - j}) + k - 1) / k + 1);
        }
    }
    cout << mini << endl;
}

