//using PP = pair<pair<int,int>,pair<int,int>>;
inline bool ok(int x,int y){return 0<=x && x<H && 0<=y && y<W ;}
void g_trace(){ rep(i,H) cerr << g[i] << endl; }
void grid(){ cin>>H>>W>>K; g.resize(H); rep(i,H) cin>>g[i]; }

// 依存ライブラリ _grid
// grid上を幅優先探索して距離を調べる
void gbfs(vvi &d , pair<int,int> start){
  using PP = pair<pair<int,int> , int>;
  d.resize( H , vi(W , -1) );
  queue<PP> Q;
  Q.emplace( start , 0 );
  while(!Q.empty()){
    PP cur = Q.front(); Q.pop();
    int x = cur.first.first , y = cur.first.second , dep = cur.second;
    if(d[x][y] != -1) continue;
    d[x][y] = dep;
    rep(i , dn){
      int dh = x + dx[i] , dw = y + dy[i];
      if( ok(dh , dw) && d[dh][dw] == -1){
        if( g[dh][dw] == '.' ){ // ここに条件を書く
          Q.emplace( make_pair(dh , dw) , dep + 1 );
        }
      }
    }
  }
}

void solve(){
  grid();
  vvi d;
  int sh,sw;
  rep(i,H)rep(j,W) if(g[i][j]=='S') sh=i,sw=j;
  gbfs(d , P(sh,sw));

  int ans = inf;

  auto f = [&](int i,int j) -> int{
    ll ret = inf;
    amin(ret , Ceil(i , K));
    amin(ret , Ceil(H - 1 - i , K));
    amin(ret , Ceil(j , K));
    amin(ret , Ceil(W - 1 - j , K));
    return ret;
  };

  rep(i , H) rep(j , W){
    if(d[i][j] != -1 && d[i][j] <= K){
      amin(ans , f(i , j));
    }
  }

  out(ans + 1);



}

