signed main() {
    int H, W, K;
    cin >> H >> W >> K;
    vector<vector<char>> A(H, vector<char>(W));
    pair<int, int> start;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            cin >> A[i][j];
            if (A[i][j] == 'S') {
                start = {i ,j};
            }
        }
    }
    int ans = INF;
    vector<vector<bool>> check(H, vector<bool>(W, false));
    stack<info> explore;
    explore.push({start.first, start.second, 0});
