class Solver {
  public:
    bool solve() {
        int H, W, K; cin >> H >> W >> K;
        vector<string> G(H); cin >> G;

        int sx = -1, sy = -1;
        rep(i, H) rep(j, W) if(G[i][j] == 'S') {
            sy = i;
            sx = j;
            break;
        }
        assert(sx >= 0 and sy >= 0);

        vector<vector<int>> visited(H, vector<int>(W));

        queue<pair<pii, int>> que;
        que.push(make_pair(make_pair(sy, sx), 0));

        const int dx[] = {0, 1, 0, -1};
        const int dy[] = {1, 0, -1, 0};

        auto eval = [&](pii p) {
            return min({p.first, H - p.first - 1, p.second, W - p.second - 1});
        };
        auto div = [&](int a) {
            return a / K + (a % K != 0);
        };
        auto calc_cost = [&] (pii pos, int c) -> int {
            return div(eval(pos)) + div(c) + (pos.first == sy and pos.second == sx);
        };

        int ans = INF;       
        while(que.size()) {
            pii now = que.front().first;
            int cost = que.front().second; que.pop();
            visited[now.first][now.second] = true;
            // cerr << "cost of " << now.first << " " << now.second << " : " << calc_cost( now,cost) << endl;
            set_min(ans, calc_cost(now, cost));
            rep(i, 4) {
                pii nxt = make_pair(now.first + dy[i],  now.second + dx[i]);
                if(0 <= nxt.first and nxt.first < H and 0 <= nxt.second and nxt.second < W) {
                    if(G[nxt.first][nxt.second] == '.') {
                        if(not visited[nxt.first][nxt.second]) que.push(make_pair(nxt, cost + 1));
                    }
                }
            }
        }
        cout << ans << endl;
        return 0;
    }
};

