    nx++;
  }

  mx = min(mx, W-1 - nx);

  nx = sx; ny = sy;
  while( 1 ) {
    if( nx == 0 ) break;
    if( data[nx-1][ny] == '#' ) break;
    nx--;
  }

  mx = min(mx, nx - 0);

