  auto dist = [&](int i, int j) {
    int res = INF;
    chmin(res, i);
    chmin(res, h - 1 - i);
    chmin(res, j);
    chmin(res, w - 1 - j);
    return res;
  };
  string s[801];
  rep(i, h) cin >> s[i];
  dijkstra<int> ds(h * w, INF);
  rep(i, h) rep(j, w - 1)
  {
    if (s[i][j] == '#' || s[i][j + 1] == '#')
      continue;
    ds.add_E(i * w + j, i * w + j + 1, 1, false);
  }
  rep(i, h - 1) rep(j, w)
  {
    if (s[i][j] == '#' || s[i + 1][j] == '#')
      continue;
    ds.add_E(i * w + j, (i + 1) * w + j, 1, false);
  }
  int s_pos;
  rep(i, h) rep(j, w)
  {
    if (s[i][j] == 'S')
      s_pos = i * w + j;
  }
  ds.calc(s_pos);
  int Min = INF;
