      continue;
    if (i == 0 || i == h - 1 || j == 0 || j == w - 1)
    {
      cout << 1 << endl;
      return 0;
    }
    chmin(Min, CEIL(dist(i, j), k) + 1);
  }
  cout << Min << endl;
  return 0;
}

