int n,m,k;
char mapp[805][805];
int vis[805][805];
int dic[][2]={{1,0},{0,1},{-1,0},{0,-1}};
struct node
{
    int x,y,step;
};
vector<int>vec;
void bfs(int x,int y)
{
    vis[x][y]=1;
    queue<node>q;
    node p1;
    p1.x=x,p1.y=y,p1.step=0;
    q.push(p1);
    while(!q.empty())
    {
        node p=q.front();
        q.pop();
        for(int i=0;i<4;i++)
        {
            int xx=p.x+dic[i][0];
            int yy=p.y+dic[i][1];
            if(xx>=0&&xx<n&&yy>=0&&yy<m&&!vis[xx][yy])
            {
                if(xx==0||xx==n-1||yy==1||yy==m-1)
                {
                    if(mapp[xx][yy]=='#')
                        vec.push_back(p.step+2);
                    else
                        vec.push_back(p.step+1);
                }
                else if(mapp[xx][yy]=='#')
                {
                    vis[xx][yy]=1;
                    node p2;
                    p2.x=xx;
                    p2.y=yy;
                    p2.step=p.step+2;
                    q.push(p2);
                }
                else
                {
                    vis[xx][yy]=1;
                    node p2;
                    p2.x=xx;
                    p2.y=yy;
                    p2.step=p.step+1;
                    q.push(p2);
                }
            }
        }
    }
    sort(vec.begin(),vec.end());
    printf("%d\n",min(*vec.begin(),k));
}
int main()
{

    scanf("%d%d%d",&n,&m,&k);
    for(int i=0;i<n;i++)
        scanf("%s",mapp[i]);
    for(int i=0;i<n;i++)
        for(int j=0;j<m;j++)
        {
            if(mapp[i][j]=='S')
            {
                bfs(i,j);
                return 0;
            }
        }
    return 0;
}

