int n,m,k;
int dx[] = {-1,1,0,0};
int dy[] = {0,0,-1,1};
char s[1005][1005];
int sx, sy;
int dist[1005][1005];
queue < pair < int , int > > q;

int main(){

	scanf("%d%d%d",&n,&m,&k);
	for ( int i = 0; i < n; i++ ){
		scanf("%s",&s[i]);
		for ( int j = 0; j < m; j++ ){
			if ( s[i][j] == 'S' ){
				sx = i;
				sy = j;
				break;
			}
		}
	}

	memset(dist,-1,sizeof(dist));
	dist[sx][sy] = 0;
	q.push(mp(sx,sy));
	while ( !q.empty() ){
		sx = q.front().fi;
		sy = q.front().se;
		q.pop();
		if ( sx == 0 || sy == 0 || sx == n-1 || sy == m-1 ) continue;
		if ( dist[sx][sy] == k ) continue;
		for ( int l = 0; l < 4; l++ ){
			int x = dx[l] + sx , y = dy[l] + sy;
			if ( dist[x][y] == -1 && s[x][y] != '#' ) {
				dist[x][y] = dist[sx][sy] + 1;
				q.push(mp(x,y));
			}
		}
	}

	int ans = 1e9;
	for ( int i = 0; i < n; i++ ){
		for ( int j = 0; j < m; j++ ){
			if ( dist[i][j] != -1 ){
				int tmp = min(i,j);
				int tmp2 = min(n-i-1, m-j-1);
				int both = min( tmp , tmp2 );
				int res = both / k;
				if ( both % k != 0 ) res++;
				ans = min( ans, res);
			}
		}
	}

	printf("%d\n",ans + 1);
	return 0;
}

