const int INF = 1e8;
using namespace std;

const int N = 1000;

struct Point{
	int x, y;
	bool operator < ( const Point &right ) const {
		return x < right.x;
	}
};
typedef pair<int,Point> pip;

int dy[4] = {0,1,0,-1}, dx[4] = {1,0,-1,0};
char c[N][N];
int m[N][N];

void bfs(int h, int w, Point p){
	priority_queue<pip, vector<pip>, greater<pip>> q;
	rep(i,N) rep(j,N) m[i][j] = INF;

	m[p.y][p.x] = 0;
	q.push(make_pair(0,p));

	pair<int, Point> cur;
	while(not q.empty()){
		cur = q.top(); q.pop();
		Point u = cur.second;
		rep(i,4){
			Point next;
			next.x = u.x + dx[i];
			next.y = u.y + dy[i];
			if(next.x < 0 || next.x >= w || next.y < 0 || next.y >= h) continue;
			if(m[next.y][next.x] > m[u.y][u.x] && c[next.y][next.x] == '.'){
				m[next.y][next.x] = m[u.y][u.x];
				q.push(make_pair(m[next.y][next.x], next));
			}else if(m[next.y][next.x] > m[u.y][u.x] + 1 && c[next.y][next.x] == '#'){
				m[next.y][next.x] = m[u.y][u.x] + 1;
				q.push(make_pair(m[next.y][next.x], next));
			}
		}
	}
}

int bfs(int h, int w, Point p, int k, int t){
	int dis[N][N];
	priority_queue<pip, vector<pip>, greater<pip>> q;
	rep(i,N) rep(j,N) dis[i][j] = INF;

	dis[p.y][p.x] = 0;
	q.push(make_pair(0,p));

	while(not q.empty()){
		pip cur = q.top(); q.pop();
		Point u = cur.second;
		rep(i,4){
			Point next;
			next.x = u.x + dx[i];
			next.y = u.y + dy[i];
			if(next.x < 0 || next.x >= w || next.y < 0 || next.y >= h) continue;
			if(dis[next.y][next.x] > dis[u.y][u.x] + 1 &&
					m[next.y][next.x] <= k * (t - 1) &&
					dis[u.y][u.x] + 1 <= t * k){
				dis[next.y][next.x] = dis[u.y][u.x] + 1;
				q.push(make_pair(dis[next.y][next.x],next));
			}
		}
	}
	rep(i,h) if(dis[i][0] != INF || dis[i][w - 1] != INF) return true;
	rep(i,w) if(dis[0][i] != INF || dis[h - 1][i] != INF) return true;
	return false;
}

int main(){
	int h, w, k;
	cin >> h >> w >> k;

	Point s;
	rep(i,h){
		rep(j,w){
			cin >> c[i][j];
			if(c[i][j] == 'S') s = Point{j,i};
		}
	}
	bfs(h, w, s);
	//rep(i,h){ rep(j,w){ cout << m[i][j] << ' '; } cout << endl; }
	int t = 1;
	while(true){
		if(bfs(h,w,s,k,t)){
			cout << t << endl;
			return 0;
		}
		t++;
	}
}

