struct D
{
	int t, use;
	D() : t(1000000000), use(0) { }
	bool operator< (const D& oth) const
	{
		if (t != oth.t) return (t > oth.t);
		return (use > oth.use);
	}
	D set(int T, int U)
	{
		t = T, use = U;
		return *this;
	}
} d[805][805];
char buf[805][805];
int r, c, k;
int si, sj;

int main()
{
	scanf("%d%d%d", &r, &c, &k);
	for (int i = 0;i < r;i++)
	{
		scanf("%s", buf[i]);
		for (int j = 0;j < c;j++)
		{
			if (buf[i][j] == 'S') si = i, sj = j;
		}
	}
	priority_queue<pair<D, pair<int, int> > > pq;
	pq.emplace(d[si][sj].set(0, 0), make_pair(si, sj));
	while (!pq.empty())
	{
		auto u = pq.top(); pq.pop();
		int ui = u.second.first, uj = u.second.second;
		if (ui == 0 || ui == r-1 || uj == 0 || uj == c-1)
		{
