			if (d[ui+dx[i]][uj+dy[i]] < alt)
				pq.emplace(d[ui+dx[i]][uj+dy[i]].set(alt.t, alt.use), make_pair(ui+dx[i], uj+dy[i]));
		}
	}
	printf("-1\n");
