				{
					a[nx][ny]=p;
					que.push(make_pair(nx,ny));
				}
			}
		}
	}
	int ans=INF;
	for(int i=0;i<n;i++)
	    for(int j=0;j<m;j++)
	        if(i==0||i==n-1||j==0||j==m-1)
