using namespace std;
typedef long long ll;

int main()
{
	int H, W, K;
	cin >> H >> W >> K;
	vector<vector<bool>> board(H, vector<bool>(W));
	pair<int, int> S;
	for (int i = 0; i < H; i++) {
		string A;
		cin >> A;
		for (int j = 0; j < W; j++) {
			if (A[j] == 'S') {
				S = make_pair(i, j);
			} else if (A[j] == '#') {
				board[i][j] = true;
			}
		}
	}
	auto calc = [H, W](const pair<int, int>& p) {
		return min({ p.first, (H - 1) - p.first, p.second, (W - 1) - p.second });
	};
	typedef tuple<int, int, pair<int, int>, set<pair<int,int>>> t;
	priority_queue<t> q;
	int score = -calc(S);
	q.emplace(score, 0, S, set<pair<int, int>>());
	while (!q.empty()) {
		int tmp;
		pair<int, int> pos;
		int K1;
		set<pair<int, int>> done;
		tie(tmp, K1, pos, done) = q.top(); q.pop();
		if (score < tmp) {
			score = tmp;
			S = pos;
		}
		done.insert(pos);
		if (pos.first == 0 || pos.first == H - 1 || pos.second == 0 || pos.second == W - 1) {
			break;
		}
		if (K1 == K)
			continue;
		static const int dx[4] = { 0, 1, 0, -1 };
		static const int dy[4] = { 1, 0, -1, 0 };
		for (int d = 0; d < 4; d++) {
			auto p2 = pos;
			p2.first += dx[d];
			p2.second += dy[d];
			if (!board[p2.first][p2.second] && done.find(p2) == done.end()) {
				q.emplace(-calc(p2), K1 + 1, p2, done);
			}
		}
	}
	int ans = (calc(S) + K - 1) / K + 1;
	cout << ans << endl;
	return 0;
}

