		x=Q[head][0],y=Q[head][1];
		Ins(x+1,y,D[x][y]+1);
		Ins(x,y+1,D[x][y]+1);
		Ins(x-1,y,D[x][y]+1);
		Ins(x,y-1,D[x][y]+1);
