			ll ny = y + dy[i];
			ll nx = x + dx[i];
			if(in(ny,nx,h,w)){
				if(d[ny][nx] != inf) continue;
				ll c = 0, K;
				if(p.second == 0){
					c++;
					K = k - 1;
				}else{
					K = p.second - 1;
				}
				d[ny][nx] = d[y][x] + c;
				que.emplace(P(ny,nx),K);
			}
		}
	}
	ll ans = inf;
	rep(i,h){
		chmin(ans, min(d[i][0], d[i][w-1]));
	}
	cout << ans << endl;
}

