			if (A[i][j] == 'S') { startx = j; starty = i; }
		}
	}

	dfs(startx, starty, 0);

	int ans = 114514;

	for (i = 0; i < H; i++) {
		for (j = 0; j < W; j++) {
			if (A[i][j] == 'S'&&field[i][j] <= K) {
				int tmp = min(min(min(H - 1 - i, i), W - 1 - j), j);
				if (tmp%K == 0) {
					tmp = tmp / K;
					tmp++;
				}
				else {
					tmp = (tmp / K) + 1;
					tmp++;
				}
				if (ans > tmp) {
					ans = tmp;
				}
			}
		}
	}
	printf("%d\n", ans);

	return 0;
}
void dfs(int posx, int posy, int depth) {

	A[posy][posx] = 'S';
	field[posy][posx] = min(field[posy][posx], depth);

	if (depth == K) { return; }

	if (0 <= posx - 1 && posx - 1 < W && 0 <= posy && posy < H) {
		if (A[posy][posx - 1] != '#' && field[posy][posx - 1] > depth + 1) {
			dfs(posx - 1, posy, depth + 1);
		}
	}
	if (0 <= posx + 1 && posx + 1 < W && 0 <= posy && posy < H) {
		if (A[posy][posx + 1] != '#'&& field[posy][posx + 1] > depth + 1) {
			dfs(posx + 1, posy, depth + 1);
		}
	}
	if (0 <= posx && posx < W && 0 <= posy - 1 && posy - 1 < H) {
		if (A[posy - 1][posx] != '#'&& field[posy - 1][posx] > depth + 1) {
			dfs(posx, posy - 1, depth + 1);	
		}
	}
	if (0 <= posx && posx < W && 0 <= posy + 1 && posy + 1 < H) {
		if (A[posy + 1][posx] != '#'&& field[posy + 1][posx] > depth + 1) {
			dfs(posx, posy + 1, depth + 1);
		}
	}
}
