int dx[]={0,0,1,-1};
int dy[]={1,-1,0,0};

char s[maxn][maxn];
int g[maxn][maxn],h,w,k,cx,cy,ans=inf;
queue<mp> q;
bool inG(int x,int y) {
	return x>=1&&y>=1&&x<=h&&y<=w&&s[x][y]!='#';
}

int main()
{
	#ifdef Amberframe
		freopen("agc014c.in","r",stdin);
		freopen("agc014c.out","w",stdout);
	#endif
	scanf("%d %d %d",&h,&w,&k);
