	for (int i=1;i<=h;i++)
	for (int j=1;j<=w;j++) g[i][j]=inf;
	for (int i=1;i<=h;i++)
	for (int j=1;j<=w;j++)
		if (s[i][j]=='S') cx=i,cy=j;

	g[cx][cy]=0;q.push(mp(cx,cy));
	while (!q.empty()) {
		int x=q.front().first;
		int y=q.front().second;
		q.pop();
		if (g[x][y]>=k) break;
		for (int nx,ny,d=0;d<4;d++)
		if (inG(nx=x+dx[d],ny=y+dy[d])&&g[nx][ny]==inf)
			g[nx][ny]=g[x][y]+1,q.push(mp(nx,ny));
	}
	for (int i=1;i<=h;i++)
	for (int j=1;j<=w;j++)
		if (g[i][j]<=k) ans=min(ans,min(min(i-1,h-i),min(j-1,w-j)));
