    ans=min(ans, x);
    ans=min(ans,n-1-x);
}

void dfs(int x,int y,int k){
    //printf("%d %d %d\n",x,y,k);

    if (k<0 || x<0 || x>=n || y<0 || y>=m || mp[x][y]=='#' || vis[x][y]==1) return;
    update(x,y);
    dfs(x-1, y, k-1);
    dfs(x+1, y, k-1);
    dfs(x, y-1, k-1);
    dfs(x, y+1, k-1);
}

