        gg2 = 0;
        if(cast2 % k != 0)
            gg2 = 1;
        cast2 /= k;
        cast2 += gg2;

        if(cast2 > cast){
            ans = min(ans,cast2 );
        }
        else 
            ans = min(ans,cast+1 );
    }

    cout<<ans<<endl;
}


signed main(){
    ios_base::sync_with_stdio(0);
    cin.tie(NULL);

    ll t=1;
    while(t--){
        solve();
    }    
}

