int res = 1000;
int xs[] = {0, 1, 0, -1};
int ys[] = {1, 0, -1, 0};
P start;
int calc(int i, int j, int h, int w){
  h--,w--;
  int ans = abs(h - i);
  ans = min(ans, i);
  ans = min(ans, j);
  ans = min(ans, abs(w - j));
  return ans;
}

int main(){
  cin >> h >> w >> k;
  for(int i = 0;i < h;i++){
    for(int j = 0;j < w;j++){
      cin >> field[i][j];
      if(field[i][j] == 'S'){
	start = P(i, j);
      }
      dist[i][j] = -1;
    }
  }

  queue<P> q;
  q.push(start);
  dist[start.first][start.second] = 0;
  while(!q.empty()){
    P tmp = q.front();q.pop();
    int x = tmp.first, y = tmp.second;
    //    cout << x << " " << y << " "<< dist[x][y] << endl;
    for(int i = 0;i < 4;i++){
