using P = pair<int, int>;
int H, W, K;
vector<vector<char>> maze;  // 迷路の内容を保存する配列
vector<vector<int>> dist;   // 距離を記録しておく配列
P s, g;

// 幅優先探索
int bfs(P s) {
    const int INF = 1e8;
    dist.assign(H, vector<int>(W, INF));  // 初期化
    int ans = INF;
    queue<pair<int, int>> que;
    que.emplace(s);
    dist[s.first][s.second] = 0;
    while (que.size() != 0) {
        pair<int, int> now = que.front();
        que.pop();
        int dis = min(now.first, min(now.second, min(H - now.first - 1, W - now.second - 1)));
        chmin(ans, 1 + (dis + K - 1) / K);
        if (dist[now.first][now.second] >= K) continue;
        int dy[4] = {0, 0, 1, -1};  // dx,dy は次の探索場所への距離を表す（４方向分）
        int dx[4] = {1, -1, 0, 0};
        for (int i = 0; i < 4; i++) {
            int ny = now.first + dy[i];
            int nx = now.second + dx[i];
            if (ny < 0 || H <= ny || nx < 0 || W <= nx) continue;
            if (maze[ny][nx] == '#') continue;  // 障害物があればスルー
            if (dist[ny][nx] != INF) continue;
            que.push(make_pair(ny, nx));
            dist[ny][nx] = dist[now.first][now.second] + 1;
        }
    }
    return ans;
}

