                long dx = dxy[di], dy = dxy[di+1];
                long nx = x + dx, ny = y + dy;
                if(!(0 <= nx && nx < w && 0 <= ny && ny < h)) continue;
                if(s.count({ny, nx})) continue;
                if(a[ny][nx] == '#') continue;
                s.insert({ny, nx});
                q.push(make_tuple(d+1, ny, nx));
            }
        }
    }

    auto f = [&](pair<long,long> t) {
        long y, x;
        tie(y, x) = t;
        return min(min(x, y), min(w-1-x, h-1-y));
    };

    long r = 1e9;
    for(auto &t: s) {
        long u = (f(t) + k-1) / k;
        r = min(r, u);
    }
    cout << 1+r << endl;
}

