int bfs(int X, int Y, int n) {
	queue<P>que;
	REP(i, 1000) {
		REP(j, 1000) {
			dist[i][j] = INF;
		}
	}
	int res= min({ X,H - X - 1,Y,W - Y - 1 });
	que.push({ X,Y });
	dist[X][Y] = 0;
	visited[X][Y] = true;
	int cnt = 0;
	while (!que.empty()) {
		if (cnt == n+1)break;
		cnt++;
		int x = que.front().first, y = que.front().second;
		que.pop();
		visited[x][y] = true;
		REP(i, 4) {
			int nx = x + dx[i];
			int ny = y + dy[i];
			if (nx >= 0 && nx < H && ny >= 0 && ny < W) {
				if (visited[nx][ny])continue;
				if (A[nx][ny] != '#') {
					dist[nx][ny] = min(dist[nx][ny], dist[x][y] + 1);
					if (dist[nx][ny] <= n) {
						res = min(res, min({ nx,H - nx - 1,ny,W - ny - 1 }));
						que.push({ nx,ny });
					}
				}
			}
		}
	}
	return res;
}
int dfs(int x,int y,int n) {
	visited[x][y] = true;
	if (n == 0) {
		return min({ x,H - x - 1,y,W - y- 1 });
	}
	int res = min({ x,H - x - 1,y,W - y-1 });
	REP(i, 4) {
		int nx = x + dx[i];
		int ny = y + dy[i];
		if (nx >= 0 && nx < H && ny >= 0 && ny < W) {
			if (visited[nx][ny])continue;
			if (A[nx][ny] != '#') {
				res=min(res,dfs(nx, ny, n - 1));
			}
		}
	}
	return res;
}

