class Node {
public:
    int x, y, d;
    Node(int a, int b, int c) {
        x = a;
        y = b;
        d = c;
    }
};

bool operator>(const Node &lhs, const Node &rhs) {
    return lhs.d > rhs.d;
}

bool operator<(const Node &lhs, const Node &rhs) {
    return lhs.d < rhs.d;
}

int f(int x, int y, int w, int h, int k) {
    int ww = ((x) > (w - x - 1)) ? (w  - x - 1) : (x);
    int hh =((y) > (h - y - 1)) ? (h  - y - 1) : (y);

    ww = (ww + k - 1)/k;
    hh = (hh + k - 1)/k;
    return (ww > hh) ? hh : ww;
}

int main() {
    int hx[4] = {0, 0, 1, -1};
    int hy[4] = {-1, 1, 0, 0};
