            if(s[i][j] == 'S') {
                s[i][j] = '#';
                x = j;
                y = i;
            }
        }
    }

    multiset<Node> q;


    Node node(x, y, 1);

    int ans = f(x, y, w, h, k) + 1;

    q.insert(node);


    while(q.size() > 0) {
        Node now = *q.begin();
        q.erase(q.begin());
        if(now.x < 0 || now.x >= w || now.y < 0 || now.y >= h) {
            ans = 0;
            break;
        }
        if(f(now.x, now.y, w, h, k) + 1 < ans) {
            ans = f(now.x, now.y, w, h, k) + 1;
        }
        if(now.d　-　1 == k) {
