void from_border() {
	queue <ii> q;
	for (int i = 1; i <= n; ++i) for (int j = 1; j <= m; ++j) d[i][j] = -1;
	for (int j = 2; j <= m - 1; ++j) d[1][j] = 1, q.push(ii(1, j));
	for (int j = 2; j <= m - 1; ++j) d[n][j] = 1, q.push(ii(n, j));
	for (int i = 1; i <= n; ++i) d[i][1] = 1, q.push(ii(i, 1));
	for (int i = 1; i <= n; ++i) d[i][m] = 1, q.push(ii(i, m));

	while(!q.empty()) {
		int x = q.front().first, y = q.front().second; q.pop();
		for (int dir = 0; dir < 4; ++dir) {
			int nx = x + dx[dir], ny = y + dy[dir];
			if (nx < 1 || nx > n || ny < 1 || ny > m || d[nx][ny] != -1) continue;
			d[nx][ny] = d[x][y] + 1;
			q.push(ii(nx, ny));
		}
	}
}

int frS[N][N];
void from_S() {
	queue <ii> q;
	for (int i = 1; i <= n; ++i) for (int j = 1; j <= m; ++j) frS[i][j] = -1;
	frS[sx][sy] = 0; q.push(ii(sx, sy));
	while(!q.empty()) {
		int x = q.front().first, y = q.front().second; q.pop();
		for (int dir = 0; dir < 4; ++dir) {
			int nx = x + dx[dir], ny = y + dy[dir];
			if (nx < 1 || nx > n || ny < 1 || ny > m || frS[nx][ny] != -1 || a[nx][ny] == '#') continue;
			frS[nx][ny] = frS[x][y] + 1;
			q.push(ii(nx, ny));
		}
	}
}

