	cin >> n >> m >> k;
	for (int i = 1; i <= n; ++i) for (int j = 1; j <= m; ++j) {
		cin >> a[i][j]; if (a[i][j] == 'S') sx = i, sy = j;
	}
	from_border();
	from_S();

	int ans = 1e9;
	for (int i = 1; i <= n; ++i) for (int j = 1; j <= m; ++j) if (frS[i][j] != -1 && frS[i][j] <= k) {
		int cur = frS[i][j] / k + (frS[i][j] % k != 0);
		for (int dir = 0; dir < 4; ++dir) {
			int nx = i + dx[dir], ny = j + dy[dir];
			if (nx < 1 || nx > n || ny < 1 || ny > m) continue;
			int add = d[nx][ny] / k + (d[nx][ny] % k != 0) + (a[nx][ny] == '#');
			ans = min(ans, add + cur);
		}
	}

