			if (A[i][j] == 'S') { startx = j; starty = i; }
		}
	}

	bfs(startx, starty);

	int ans = 114514;

	for (i = 0; i < H; i++) {
		for (j = 0; j < W; j++) {
			if (found[i][j] && depth[i][j] <= K) {
				int tmp = min(min(min(H - 1 - i, i), W - 1 - j), j);
				if (tmp%K == 0) {
					ans = min(ans, 1 + (tmp / K));
				}
				else {
					ans = min(ans, 2 + (tmp / K));
				}
			}
		}
	}
