	return 0;
}
void bfs(int posx, int posy) {
	queue<pair<int, int> >q;

	q.push(make_pair(posy, posx));
	found[posy][posx] = 1;

	while (!q.empty()) {
		pair<int, int>p = q.front();
		q.pop();
		if (p.first > 0) {
			if (!found[p.first - 1][p.second] && A[p.first - 1][p.second] != '#') {
				q.push(make_pair(p.first - 1, p.second));
				found[p.first - 1][p.second] = true;
				depth[p.first - 1][p.second] = depth[p.first][p.second] + 1;
			}
		}
		if (p.first < H - 1) {
			//下を調査
			if (!found[p.first + 1][p.second] && A[p.first + 1][p.second] != '#') {
				q.push(make_pair(p.first + 1, p.second));
				found[p.first + 1][p.second] = true;
				depth[p.first + 1][p.second] = depth[p.first][p.second] + 1;
			}
		}
		if (p.second > 0) {
			//左を調査
			if (!found[p.first][p.second - 1] && A[p.first][p.second - 1] != '#') {
				q.push(make_pair(p.first, p.second - 1));
				found[p.first][p.second - 1] = true;
				depth[p.first][p.second - 1] = depth[p.first][p.second] + 1;
			}
		}
		if (p.second < W - 1) {
			//右を調査
			if (!found[p.first][p.second + 1] && A[p.first][p.second + 1] != '#') {
				q.push(make_pair(p.first, p.second + 1));
				found[p.first][p.second + 1] = true;
				depth[p.first][p.second + 1] = depth[p.first][p.second] + 1;
			}
		}
	}

}

