int main(void)
{
	cin >> h >> w >> k;
	for (int i = 0; i < h; ++i)
	{
		string s;
		cin >> s;
		brd.push_back(s);
	}
	int sx, sy;
	for (int i = 0; i < h; ++i)for (int j = 0; j < w; ++j)
	{
