		{
			brd[i][j] = '.';
			sx = i;
			sy = j;
		}
	}
	memset(dist, 0xff, sizeof(dist));
	int ans = INT_MAX;
	queue<pair<pair<int, int>, int>>que;
	dist[sx][sy] = 0;
	que.push({ {sx,sy},0 });
	while (!que.empty())
	{
		auto par = que.front();
		que.pop();
		int i = par.first.first;
		int j = par.first.second;
		int dis = par.second;
		if (i < 0 || j < 0 || i >= h || j >= w)
		{
			//距離0の#と扱う
			int can = max(1, ceil_m(dis, k));
			ans = min(ans, can);
			continue;
		}
		if (brd[i][j] == '#')
		{
			int P = min({ h - i,i + 1 ,w - j ,j + 1 });
			int can = max(ceil_m(P, k) + 1, ceil_m(dis + P - 1, k));
			ans = min(ans, can);
			continue;
		}
		for (int dir = 0; dir < 4; ++dir)
		{
			int ii = i + dxy[dir];
			int jj = j + dxy[dir + 1];
			if (ii < 0 || jj < 0 || ii >= h || jj >= w)
			{
				que.push({ { ii,jj },dis + 1 });
			}
			else
			{
				if (dist[ii][jj] < 0)
				{
					dist[ii][jj] = dis + 1;
					que.push({ {ii,jj},dis + 1 });
				}
			}
		}
	}
	cout << ans << endl;
	return 0;
}

