const int dx[4] = {1, 0, -1, 0}, dy[4] = {0, 1, 0, -1};
const int INF = 1e8;

struct point {
  int x, y;
};

void solve(long long H, long long W, long long K, std::vector<std::string> A) {
  vector<vl> dp(H, vl(W, -1));

  queue<point> q;
  rep(i, 0, H) {
    rep(j, 0, W) {
      if (A[i][j] == 'S') {
        q.push((point){i, j});
      }
    }
  }

  // K回までで移動できるところに移動
  vector<point> next;
  int cnt = 1;
  while (!q.empty()) {
    point p = q.front();
    q.pop();

    if (A[p.x][p.y] == '#') {
      continue;
    }

    if (dp[p.x][p.y] == -1) {
      next.push_back(p);
      dp[p.x][p.y] = cnt;

      rep(k, 0, 4) {
        int nx = p.x + dx[k];
        int ny = p.y + dy[k];

        if (nx >= 0 && nx < H && ny >= 0 && ny < W) {
          q.push((point){nx, ny});
        }
      }
    }
  }

  // K以内で進めるところに移動し続ける
  while (!next.empty()) {
    cnt++;

    queue<pair<point, int>> qq;
    for (auto p : next) {
      qq.push(mp(p, K));
    }

    vector<point> tmpNext;
    while (!qq.empty()) {
      auto p = qq.front().first;
      auto r = qq.front().second;
      qq.pop();

      if (r < 0) {
        continue;
      }

      if (dp[p.x][p.y] != -1 && dp[p.x][p.y] != cnt - 1) {
        continue;
      }

      if (dp[p.x][p.y] == -1) {
        tmpNext.push_back((point){p.x, p.y});
        dp[p.x][p.y] = cnt;
      }

      rep(k, 0, 4) {
        int nx = p.x + dx[k];
        int ny = p.y + dy[k];

        if (nx >= 0 && nx < H && ny >= 0 && ny < W && dp[nx][ny] == -1) {
          qq.push(mp((point){nx, ny}, r - 1));
        }
      }
    }
    next = tmpNext;
  }

  ll ans = 1e9;
  rep(i, 0, H) {
    chmin(ans, dp[i][0]);
    chmin(ans, dp[i][W - 1]);
  }
  rep(i, 0, W) {
    chmin(ans, dp[0][i]);
    chmin(ans, dp[H - 1][i]);
  }
  print(ans);
}

int main() {
  long long H;
  scanf("%lld", &H);
  long long W;
  scanf("%lld", &W);
  long long K;
  scanf("%lld", &K);

  vector<string> A(H);
  for (int i = 0; i < H; i++) {
    cin >> A[i];
  }
  solve(H, W, K, std::move(A));
  return 0;
}

