void bfs(int x, int y) {

	dis[x][y] = 0;
	queue<pair<int, int> > q;
	q.push( { x, y });
	int T = min(x, min(R - x - 1, min(C - y - 1, y)));
	v.push_back((T + K - 1) / K);
	while (!q.empty()) {
		x = q.front().first;
		y = q.front().second;
