			if (tx < 0 || tx >= R || ty < 0 || ty >= C || dis[tx][ty] != -1
					|| g[tx][ty] != '.') continue;
			dis[tx][ty] = dis[x][y] + 1;
			int T = min(tx, min(R - tx - 1, min(C - ty - 1, ty)));
			v.push_back((T + K - 1) / K);
		}
	}
}

