struct state
{
    int cnt;
    int move;
    int blast;

    state() : cnt(INF), move(0), blast(0){}
    state(int cnt, int move, int blast) : cnt(cnt), move(move), blast(blast){}
    bool operator<(const state& s) const
    {
        if (cnt < s.cnt) return true;
        if (cnt == s.cnt && move > s.move) return true;
        if (cnt == s.cnt && move == s.move && blast > s.blast) return true;
        return false;
    }

    state next(char current, char dest) const
    {
        state ns = *this;
        if (dest == '#'){
            if (current == '.' && blast <= k) ns.move = 0;
            --ns.blast;
            if (ns.blast < 0){
                ns.move += k;
                ns.blast = k;
                ++ns.cnt;
            }
        }
        --ns.move;
