int DX[4] = {-1, 0, 1, 0};
int DY[4] = {0, -1, 0, 1};

int H, W, K;
int SX, SY;
char A[800][800];
int D[800][800];

signed main() {
  ios::sync_with_stdio(false); cin.tie(0);
  cin >> H >> W >> K;
  rep(y, H) {
    rep(x, W) {
      cin >> A[x][y];
      if (A[x][y] == 'S') SX = x, SY = y;
    }
  }
