int main() {
    int H, W, K;
    cin >> H >> W >> K;

    int sx,sy;
    rep(i, H) rep(j, W) {
        cin >> f[i][j];
        d[i][j] = 1e8;
        if (f[i][j] == 'S') sy=i, sx=j;
    }

    d[sy][sx] = 0;
    queue< pair<int, int> > que;
    que.push({ sy, sx });

    const int dx[] = { 1, 0, -1, 0 };
    const int dy[] = { 0, 1, 0, -1 };
    while (que.size()) {
        pair<int, int> p = que.front();
        que.pop();

        if (d[p.first][p.second] >= K) {
            continue;
        }

        rep(dd, 4) {
            int py = p.first + dy[dd];
            int px = p.second + dx[dd];
            if (0 <= py && py < H && 0 <= px && px < W && f[py][px] == '.' && d[py][px] == 1e8) {
                d[py][px] = d[p.first][p.second] + 1;
                que.push({ py, px });
            }
        }
    }

    int ans=1e8;
    rep(y, H) rep(x, W) {
        if (d[y][x] != 1e8) {
            int Y = min(y, H-y-1);
            int X = min(x, W-x-1);
            ans = min(ans, min(Y/K+bool(Y%K), X/K+bool(X%K)));
        }
    }

    cout << ans+1 << endl;
}

