    function<int(int, int, int)> bfs = [&](int x, int y, int count)
    {
        queue<P> que;
        que.push(P(x, y));
        d[x][y] = true;
        int tmp = min(min(x, h-x-1), min(y, w-y-1));
        while(count--)
        {
            queue<P> nque;
            while(que.size())
            {
                P p = que.front();
                que.pop();
                int mi = min(min(p.first, h-p.first-1), min(p.second, w-p.second-1));
                tmp = min(tmp, mi);
                for(int i = 0; i < 4; i++)
                {
                    int nx = p.first+dx[i];
                    int ny = p.second+dy[i];
                    if(0 <= nx && nx < h && 0 <= ny && ny < w && field[nx][ny] == '.' && d[nx][ny] == false)
                    {
                        d[nx][ny] = true;
                        nque.push(P(nx, ny));
                    }
                }
            }
            que = nque;
        }
        return tmp;
    };
    int mi = bfs(x, y, k);
    if(mi == 0) cout << 1 << endl;
    else
    {
        cout << (mi-1) / k + 2 << endl;
    }
}

