	for(int i=0;i<h;i++){
		cin >> s;
		v.push_back(s);
	}
	queue<pair<int,int> > q;
	int flag[802][802]={};
	for(int i=0;i<h;i++){
		for(int j=0;j<w;j++){
			if(v[i][j]=='S'){
				flag[i][j]=1;
				q.push(make_pair(i,j));
			}else if(v[i][j]=='#'){
				flag[i][j]=-1;
			}
		}
	}
	int count =0;
	pair<int,int> p;
	int x,y;
	while(!q.empty()&&count<k){
		p = q.front();
		q.pop();
		x = p.first;
		y = p.second;
		if(x+1<h){
			if(flag[x+1][y]==0){
				flag[x+1][y]=1;
				q.push(make_pair(x+1,y));
			}
		}
		if(y+1<w){
			if(flag[x][y+1]==0){
				flag[x][y+1]=1;
				q.push(make_pair(x,y+1));
			}
		}
		if(x>0){
			if(flag[x-1][y]==0){
				flag[x-1][y]=1;
				q.push(make_pair(x-1,y));
			}
		}
		if(y>0){
			if(flag[x][y-1]==0){
				flag[x][y-1]=1;
				q.push(make_pair(x,y-1));
			}
		}
