		for(int j=0;j<w;j++){
			if(flag[i][j]==1){
				tmp = std::min(i,j);
				tmp = std::min(tmp,h-i-1);
				tmp = std::min(tmp,w-j-1);
				if(min>tmp){
					min = tmp;
				}
			}
		}
	}
	if(min==0){
		cout << 1 << endl;
	}else{
		if(min%k==0){
			cout << 1+min/k <<endl;
		}else{
			cout << 1+min/k+1 <<endl;
		}
	}
	return 0;
}

