				continue;
			}
			A[p.first][p.second] = 'k';
			p.first++;
			que.push(p);
			p.first -= 2;
			que.push(p);
			p.first++;
			p.second++;
			que.push(p);
			p.second -= 2;
			que.push(p);
		}
	}

	int ans = 1000;

	for(int i = 0; i < H; i++){
		for(int j = 0; j < W; j++){
			if(A[i][j] == 'k'){
				int dist = min(min(min(i, j), H - 1 - i), W - 1 - j);
				ans = min(ans, (dist - 1) / K + 2);
				if(dist == 0){
					ans = 1;
				}
			}
		}
	}

	cout << ans << endl;

	return 0;
}

