const int MAX_K = MAX_HW * MAX_HW;
char board[MAX_HW][MAX_HW];
int visited[MAX_HW][MAX_HW][MAX_HW / 2];
int sy,sx;
int main() {
  cin >> H >> W >> K;
  for (int i = 0; i < H; i++){
    for (int j = 0; j < W; j++){
      cin >> board[i][j];
      if (board[i][j] == 'S'){
        sy = i;
        sx = j;
      }
    }
  }
