  que.emplace(mp(mp(sy, sx), mp(0, 0)));
  int result = 1 << 30;
  while (not que.empty()){
    auto p = que.front();
    que.pop();
    auto pos = p.first;
    auto state = p.second;
    int py,px;
    py = pos.first;
    px = pos.second;

    int cost,rest;
    cost = state.first;
    rest = state.second;
    if (result < cost)continue;
    if (visited[py][px][rest])continue;
    visited[py][px][rest] = true;
    //goal
    if (py == 0 or py == H - 1 or px == 0 or px == W - 1){
      result = min(result, cost);
      continue;
