int main() {
    cout<<fixed<<setprecision(10);

    ll h,w,k; cin>>h>>w>>k;
    vector<vector<char>> a(h, vector<char>(w)); rep(i,h)rep(j,w) cin>>a[i][j];

    using P = pair<ll,ll>;
    auto isOutside = [&](P &p){
        ll r,c;
        tie(r,c) = p;
        return r < 0 or r >= h or c < 0 or c >= w;
    };

    auto getDist = [&](P &p){
        ll r,c;
        tie(r,c) = p;
        return min({r, h-1-r, c, w-1-c});
    };

    auto isWall = [&](P &p){
        ll r,c;
        tie(r,c) = p;
        return a[r][c] == '#';
    };

    P st;

    rep(i,h){
        rep(j,w){
            if(a[i][j] == 'S') st = mp(i,j);
        }
    }

    queue<P> q;
    q.push(st);
    set<P> canReach;

    ll d = LLONG_MAX;

    while(!q.empty()){
        P cur = q.front();
        q.pop();
        if(canReach.count(cur)) continue;
        canReach.insert(cur);
        chmin(d, getDist(cur));

        rep(i,4){
            P nxt = cur;
            nxt.first += dx[i];
            nxt.second += dy[i];
            if(isOutside(nxt)) continue;
            if(canReach.count(nxt)) continue;
            if(isWall(nxt)) continue;
            q.push(nxt);
        }
    }

    cout<<1+(d+k-1)/k<<endl;


    return 0;

}

