typedef pair<int, int> ii;
const int Nmax  = 900;

int n, m, k, d[Nmax][Nmax], ans = 1e9 + 10;
char a[Nmax][Nmax];
ii s, mv[] = {ii(-1, 0), ii(1, 0), ii(0, -1), ii(0, 1)};
queue<ii> qu;

void visit() {
    qu.push(s);
    while(!qu.empty()) {
        ii u = qu.front(); qu.pop();
        if (d[u.first][u.second] == k) continue;
        for(int i = 0; i < 4; ++i) {
            int x = u.first + mv[i].first, y = u.second + mv[i].second;
            if (a[x][y] == '#') continue;
            if (x == 1 || x == n+1 || y == 1 || y == m+1) continue;
            if (d[x][y] == -1) {
                d[x][y] = d[u.first][u.second] + 1;
                qu.push(ii(x, y));
            }
        }
    }
}

int main() {
    //freopen("in.txt", "r", stdin);
    ios::sync_with_stdio(0); cin.tie(0);
    memset(d, -1, sizeof(d));
    cin >> n >> m >> k;
    FOR(i, 1, n) FOR(j, 1, m) {
        cin >> a[i][j];
        if (a[i][j] == 'S') s = ii(i, j);
    }
    d[s.first][s.second] = 0;
    visit();
    FOR(i, 1, n) FOR(j, 1, m) {
        if (d[i][j] == -1) continue;
        int tmp = min(min(i-1, n-i), min(j-1, m-j));
        tmp = ceil(float(tmp)/k);
        ans = min(ans, 1 + tmp);
    }
    cout << ans;
}

