			if(grid[i][j] == 'S') {
				starty = i;
				startx = j;
				starty2 = i;
				startx2 = j;
				break;
			}
		}
	}

	ll steps;
	ll mindist = INT_MAX;

	// up
	starty = starty2;
	startx = startx2;
	steps = k;
	mindist = min(mindist, starty);
	while(steps > 0) {
		if(starty > 0 && grid[starty-1][startx] != '#') {
			starty--;
			steps--;
			mindist = min(mindist, starty);
		}
		else break;
	}

	// down
	starty = starty2;
	startx = startx2;
	steps = k;
	mindist = min(mindist, h-starty-1);
	while(steps > 0) {
		if(starty < h-1 && grid[starty+1][startx] != '#') {
			starty++;
			steps--;
			mindist = min(mindist, h-starty-1);
		}
		else break;
	}

	// left
	starty = starty2;
	startx = startx2;
	steps = k;
	mindist = min(mindist, startx);
	while(steps > 0) {
		if(startx > 0 && grid[starty][startx-1] != '#') {
			startx--;
			steps--;
			mindist = min(mindist, startx);
		}
		else break;
	}

	// right
	starty = starty2;
	startx = startx2;
	steps = k;
	mindist = min(mindist, w-startx-1);
	while(steps > 0) {
		if(startx < w-1 && grid[starty][startx+1] != '#') {
			startx++;
			steps--;
			mindist = min(mindist, w-startx-1);
		}
		else break;
	}

	// cout<<"mindist: "<<mindist<<endl;

	starty = starty2;
	startx = startx2;

	ll temp = magic(starty, startx);
	// cout<<"temp: "<<temp<<endl;
	ll ans = min(1 + mindist / k + (mindist % k > 0), temp / k + (temp % k > 0));

	cout<<ans<<endl;

}

