      pos.x = j;
      pos.y = i;
      break;
    }

    q.push({ pos,0 });
  }
  int mini = INF;
  while (q.size()) {
    auto p = q.front();
    q.pop();
    auto pos = p.first;
    auto cost = p.second;
    amin(mini, dfs(q, pos, cost + 1, k));
  }
  cout << (mini) << endl;


  err(a);
}

