int calc(int x,int y)
{
	if (min(min(x-1,n-x),min(y-1,m-y))==0) return 0;
	return (min(min(x-1,n-x),min(y-1,m-y))-1)/k+1;
}
void dfs(int x,int y,int deep)
{
	vis[x][y]=1;
	ans=min(ans,calc(x,y));
	for (int i=0;i<4;i++)
	{
