using namespace std;

const int INF = 0x3f3f3f3f;
const int N = 1e5+20;
const double eps = 1e-8;

char mp[1000][1000];
int dir[4][2] = {1, 0, -1, 0, 0, 1, 0, -1};
int vis[1000][1000];
int n, m, k;
int bfs(int sx, int sy)
{
	MMF(vis);
	int ans = INF;
	queue<PII >q;
	q.push(MP(sx, sy));
	while(!q.empty())
	{
		PII nw = q.front();
		q.pop();
		int sp = min(min(nw.fi - 1, nw.se - 1), min(n - nw.fi , m - nw.se));
		ans = min(sp / k + ((sp%k)?1:0), ans);
		for(int i = 0; i < 4; i++)
		{
			int nx = nw.fi + dir[i][0];
			int ny = nw.se + dir[i][1];
			if(nx > 0 && ny > 0 && nx <= n && ny <= m && mp[nx][ny] == '.')
			{
				if(!vis[nx][ny] && abs(nx - sx + ny - sy) <= k)
					vis[nx][ny] = 1, q.push(MP(nx, ny));
			}
		}
	}
	return ans;
}

