#define maxn 810
int h, w, k, sh, sw;
int g[maxn][maxn];
int moves[maxn][maxn];
int r_idx[] = {-1, 1, 0, 0};
int c_idx[] = {0, 0, -1, 1};

priority_queue< pair<int, PII> > Q;
void unlock(int dist, int r, int c, int cnt) {
  g[r][c] = 1;
  if (cnt == k) return;
//  printf("UNLOCK: (%d, %d) at dist %d, type %d, moves[r][c] = %d, cnt = %d\n", r, c, dist, g[r][c], moves[r][c], cnt);

  FORN(i, 4) {
    int nr = r + r_idx[i];
    int nc = c + c_idx[i];
    if (nr < 1 || nr > h || nc < 1 || nc > w) continue;

    if (moves[nr][nc] >= 0) continue;
    if (g[nr][nc] != 0) continue;
    if (cnt == k) continue;
    else {
      unlock(dist, nr, nc, cnt+1);
    }
  }
}

void step(int dist, int r, int c, int cnt) {
//  printf("STEP: (%d, %d) at dist %d, moves[r][c] = %d\n", r, c, dist, moves[r][c]);
  moves[r][c] = dist;
  FORN(i, 4) {
    int nr = r + r_idx[i];
    int nc = c + c_idx[i];

    if (nr < 1 || nr > h || nc < 1 || nc > w) continue;
    if (moves[nr][nc] >= 0) continue;

    if (g[nr][nc] == 0 || cnt == k);
    else {
      Q.push(MP(-dist, MP(nr, nc)));
//      printf("         PUSHING (%d, %d) at dist %d, moves[nr][nc] = %d\n", nr, nc, dist, moves[nr][nc]);

      step(dist, nr, nc, cnt+1);
    }
  }

//  printf("Unlocking for STEP: (%d, %d) at dist %d, moves[r][c] = %d\n", r, c, dist, moves[r][c]);
  FORN(i, 4) {
    int nr = r + r_idx[i];
    int nc = c + c_idx[i];

    if (nr < 1 || nr > h || nc < 1 || nc > w) continue;
    if (moves[nr][nc] >= 0) continue;

    if (g[nr][nc] == 0 || cnt == k) unlock(dist, nr, nc, 1);
  }
}

int main() {
  GI(h); GI(w); GI(k);
  memset(moves, -1, sizeof moves);

  FOR1(i, h) {
    string line; cin >> line;
    FORN(j, w) {
      if (line[j] == '#') g[i][j+1] = 0;
      else g[i][j+1] = 1;

      if (line[j] == 'S') {
        sh = i; sw = j+1;
      }
    }
  }

  Q.push( MP(0, MP(sh, sw)) );
  while (Q.size() > 0) {
    pair<int, PII> node = Q.top(); Q.pop();
    int dist = -node.FF;
    int r = node.SS.FF;
    int c = node.SS.SS;
    moves[r][c] = dist;

//    printf("--------------------------- (%d, %d) at dist %d\n", r, c, dist);

    if (r == h || r == 1 || c == w || c == 1) {
      printf("%d\n", dist);
      return 0;
    }

    step(dist+1, r, c, 0);
    if (Q.size() == 0) {
      Q.push(MP(-dist-1, MP(r, c)));
    }
  }
  return 0;
}

