int H, W, K;
string s[810];
int memo[810][810];

const int INF = 1001001001;
const int dr[] = {0, 1, 0, -1};
const int dc[] = {1, 0, -1, 0};

void bfs(int r, int c, int walk) {
  REP(i, H) REP(j, W) memo[i][j] = INF;
  memo[r][c] = 0;
  queue<int> q;
  q.push(r); q.push(c);
  while (q.size() > 0) {
    r = q.front(); q.pop();
    c = q.front(); q.pop();
    if (memo[r][c] == walk) break;
    for (int i = 0; i < 4; i++) {
      int nr = r + dr[i];
      int nc = c + dc[i];
      if (0 <= nr && nr < H && 0 <= nc && nc < H && s[nr][nc] == '.' && memo[nr][nc] == INF) {
        memo[nr][nc] = memo[r][c] + 1;
        q.push(nr);
        q.push(nc);
      }
    }
  }
}

int ceil(int r, int x) {
  return (r + x - 1) / x;
}

int f(int r, int c) {
  if (r == 0 || c == 0 || r == H - 1 || c == W - 1) return 0;
  return min({
    ceil(r, K),
    ceil(H - 1 - r, K),
    ceil(c, K),
    ceil(W - 1 - c, K)});
}

int main2() {
  cin >> H >> W >> K;
  REP(i, H) cin >> s[i];

  int si = 0, sj = 0;
  REP(i, H) REP(j, W) if (s[i][j] == 'S') {
    si = i; sj = j; s[i][j] = '.'; break;
  }
  bfs(si, sj, K);

  int ans = INF;
  REP(i, H) REP(j, W) {
    if (memo[i][j] <= K) {
      chmin(ans, f(i, j) + 1);
    }
  }
  cout << ans << endl;
  return 0;
}

int main() {
  for (;!cin.eof();cin>>ws)
    main2();
  return 0;
}

