    while(!Q.empty()) {
        pair<pair<ll,ll>,ll> p = Q.front();
        Q.pop();
        vp.push_back(p.first);
        if(p.second==0) continue;
        if(p.first.first-1>=0) {
            if(A[p.first.first-1][p.first.second]=='.') {
                if(M[make_pair(p.first.first-1,p.first.second)]>0) continue;
                M[make_pair(p.first.first-1,p.first.second)]++;
                Q.push(make_pair(make_pair(p.first.first-1,p.first.second),p.second-1));
            }
        }
        if(p.first.first+1>=0) {
            if(A[p.first.first+1][p.first.second]=='.') {
                if(M[make_pair(p.first.first+1,p.first.second)]>0) continue;
                M[make_pair(p.first.first+1,p.first.second)]++;
                Q.push(make_pair(make_pair(p.first.first+1,p.first.second),p.second-1));
            }
        }
        if(p.first.second-1>=0) {
            if(A[p.first.first][p.first.second-1]=='.') {
                if(M[make_pair(p.first.first,p.first.second-1)]>0) continue;
                M[make_pair(p.first.first,p.first.second-1)]++;
