void go(int x, int y) {
	for (int i = 0; i < h; i++) for (int j = 0; j < w; j++) dist[i][j] = 1 << 30;
	dist[x][y] = 0;
	pq.push({0, {x, y}});
	int d;
	while (!pq.empty()) {
		auto v = pq.top(); pq.pop();
		d = v.fst, x = v.snd.fst, y = v.snd.snd;
		if (d > dist[x][y]) continue;
		for (int k = 0; k < 4; k++) {
			int xk = x + dx[k];
			int yk = y + dy[k];
			if (xk < 0 || xk >= h || yk < 0 || yk >= w) continue;
			if (grid[xk][yk] == '#') {
				if (dist[xk][yk] > dist[x][y] + 1) {
					dist[xk][yk] = dist[x][y] + 1;
					pq.push({dist[xk][yk], {xk, yk}});
				}
			} else {
				if (dist[xk][yk] > dist[x][y]) {
					dist[xk][yk] = dist[x][y];
					pq.push({dist[xk][yk], {xk, yk}});
				}
			}
		}
	}
}

