ll solve(pair<ll, ll> s){
    //dfs(que, s.first, s.second, K);
    queue<pair<pair<ll, ll>, ll>> que2;
    que2.push(mp(s, K));
    set<pair<ll, ll>> pos;
    while(!que2.empty()){
        auto p = que2.front();
        que2.pop();
        ll num = p.second;
        auto po = p.first;
        ll y, x;
        tie(y, x) = po;
        if(y >= H) continue;
        if(x >= W) continue;
        if(y < 0) continue;
        if(x < 0) continue;
        if(isvisit[y][x]) continue;
        if(num < 0) continue;
        if(!X[y][x]) continue;

        isvisit[y][x] = true;
        pos.insert(po);
        que2.push(mp(mp(y+1, x), num-1));
        que2.push(mp(mp(y-1, x), num-1));
        que2.push(mp(mp(y, x+1), num-1));
        que2.push(mp(mp(y, x-1), num-1));
    }


    ll ans = 1000;
    for(auto&& p : pos){
        ll y = p.first;
        ll x = p.second;
        ll dist = 1000;
        chmin(dist, y);
        chmin(dist, x);
        chmin(dist, H-1-y);
        chmin(dist, W-1-x);
        chmin(ans, dist/K + (dist%K != 0));
    }
    return ans+1;
}

