char s[maxn][maxn];

bool inside(int x, int y) {
  return 0 <= x && x < n && 0 <= y && y < m;
}

int curx, cury;
int k;

bool read() {
  if (scanf("%d%d%d", &n, &m, &k) < 3) {
    return false;
  }
  for (int i = 0; i < n; i++) {
    scanf("%s", s[i]);
  }
  return true;
}

int dist[maxn][maxn];

void solve() {
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < m; j++) {
      if (s[i][j] == 'S') {
        eprintf("!\n");
        curx = i, cury = j;
      }
      dist[i][j] = inf;
    }
  }
  vector<pair<int, int> > q(1, mp(curx, cury));
  dist[curx][cury] = 0;
  int res = inf;
  for (int i = 0; i < sz(q); i++) {
    int curx = q[i].first;
    int cury = q[i].second;
    eprintf("%d %d\n", curx, cury);
    if (dist[curx][cury] > k) {
      break;
    }
    res = min(res, 1 + (min(min(curx, n - 1 - curx), min(cury, m - 1 - cury)) + k - 1) / k);
    for (int j = 0; j < 4; j++) {
      int nx = curx + gox[j];
      int ny = cury + goy[j];
      if (dist[nx][ny] < inf) {
        continue;
      }
      if (!inside(nx, ny)) {
        continue;
      }
      if (s[nx][ny] == '#') {
        continue;
      }
      dist[nx][ny] = dist[curx][cury] + 1;
      q.pb(mp(nx, ny));
    }
  }
  printf("%d\n", res);
}

