const int INF = 1e9;

int nokori(int i, int j, int h, int w){
    return min({i, j, h-i-1, w-j-1});
}

int main(){
    int h, w, k;
    cin >> h >> w >> k;
    vector<string> s(h);
    REP(i,h) cin >> s[i];
    int si, sj;
    REP(i,h) REP(j,w) if (s[i][j] == 'S') si = i, sj = j;

    VVI dist(h, VI(w, INF));
    queue<P> que;
    que.push(P(si,sj));
    dist[si][sj] = 0;
    int di[] = {1,-1,0,0}, dj[] = {0,0,1,-1};
    while (!que.empty()){
        P p = que.front();
        que.pop();
        int i = p.first, j = p.second;
        REP(k,4){
            int ii = i + di[k], jj = j + dj[k];
            if (ii < 0 || ii >= h || jj < 0 || jj >= w || s[ii][jj] == '#') continue;
            if (dist[ii][jj] != INF) continue;
            dist[ii][jj] = dist[i][j] + 1;
            if (dist[ii][jj] == k) continue;
            que.push(P(ii,jj));
        }
    }

    int ans = INF;
    REP(i,h) REP(j,w){
        if (dist[i][j] == INF) continue;
        ans = min(ans, 1 + (nokori(i, j, h, w)+k-1)/k);
    }
    cout << ans << endl;

    return 0;
}

