V<V<int>> dirs = {{0,1},{0,-1},{1,0},{-1,0}};

bool check(int allowed, int moves) {
	V<V<int>> vis(R, V<int>(C));
	queue<tuple<int, int, int, int>> Q;
	Q.emplace(sr, sc, 0, 0);
	vis[sr][sc] = 1;
	while (Q.size()) {
		int r, c, seen, dist;
		tie(r, c, seen, dist) = Q.front();
		// cout << r << " " << c << endl;
		Q.pop();
		if (r == 0 || c == 0)
			return 1;
		for (const auto& dir : dirs) {
			int cr = r+dir[0], cc = c+dir[1];
			// cout << " " << cr << " " << cc << endl;
			if (cr < 0 || cr >= R || cc < 0 || cc >= C)
				continue;
			if (vis[cr][cc])
				continue;
			if (seen + (G[cr][cc]=='#') > allowed)
				continue;
			if (dist+1 > moves)
				continue;
			Q.emplace(cr, cc, seen + (G[cr][cc]=='#'), dist+1);
			vis[cr][cc] = 1;
		}
	}
	return 0;
}

int solve_fast() {
	int lo = 1, hi = R*C+100;
	while (lo < hi) {
		int mid = (lo+hi)/2;
		int64_t num = int64_t(mid-1)*int64_t(K);
		if (num > R*C)
			num = R*C;
		// cout << mid << " " << num << " " << check(num, num+K) << endl;
		if (check(num, num+K)) {
			hi = mid;
		} else {
			lo = mid+1;
		}
	}
	return lo;
}

int solve_slow() {
	V<V<unordered_map<int, bool>>> vis(R, V<unordered_map<int, bool>>(C));
	V<V<int>> dist(R, V<int>(C, 1e9));
	queue<tuple<int, int, int, int>> Q;
	Q.emplace(sr, sc, 0, 0);
	vis[sr][sc][0] = 1;
	dist[sr][sc] = 1;
	while (Q.size()) {
		int r, c, seen, d;
		tie(r, c, seen, d) = Q.front();
		dist[r][c] = min(dist[r][c], max(seen/K + bool(seen%K) + 1, d/K + bool(d%K)));
		// cout << r << " " << c << " " << seen << " " << d << endl;
		Q.pop();
		for (const auto& dir : dirs) {
			int cr = r+dir[0], cc = c+dir[1];
			// cout << " " << cr << " " << cc << endl;
			if (cr < 0 || cr >= R || cc < 0 || cc >= C)
				continue;
			if (seen + (G[cr][cc]=='#') > 20)
				continue;
			if (vis[cr][cc][seen + (G[cr][cc]=='#')])
				continue;
			Q.emplace(cr, cc, seen + (G[cr][cc]=='#'), d+1);
			vis[cr][cc][seen + (G[cr][cc]=='#')] = 1;
		}
	}
	int ans = 1e9;
	REP(r, R) {
		ans = min(ans, dist[r][0]);
	}
	REP(c, C) {
		ans = min(ans, dist[0][c]);
	}
	return ans;
}

