int h, w, k;
vector<vector<int>> grid;

int x, y;

int val(int x1, int y1)
{
    int ans = 1e9;
    ans = min(ans, (x1+k-1)/k);
    ans = min(ans, (y1+k-1)/k);
    ans = min(ans, (w-1-x1 + k-1)/k);
    ans = min(ans, (h-1-y1 + k-1)/k);
    return ans;
}

bool check_valid(int x1, int y1)
{
    return (0<=x1 && x1<w && 0<=y1 && y1<h);
}

queue<pair<pair<int, int>, int>> q;

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(nullptr);
    cin>>h>>w>>k;

    grid = vector<vector<int>> (h, vector<int>(w));

    string s;
    for (int i = 0; i<h; i++)
    {
        cin>>s;
        for (int j = 0; j<w; j++)
        {
            if (s[j]=='#') grid[i][j] = 2;
            if (s[j]=='S') {x = j; y = i;}
        }
    }

    int ans = 1e9;

    q.push(mp(mp(x, y), k));
    grid[x][y] = 1;
    while (!q.empty())
    {
        auto cell = q.front();
        q.pop();
        int x1 = cell.first.first;
        int y1 = cell.first.second;
        ans = min(ans, 1 + val(x1, y1));
        int left = cell.second;
        if (left==0) continue;
        if (check_valid(x1-1, y1) && grid[x1-1][y1]==0) {grid[x1-1][y1] = 1; q.push(mp(mp(x1-1, y1), left-1));}
        if (check_valid(x1+1, y1) && grid[x1+1][y1]==0) {grid[x1+1][y1] = 1; q.push(mp(mp(x1+1, y1), left-1));}
        if (check_valid(x1, y1-1) && grid[x1][y1-1]==0) {grid[x1][y1-1] = 1; q.push(mp(mp(x1, y1-1), left-1));}
        if (check_valid(x1, y1+1) && grid[x1][y1+1]==0) {grid[x1][y1+1] = 1; q.push(mp(mp(x1, y1+1), left-1));}
    }

    cout<<ans;



}

