// クラスカル法
// 連結グラフの最小全域木を求める
class Kruskal {
private:
  Graph graph;
  vector<Edge> MinimumSpanningTree;
  ll minimumCost;
  void searchMinimumSpanningTree() {
    UnionFindTree uf(graph.nodes);
    sort(all(graph.edges));
    itrep(edge, graph.edges) {
      if (!uf.same(edge->from, edge->to)) {
        uf.unite(edge->from, edge->to);
        MinimumSpanningTree.push_back(*edge);
      }
    }
  }

public:
  Kruskal(Graph graph) { this->graph = graph; }
  ll getMinimumSpanningTreeCost() {
    searchMinimumSpanningTree();
    ll cost = 0;
    itrep(it, MinimumSpanningTree) { cost += it->cost; }
    return cost;
  }
};

// ダイクストラ法 O((E+V)logV)
// 最小経路問題を解くためのアルゴリズム。辺の重みに負数を含む場合は利用不可
// 無向グラフの場合はコメントアウト箇所をコメントイン
class Dijkstra {
private:
  Graph graph;
  map<ll, vector<Edge>> fromPaths;
  vl distances;
  vl srcs;

public:
  Dijkstra(Graph graph) {
    this->graph = graph;
    itrep(edge, graph.edges) {
      fromPaths[edge->from].push_back(*edge);
      // fromPaths[edge->to].push_back(Edge(edge->to, edge->from, edge->cost));
    }
  }
  void searchMinimumPathFrom(ll src) {
    // 複数回呼ばれる度に計算する
    distances = vl(graph.nodes + 1, INF);
    srcs = vl(graph.nodes + 1, INF);

    // 距離が近い順番に捜査していく
    priority_queue<pll, vector<pll>, greater<pll>> pq;
    distances[src] = 0;
    srcs[src] = -1;

    pq.push(mp(0ll, src));
    while (!pq.empty()) {
      int u = pq.top().second;
      double uw = pq.top().first;
      pq.pop();

      if (distances[u] < uw) {
        continue;
      };

      itrep(edge, fromPaths[u]) {
        int v = edge->to;
        ll w = edge->cost;
        if (distances[v] > distances[u] + w) {
          distances[v] = distances[u] + w;
          srcs[v] = u;
          pq.push(mp(distances[v], v));
        }
      }
    }
  };
  ll getDistance(ll n) { return distances[n]; }
  ll getFrom(ll n) { return srcs[n]; }
};

// ベルマンフォード O(|V||E|)
// 負コストが含まれていても最短経路問題を解くためのアルゴリズム。閉路の検出も可能
// 有向グラフ
class BellmanFord {
private:
  Graph graph;
  // 閉路が含まれるかは個々のノードごとに管理する必要あり
  vector<bool> hasNegativeCycles;
  vector<ll> distances;
  vl srcs;

public:
  BellmanFord(Graph graph) {
    ll nodes = graph.nodes + 1;

    this->graph = graph;
    distances = vector<ll>(nodes, INF);
    hasNegativeCycles = vector<bool>(nodes, false);
  }
  void searchMinimumPathFrom(ll src) {
    distances[src] = 0;

    for (ll i = 0; i < graph.nodes - 1; i++) {
      itrep(edge, graph.edges) {
        ll u = edge->from;
        ll v = edge->to;
        ll w = edge->cost;
        if (distances[u] != INF) {
          chmin(distances[v], distances[u] + w);
        }
      }
    }

    itrep(edge, graph.edges) {
      ll u = edge->from;
      ll v = edge->to;
      ll w = edge->cost;
      if (distances[u] == INF) {
        continue;
      }
      if (distances[u] + w < distances[v]) {
        hasNegativeCycles[v] = true;
      }
    }

    for (ll i = 0; i < graph.nodes; i++) {
      itrep(edge, graph.edges) {
        ll u = edge->from;
        ll v = edge->to;
        ll w = edge->cost;
        if (distances[u] == INF) {
          continue;
        }
        chmin(distances[v], distances[u] + w);
        if (hasNegativeCycles[u] == true) {
          hasNegativeCycles[v] = true;
        }
      }
    }
  }
  ll getDistance(ll n) { return distances[n]; }
  bool hasNegativeCycle(ll n) { return hasNegativeCycles[n]; }
  ll getFrom(ll n) { return srcs[n]; }
};

// O(V^3) 有向グラフ
class WarshallFloyd {
private:
  Graph graph;
  int nodes = this->graph.nodes + 1;
  vector<vector<ll>> distances;

public:
  WarshallFloyd(Graph graph) {
    this->graph = graph;
    nodes = this->graph.nodes + 1;
    this->distances = vector<vector<ll>>(nodes, vector<ll>(nodes, INF));
    itrep(edge, graph.edges) {
      int from = edge->from;
      int to = edge->to;
      int cost = edge->cost;
      distances[from][to] = cost;
    }
  }
  void searchMinimumPath() {
    for (int k = 0; k < nodes; k++) {
      for (int i = 0; i < nodes; i++) {
        for (int j = 0; j < nodes; j++) {
          if (distances[i][k] == INF || distances[k][j] == INF) {
            continue;
          }
          if (distances[i][k] + distances[k][j] < distances[i][j]) {
            distances[i][j] = distances[i][k] + distances[k][j];
          }
        }
      }
    }
  }
  ll getDistance(int from, int to) { return distances[from][to]; }
};

struct point {
  int x, y;
};

void solve(long long H, long long W, long long K, std::vector<std::string> A) {
  vector<vl> dp(H, vl(W, -1));

  queue<point> q;
  rep(i, 0, H) {
    rep(j, 0, W) {
      if (A[i][j] == 'S') {
        q.push((point){i, j});
      }
    }
  }

  // K回までで移動できるところに移動
  vector<point> next;
  int cnt = 1;
  while (!q.empty()) {
    point p = q.front();
    q.pop();

    if (A[p.x][p.y] == '#') {
      continue;
    }

    if (dp[p.x][p.y] == -1) {
      next.push_back(p);
      dp[p.x][p.y] = cnt;

      rep(k, 0, 4) {
        int nx = p.x + dx[k];
        int ny = p.y + dy[k];

        if (nx >= 0 && nx < H && ny >= 0 && ny < W) {
          q.push((point){nx, ny});
        }
      }
    }
  }

  // K以内で進めるところに移動し続ける
  while (!next.empty()) {
    cnt++;

    queue<pair<point, int>> qq;
    for (auto p : next) {
      qq.push(mp(p, K));
    }

    vector<point> tmpNext;
    while (!qq.empty()) {
      auto p = qq.front().first;
      auto r = qq.front().second;
      qq.pop();

      if (r < 0) {
        continue;
      }

      if (dp[p.x][p.y] != -1 && dp[p.x][p.y] != cnt - 1) {
        continue;
      }

      if (dp[p.x][p.y] == -1) {
        tmpNext.push_back((point){p.x, p.y});
        dp[p.x][p.y] = cnt;
      }

      rep(k, 0, 4) {
        int nx = p.x + dx[k];
        int ny = p.y + dy[k];

        if (nx >= 0 && nx < H && ny >= 0 && ny < W && dp[nx][ny] == -1) {
          qq.push(mp((point){nx, ny}, r - 1));
        }
      }
    }
    next = tmpNext;
  }

  ll ans = 1e9;
  rep(i, 0, H) {
    chmin(ans, dp[i][0]);
    chmin(ans, dp[i][W - 1]);
  }
  rep(i, 0, W) {
    chmin(ans, dp[0][i]);
    chmin(ans, dp[H - 1][i]);
  }
  print(ans);
}

int main() {
  long long H;
  scanf("%lld", &H);
  long long W;
  scanf("%lld", &W);
  long long K;
  scanf("%lld", &K);
  std::vector<std::string> A(W);
  for (int i = 0; i < W; i++) {
    std::cin >> A[i];
  }
  solve(H, W, K, std::move(A));
  return 0;
}

