    while(Q.size()){
        pair<int,int> now=Q.front();
        Q.pop();
        int x=now.first;
        int y=now.second;
        ans=min(ans,(x+K-1)/K);
        ans=min(ans,(y+K-1)/K);
        ans=min(ans,(H-1-x+K-1)/K);
        ans=min(ans,(W-1-y+K-1)/K);
        if(dist[x][y]==K) continue;
        for(int i=0;i<4;i++){
            int nx=x+dx[i];
            int ny=y+dy[i];
            if(nx<0||ny<0||nx>=H||ny>=W) continue;
            if(used[nx][ny]) continue;
            if(A[nx][ny]=='#') continue;
            dist[nx][ny]=dist[x][y]+1;
            Q.push(make_pair(nx,ny));
        }
    }
    return;
}

