	struct node_sub *next;
}node;

typedef struct {
	node fst;
	node *last;
	int num;
}queue;

queue *make_queue(){
	queue *q = (queue *)malloc(sizeof(queue));
	q->fst.next = NULL;
	q->last = &(q->fst);
	q->num = 0;
	return q;
}

int is_empty(queue *q){
	if(q->num == 0){
		return 1;
	}
	else{
		return 0;
	}
}

void add_data(position p, queue *q){
	node *last = (node *)malloc(sizeof(node));
	last->data = p;
	last->next = NULL;
	q->last->next = last;
	q->last = last;
	q->num++;
}

int min(int a, int b){
	if(a < b){
		return a;
	}
	else{
		return b;
	}
}

int min4(int a, int b, int c, int d){
	return min(min(a, b), min(c, d));
}

position take_data(queue *q){
	node *fst = q->fst.next;
	q->fst.next = fst->next;
	position ans = fst->data;
	free(fst);
	if(q->num == 1){
		q->last = &(q->fst);
	}
	q->num--;
	return ans;
}

