int check_finish(void) {
	int i;
	for (i = 0; i < H; i++) 
		if (room[i][0] == 'S' || room[i][W - 1] == 'S')
			return 1;
	for (i = 0; i < W; i++)
		if (room[0][i] == 'S' || room[H - 1][i] == 'S')
			return 1;
	return 0;
}

void find_start() {
	int i, j;
	for (i = 0; i < H; i++)
		for (j = 0; j < W; j++)
			if (room[i][j] == 'S')
				visited[i][j] = 2;
}

void clear_visited() {
	int i, j;
	for (i = 0; i < H; i++)
		for (j = 0; j < W; j++)
			if (visited[i][j] == 1)
				visited[i][j] = 0;
}

void visit() {
	int i, j;
	for (i = 0; i < H; i++)
		for (j = 0; j < W; j++)
			if (visited[i][j] == 1)
				visited[i][j] = 2;
}

void replace(int h, int w, char c1, char c2, int range) {
	if (0 <= h && h <= H - 1 && 0 <= w && w <= W - 1 && range >= 0) {
		if (room[h][w] == c1 || room[h][w] == c2) {
			if (visited[h][w] == 0)
				visited[h][w] = 1;
			// printf("replace(%d, %d)\n", h, w);
			room[h][w] = c2;
			replace(h - 1, w, c1, c2, range - 1);
			replace(h + 1, w, c1, c2, range - 1);
			replace(h, w - 1, c1, c2, range - 1);
			replace(h, w + 1, c1, c2, range - 1);
		}
	}
}

int not_need(int h, int w) {
	char c = room[h][w];
	if (h - 1 >= 0 && room[h - 1][w] != c)
		return 0;
	if (h + 1 <= H - 1 && room[h + 1][w] != c)
		return 0;
	if (w - 1 >= 0 && room[h][w - 1] != c)
		return 0;
	if (w + 1 <= W - 1 && room[h][w + 1] != c)
		return 0;
	return 1;
}

