	for (i=0;i<H;i++) scanf("%s", &A[i]);
	pos = memchr(A, 'S', 810*H);
	x = (pos-A[0])/810;
	y = (pos-A[0])%810;
//	printf("%d %d\n", x, y);

	while (check()) {
		res = K;
		while (1) {
			ret = move(res);
//			printf("%d: %d %d\n", M, x, y);
			if (ret) break;
			else res--;
		}
		if (check()) {
			M++;
			change(K);
		} else break;
	}

	printf("%d\n", M);

