				sx = i;
				sy = j;
			}
		}
	}
	//
	int l = 0, r = 1;
	q[0][0] = sx;
	q[0][1] = sy;
	FOR(k, 0, K)
	{
		if (l == r) {
			break;
		}
		int d = 0;
		FOR(i, l, r)
		{
			int x = q[i][0];
			int y = q[i][1];
			if (!is_edge(x, y)) {
				if (map[x - 1][y] == '.') {
					q[r + d][0] = x - 1;
					q[r + d][1] = y;
					map[x - 1][y] = 'x';
					d++;
				}
				if (map[x + 1][y] == '.') {
					q[r + d][0] = x + 1;
					q[r + d][1] = y;
					map[x + 1][y] = 'x';
					d++;
				}
				if (map[x][y - 1] == '.') {
					q[r + d][0] = x;
					q[r + d][1] = y - 1;
					map[x][y - 1] = 'x';
					d++;
				}
				if (map[x][y + 1] == '.') {
					q[r + d][0] = x;
					q[r + d][1] = y + 1;
					map[x][y + 1] = 'x';
					d++;
				}
			}
		}
		l = r;
		r += d;
	}
	int min_score = score(q[0]);
	FOR(i, 1, r)
	{
		min_score = min(min_score, score(q[i]));
	}
	printf("%d\n", (int) ceil(((double) min_score) / K) + 1);
}

