queue *make_queue(){
	queue *q = (queue *)malloc(sizeof(queue));
	q->fst.next = NULL;
	q->last = &(q->fst);
	q->num = 0;
	return q;
}

int is_empty(queue *q){
	if(q->num == 0){
		return 1;
	}
	else{
		return 0;
	}
}

void add_data(position p, queue *q){
	node *last = (node *)malloc(sizeof(node));
	last->data = p;
	last->next = NULL;
	q->last->next = last;
	q->last = last;
	q->num++;
}

