						else{
							nowq.add(encode(ny,nx));
						}
					}
				}
			}
			nowq=nextq;

			while(true){
				count++;
				//開けた部屋を入れるキュー
				Queue<Integer> nq=new LinkedList<Integer>();

				while(!nowq.isEmpty()){
					int now=nowq.poll();
					int y=now/1000;
					int x=now%1000;
					//K回まで移動できる
					for(int i=0;i<K;i++){
						for(int j=0;j<4;j++){
							int ny=y+vy[j];
							int nx=x+vx[j];

