				}
			}
		}
	}
	void bfs2()
	{
		Queue<Point> queue=new LinkedList<>();
		for(int i=1;i<=n;i++)
			for(int j=1;j<=m;j++)
				if(dist[i][j]==0)
					queue.add(new Point(i,j));
		while(!queue.isEmpty())
		{
			Point p=queue.remove();
			for(int i=0;i<4;i++)
			{
