 */
public class Main implements Runnable {
    static EventType eventType = EventType.DEFAULT; //EventType.GOOGLE_CODE_JAM;
    static int T = 1; // T \in {0,1}. If T=0, it will be read from the input.
    static String inputFilename = null; // if 'null', it reads data from std-in.

    static boolean largeFakeTest = false; // Check if you generate data on fly
    static int largeFakeTest_T = 1;

    //--------------------------------------------------------------------
    public static class Solver extends  SolverAbstract{

        int H, W, K; //800,   K<H*W
        char[][] Map;
        int[][] d;

        @Override
        public void readInput() throws IOException {
            H = scanner.nextInt();
            W = scanner.nextInt();
            K = scanner.nextInt();
            Map = new char[H][];
            for (int i = 0; i < H; i++) {
                Map[i] = scanner.nextToken().toCharArray(); // size W
            }
        }

        @Override
        protected void solve() throws IOException {
            int MAX = Integer.MAX_VALUE / 3;
            d = new int[H][W];
            for (int i = 0; i < H; i++) {
                Arrays.fill(d[i], MAX);
            }
            int[] posCur = find('S');
            d[posCur[0]][posCur[1]] = 0;
            //bfs
            Queue<Integer> queue = new LinkedList<>();
            queue.add(posCur[0]);
            queue.add(posCur[1]);
            while(!queue.isEmpty()){
                int[] p = new int[2];
                p[0] = queue.poll();
                p[1] = queue.poll();
                if (d[p[0]][p[1]] < K){
                    for (int i = -1; i <= 1; i++) {
                        for (int j = -1; j <= 1; j++) if (i+j == -1 || i+j == 1){
                            int[] pn = new int[2];
                            pn[0] = p[0] + i;
                            pn[1] = p[1] + j;
                            if (pn[0]<0 || pn[0]>=H || pn[1]<0 || pn[1]>=W)
                                continue;
                            if (Map[pn[0]][pn[1]]=='.' && d[pn[0]][pn[1]] > d[p[0]][p[1]] + 1){
                                d[pn[0]][pn[1]] = d[p[0]][p[1]] + 1;
                                queue.add(pn[0]);
                                queue.add(pn[1]);
                            }
                        }
                    }
                }
            }
            int best = MAX;
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    if (d[i][j] <= K){
                        best = Math.min(best, calc(i,j));
                    }
                }
            }
            out.println(best);
        }

        private int calc(int i, int j){
            int dist = Math.min(findMin(i, H), findMin(j, W));
            return dist + 1;
        }

        private int findMin(int i, int border) {
            int dist = Math.min(i, border-1 - i);
            return dist%K==0?   dist/K:   dist/K + 1;
        }

        private int[] find(char s) {
            for (int i = 0; i < H; i++) {
                for (int j = 0; j < W; j++) {
                    if (Map[i][j] == s){
                        return new int[]{i,j};
                    }
                }
            }
            throw new RuntimeException();
        }
    }

