        boolean[][] visited = new boolean[h][w];
        Queue<SimplePair> queue = new ArrayDeque<SimplePair>();
        boolean isStart = false;
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (a[i][j] == 'S') {
                    queue.add(new SimplePair(i, j));
                    visited[i][j] = true;
                    isStart = true;
                    break;
                }
            }
            if (isStart)
                break;
        }
        int[] dx = {-1, 0, 1, 0};
        int[] dy = {0, -1, 0, 1};
        int moveCnt = 1;
        while (!queue.isEmpty()) {
            if (moveCnt == k)
                break;
            int cnt = queue.size();
            for (int i = 0; i < cnt; i++) {
                SimplePair p = queue.poll();
                for (int j = 0; j < 4; j++) {
