                int u = 1 + (i + k - 1) / k;
                int d = 1 + (h - i + k - 1) / k;
                int l = 1 + (j + k - 1) / k;
                int r = 1 + (w - j + k - 1) / k;
                minLen = min(minLen, u, d, l, r);
            }
        }
        out.println(minLen);
    }

