public void solve() {
	int h = ni();
	int w = ni();
	int kk = ni();
	char c[][] = nc(h, w);
	boolean b[][] = new boolean[h][w];
	Grids g = new Grids(h, w);
	Grid start = g.get(0, 0);
	for(int i = 0; i < h; i ++) {
		for(int j = 0; j < w; j ++) {
			b[i][j] = c[i][j] != '.';
			if(c[i][j] == 'S') start = g.get(i, j);
		}
	}
	g.init(b);

	long dist[] = new long[h * w];
	long block[] = new long[h * w];
	Arrays.fill(dist, INF);

	Deque<Grid> s = new ArrayDeque<>();
	s.addLast(start);
	dist[start.i] = 0;
	block[start.i] = 0;
	while(!s.isEmpty()) {
		Grid crt = s.removeFirst();
		for(int add = 1; add <= 4; add ++) {
			Grid next = g.next(crt, add);
			if(next == null) { continue; }
			long tmpB = block[crt.i] + (next.b ? 1 : 0);
			long tmpD = max(dist[crt.i] + 1, divceil(tmpB, kk) * kk + 1);
			if(dist[next.i] > tmpD || (dist[next.i] == tmpD && block[next.i] > tmpB)) {
				dist[next.i] = tmpD;
				block[next.i] = tmpB;
				s.addLast(next);
			}
		}
	}
	errprtln(dist);
	errprtln(block);
	long ans = INF;
	for(int i = 0; i < h; i ++) {
		for(int j = 0; j < w; j ++) {
			boolean edge = false;
			for(int add = 1; add <= 4; add ++) {
				Grid next = g.next(g.get(i, j), add);
				edge |= next == null;
			}
			if(edge) {
				ans = min(ans, divceil(dist[g.get(i, j).i], kk));
			}
		}
	}
	prtln(ans);
