							nextq.add(encode(y,x));
							check[y][x]=true;
						}
						else if(A[ny].charAt(nx)=='.'){
							nowq.add(encode(ny,nx));
							check[ny][nx]=true;
						}
					}
				}
			}

			nowq=nextq;

			while(true){
				count++;
				for(int i=0;i<K;i++){
					Queue <Integer>nq=new LinkedList<Integer>();

					while(!nowq.isEmpty()){
						int now=nowq.poll();
						int y=now/1000;
						int x=now%1000;

							for(int j=0;j<4;j++){
								int ny=y+vy[j];
								int	nx=x+vx[j];

								if(!ok(ny,nx))continue;

								if(check[ny][nx])continue;

