/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskC solver = new TaskC();
		solver.solve(1, in, out);
		out.close();
	}

	static class TaskC {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			final int infinity = 1000000000;
			int height = in.nextInt();
			int width = in.nextInt();
			int k = in.nextInt();
			char[][] s = new char[height][];
			int sr = -1;
			int sc = -1;
			for (int r = 0; r < height; r++) {
				s[r] = in.next().toCharArray();
				for (int c = 0; c < width; c++) {
					if (s[r][c] == 'S') {
						sr = r;
						sc = c;
					}
				}
			}
			int[] q = new int[2 * height * width];
			int[][] dist = new int[height][width];
			for (int[] arr : dist) {
				Arrays.fill(arr, infinity);
			}
			dist[sr][sc] = 0;
			int qt = 0;
			int qh = 0;
			q[qh++] = sr;
			q[qh++] = sc;
			int[] dr = {-1, 0, 1, 0};
			int[] dc = {0, -1, 0, 1};
			while (qt < qh) {
				int r = q[qt++];
				int c = q[qt++];
				for (int dir = 0; dir < 4; dir++) {
					int nr = r + dr[dir];
					int nc = c + dc[dir];
					if (nr < 0 || nr >= height || nc < 0 || nc >= width) {
						continue;
					}
					if (s[nr][nc] == '#') {
						continue;
					}
					if (dist[nr][nc] > 1 + dist[r][c]) {
						dist[nr][nc] = 1 + dist[r][c];
						q[qh++] = nr;
						q[qh++] = nc;
					}
				}
			}
			int ans = infinity;
			for (int r = 0; r < height; r++) {
				for (int c = 0; c < width; c++) {
					if (dist[r][c] > k) {
						continue;
					}
					int d = infinity;
					d = Math.min(d, r);
					d = Math.min(d, height - r - 1);
					d = Math.min(d, c);
					d = Math.min(d, width - c - 1);
					ans = Math.min(ans, 1 + (d + k - 1) / k);
				}
			}
			out.println(ans);
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					String rl = in.readLine();
					if (rl == null) {
						return null;
					}
					st = new StringTokenizer(rl);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;

public class Main {
	public static void main(String[] args) {
		new Main().run();
	}

	final int[] dx = new int[] { 1, -1, 0, 0 };
	final int[] dy = new int[] { 0, 0, 1, -1 };

	void run() {
		Scanner sc = new Scanner(System.in);
		int H = sc.nextInt();
		int W = sc.nextInt();
		int K = sc.nextInt();
		char[][] A = new char[H][W];
		for (int i = 0; i < H; ++i) {
			A[i] = sc.next().toCharArray();
		}
		int sh = -1, sw = -1;
		for (int i = 0; i < H; ++i) {
			for (int j = 0; j < W; ++j) {
				if (A[i][j] == 'S') {
					sh = i;
					sw = j;
				}
			}
		}

		int[][] d = new int[H][W];
		for (int i = 0; i < d.length; ++i) {
			for (int j = 0; j < d[i].length; ++j) {
				d[i][j] = Integer.MAX_VALUE / 16;
			}
		}
		d[sh][sw] = 0;
		class P {
			int h, w;

			public P(int h, int w) {
				this.h = h;
				this.w = w;
			}
		}

		ArrayDeque<P> que = new ArrayDeque<>();
		que.add(new P(sh, sw));
		while (!que.isEmpty()) {
			P p = que.poll();
			for (int i = 0; i < 4; ++i) {
				P np = new P(p.h + dy[i], p.w + dx[i]);
				if (!movable(np.h, np.w, A))
					continue;
				if (d[np.h][np.w] > d[p.h][p.w] + 1 && d[p.h][p.w] + 1 <= K) {
					d[np.h][np.w] = d[p.h][p.w] + 1;
					que.add(np);
				}
			}
		}

		int ans = Integer.MAX_VALUE / 16;
		for (int i = 0; i < H; ++i) {
			for (int j = 0; j < W; ++j) {
				if (d[i][j] > K)
					continue;
				ans = Math.min(ans, 1 + (f(i, j, H, W) + K - 1) / K);
			}
		}
		System.out.println(ans);
	}

	int f(int h, int w, int H, int W) {
		int ret = Integer.MAX_VALUE / 16;
		ret = Math.min(ret, h);
		ret = Math.min(ret, H - 1 - h);
		ret = Math.min(ret, w);
		ret = Math.min(ret, W - 1 - w);
		return ret;
	}

	boolean movable(int h, int w, char[][] map) {
		if (h < 0 || w < 0 || h >= map.length || w >= map[0].length) {
			return false;
		}
		if (map[h][w] == '#') {
			return false;
		}
		return true;
	}

	private static void tr(Object... o) {
		System.out.println(Arrays.deepToString(o));
	}
}

