        List<Integer> queue = new ArrayList<>();

        int[][] distances = new int[n][m];
        for (int[] row : distances) {
            Arrays.fill(row, -1);
        }

        queue.add(start.x * m + start.y);
        distances[start.x][start.y] = 0;

        boolean alreadyBorder = false;
        for (int index = 0; index < queue.size(); ++index) {
            int from = queue.get(index);
            int fromX = from / m, fromY = from % m;

            if (borderCell(fromX, n, fromY, m)) {
                alreadyBorder = true;
            }

            if (distances[fromX][fromY] == k) continue;

            for (int[] step : steps) {
                int toX = fromX + step[0];
                int toY = fromY + step[1];

                if (!checkCell(toX, n, toY, m)) continue;
                if (distances[toX][toY] != -1) continue;
                if (EMPTY != field[toX][toY]) continue;

                distances[toX][toY] = distances[fromX][fromY] + 1;
                queue.add(toX * m + toY);
            }
        }

        if (alreadyBorder) {
            out.println(1);
            return;
        }

        for (int v : queue) {
            distances[v / m][v % m] = 0;
        }

        for (int index = 0; index < queue.size(); ++index) {
            int from = queue.get(index);
            int fromX = from / m, fromY = from % m;

            if (borderCell(fromX, n, fromY, m)) {
                int answerDistance = distances[fromX][fromY];
                int answerIterations = (answerDistance - 1) / k + 1;

                int answer = 1 + answerIterations;
                out.println(answer);

                return;
            }

            for (int[] step : steps) {
                int toX = fromX + step[0];
                int toY = fromY + step[1];

                if (!checkCell(toX, n, toY, m)) continue;
                if (distances[toX][toY] != -1) continue;

                distances[toX][toY] = distances[fromX][fromY] + 1;
                queue.add(toX * m + toY);
            }
        }
    }

    boolean borderCell(int x, int n, int y, int m) {
