class Solver {
	private class Point {
		int X;
		int Y;

		@Override
		public int hashCode() {
			final int prime = 31;
			int result = 1;
			result = prime * result + getOuterType().hashCode();
			result = prime * result + X;
			result = prime * result + Y;
			return result;
		}

		@Override
		public boolean equals(Object obj) {
			if (this == obj)
				return true;
			if (obj == null)
				return false;
			if (getClass() != obj.getClass())
				return false;
			Point other = (Point) obj;
			if (!getOuterType().equals(other.getOuterType()))
				return false;
			if (X != other.X)
				return false;
			if (Y != other.Y)
				return false;
			return true;
		}

		public Point(int x, int y) {
			super();
			X = x;
			Y = y;
		}

		private Solver getOuterType() {
			return Solver.this;
		}
	}

	int H;
	int W;
	int K;
	int cnt;
	boolean[][] Room;
	Point Start;

	public void init() {
		H = 0;
		W = 0;
		K = 0;
		cnt = 0;
	}

	public void readHead(String str) {
		String[] strArr = str.split(" ");
		H = Integer.parseInt(strArr[0]);
		W = Integer.parseInt(strArr[1]);
		K = Integer.parseInt(strArr[2]);
		Room = new boolean[H + 1][W + 1];
	}

	public boolean hasNext() {
		return cnt < H;
	}

	public void readBody(String str) {
		// System.out.println(str);
		// String[] strArr = str.split(" ");
		cnt++;
		for (int i = 0; i < W; i++) {
			Room[cnt][i + 1] = (str.charAt(i) == '.' || str.charAt(i) == 'S');
			if (str.charAt(i) == 'S')
				Start = new Point(i + 1, cnt);
		}
	}

	public void solve() {
		footPrint = new HashSet<Point>();
		footPrint.add(Start);
		// print();
		updFootPrint(null, Start, K);
		// System.out.println();
		// print();
		int min = Integer.MAX_VALUE;
		for (Point p : footPrint) {
			min = Integer.min(min, p.X - 1);
			min = Integer.min(min, W - p.X);
			min = Integer.min(min, p.Y - 1);
			min = Integer.min(min, H - p.Y);
		}
		int ans = min / K + 1;
		if (min % K != 0)
			ans++;
		System.out.println(ans);
	}

	HashSet<Point> footPrint;

	private void updFootPrint(Point prev, Point curr, int step) {
		for (int dy = -1; dy <= 1; dy++) {
			for (int dx = (dy == 0 ? -1 : 0); dx <= 1; dx += 2) {
				int x = curr.X + dx;
				int y = curr.Y + dy;
				if (prev != null && prev.X == x && prev.Y == y)
					continue;
				if (x < 1 || y < 1 || x > W || y > H)
					continue;
				if (!Room[y][x])
					continue;
				if (x == 1 || y == 1 || x == W || y == H) {
					footPrint.add(new Point(x, y));
				} else if (step <= 1) {
					footPrint.add(new Point(x, y));
				}
				// updFootPrint(curr, new Point(x, y), step - 1);
			}
		}
	}

	private void print() {
		for (int y = 1; y <= H; y++) {
			for (int x = 1; x <= W; x++) {
				// if (Start.X == x && Start.Y == y) {
				// System.out.print("S");
				// continue;
				// }
				if (footPrint.contains(new Point(x, y))) {
					System.out.print("*");
					continue;
				}
				System.out.print(Room[y][x] ? "□" : "■");
			}
			System.out.println();
		}
	}
}

import java.io.IOException;
import java.io.InputStream;
import java.util.Comparator;
import java.util.NoSuchElementException;
import java.util.PriorityQueue;


public class Main {
  private static int[][] DIR = {{-1, 0}, {1, 0}, {0, 1}, {0, -1}};
  private static int H;
  private static int W;
  private static int K;
  private static char[][] map;
  private static int[] start;
  public static void main(String[] args) {
    FastScanner sc = new FastScanner();
    H = sc.nextInt();
    W = sc.nextInt();
    K = sc.nextInt();
    map = new char[H + 2][W + 2];

    start = new int[2];
    for (int i = 1; i <= H; i ++) {
      String s = sc.next();
      for (int j = 1; j <= W; j ++) {
        char c = s.charAt(j - 1);
        if (c == 'S') {
          start[0] = i;
          start[1] = j;
          c = '.';
        }
        map[i][j] = c;
      }
    }
    int ret = Integer.MAX_VALUE;

    long[][] len = dijkstra(map, start);
    for (int i = 1; i <= H; i ++) {
      for (int j = 1; j <= W; j ++ ) {
        if (len[i][j] <= K) {
          ret = Math.min(ret, (i - 1 + (K - 1)) / K + 1);
          ret = Math.min(ret, (j - 1 + (K - 1)) / K + 1);
          ret = Math.min(ret, (H - i + (K - 1)) / K + 1);
          ret = Math.min(ret, (W - j + (K - 1)) / K + 1);
        }
      }
    }
    System.out.println(ret);
  }

  public static long[][] dijkstra(char[][] map, int[] start) {
    int w = map[0].length;
    int h = map.length;
    long[][] len = new long[h][w];
    for (int i = 0; i < h; i ++) {
        for (int j = 0; j < w; j ++) {
            len[i][j] = Long.MAX_VALUE;
        }
    }

    PriorityQueue<long[]> queue = new PriorityQueue<long[]>(new Comparator<long[]>() {
        @Override
        public int compare(long[] o1, long[] o2) {
            return Long.compare(o1[2], o2[2]);
        }
    });

    queue.add(new long[]{start[1], start[0], 0});

    boolean[][] visited = new boolean[h][w];

    while (queue.size() > 0) {
        long[] pos = queue.poll();
        int x = (int)pos[0];
        int y = (int)pos[1];
        len[y][x] = pos[2];
        if (visited[y][x]) {
            continue;
        }
        visited[y][x] = true;

        for (int[] d : DIR) {
            int nextX = x + d[0];
            int nextY = y + d[1];
            if (map[nextY][nextX] == '.') {
                if (!visited[nextY][nextX]) {
                    long newCost = pos[2] + 1;
                    queue.add(new long[]{nextX, nextY, newCost});
                }
            }
        }
    }
    return len;
  }

}


class FastScanner {
	public static String debug = null;

	private final InputStream in = System.in;
	private int ptr = 0;
	private int buflen = 0;
	private byte[] buffer = new byte[1024];
	private boolean eos = false;

	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		} else {
			ptr = 0;
			try {
				if (debug != null) {
					buflen = debug.length();
					buffer = debug.getBytes();
					debug = "";
					eos = true;
				} else {
					buflen = in.read(buffer);
				}
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen < 0) {
				eos = true;
				return false;
			} else if (buflen == 0) {
				return false;
			}
		}
		return true;
	}

	private int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	private static boolean isPrintableChar(int c) {
		return 33 <= c && c <= 126;
	}

	private void skipUnprintable() {
		while (hasNextByte() && !isPrintableChar(buffer[ptr]))
			ptr++;
	}

	public boolean isEOS() {
		return this.eos;
	}

	public boolean hasNext() {
		skipUnprintable();
		return hasNextByte();
	}

	public String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	public long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			} else if (b == -1 || !isPrintableChar(b)) {
				return minus ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}

	public int nextInt() {
		return (int) nextLong();
	}

	public long[] nextLongList(int n) {
		return nextLongTable(1, n)[0];
	}

	public int[] nextIntList(int n) {
		return nextIntTable(1, n)[0];
	}

	public long[][] nextLongTable(int n, int m) {
		long[][] ret = new long[n][m];
		for (int i = 0; i < n; i ++) {
			for (int j = 0; j < m; j ++) {
				ret[i][j] = nextLong();
			}
		}
		return ret;
	}

	public int[][] nextIntTable(int n, int m) {
		int[][] ret = new int[n][m];
		for (int i = 0; i < n; i ++) {
			for (int j = 0; j < m; j ++) {
				ret[i][j] = nextInt();
			}
		}
		return ret;
	}
}

