public class Main {
  private static int[][] DIR = {{-1, 0}, {1, 0}, {0, 1}, {0, -1}};
  private static int H;
  private static int W;
  private static int K;
  private static char[][] map;
  private static int[] start;
  public static void main(String[] args) {
    FastScanner sc = new FastScanner();
    H = sc.nextInt();
    W = sc.nextInt();
    K = sc.nextInt();
    map = new char[H + 2][W + 2];

    start = new int[2];
    for (int i = 1; i <= H; i ++) {
      String s = sc.next();
      for (int j = 1; j <= W; j ++) {
        char c = s.charAt(j - 1);
        if (c == 'S') {
          start[0] = i;
          start[1] = j;
          c = '.';
        }
        map[i][j] = c;
      }
    }
    int ret = Integer.MAX_VALUE;
    for (int i = 0; i < 4; i ++) {
      ret = Math.min(ret, calc(i));
    }

    long[][] d = dijkstra(map, start);
    for (int i = 1; i <= W; i ++) {
      if (d[1][i] <= K || d[H][i] <= K) {
        System.out.println(1);
        return;
      }
    }
    for (int i = 1; i <= H; i ++) {
      if (d[i][1] <= K || d[i][W] <= K) {
        System.out.println(1);
        return;
      }
    }
    System.out.println(ret);
  }

  public static long[][] dijkstra(char[][] map, int[] start) {
    int w = map[0].length;
    int h = map.length;
    long[][] len = new long[h][w];
    for (int i = 0; i < h; i ++) {
        for (int j = 0; j < w; j ++) {
            len[i][j] = Long.MAX_VALUE;
        }
    }

    PriorityQueue<long[]> queue = new PriorityQueue<long[]>(new Comparator<long[]>() {
        @Override
        public int compare(long[] o1, long[] o2) {
            return Long.compare(o1[2], o2[2]);
        }
    });

    queue.add(new long[]{start[0], start[1], 0});

    boolean[][] visited = new boolean[h][w];

    while (queue.size() > 0) {
        long[] pos = queue.poll();
        int x = (int)pos[0];
        int y = (int)pos[1];
        len[y][x] = pos[2];
        if (visited[y][x]) {
            continue;
        }
        visited[y][x] = true;

        for (int[] d : DIR) {
            int nextX = x + d[0];
            int nextY = y + d[1];
            if (map[nextY][nextX] == '.') {
                if (!visited[nextY][nextX]) {
                    long newCost = pos[2] + 1;
                    queue.add(new long[]{nextX, nextY, newCost});
                }
            }
        }
    }
    return len;
  }

  private static int calc(int dir) {
    char[][] m = new char[map.length][];
    for (int i = 0; i < map.length; i++) {
      m[i] = Arrays.copyOf(map[i], map[i].length);
    }

    int[] d = DIR[dir];
    int y = start[0];
    int x = start[1];

    int count = 0;
    while (m[y + d[0]][x + d[1]] != 0) {
      for (int i = 0; i < K && m[y + d[0]][x + d[1]] == '.'; i ++) {
        y += d[0];
        x += d[1];
      }

      int ny = y;
      int nx = x;
      for (int i = 0; i < K && m[ny + d[0]][nx + d[1]] != 0;) {
        ny += d[0];
        nx += d[1];
        if (m[ny][nx] == '#') {
          i ++;
          m[ny][nx] = '.';
        }
      }
      count ++;
    }
    return count;
  }

}


