import java.util.LinkedList;
import java.util.Queue;
import java.util.Scanner;


public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int a = sc.nextInt(), b = sc.nextInt(), k = sc.nextInt();
		char[][] cs = new char[a][b];
		int sx = -1, sy = -1;
		for(int i=0; i<a; i++) {
			String s = sc.next();
			if(s.indexOf('S') != -1) {
				sx = i;
				sy = s.indexOf('S');
			}
			cs[i] = s.toCharArray();
		}

		int[] dx = new int[]{0,0,1,-1};
		int[] dy = new int[]{1,-1,0,0};
		Queue<int[]> q = new LinkedList<int[]>();
		Queue<int[]> qq = new LinkedList<int[]>();
		q.add(new int[]{sx, sy});
		int step = 0;
		int min = get(cs, sx, sy);

		while(!q.isEmpty()) {
			int[] p = q.remove();
			for(int i=0; i<4; i++) {
				int newi=p[0]+dx[i];
				int newj=p[1]+dy[i];
				if(ok(cs, newi, newj)) {
					qq.add(new int[]{newi, newj});
					int t = get(cs, newi, newj);
					if(t < min)	min = t;
				}
			}

			if(q.isEmpty()) {
				q = qq;
				qq = new LinkedList<int[]>();
				step ++;
				if(step == k)	break;
			}
		}

		System.out.println(1 + (int)Math.ceil((0.0+min)/k));
	}

	private static int get(char[][] cs, int newi, int newj) {
		int row  = Math.min(newi, cs.length-newi);
		int col  = Math.min(newj, cs[0].length-newj);
		return Math.min(row, col);
	}

	private static boolean ok(char[][] cs, int newi, int newj) {
		if(newi<0 || newj<0 || newi>=cs.length || newj>=cs[0].length)	return false;
		if(cs[newi][newj] == '#')	return false;
		return true;
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main{

	public static void main(String[] args) {
		InputReader reader = new InputReader(System.in);
		int H = reader.nextInt();
		int W = reader.nextInt();
		int K = reader.nextInt();
		char[][] A = new char[H + 2][W + 2];

		int si = 0;
		int sj = 0;

		for (int i = 1; i <= H; i++) {
			String istr = reader.next();
			for (int j = 1; j <= W; j++) {
				A[i][j] = istr.charAt(j - 1);
				if (A[i][j] == 'S') {
					A[i][j] = 0;
					si = i;
					sj = j;
				}
			}
		}

		int minDistanceToEnd = computeDistanceToEnd(si, sj, H, W);
		// mark initial move position
		for (int k_iterator = 1; k_iterator <= K; k_iterator++) {
			for (int i = 1; i <= H; i++) {
				for (int j = 1; j <= W; j++) {
					if (A[i][j] == '.') { // empty?
						if (A[i - 1][j] == k_iterator - 1 || A[i + 1][j] == k_iterator - 1
								|| A[i][j - 1] == k_iterator - 1 || A[i][j + 1] == k_iterator - 1) {
							A[i][j] = (char) k_iterator;
							minDistanceToEnd = Math.min(minDistanceToEnd, computeDistanceToEnd(i, j, H, W));
						}
					}
				}
			}
		}

		int minMagicCount = (minDistanceToEnd + K - 1) / K + 1;
		System.out.println(minMagicCount);

	}

	public static int computeDistanceToEnd(int i, int j, int H, int W) {
		int res = Math.min(i - 1, H - i);
		res = Math.min(res, Math.min(j - 1, W - j));

		return (res);
	}

}

class InputReader {
	public BufferedReader reader;
	public StringTokenizer tokenizer;

	public InputReader(InputStream stream) {
		reader = new BufferedReader(new InputStreamReader(stream), 32768);
		tokenizer = null;
	}

	public String next() {
		while (tokenizer == null || !tokenizer.hasMoreTokens()) {
			try {
				tokenizer = new StringTokenizer(reader.readLine());
			} catch (IOException e) {
				throw new RuntimeException(e);
			}
		}
		return tokenizer.nextToken();
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public long nextLong() {
		return Long.parseLong(next());
	}
}

