                    int nh = now.h + dy[j];
                    int nw = now.w + dx[j];
                    if (inner(nh, nw, H, W) && A[nh][nw] == '.' && !v[nh][nw]) {
                        v[nh][nw] = true;
                        que.add(new Node(nh, nw));
                    }
                }
            }
            cost++;
        }
        int res = 1;
        if(min % K == 0) res += min / K; 
        else  res += min / K + 1; 
        System.out.println(res);
    }

    int getMin(int nh, int nw, int H, int W) {
        return Math.min(Math.min(nh, H - nh - 1), Math.min(nw, W - nw - 1));
    }

