        for( int t=0; t<w; t++ )if(c[i][t]=='S'){
            sx=i; sy=t; break;
        }

    }
    // db(c,sx,sy);

    boolean used[][]=new boolean[h][w];
    used[sx][sy]=true;
    que.add(new XY(sx,sy,k));
    while(!que.isEmpty()) {
        XY p = que.poll();
        for( int t=0; t<4; t++ ){
            int nx=dx[t] + p.x;
            int ny=dy[t] + p.y;
            if(validpos(nx,ny,h,w)){
                if( used[nx][ny] || c[nx][ny]=='#' )continue;
                if(nx==h-1 || ny==w-1){used[nx][ny] = true;break;}
                used[nx][ny] = true;
                if(p.d>1)que.add(new XY(nx,ny,p.d-1));
            }
        }
    }

    for( int i=0; i<h; i++ ){
        for( int t=0; t<w; t++ ){
            if(used[i][t]){
                ans=min(ans,(t+k-1)/k);
                ans=min(ans,(w-t+k)/k);
                ans=min(ans,(i+k-1)/k);
                ans=min(ans,(h-i+k)/k);
            }
        }
    }
    ans++;
    out.println(ans);
    out.flush();
}

