    private int search(int x, int y, int dx, int dy) {
        if (edge(x, y)) {
            return 0;
        }

        for (int i = 0; i < K && b[y + dy][x + dx] >= 0; ++i) {
            x += dx;
            y += dy;
            if (edge(x, y)) {
                break;
            }
        }
        if (edge(x, y)) {
