			long tmpB = crt.dist.b + (next.b ? 1 : 0);
			long tmpD = max(crt.dist.d + 1, divceil(tmpB, kk) * kk + 1);
			Dist tmp = new Dist(tmpD, tmpB);
			if(tmp.compareTo(next.dist) < 0) {
				next.dist.set(tmp);
				pq.add(next);
			}
		}
	}
	long ans = INF;
	for(int i = 0; i < h; i ++) {
		for(int j = 0; j < w; j ++) {
			boolean edge = false;
			for(int add = 1; add <= 4; add ++) {
				Grid next = g.next(g.get(i, j), add);
				edge |= next == null;
			}
			if(edge) {
				ans = min(ans, divceil(g.get(i, j).dist.d, kk));
			}
		}
	}
	prtln(ans);
}

class Dist implements Comparable<Dist> {
	long d;
	long b;
	Dist(long d, long b) {
		this.d = d;
		this.b = b;
	}
	void set(Dist dist) {
		this.d = dist.d;
		this.b = dist.b;
	}
	void set(long d, long b) {
		this.d = d;
		this.b = b;
	}
	void setD(long d) {
		this.d = d;
	}
	void setB(long b) {
		this.b = b;
	}

	@Override
	public int compareTo(Dist dist) {
		int cD = Long.compare(this.d, dist.d);
		int cB = Long.compare(this.b, dist.b);
		return cD == 0 ? cB : cD;
	}
}

