    void run() {
        int H = sc.nextInt();
        int W = sc.nextInt();
        int K = sc.nextInt();
        char[][] A = sc.nextCharField(H, W);
        int sh = 0;
        int sw = 0;
        for (int i = 0; i < H; i++) {
