                    }
                    visited[wkY][wkX] = true;
                    queue.add(new SimplePair(wkY, wkX));
                }
            }
            moveCnt++;
        }
        long minLen = Integer.MAX_VALUE;
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (!visited[i][j])
                    continue;
                int u = 1 + ((i + 1) + (k - 1)) / k;
                int d = 1 + (h - (i + 1) + (k - 1)) / k;
                int l = 1 + ((j + 1) + (k - 1)) / k;
                int r = 1 + (w - (j + 1) + (k - 1)) / k;
                minLen = min(minLen, u, d, l, r);
            }
        }
        out.println(minLen);
    }

