            for (int j = 0; j < w; j++) {
                if (dist[i][j] < iinf) {
                    ans = Math.min(ans, 1 + (Math.min(Math.min(i, j), Math.min(h - 1 - i, w - 1 - j)) + k - 1) / k);
                }
            }
        }
        out.println(ans);
    }


    static class Point implements Comparable<Point> {
        static int h, w;
        static int[] da = {-1, 0, 1, 0, -1, 1, 1, -1, -1};
        int x, y, z;

        Point(int z) {
            this.x = z % w;
            this.y = z / w;
            this.z = z;
        }

        Point(int x, int y) {
            this.x = x;
            this.y = y;
            this.z = y * w + x;
        }

        Point move(int d) {
            x += da[d];
            y += da[d + 1];
            return this;
        }

        boolean isInner() {
            return 0 <= x && x < w && 0 <= y && y < h;
        }

        List<Point> aroundPoints(int type) {
            List<Point> list = new ArrayList<>();
            for (int i = 0; i < type; i++) {
                int nx = x + da[i];
                int ny = y + da[i + 1];
                Point point = new Point(nx, ny);
                if (point.isInner()) {
                    list.add(point);
                }
            }
            return list;
        }

        @Override
        public int compareTo(Point o) {
            return x == o.x ? Integer.compare(y, o.y) : Integer.compare(x, o.x);
        }

        @Override
        public String toString() {
            return String.format("(%d, %d)", x, y);
        }
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
