public class Main{

	int H, W, K;
	int[][] flg;
	int[] dh = {1, 0, -1, 0};
	int[] dw =  {0, 1, 0, -1};

	public void solve(){
		H = nextInt();
		W = nextInt();
		K = nextInt();

		flg = new int[H][W];

		int h = 0, w = 0;
		for(int i = 0; i < H; i++){
			String str = next();
			for(int j = 0; j < W; j++){
				if(str.charAt(j) == '#'){
					flg[i][j] += 2;
				}else if(str.charAt(j) == 'S'){
					h = i;
					w = j;
				}
			}
		}
		Queue<Pair> queue = new ArrayDeque<>();
		int[][] count = new int[H][W];
		count[h][w] = 1;
		queue.offer(new Pair(h, w));

		int mind = H * W;

		while(!queue.isEmpty()){
			Pair p = queue.poll();
			int cnt = count[p.h][p.w] - 1;
			mind = Math.min(mind, dis(p.h, p.w));
			if(cnt < K){
				for(int i = 0; i < 4; i++){
					int hh = p.h + dh[i];
					int ww = p.w + dw[i];
					if(0 <= hh && hh < H && 0 <= ww && ww < W &&
						count[hh][ww] == 0 && flg[hh][ww] == 0){
						count[hh][ww] = cnt + 2;
						queue.offer(new Pair(hh, ww));
					}
				}
			}
		}
		//if(mind == 0) mind = 1;
		out.println((mind + K - 1) / K + 1);
	}

	int dis(int h, int w){
		int ret = Math.min(h,  w);
		ret = Math.min(ret, H - h - 1);
		ret = Math.min(ret, (W - 1 - w));
		return ret;
	}

	class Pair{
		int h;
		int w;
		public Pair(int h, int w){
			this.h = h;
			this.w = w;
		}


	}

