import java.util.NoSuchElementException;

public class Main {
	int H,W,K;
	int[] dx = {0,0,-1,1},dy = {-1,1,0,0};
	char[][] ch;
	boolean[][] canGo;

	public boolean isRange(int x,int y){
		return x >= 0 && x < W && y >= 0 && y < H;
	}

	public void first_bfs(int sx,int sy){
		ArrayDeque<Integer> q = new ArrayDeque<Integer>();
		q.add(sx * 1000 + sy);

		while(q.size() > 0){
			int p = q.poll();

			int x = p/1000;
			int y = p%1000;

			if(canGo[y][x])continue;
			canGo[y][x] = true;
			for(int i = 0;i < 4;i++){
				int nx = x + dx[i];
				int ny = y + dy[i];
				if(isRange(nx,ny) && !canGo[ny][nx] && ch[ny][nx] == '.'){
					q.add(nx * 1000 + ny);
				}
			}
		}
	}

	public void solve(){
		H = nextInt();
		W = nextInt();
		K = nextInt();

		ch = new char[H][];
		for(int i = 0;i < H;i++){
			ch[i] = next().toCharArray();
		}

		int sx = -1,sy = -1;
		for(int i = 0;i < H;i++){
			for(int j = 0;j < W;j++){
				if(ch[i][j] == 'S'){
					sx = j;
					sy = i;
				}
			}
		}
		canGo = new boolean[H][W];
		first_bfs(sx,sy);

		ArrayList<Integer> points = new ArrayList<Integer>();
		for(int i = 0;i < H;i++){
			for(int j = 0;j < W;j++){
				if(canGo[i][j]){
					points.add(j * 1000 + i);
				}
			}
		}

		int min = Integer.MAX_VALUE;

		for(int p : points){
			int x = p / 1000;
			int y = p % 1000;

			if(x == 0 || y == 0 || x == W-1 || y == H-1){
				min = 1;
				continue;
			}

			int x1 = x;
			int y1 = y;
			int x2 = W-x-1;
			int y2 = H-y-1;

			int minDis = Math.min(Math.min(x1,y1), Math.min(x2, y2));
			min = Math.min(min, minDis/K + (minDis % K != 0 ? 1 : 0)+1);
		}

		out.println(min);
	}

	public static void main(String[] args) {
		out.flush();
		new Main().solve();
		out.close();
	}

