import java.util.Arrays;
import java.util.NoSuchElementException;

public class Main {

  private final int[] Di = new int[]{-1, 1, 0, 0};
  private final int[] Dj = new int[]{0, 0, -1, 1};

  private void solve(FastScanner in, PrintWriter out) {
    int H = in.nextInt();
    int W = in.nextInt();
    int K = in.nextInt();
    char[][] maze = new char[H][];
    for (int i = 0; i < H; i++) {
      maze[i] = in.next().toCharArray();
    }

    int si = -1, sj = -1;
    for (int i = 0; i < H; i++) {
      for (int j = 0; j < W; j++) {
        if (maze[i][j] == 'S') {
          si = i;
          sj = j;
        }
      }
    }

    int[][] dist = new int[H][W];
    for (int[] d : dist) {
      Arrays.fill(d, 10000000);
    }

    ArrayDeque<int[]> deque = new ArrayDeque<>();
    dist[si][sj] = 0;
    deque.add(new int[]{si, sj});
    while (!deque.isEmpty()) {
      int[] q = deque.poll();
      int i = q[0];
      int j = q[1];

      for (int d = 0; d < 4; d++) {
        int ni = i + Di[d];
        int nj = j + Dj[d];

        if (ni < 0 || ni == H || nj < 0 || nj == W) {
          continue;
        }
        if (maze[ni][nj] == '#') {
          continue;
        }
        if (dist[ni][nj] > dist[i][j] + 1) {
          dist[ni][nj] = dist[i][j] + 1;
          deque.add(new int[]{ni, nj});
        }
      }
    }

    int ans = Integer.MAX_VALUE;
    for (int i = 0; i < H; i++) {
      for (int j = 0; j < W; j++) {
        if (dist[i][j] > K) {
          continue;
        }

        int h = Math.min(i, H - 1 - i);
        int w = Math.min(j, W - 1 - j);
        int magic = (Math.min(h, w) + K - 1) / K + 1;
        ans = Math.min(ans, magic);
      }
    }

    out.println(ans);
  }

  public static void main(String[] args) {
    PrintWriter out = new PrintWriter(System.out);
    new Main().solve(new FastScanner(), out);
    out.close();
  }

