  static class TaskC {

    static final int[] dx = new int[]{-1, 1, 0, 0};
    static final int[] dy = new int[]{0, 0, -1, 1};
    char[][] a;
    int[] q;

    public void solve(int testNumber, InputReader in, OutputWriter out) {
      int n = in.nextInt();
      int m = in.nextInt();
      int k = in.nextInt();
      int sx = -1, sy = -1;
      a = new char[n][];
      for (int i = 0; i < n; ++i) {
        a[i] = in.nextToken().toCharArray();
        for (int j = 0; j < m; ++j) {
          if (a[i][j] == 'S') {
            sx = i;
            sy = j;
          }
        }
      }
      int[][] d = new int[n][m];
      for (int i = 0; i < n; ++i) {
        Arrays.fill(d[i], -1);
      }
      d[sx][sy] = 0;
      q = new int[n * m + 10];
      int ql = 0, qr = 0;
      q[ql++] = sx * m + sy;
      int res = -1;
      while (ql > qr) {
        int x = q[qr] / m;
        int y = q[qr] % m;
        int dist = d[x][y];
        ++qr;
        for (int dir = 0; dir < 4; ++dir) {
          int nx = x + dx[dir];
          int ny = y + dy[dir];
          int nd = dist + 1;
          if (a[nx][ny] == '#' && nd < k + 1) {
            nd = k + 1;
          }
          if (nx == 0 || nx == n - 1 || ny == 0 || ny == m - 1) {
            res = nd;
            break;
          }
          if (d[nx][ny] != -1) {
            continue;
          }
          d[nx][ny] = nd;
          q[ql++] = nx * m + ny;
        }
        if (res != -1) {
          break;
        }
      }
      res = res / k + (res % k == 0 ? 0 : 1);
      out.printLine(res);
    }

  }

  static class OutputWriter {

    private final PrintWriter writer;

    public OutputWriter(OutputStream outputStream) {
      writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
