    private void solveF() {
        int h = nextInt();
        int w = nextInt();
        int k = nextInt();
        char[][] a = IntStream.range(0, h).mapToObj(i -> next().toCharArray()).toArray(char[][]::new);
        boolean[][] visited = new boolean[h][w];
        Queue<SimplePair> queue = new ArrayDeque<SimplePair>();
        boolean isStart = false;
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (a[i][j] == 'S') {
                    queue.add(new SimplePair(i, j));
                    visited[i][j] = true;
                    isStart = true;
                    break;
                }
            }
            if (isStart)
                break;
        }
        int[] dx = {-1, 0, 1, 0};
        int[] dy = {0, -1, 0, 1};
        int moveCnt = 0;
        while (!queue.isEmpty()) {
            if (moveCnt == k)
                break;
            int cnt = queue.size();
            for (int i = 0; i < cnt; i++) {
                SimplePair p = queue.poll();
                for (int j = 0; j < 4; j++) {
                    int wkY = (int) (dy[j] + p.k);
                    int wkX = (int) (dx[j] + p.v);
                    if (wkY < 0 || wkY >= h | wkX < 0 || wkX >= w || visited[wkY][wkX] || a[wkY][wkX] == '#')
                        continue;
                    if (wkY == 0 || wkY == h - 1 || wkX == 0 || wkX == w - 1) {
                        out.println(1);
                        return;
                    }
                    visited[wkY][wkX] = true;
                    queue.add(new SimplePair(wkY, wkX));
                }
            }
            moveCnt++;
        }
        long minLen = Integer.MAX_VALUE;
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (!visited[i][j])
                    continue;
                int u = 1 + (i + (k - 1)) / k;
                int d = 1 + (h - i + (k - 1)) / k;
                int l = 1 + (j + (k - 1)) / k;
                int r = 1 + (w - j + (k - 1)) / k;
                minLen = min(minLen, u, d, l, r);
            }
        }
        out.println(minLen);
    }

