			sy = p.y;
			x1 = sx;
			y1 = sy;
			x2 = w - 1 - sx;
			y2 = h - 1 - sy;

			min = Math.min(min, Math.min(x1, Math.min(y1, Math.min(x2, y2))));
		}
		System.out.println(min);
	}

