        }
        int[] dx = {-1, 0, 1, 0};
        int[] dy = {0, -1, 0, 1};
        int moveCnt = 1;
        while (!queue.isEmpty()) {
            if (moveCnt == k)
                break;
            int cnt = queue.size();
            for (int i = 0; i < cnt; i++) {
                SimplePair p = queue.poll();
                for (int j = 0; j < 4; j++) {
