					var y = t.Item2 + dx[i + 1];
					if (IsIn(x, y) && map[x, y] && d[x, y] == Inf)
					{
						d[x, y] = d[t.Item1, t.Item2] + 1;
						q.Enqueue(new Tuple<int, int>(x, y));
					}
				}
			}
			var min = Inf;
			for (var x = 0; x < X; x++) for (var y = 0; y < Y; y++) if (d[x, y] <= K) min = Min(min, x, y, X - x - 1, Y - y - 1);
