                        sY = i;
                    }
                    map[i, j] = true;
                }
            }
            long[,] distances = new long[h, w];
            for (int i = 0; i < h; i++)
            {
                for (int j = 0; j < w; j++)
                {
                    distances[i, j] = long.MaxValue / 4;

                }
            }
            int[] dx = new int[4] { 1, -1, 0, 0 };
            int[] dy = new int[4] { 0, 0, 1, -1 };
            PriorityQueue<int[]> queue = new PriorityQueue<int[]>();
            queue.Enqueue(0, new int[2] { sX, sY });
            while (queue.Count > 0)
            {
                var pair = queue.Dequeue();
                long distance = pair.Key;
                int x = pair.Value[0];
                int y = pair.Value[1];

                if (distance >= distances[y, x]) continue;

                distances[y, x] = distance;
                for (int i = 0; i < 4; i++)
                {
                    int nx = x + dx[i];
                    int ny = y + dy[i];
                    if (nx < 0 || w <= nx || ny < 0 || h <= ny)
                    {
                        continue;
                    }
                    if (!map[ny, nx]) continue;

                    long newDistance = distance + 1;
                    if (newDistance >= distances[ny, nx]) continue;
                    queue.Enqueue(newDistance, new int[2] { nx, ny });
                }
            }
            bool[,] fixMap = new bool[h, w];
            for (int i = 0; i < h; i++)
            {
                for(int j = 0; j < w; j++)
                {
                    if (distances[i, j] < long.MaxValue / 4)
                    {
                        fixMap[i, j] = true;
                        for (int l = 0; l < 4; l++)
                        {
                            int nx = j + dx[l];
                            int ny = i + dy[l];
                            if (nx < 0 || w <= nx || ny < 0 || h <= ny)
                            {
                                continue;
                            }

                            long newDistance = distances[i,j] + 1;
                            queue.Enqueue(newDistance, new int[2] { nx, ny });
                        }
                    }
                }
            }
            while (queue.Count > 0)
            {
                var pair = queue.Dequeue();
                long distance = pair.Key;
                int x = pair.Value[0];
                int y = pair.Value[1];

                if (fixMap[y, x] || distance >= distances[y, x]) continue;

                distances[y, x] = distance;
                for (int i = 0; i < 4; i++)
                {
                    int nx = x + dx[i];
                    int ny = y + dy[i];
                    if (nx < 0 || w <= nx || ny < 0 || h <= ny)
                    {
                        continue;
                    }

                    long newDistance = distance + 1;
                    if (fixMap[ny, nx] || newDistance >= distances[ny, nx]) continue;
                    queue.Enqueue(newDistance, new int[2] { nx, ny });
                }
            }

            long res = long.MaxValue;
            for (int i = 0; i < h; i++)
            {
