class Sol{
	public void Solve(){

		long mod = 1000000;
		long Inf = (long) 1e18;
		long[][] min = new long[H][];
		bool[][] used = new bool[H][];
		for(int i=0;i<H;i++){
			min[i] = new long[W];
			used[i] = new bool[W];
			for(int j=0;j<W;j++) min[i][j] = Inf;
		}

		var SH = new SkewHeap<Pair>();
		int r0 = 0, c0 = 0;
		for(int i=0;i<H;i++){
			for(int j=0;j<W;j++){
				if(S[i][j] == 'S'){
					r0 = i; c0 = j;
				}
			}
		}

		SH.Push(new Pair(enc(r0,c0),0));
		min[r0][c0] = 0;
		while(SH.Count>0){
			var p = SH.Top; SH.Pop();
			int rc = p.Pos;
			int r = decR(rc);
			int c = decC(rc);
			long cost = p.Cost;
			if(used[decR(rc)][decC(rc)]) break;
			min[r][c] = cost;
			used[r][c] = true;
			for(int t=0;t<4;t++){
				int nr = r + dy[t];
				int nc = c + dx[t];
				if(!InRange(nr,0,H) || !InRange(nc,0,W)) continue;
				long ncost = cost;
				if(S[nr][nc] == '.') ncost ++;
				if(S[nr][nc] == '#') ncost += mod + 1;
				if(min[nr][nc] > ncost){
					min[nr][nc] = ncost;
					SH.Push(new Pair(enc(nr,nc),ncost));
				}
			}
		}

		//for(int i=0;i<H;i++) Console.WriteLine(String.Join(" ",min[i]));

		long ans = Inf;
		for(int i=0;i<H;i++){
			for(int j=0;j<W;j++){
				if(InRange(i,1,H-1) && InRange(j,1,W-1)) continue;
				long nes = min[i][j] + 1;
				long toho = nes % mod;
				long maho = nes / mod;
				long turn = 0;
				if(maho > 0) turn += (maho-1) / K + 1;
				long ntoho = (toho-1) / K + 1;
				if(turn < ntoho) turn += ntoho - turn; 
				//Console.WriteLine("{0} {1},ma;{2}, to:{3}, {4}",i,j,maho,toho,turn);
				ans = Math.Min(ans,turn);
			}
		}
		Console.WriteLine(ans);


	}

	int[] dy = new int[] {0, 1, 0, -1};
	int[] dx = new int[] {1, 0, -1, 0};
	bool InRange(int t, int l, int r){
		return l <= t && t < r;
	}
	int enc(int r, int c){ return (r*1024) | c;}
	int decR(int rc){ return rc / 1024;}
	int decC(int rc){ return rc % 1024;}


	int H,W;
	long K;
	String[] S;
	public Sol(){
		var d = ria();
		H = d[0]; W = d[1]; K = d[2];
		S = new String[H];
		for(int i=0;i<H;i++) S[i] = rs();


	}

