    class Problem : IDisposable
    {
        bool IsGCJ;
        int Repeat;
        Scanner sc;
        Printer pr;
        public Problem(bool isGCJ, Scanner scanner, Printer printer)
        {
            sc = scanner;
            pr = printer;
            IsGCJ = isGCJ;
            if (isGCJ) Repeat = sc.nextInt();
            else Read();
        }
        public Problem(bool isGCJ) : this(isGCJ, new Scanner(), new Printer()) { }
        public Problem(bool isGCJ, Scanner scanner) : this(isGCJ, scanner, new Printer()) { }
        public Problem(bool isGCJ, Printer printer) : this(isGCJ, new Scanner(), printer) { }
        public void Solve()
        {
            if (IsGCJ) for (var i = 0; i < Repeat; i++) { Read(); pr.Write("Case #" + (i + 1) + ": "); SolveOne(); }
            else SolveOne();
        }
        public void Dispose()
        {
            sc.Dispose();
            pr.Dispose();
        }
        public int Size { get { return 1; } }
        public const long Mod = 1000000007;

        // 使用する変数をここに書く
        // string S;
        // int a;
        int h, w, k, sx, sy;
        string[] map;
        int[,] count;
        /// <summary>
        /// 読み込み処理をここに書く
        /// </summary>
        void Read()
        {

        }
        /// <summary>
        /// メイン処理をここに書く
        /// </summary>
        void SolveOne()
        {
            int[] vy = { 1, 0, -1, 0 };
            int[] vx = { 0, 1, 0, -1 }; 

            h = sc.nextInt();
            w = sc.nextInt();
            k = sc.nextInt();
            map = new string[h];
            count = new int[h, w];

            Queue<int> qx = new Queue<int>();
            Queue<int> qy = new Queue<int>();
            Queue<int> qx2 = new Queue<int>();
            Queue<int> qy2 = new Queue<int>();

            for (int i = 0; i < h; i++)
            {
                map[i] = sc.next();
                for (int j = 0; j < w; j++)
                {
                    count[i, j] = -1;
                    if(map[i][j] =='S')
                    {
                        sy = i;
                        sx = j;
                        qy.Enqueue(sy);
                        qx.Enqueue(sx);
                        count[i, j] = 0;
                    }
                }
            }

            while(qx.Count>0)
            {
                int nowx = qx.Dequeue();
                int nowy = qy.Dequeue();

                for (int i = 0; i < 4; i++)
                {
                    int nextx = nowx + vx[i];
                    int nexty = nowy + vy[i];
                    if(inside(nexty,nextx) && count[nexty,nextx] ==-1)
                    {
                        if(map[nexty][nextx]=='.' && count[nowy, nowx] < k)
                        {
                            count[nexty, nextx] = count[nowy, nowx] + 1;
                            qx.Enqueue(nextx);
                            qy.Enqueue(nexty);
                        }
                        else
                        {
                            count[nexty, nextx] = k + 1;
                            qx2.Enqueue(nextx);
                            qy2.Enqueue(nexty);
                        }
                    }
                }
            }

            for (int i = 0; i < h; i++)
            {
                for (int j = 0; j < w; j++)
                {
                    if (0 <= count[i, j] && count[i, j] <= k)
                    {
                        count[i, j] = k;
                    }
                }
            }

            while (qx2.Count > 0)
            {
                int nowx = qx2.Dequeue();
                int nowy = qy2.Dequeue();

                for (int i = 0; i < 4; i++)
                {
                    int nextx = nowx + vx[i];
                    int nexty = nowy + vy[i];
                    if (inside(nexty, nextx) && count[nexty, nextx] == -1)
                    {
                        count[nexty, nextx] = count[nowy, nowx] + 1;
                        qx2.Enqueue(nextx);
                        qy2.Enqueue(nexty);
                    }
                }
            }

            int ans = int.MaxValue;
            for (int i = 0; i < h; i++)
            {
                for (int j = 0; j < w; j++)
                {
                    if (i==0 || i ==h-1 || j==0 ||j==w-1)
                    {
                        ans = Math.Min(ans, count[i, j]);
                    }
                }
            }
            Console.WriteLine((ans - 1) / k + 1);
        }

        bool inside(int y, int x)
        {
            return y >= 0 && x >= 0 && y < h && x < w;
        } 
    }
