            for (var i = 0; i < H; i++)
            {
                map[i] = Str;
                for(var j = 0; j < W; j++) if (map[i][j] == 'S') { si = i;sj = j; }
            }
            var dp = new int[H, W];
            for (var i = 0; i < H; i++) for (var j = 0; j < W; j++) dp[i, j] = INF;
            dp[si, sj] = 0;
            var bfs = new Queue<Tuple<int, int>>();
            bfs.Enqueue(new Tuple<int, int>(si, sj));
            while (bfs.Any())
            {
                var t = bfs.Dequeue();
                int i = t.Item1;
                int j = t.Item2;
                for(var k = 0; k < 4; k++)
                {
                    int ni = i + dI[k];
                    int nj = j + dJ[k];
                    if (0 <= ni && ni < H && 0 <= nj && nj < W)
                    {
                        if (dp[ni, nj] != INF || map[ni][nj] == '#') continue;
                        dp[ni, nj] = dp[i, j] + 1;
                        bfs.Enqueue(new Tuple<int, int>(ni, nj));
                    }
                }
            }


            int ans = INF;
            for(var i = 0; i < H; i++)
            {
                for(var j = 0; j < W; j++)
                {
                    if (dp[i, j] <= K)
                    {
                        int dist = Min(Min(i, H - 1 - i), Min(j, W - 1 - j));
                        ans = Min(ans, (dist + K - 1) / K);
                    }
                }
            }
            OutL(++ans);

