                    d[i, j] = -1;
                }
            }

            d[sx, sy] = 0;
            Queue<Point> queue = new Queue<Point>();
            queue.Enqueue(new Point(sx, sy));

            int[] shx = new[] { 1, 0, -1, 0 };
            int[] shy = new[] { 0, 1, 0, -1 };

            while (queue.Count > 0)
            {
                var p = queue.Dequeue();
                int cd = d[p.X, p.Y];
                if (cd >= k)
                {
                    break;
                }
                for (int i = 0; i < 4; i++)
                {
                    int nx = p.X + shx[i];
                    int ny = p.Y + shy[i];
