			rl(h,out a);

			Func<int,int,int> bfs = (i,j)=>{
				int dist2exit = int.MaxValue;
				bool[][] visit = initm(h,w,false);
				Queue<P<int,int,int>> q = new Queue<P<int, int, int>>();
				q.Enqueue(new P<int, int, int>(i,j,0));
				while(0<q.Count){
					var e = q.Dequeue();
					if(k<e.C) continue;
					if(visit[e.A][e.B]||a[e.A][e.B]=='#') continue;
					chmin(ref dist2exit,(int)min(e.A,e.B,h-e.A-1,w-e.B-1));
					visit[e.A][e.B] = true;

					if(0<=e.A-1)q.Enqueue(new P<int, int, int>(e.A-1,e.B,e.C+1));
					if(e.A+1<h)q.Enqueue(new P<int, int, int>(e.A+1,e.B,e.C+1));
					if(0<=e.B-1)q.Enqueue(new P<int, int, int>(e.A,e.B-1,e.C+1));
					if(e.B+1<h)q.Enqueue(new P<int, int, int>(e.A,e.B+1,e.C+1));
				}
				return dist2exit;
			};

			long ans = 0;
			for (int i = 0; i < h; i++)
			{
				for (int j = 0; j < w; j++)
				{
