                {
                    S[i][j] = s[j] == '.';

                    if (s[j] == 'S')
                    {
                        X = j;
                        Y = i;
                        S[i][j] = true;
                    }
                }
            }
        }

        private long H;
        private long W;
        private long K;
        private bool[][] S;
        private long X;
        private long Y;

        public void Solve()
        {

            //探索済み
            Dictionary<long, long> memo = new Dictionary<long, long>();

            Queue<long> q = new Queue<long>();
            q.Enqueue(a(Y, X));
            memo.Add(a(Y, X), 0);

            while (q.Count > 0)
            {
                // 今の場所
                var c = q.Dequeue();

                List<long> qq = new List<long>();

                //up
                if (c - W >= 0)
                {
                    qq.Add(c - W);
                }

                //down
                if (c + W < H * W)
                {
                    qq.Add(c + W);
                }

                //right
                if (y(c + 1) == y(c) && c + 1 < H * W)
                {
                    qq.Add(c + 1);
                }

                //left
                if (y(c - 1) == y(c) && c - 1 >= 0)
                {
                    qq.Add(c - 1);
                }

                foreach (long l in qq)
                {
                    if (memo.ContainsKey(l))
                    {
                        continue;
                    }

                    if (!isWay(l))
                    {
                        memo.Add(l, Int32.MaxValue);
                        continue;
                    }

                    memo.Add(l, memo[c] + 1);
                    q.Enqueue(l);
                }
            }

            long score = Int32.MaxValue;
            foreach (KeyValuePair<long,long> kp in memo)
            {
                if (kp.Value > K)
                {
                    continue;
                }

                // 上
                score = Math.Min(score, y(kp.Key));
                //下
                score = Math.Min(score, H - y(kp.Key));
                // 右
                score = Math.Min(score, W - x(kp.Key));
                // 左
                score = Math.Min(score, x(kp.Key));
            }

            if (score <= 0)
            {
                Console.WriteLine(1);
                return;
            }

            Console.WriteLine(score / K + 1 + (score % K != 0 ? 1 : 0) );
        }

        public bool isWay(long a)
        {
            //    Console.WriteLine("" + y(a) + " " + x(a));
            //    Console.WriteLine(S[y(a)][x(a)] ? "way" : "wall");

            return S[y(a)][x(a)];
        }

        public long a(long h, long w)
        {
            return h * W + w;
        }

        public long x(long a)
        {
            return a % W;
        }

        public long y(long a)
        {
            return a / W;
        }
    }

}

