		int[][] b=new int[h+2][];
		int[][] bh=new int[h+2][];
		var pq=new Pq<Mo<int[]>>(64,true);
		var pq2=new Pq<Mo<int[]>>(64,true);
		const int ts=9;
		for(int i = 1;i<=h;i++) {
			bm[i]="X"+sc.S+"X";
			bh[i]=new int[w+2];
