				}
				else if(bm[i][j]=='#'){
					b[i][j]=ts;
				}
			}
		}
		bm[0]=new string('X',w+2);
		bm[h+1]=new string('X',w+2);
		int ans=0;
		for(int k = 1;k<5;k++) {
			while(pq.cnt>0&&pq.Top.n<=s[2]*k&&ans==0){
				Mo<int[]> q=pq.Top;
				pq.Pop();
				bh[q.d[0]][q.d[1]]=q.n;
				for(int i = 0;i<4;i++) {
					if(bm[q.d[0]+di[i][0]][q.d[1]+di[i][1]]=='X'){ans=k;break;}
					if(b[q.d[0]+di[i][0]][q.d[1]+di[i][1]]!=ts&&bh[q.d[0]+di[i][0]][q.d[1]+di[i][1]]==ts){
						bh[q.d[0]+di[i][0]][q.d[1]+di[i][1]]=q.n+1;
						pq.Push(new Mo<int[]>(q.n+1,new int[]{q.d[0]+di[i][0],q.d[1]+di[i][1]}));
						if(q.n==s[2]*k){
							pq2.Push(new Mo<int[]>(s[2]*(k-1),new int[]{q.d[0]+di[i][0],q.d[1]+di[i][1]}));
						}
					}
					else if(bh[q.d[0]+di[i][0]][q.d[1]+di[i][1]]==ts){
						bh[q.d[0]+di[i][0]][q.d[1]+di[i][1]]=s[2]*k+1;
						pq.Push(new Mo<int[]>(s[2]*k+1,new int[]{q.d[0]+di[i][0],q.d[1]+di[i][1]}));
						pq2.Push(new Mo<int[]>(s[2]*(k-1)+1,new int[]{q.d[0]+di[i][0],q.d[1]+di[i][1]}));
					}
				}

			}
			if(ans!=0){break;}
			while(pq2.cnt>0&&pq2.Top.n<=s[2]*k){
				Mo<int[]> q=pq2.Top;
				pq2.Pop();
				if(b[q.d[0]][q.d[1]]==k){continue;}
				b[q.d[0]][q.d[1]]=k;
				for(int i = 0;i<4;i++) {
					if(bm[q.d[0]+di[i][0]][q.d[1]+di[i][1]]=='X'){continue;}
					if(bh[q.d[0]+di[i][0]][q.d[1]+di[i][1]]==ts&&b[q.d[0]+di[i][0]][q.d[1]+di[i][1]]==0){
						pq2.Push(new Mo<int[]>(q.n,new int[]{q.d[0]+di[i][0],q.d[1]+di[i][1]}));
					}
					else if(b[q.d[0]+di[i][0]][q.d[1]+di[i][1]]==ts){
						b[q.d[0]+di[i][0]][q.d[1]+di[i][1]]=ts-1;
						pq2.Push(new Mo<int[]>(q.n+1,new int[]{q.d[0]+di[i][0],q.d[1]+di[i][1]}));
					}
				}
			}
		}
		Console.WriteLine("{0}",ans);
	}
