class Solver
{
    int h, w, k, res;
    public void Solve()
    {
        Input.Make(out h, out w, out k);
        var grid = Input.grid(h);
        var st = new Pi(0, 0);
        for (var i = 0; i < h; i++)
            for (var j = 0; j < w; j++)
                if (grid[i][j] == 'S')
                    st = new Pi(i, j);
        res = int.MaxValue;
        Grid_bfs(grid, st);
        WriteLine(res + 1);
    }

    public int[][] Grid_bfs(char[][] grid, Pi st, char ng = '#')
    {
        int h = grid.Length, w = grid[0].Length;
        var dist = Create(h, () => Create(w, () => -1));
        var que = new Queue<Pi>();

        dist[st.v1][st.v2] = 0;
        que.Enqueue(st);

        while (que.Any())
        {
            var p = que.Dequeue(); 

            chmin(ref res, new[] { p.v1, h - p.v1 - 1, p.v2, w - p.v2 - 1 }.Select(v => (v + k - 1) / k).Min());
            for (var i = 0; i < 4; i++)
            {
                int nh = gh[i] + p.v1, nw = gw[i] + p.v2;
                if (!Inside(nh, nw, h, w) || dist[nh][nw] != -1 || grid[nh][nw] == ng) continue;

                dist[nh][nw] = dist[p.v1][p.v2] + 1;
                if (dist[nh][nw] <= k)
                    que.Enqueue(new Pi(nh, nw));
            }
        }
        return dist;
    }
    int[] gh = new[] { 0, 0, 1, -1 }, gw = new[] { 1, -1, 0, 0 };
    public static bool Inside(int h, int w, int hh, int ww)
        => 0 <= h && h < hh && 0 <= w && w < ww;
}

