namespace AGC014
{
    public class C
    {
        private void Run()
        {
            var input = Console.ReadLine().Trim().Split();
            var H = int.Parse(input[0]);
            var W = int.Parse(input[1]);
            var K = int.Parse(input[2]);
            var field = Enumerable.Range(0, H).Select(_ => Console.ReadLine().Trim().ToCharArray()).ToArray();

            var beginY = Array.FindIndex(field, line => line.Contains('S'));
            var beginX = Array.IndexOf<char>(field[beginY], 'S');

            var q = new Queue<Tuple<int, int, int>>(); // [x, y, rest]
            q.Enqueue(Tuple.Create(beginX, beginY, K));
            field[beginY][beginX] = '#';

            var minX = beginX;
            var maxX = beginX;
            var minY = beginY;
            var maxY = beginY;

            var dist = new[] { 1, 0, -1, 0, 1 };
            while (q.Count > 0)
            {
                var t = q.Dequeue();
                var x = t.Item1;
                var y = t.Item2;
                var rest = t.Item3;
                minX = Math.Min(minX, x);
                maxX = Math.Max(maxX, x);
                minY = Math.Min(minY, y);
                maxY = Math.Max(maxY, y);

                if (rest == 0) { continue; }
                for (int i = 0; i < 4; i++)
                {
                    var nx = x + dist[i];
                    var ny = y + dist[i + 1];

                    if (nx < 0 || nx >= W || ny < 0 || ny >= H) { continue; }
                    if (field[ny][nx] == '#') { continue; }
                    field[ny][nx] = '#';
                    q.Enqueue(Tuple.Create(nx, ny, rest - 1));
                }
            }

            var d = int.MaxValue;
            d = Math.Min(d, minX);
            d = Math.Min(d, minY);
            d = Math.Min(d, W - 1 - maxX);
            d = Math.Min(d, H - 1 - maxY);

            Console.WriteLine(1 + (d + K - 1) / K);
        }

        public static void Main()
        {
            var old = Console.Out;
            using (var writer = new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false })
            {
                Console.SetOut(writer);
                new C().Run();
                Console.Out.Flush();
                Console.SetOut(old);
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

static class Program
{
    class PriorityQueue<T>
    {
        private readonly List<T> m_list;
        private readonly Comparison<T> m_compare;
        public int Count { get; private set; }
        public PriorityQueue(Comparison<T> compare)
        {
            m_list = new List<T>();
            m_compare = compare;
            Count = 0;
        }
        private int Add(T value)
        {
            if (Count == m_list.Count)
            {
                m_list.Add(value);
            }
            else
            {
                m_list[Count] = value;
            }
            return Count++;
        }
        private void Swap(int a, int b)
        {
            T tmp = m_list[a];
            m_list[a] = m_list[b];
            m_list[b] = tmp;
        }
        public void Enqueue(T value)
        {
            int c = Add(value);
            while (c > 0)
            {
                int p = (c - 1) / 2;
                if (m_compare(m_list[c], m_list[p]) < 0) { Swap(p, c); } else { break; }
                c = p;
            }
        }
        public T Dequeue()
        {
            T value = m_list[0];
            m_list[0] = m_list[--Count];
            int p = 0;
            while (true)
            {
                int c1 = p * 2 + 1;
                int c2 = p * 2 + 2;
                if (c1 >= Count) { break; }
                int c = (c2 >= Count || m_compare(m_list[c1], m_list[c2]) < 0) ? c1 : c2;
                if (m_compare(m_list[c], m_list[p]) < 0) { Swap(p, c); } else { break; }
                p = c;
            }
            return value;
        }
    }

    static int Solve(int H, int W, int K, string[] lines)
    {
        const int INF = int.MaxValue / 2;
        int T = 0, B = 0, L = 0, R = 0;
        var memo = new int[H][];
        var queue = new PriorityQueue<Tuple<int, int>>((a, b) => memo[a.Item1][a.Item2].CompareTo(memo[b.Item1][b.Item2]));
        for (int i = 0; i < H; ++i)
        {
            memo[i] = Enumerable.Repeat(INF, W).ToArray();
            for (int j = 0; j < W; ++j)
            {
                if (lines[i][j] == 'S')
                {
                    memo[i][j] = 0;
                    queue.Enqueue(Tuple.Create(i, j));
                    T = i;
                    B = i;
                    L = j;
                    R = j;
                }
            }
        }
        while (queue.Count > 0)
        {
            var t = queue.Dequeue();
            int h1 = t.Item1;
            int w1 = t.Item2;
            foreach (var u in new[] { Tuple.Create(h1 - 1, w1),
                                      Tuple.Create(h1 + 1, w1),
                                      Tuple.Create(h1, w1 - 1),
                                      Tuple.Create(h1, w1 + 1), })
            {
                int h2 = u.Item1;
                int w2 = u.Item2;
                if (0 <= h2 && h2 < H && 0 <= w2 && w2 < W)
                {
                    if (lines[h2][w2] != '#' && memo[h2][w2] > memo[h1][w1] + 1)
                    {
                        memo[h2][w2] = memo[h1][w1] + 1;
                        queue.Enqueue(Tuple.Create(h2, w2));
                        if (memo[h2][w2] <= K)
                        {
                            T = Math.Min(h2, T);
                            B = Math.Max(h2, B);
                            L = Math.Min(w2, L);
                            R = Math.Max(w2, R);
                        }
                    }
                }
            }
        }
        return (new[] { T, H - B - 1, L, W - R - 1 }.Min() + K - 1) / K + 1;
    }

    static void Main(string[] args)
    {
        var V = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        int H = V[0], W = V[1], K = V[2];
        var lines = new string[H];
        for (int i = 0; i < H; ++i) { lines[i] = Console.ReadLine(); }
        Console.WriteLine(Solve(H, W, K, lines));
    }
}

