public class Solver
{
	public void Solve()
	{
		long H = GetLong();
		long W = GetLong();
		long K = GetLong();

		var grid = new char[H, W];
		(long, long) s = (-1, -1);
		for(long i = 0; i < H; i++)
		{
			var A = GetString().ToCharArray();
			for(long j = 0; j < W; j++)
			{
				grid[i, j] = A[j];
				if(A[j] == 'S')
					s = (i, j);
			}
		}

		long ans = long.MaxValue;
		var queue = new Queue<(long, long, long)>();
		var visited = new bool[H, W];
		queue.Enqueue((s.Item1, s.Item2, 0));
		visited[s.Item1, s.Item2] = true;

		var dy = new long[] { -1, 0, 1, 0 };
		var dx = new long[] { 0, -1, 0, 1 };

		while(queue.Count > 0)
		{
			var (y, x, d) = queue.Dequeue();

			chmin(ref ans, (y + K - 1)/ K + 1);
			chmin(ref ans, (H - y + K - 1)/ K + 1);
			chmin(ref ans, (x + K - 1)/ K + 1);
			chmin(ref ans, (W - x + K - 1)/ K + 1);

			for(long i = 0; i < 4; i++)
			{
				long ny = y + dy[i];
				long nx = x + dx[i];
				if(ny < 0 || ny >= H || nx < 0 || nx >= W || grid[ny, nx] == '#' || visited[ny, nx])
					continue;

				visited[ny, nx] = true;

				if(d < K)
					queue.Enqueue((ny, nx, d + 1));
			}
		}
		WriteLine(ans);
	}
}

