            int q = 1;
            P[0] = Si*W+Sj;
            DP[Si,Sj] = 0;
            while(p != q){
                int x = P[p] / W;
                int y = P[p] % W;
                p++;
                {
                    int i = -1;
                    int j = 0;
                    if(x+i >= 0 && x+i < H && y+j >= 0 && y+j < W){
                        if(DP[x+i,y+j] == -1 && b[x+i,y+j]){
                            DP[x+i,y+j] = DP[x,y] + 1;
                            if(DP[x+i,y+j] != K){
                                P[q] = (x+i)*W + (y+j);
                                q++;
                            }
                        }
                    }
                    i = 1;
                    j = 0;
                    if(x+i >= 0 && x+i < H && y+j >= 0 && y+j < W){
                        if(DP[x+i,y+j] == -1 && b[x+i,y+j]){
                            DP[x+i,y+j] = DP[x,y] + 1;
                            if(DP[x+i,y+j] != K){
                                P[q] = (x+i)*W + (y+j);
                                q++;
                            }
                        }
                    }
                    i = 0;
                    j = -1;
                    if(x+i >= 0 && x+i < H && y+j >= 0 && y+j < W){
                        if(DP[x+i,y+j] == -1 && b[x+i,y+j]){
                            DP[x+i,y+j] = DP[x,y] + 1;
                            if(DP[x+i,y+j] != K){
                                P[q] = (x+i)*W + (y+j);
                                q++;
                            }
                        }
                    }
                    i = 0;
                    j = 1;
                    if(x+i >= 0 && x+i < H && y+j >= 0 && y+j < W){
                        if(DP[x+i,y+j] == -1 && b[x+i,y+j]){
                            DP[x+i,y+j] = DP[x,y] + 1;
                            if(DP[x+i,y+j] != K){
                                P[q] = (x+i)*W + (y+j);
                                q++;
                            }
                        }
                    }
                }
            }
        }
        int count = 100000;
        for(int i=0;i<H;i++){
            for(int j=0;j<W;j++){
                if(DP[i,j] != -1){
                    count = Math.Min(H-1-i,count);
                    count = Math.Min(i,count);
                    count = Math.Min(W-1-j,count);
                    count = Math.Min(j,count);
                }
            }
        }
        count = (count + K - 1) / K;
        count++;
        sb.Append(count+"\n");
