      }
    }

    BFS(startPositionsSecond);//幅優先探索

    long answer = long.MaxValue;
    for(long i = 0; i < r; i++)
    {
      answer = Math.Min(answer, (distances[i,0]+(k-1))/k);
      answer = Math.Min(answer, (distances[i,c-1]+(k-1))/k);
    }
    for(long i = 0; i < c; i++)
    {
      answer = Math.Min(answer, (distances[0,i]+(k-1))/k);
      answer = Math.Min(answer, (distances[r-1,i]+(k-1))/k);
    }
    answer++;
    Console.WriteLine(answer);
	}

  static void BFS(long[,] startPositions)//幅優先探索。引数はスタートの座標。
  {
    int n = startPositions.GetLength(0);//スタート地点の個数
    long[][] startPosition = new long[n][];
    for(int i = 0; i < n; i++)
    {
      startPosition[i] = new long[2];
      startPosition[i][0] = startPositions[i,0];
      startPosition[i][1] = startPositions[i,1];
      que.Enqueue(startPosition[i]);
    }

    for(long i = 0; i < r; i++)
    {
      for(long j = 0; j < c; j++)
      {
        distances[i,j] = long.MaxValue;//距離を無限と仮定
      }
    }

    for(int i = 0; i < n; i++)
    {
      distances[startPosition[i][0], startPosition[i][1]] = 0;//スタート地点までの距離は0
    }
    long poppedMemoX = 0;
    long poppedMemoY = 0;
    while(que.Count > 0)
    {
      poppedMemoX = que.Peek()[0];
      poppedMemoY = que.Peek()[1];
      que.Dequeue();

      for(long partnerNum = 0; partnerNum < 4; partnerNum++)//上下左右に進みたい
      {
        long aimX = poppedMemoX+VectorArrow[2*partnerNum];
        long aimY = poppedMemoY+VectorArrow[2*partnerNum+1];
        if(wallPositions[aimX+1, aimY+1] == 1) continue;//壁なら無視
        if(distances[aimX, aimY] != long.MaxValue) continue;//距離が確定済みなら無視
        distances[aimX, aimY] = distances[poppedMemoX, poppedMemoY] + 1;//距離の加算
        que.Enqueue(new long[2]{aimX, aimY});
      }
    }

      /*
      for(long i = 0; i < r; i++)//各点までの距離の表示
      {
        string answer = "";
        for(long j = 0; j < c; j++)
        {
          if(wallPositions[i+1,j+1] == 1) answer += "#";
          else answer += distances[i,j].ToString();
        }
        Console.WriteLine(answer);
      }
      */

      //Console.WriteLine(distances[goalPosition[0], goalPosition[1]]);//ゴールまでの最短距離
  }
