class Solver
{
    public void Solve()
    {
        int h, w, k;
        Input.Make(out h, out w, out k);
        var grid = Input.grid(h);
        var st = new Pi(0, 0);
        for (var i = 0; i < h; i++)
            for (var j = 0; j < w; j++)
                if (grid[i][j] == 'S')
                    st = new Pi(i, j);
        var res = int.MaxValue;
        for (var i = 0; i < h; i++)
            for (var j = 0; j < w; j++)
                if (grid[i][j] != '#' && Abs(st.v1 - i) + Abs(st.v2 - j) <= k)
                    chmin(ref res, new[] { i, h - i - 1, j, w - j - 1 }.Min());
        WriteLine(res + 1);
    }
}

