import (
  "container/heap"
  "fmt"
)
const INF = 1000000000
var k int
var closed []bool
func main() {
  var h,w int
  var s string
  fmt.Scan(&h,&w,&k)
  g := make([][]int,h*w+1)
  start := -1
  closed = make([]bool,h*w+1)
  for i:=0;i<h;i++ {
    fmt.Scan(&s)
    for j:=0;j<w;j++ {
      id := w*i+j
      if s[j:j+1] == "#" { closed[id] = true }
      if s[j:j+1] == "S" { start = id }
      if i == 0 {
        g[id] = append(g[id],h*w)
      } else {
        g[id] = append(g[id],w*(i-1)+j)
        g[w*(i-1)+j] = append(g[w*(i-1)+j],id)
      }
      if i == h-1 {
        g[id] = append(g[id],h*w)
      } else {
        g[id] = append(g[id],w*(i+1)+j)
        g[w*(i+1)+j] = append(g[w*(i+1)+j],id)
      }
      if j == 0 {
        g[id] = append(g[id],h*w)
      } else {
        g[id] = append(g[id],w*i+j-1)
        g[w*i+j-1] = append(g[w*i+j-1],id)
      }
      if j == w-1 {
        g[id] = append(g[id],h*w)
      } else {
        g[id] = append(g[id],w*i+j+1)
        g[w*i+j+1] = append(g[w*i+j+1],id)
      }
    }
  }
  c := dijkstra(g,start)
  fmt.Println(c[h*w])
}
func max(n,m int) int {
  if n > m { return n }
  return m
}
func dijkstra(g [][]int,start int) []int {
  n := len(g)
  c := make([]int,n)
  for i:=0;i<n;i++ { c[i] = INF }
  var pq PriorityQueue
  heap.Init(&pq)
  heap.Push(&pq,&Item{start,0,0})
  c[start] = 0
  for pq.Len() > 0 {
    s := heap.Pop(&pq).(*Item)
    if s.Cost() > c[s.pos] { continue }
    for _,e := range g[s.pos] {
      t := Item{e,s.dist+1,s.closed}
      if closed[e] { t.closed++ }
      if c[e] > t.Cost() {
        c[e] = t.Cost()
        heap.Push(&pq,&t)
      }
    }
  }
  return c
}
type Item struct { pos,dist,closed int }
func(i Item) Cost() int { return max((i.dist+k-1)/k,(i.closed+k-1)/k) }
type PriorityQueue []*Item
func(pq PriorityQueue) Len() int { return len(pq) }
func(pq PriorityQueue) Less(i,j int) bool { return pq[i].Cost() < pq[j].Cost() }
func(pq PriorityQueue) Swap(i,j int) { pq[i],pq[j] = pq[j],pq[i] }
func(pq *PriorityQueue) Push(x interface{}) {
  item := x.(*Item)
  *pq = append(*pq,item)
}
func(pq *PriorityQueue) Pop() interface{} {
  old := *pq
  n := len(old)
  item := old[n-1]
  *pq = old[0:n-1]
  return item
}

