	i, _ := strconv.ParseFloat(getNextString(scanner), 64)
	return i
}

func main() {
	fp := os.Stdin
	wfp := os.Stdout
	cnt := 0

	if os.Getenv("MASPY") == "ますピ" {
		fp, _ = os.Open(os.Getenv("BEET_THE_HARMONY_OF_PERFECT"))
		cnt = 2
	}
	if os.Getenv("MASPYPY") == "ますピッピ" {
		wfp, _ = os.Create(os.Getenv("NGTKANA_IS_GENIUS10"))
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)
	solve(scanner, writer)
	for i := 0; i < cnt; i++ {
		fmt.Fprintln(writer, "-----------------------------------")
		solve(scanner, writer)
	}

	writer.Flush()
}

func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	h := getNextInt(scanner)
	w := getNextInt(scanner)
	k := getNextInt(scanner)
	aa := make([][]string, h)
	sx := -1
	sy := -1
	for i := 0; i < h; i++ {
		aa[i] = strings.Split(getNextString(scanner), "")
		for j := 0; j < w; j++ {
			if aa[i][j] == "S" {
				sx = j
				sy = i
			}
		}
	}
	q := make([]takahashi, 0)
	q = append(q, newt(sy, sx, 0))
	dy := [4]int{-1, 0, 0, 1}
	dx := [4]int{0, -1, 1, 0}
	ans := math.MaxInt32
	visited := makeInts(h, w)
	for len(q) > 0 {
		p := q[0]
		q = q[1:]

		visited[p.y][p.x] = 1
		ans = minint(ans, shortest(p.y, p.x, h, w))
		if p.k == k {
			continue
		}
		for i := 0; i < 4; i++ {
			xx := p.x + dx[i]
			yy := p.y + dy[i]
			if yy < 0 || yy >= h {
				continue
			}
			if xx < 0 || xx >= w {
				continue
			}
			if aa[yy][xx] == "#" {
				continue
			}
			if visited[yy][xx] == 1 {
				continue
			}
			visited[yy][xx] = 1
			q = append(q, newt(yy, xx, p.k+1))
		}
	}
	fmt.Fprintln(writer, 1+covered(ans, k))
