    Deque!(int[2]) q;
    q.insertBack(sv);
    dist.at2D(sv) = 0;
    int ans = 10^^9;
    while (q.empty == false) {
        auto p = q.front; q.removeFront;
        if (vis.at2D(p)) continue;
        vis.at2D(p) = true;
        int di = min(p[0], H-1-p[0], p[1], W-1-p[1]);
        ans = min(ans, 1+(di+k-1)/k);
//        writeln(p, di);
