        foreach (np; p.neighbors4(Dungeon(H, W))) {
            if (g.at2D(np) == '#') continue;
            if (dist.at2D(np) <= dist.at2D(p) + 1) continue;            
            dist.at2D(np) = dist.at2D(p) + 1;
            q.insertBack(np);
        }
    }
