        k = K
        while k > 0 and A[pi + vi][pj + vj] != '#':
            pi, pj = pi + vi, pj + vj
            goal = pi == 1 or pi == H or pj == 1 or pj == W
            if goal:
                break
            k -= 1

    return mahou

