def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(H, W, K, A):
    for i in range(H):
        for j in range(W):
            if A[i][j] == 'S':
                s = (i, j)
    from collections import deque
    q = deque([(s, 0)])
    d = {}
    d[s] = 0
    while q:
        u, c = q.popleft()
        for x, y in [(-1, 0), (0, -1), (0, 1), (1, 0)]:
            vx, vy = (u[0]+x, u[1]+y)
            if not (0 <= vx < H and 0 <= vy < W):
                continue
            if A[vx][vy] != '.':
                continue
            if c + 1 <= K:
                q.append(((vx, vy), c+1))
                d[(vx, vy)] = 0
    q = set()
    for u in list(d.keys()):
        for x, y in [(-1, 0), (0, -1), (0, 1), (1, 0)]:
            vx, vy = (u[0]+x, u[1]+y)
            if not (0 <= vx < H and 0 <= vy < W):
                continue
            if (vx, vy) not in d:
                q.add(((vx, vy), 1))
                d[(vx, vy)] = 1
    q = deque(q)

    while q:
        u, c = q.popleft()
        for x, y in [(-1, 0), (0, -1), (0, 1), (1, 0)]:
            vx, vy = (u[0]+x, u[1]+y)
            if not (0 <= vx < H and 0 <= vy < W):
                continue
            if (vx, vy) not in d:
                q.append(((vx, vy), c+1))
                d[(vx, vy)] = c+1

    ans = INF
    for j in range(W):
        ans = min(ans, d[(0, j)])
        ans = min(ans, d[(H-1, j)])
    for i in range(H):
        ans = min(ans, d[(i, 0)])
        ans = min(ans, d[(i, W-1)])
    return -(-ans // 2) + 1



