def __opt_start(pos, vec, k):
    pi, pj = pos
    score = 0
    V[pi][pj] = True
    if k == 0:
        score = __score(pos, vec)
        return pos, vec, score

    opt, optvec, optscore = pos, vec, score
    if (not V[pi - 1][pj]) and pi - 1 >= 1 and A[pi - 1][pj] != '#':
        p, v, s = __opt_start((pi - 1, pj), (-1, 0), k - 1)
        if s >= optscore:
            opt, optvec, optscore = p, v, s

    if (not V[pi + 1][pj]) and pi + 1 <= H and A[pi + 1][pj] != '#':
        p, v, s = __opt_start((pi + 1, pj), (+1, 0), k - 1)
        if s >= optscore:
            opt, optvec, optscore = p, v, s

    if (not V[pi][pj - 1]) and pj - 1 >= 1 and A[pi][pj - 1] != '#':
        p, v, s = __opt_start((pi, pj - 1), (0, -1), k - 1)
        if s >= optscore:
            opt, optvec, optscore = p, v, s

    if (not V[pi][pj + 1]) and pj + 1 <= W and A[pi][pj + 1] != '#':
        p, v, s = __opt_start((pi, pj + 1), (0, +1), k - 1)
        if s >= optscore:
            opt, optvec, optscore = p, v, s

    return opt, optvec, optscore


def __score(pos, vec):
    vi, vj = vec
    i, j = pos
    if vec == (0, 1):
        return W - j
    elif vec == (0, -1):
        return j - 1
    elif vec == (1, 0):
        return H - i
    elif vec == (-1, 0):
        return i - 1
    else:
        return None


