fn main() {
    input! { h, w, k, a: [chars; h] };
    let mut start = (0, 0);
    for i in 0..h {
        for j in 0..w {
            if a[i][j] == 'S' {
                start = (i, j);
            }
        }
    }
    let mut heap = BinaryHeap::new();
    let mut visited = vec![vec![false; w]; h];
    visited[start.0][start.1] = true;
    heap.push(Rev((1, 0, Rev(0), start)));
    let dir = vec![1, 0, -1, 0, 1];
    while let Some(u) = heap.pop() {
        let (mut m, mut l, mut p, u) = u.0;
        if u.0 == 0 || u.0 == h - 1 || u.1 == 0 || u.1 == w - 1 {
            println!("{}", m);
            break;
        }
        if l == k {
            l = 0;
            m += 1;
            p.0 += k;
        }
