use std::cmp;

fn dfs((x, y): (usize, usize), board: &mut [Vec<char>]) -> usize {
    if board[y][x] == '#' {
        return 1_000_000_000;
    } else {
        board[y][x] = '#';
        let h = board.len();
        let w = board[0].len();
        let d = vec![x-1, w-x-1, y-1, h-y-1].into_iter().min().unwrap();
        let adj_d = vec![(x-1, y), (x+1, y), (x, y-1), (x, y+1)].into_iter()
            .map(|next| dfs(next, board))
            .min().unwrap();
        cmp::min(d, adj_d)
    }
}

fn main() {
    read!(h = usize, w = usize, k = usize);
    let mut board = readx::<Chars>();
    for line in &mut board {
        line.insert(0, '#');
        line.push('#');
    }
    board.insert(0, vec!['#'; w+2]);
    board.push(vec!['#'; w+2]);

    let mut sx = 0;
    let mut sy = 0;
    'outer: for y in 0..h+2 {
        for x in 0..w+2 {
            if board[y][x] == 'S' {
                board[y][x] = '.';
                sx = x;
                sy = y;
                break 'outer;
            }
        }
    }

    dbg!(&board);
    let min_d = dfs((sx, sy), &mut board);
    println!("{}", 1 + min_d.ceil_div(k));
}

use std::io::{stdin, Read, StdinLock};
use std::str::FromStr;
use std::iter::FromIterator;
use std::collections::VecDeque;
use std::cmp::min;

fn main() {
    let cin = stdin();
    let mut scan = Scanner::new(cin.lock());
    let h = scan.read::<usize>();
    let w = scan.read::<usize>();
    let k = scan.read::<usize>();
    let a = arr(h, |_| scan.chars());
    let mut s = 0;
    for y in 0..h { for x in 0..w {if a[y][x]=='S' {s = y * w + x;}}}
    let mut que = VecDeque::new();
    que.push_back((s, 0));
    let mut used = vec![vec![false;w];h];
    while let Some((pos, cnt)) = que.pop_front() {
        let y = pos/w;
        let x = pos%w;
        if y == 0 || y == h-1 || x == 0 || x == w-1 {
            println!("1");
            return;
        }
        if cnt==k {continue;}
        for (ny, nx) in adjacent4(y, x, h, w) {
            if a[ny][nx] != '#' && !used[ny][nx] {
                used[ny][nx] = true;
                que.push_back((ny * w + nx, cnt + 1));
            }
        }
    }
    let mut ret = 1i64 << 60;
    for y in 0..h {
        for x in 0..w {
            if used[y][x] {
                let c = min(min(min(x, w-1-x), y), h-1-y);
                ret = min(ret, ceil_div( ui(c) , ui(k)) + 1);
            }
        }
    }
    println!("{}", ret);
}

