pub struct Unfold<T, F>
where
    F: FnMut(&T) -> Option<T>,
{
    state: Option<T>,
    f: F,
}
impl<T, F> Iterator for Unfold<T, F>
where
    F: FnMut(&T) -> Option<T>,
{
    type Item = T;
    fn next(&mut self) -> Option<T> {
        if self.state.is_none() {
            return None;
        }
        let state_inner = self.state.take().unwrap();
        self.state = (self.f)(&state_inner);
        Some(state_inner)
    }
}
pub fn unfold<T, F>(init: T, f: F) -> Unfold<T, F>
where
    F: FnMut(&T) -> Option<T>,
{
    Unfold {
        state: Some(init),
        f: f,
    }
}
pub struct Iterate<T, F>
where
    F: FnMut(&T) -> T,
{
    state: T,
    f: F,
}
impl<T, F> Iterator for Iterate<T, F>
where
    F: FnMut(&T) -> T,
{
    type Item = T;
    fn next(&mut self) -> Option<T> {
        use std::mem::swap;
        let mut state = (self.f)(&self.state);
        swap(&mut state, &mut self.state);
        Some(state)
    }
}
pub fn iterate<T, F>(init: T, f: F) -> Iterate<T, F>
where
    F: FnMut(&T) -> T,
{
    Iterate { state: init, f: f }
}

use std::cmp;
use std::collections::VecDeque;

fn bfs((sx, sy): (usize, usize), k: usize, mut board: Vec<Vec<char>>) -> usize {
    let mut res = 1_000_000_000;
    let mut queue = VecDeque::new();
    board[sy][sx] = '#';
    queue.push_back(((sx, sy), k));
    let h = board.len();
    let w = board[0].len();

    while let Some(((x, y), rest)) = queue.pop_front() {
        res = cmp::min(res, vec![x-1, w-x-2, y-1, h-y-2].into_iter().min().unwrap());
        if let Some(next_rest) = rest.checked_sub(1) {
            for (nx, ny) in vec![(x-1, y), (x+1, y), (x, y-1), (x, y+1)] {
                if board[ny][nx] == '.' {
                    board[ny][nx] = '#';
                    queue.push_back(((nx, ny), next_rest));
                }
            }
        }
    }

    res
}

fn main() {
    read!(h = usize, w = usize, k = usize);
    let mut board = readx::<Chars>();
    for line in &mut board {
        line.insert(0, '#');
        line.push('#');
    }
    board.insert(0, vec!['#'; w+2]);
    board.push(vec!['#'; w+2]);

    let start = (1..h+1).map(|y| (1..w+1).map(move |x| (x, y))).flatten()
        .find(|&(x, y)| board[y][x] == 'S')
        .unwrap();
    let min_d = bfs(start, k, board);
    println!("{}", 1 + min_d.ceil_div(k));
}

use std::io;
use std::collections::VecDeque;

fn main() {
    let mut input = Input::new();
    let h: usize = input.next();
    let w: usize = input.next();
    let k: usize = input.next();
    let mut s = (0, 0, 0);
    let mut a: Vec<Vec<bool>> = (0..h)
        .map(|i| {
            input
                .next::<String>()
                .chars()
                .enumerate()
                .map(|(j, c)| {
                         if c == 'S' {
                             s = (i, j, 0);
                         }
                         c != '#'
                     })
                .collect()
        })
        .collect();
    let mut min = h + w;
    let mut queue = VecDeque::<(usize, usize, usize)>::new();
    queue.push_back(s);
    while !queue.is_empty() {
        let (y, x, d) = queue.pop_front().unwrap();
        if d == k + 1 {
            break;
        }
        min = *[min, x, y, w - x - 1, h - y - 1].iter().min().unwrap();
        let mut action = |y: usize, x: usize| if a[y][x] {
            a[y][x] = false;
            queue.push_back((y, x, d + 1));
        };
        if y > 0 {
            action(y - 1, x);
        }
        if y + 1 < h {
            action(y + 1, x);
        }
        if x > 0 {
            action(y, x - 1);
        }
        if x + 1 < w {
            action(y, x + 1);
        }
    }
    println!("{}", 1 + (min + k - 1) / k);
}

struct Input {
    queue: VecDeque<String>,
}

impl Input {
    fn new() -> Input {
        Input { queue: VecDeque::new() }
    }

    fn next<T>(&mut self) -> T
        where T: std::str::FromStr,
              T::Err: std::fmt::Debug
    {
        if self.queue.is_empty() {
            let mut line = String::new();
            let _ = io::stdin().read_line(&mut line);
            for x in line.split_whitespace() {
                self.queue.push_back(String::from(x));
            }
        }
        return self.queue.pop_front().unwrap().parse::<T>().unwrap();
    }
}

macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String {
            bytes
                .by_ref()
                .map(|r| r.unwrap() as char)
                .skip_while(|c| c.is_whitespace())
                .take_while(|c| !c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, [ $t:tt ]) => {
        {
            let len = read_value!($next, usize);
            (0..len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
        }
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

