        w: usize,
        k: usize,
        v: [chars; h]
    }
    let mut q = VecDeque::new();
    let mut dist = vec![vec![usize::max_value(); w]; h];
    let mut s = (0, 0);
    'outer: for i in 0..h {
        for j in 0..w {
            if v[i][j] == 'S' {
                s = (i, j);
                break 'outer;
            }
        }
    }
    dist[s.0][s.1] = 0;
    q.push_back(s);
    while let Some((i, j)) = q.pop_front() {
        if i == 0 || i == h - 1 || j == 0 || j == w - 1 {
            println!("1");
            return;
        }
        if dist[i][j] == k {
            continue;
        }
        if v[i][j + 1] == '.' && dist[i][j + 1] > dist[i][j] + 1 {
            dist[i][j + 1] = dist[i][j] + 1;
            q.push_back((i, j + 1));
        }
        if v[i][j - 1] == '.' && dist[i][j - 1] > dist[i][j] + 1 {
            dist[i][j - 1] = dist[i][j] + 1;
            q.push_back((i, j - 1));
