            q.push_back((i - 1, j));
        }
    }
    for i in 0..h {
        for j in 0..w {
            if dist[i][j] < usize::max_value() {
                dist[i][j] = k;
                q.push_back((i, j));
            }
        }
    }
    while let Some((i, j)) = q.pop_front() {
        if i == 0 || i == h - 1 || j == 0 || j == w - 1 {
            println!("{}", (dist[i][j] + k - 1) / k);
