    let h: usize = sc.cin();
    let w: usize = sc.cin();
    let k: usize = sc.cin();
    let mut s = (0, 0);
    let mut fs = vec![vec![false; w]; h];
    for i in 0..h {
        let cs: Vec<char> = sc.cin::<String>().chars().collect();
        for j in 0..w {
            fs[i][j] = cs[j] != '#';
            if cs[j] == 'S' {
                s = (i, j);
            }
        }
    }

    let mut memo = vec![vec![k * 2; w]; h];
    memo[s.0][s.1] = 0;

    // use std::collections::BinaryHeap;
    // let mut q = BinaryHeap::new();
    // q.push((0, s));
    let mut q = vec![s];

    while let Some((i, j)) = q.pop() {
        if memo[i][j] == k { continue }
        if i > 0 && fs[i-1][j] && memo[i-1][j] > memo[i][j] + 1 {
            memo[i-1][j] = memo[i][j] + 1;
            q.push((i-1, j));
        }
        if j > 0 && fs[i][j-1] && memo[i][j-1] > memo[i][j] + 1 {
            memo[i][j-1] = memo[i][j] + 1;
            q.push((i, j-1));
        }
        if i < h + 1 && fs[i+1][j] && memo[i+1][j] > memo[i][j] + 1 {
            memo[i+1][j] = memo[i][j] + 1;
            q.push((i+1, j));
        }
        if j < w + 1 && fs[i][j+1] && memo[i][j+1] > memo[i][j] + 1 {
            memo[i][j+1] = memo[i][j] + 1;
            q.push((i, j+1));
        }
    }

    let mut ans = 1000 + h * w;
    for i in 0..h {
        // trace!(&memo[i]);
        for j in 0..w {
            if memo[i][j] <= k {
                ans = min!(ans, 1 + (i + k - 1) / k);
                ans = min!(ans, 1 + (j + k - 1) / k);
                ans = min!(ans, 1 + (h - i - 1 + k - 1) / k);
