fn dijkstra(s:usize, g:&Vec<Vec<(usize, i64)>>)->(Vec<usize>, Vec<i64>){
    let mut d = vec![INF;g.len()];
    let mut prev = vec![g.len();g.len()];
    d[s] = 0;
    let mut h = BinaryHeap::new();
    h.push((0, s));
    while(h.len() != 0){
        let mut top = h.pop().unwrap();
        let mut v = top.1;
        let mut l = top.0 * -1;
        if l > d[v]{
            continue;
        }
        for i in 0..g[v].len(){
            let nl = l + g[v][i].1;
            let n = g[v][i].0;
            if d[n] > nl{
                prev[n] = v;
                d[n] = nl;
                h.push((nl*-1, n));
            }
        }
    }
    (prev, d)
}
