                now.push(vec![0, i as i64, j as i64]);
            }
        }
    }
    let dx = vec![0, 0, 1, -1];
    let dy = vec![1, -1, 0, 0];
    while(now.len() != 0){
        let mut top = now.pop().unwrap();
        let d = top[0]*-1;
        let x = top[1];
        let y = top[2];
        if dist[x as usize][y as usize]<d as usize{
            continue;
        }
        for i in 0..4{
            let mut xx = dx[i]+x as i64;
            let mut yy = dy[i]+y as i64;
