        }
    }
    const DX: [i32; 4] = [-1, 0, 0, 1];
    const DY: [i32; 4] = [0, -1, 1, 0];
    while let Some((x, y)) = que.pop_front() {
        let cd = dist[y as usize][x as usize];
        for i in 0..4 {
            let nx = x + DX[i];
            let ny = y + DY[i];
            if nx < 0 || ny < 0 || nx >= (w as i32) || ny >= (h as i32) {
                continue;
            }
            if dist[ny as usize][nx as usize] < INF {
                continue;
            }
            if fld[ny as usize][nx as usize] == b'#' {
                continue;
            }
            dist[ny as usize][nx as usize] = cd + 1;
            que.push_back((nx, ny));
        }
    }
    let mut ans = INF;
    for i in 0..h {
        for j in 0..w {
            ans = min(ans, score[i][j] + max(1, (dist[i][j] + k - 1) / k));
        }
    }

    println!("{}", ans);
}

