                res = cmp::min(res, 1+ (i)/K + if (i+1)%K == 0{0}else{1});
                res = cmp::min(res, 1+ (H-i-1)/K + if (H-i-1)%K == 0{0}else{1});
                res = cmp::min(res, 1+ (j)/K + if (j+1)%K == 0{0}else{1});
                res = cmp::min(res, 1+ (W-j-1)/K + if (W-j-1)%K == 0{0}else{1});
            }
        }
    }
