pub struct Unfold<T, F>
where
    F: FnMut(&T) -> Option<T>,
{
    state: Option<T>,
    f: F,
}
impl<T, F> Iterator for Unfold<T, F>
where
    F: FnMut(&T) -> Option<T>,
{
    type Item = T;
    fn next(&mut self) -> Option<T> {
        if self.state.is_none() {
            return None;
        }
        let state_inner = self.state.take().unwrap();
        self.state = (self.f)(&state_inner);
        Some(state_inner)
    }
}
pub fn unfold<T, F>(init: T, f: F) -> Unfold<T, F>
where
    F: FnMut(&T) -> Option<T>,
{
    Unfold {
        state: Some(init),
        f: f,
    }
}
pub struct Iterate<T, F>
where
    F: FnMut(&T) -> T,
{
    state: T,
    f: F,
}
impl<T, F> Iterator for Iterate<T, F>
where
    F: FnMut(&T) -> T,
{
    type Item = T;
    fn next(&mut self) -> Option<T> {
        use std::mem::swap;
        let mut state = (self.f)(&self.state);
        swap(&mut state, &mut self.state);
        Some(state)
    }
}
pub fn iterate<T, F>(init: T, f: F) -> Iterate<T, F>
where
    F: FnMut(&T) -> T,
{
    Iterate { state: init, f: f }
}

use std::cmp;
use std::collections::VecDeque;

fn bfs((sx, sy): (usize, usize), k: usize, board: &mut [Vec<char>]) -> usize {
    let mut res = 1_000_000_000;
    let mut queue = VecDeque::new();
    board[sy][sx] = '#';
    queue.push_back(((sx, sy), k));
    let h = board.len();
    let w = board[0].len();

    while let Some(((x, y), rest)) = queue.pop_front() {
        res = cmp::min(res, vec![x-1, w-x-1, y-1, h-y-1].into_iter().min().unwrap());
        if let Some(next_rest) = rest.checked_sub(1) {
            for (nx, ny) in vec![(x-1, y), (x+1, y), (x, y-1), (x, y+1)] {
                if board[ny][nx] == '.' {
                    board[ny][nx] = '#';
                    queue.push_back(((nx, ny), next_rest));
                }
            }
        }
    }

    res
}

