fn dist((x,y): (usize, usize), (h,w): (usize, usize)) -> usize {
    min!(h-x-1,x,w-y-1,y)
}
fn solve() {
    let (h,w,k) = get!(usize, usize, usize);
    let a = get!(String; h).into_iter().map(|e| e.chars().collect::<Vec<_>>()).collect::<Vec<_>>();
    let dx = [0,0,1,-1];
    let dy = [1,-1,0,0];
    let mut queue = VecDeque::new();
    let mut visited = vec![vec![false; w];h];
    let mut mn = (0,0);
    for x in 0..h {
        for y in 0..w {
            if a[x][y] == 'S' {
                queue.push_back((x,y,0));
                visited[x][y] = true;
                mn = (x,y);
            }
        }
    }

    let mut flag = false;
    while let Some((x,y,depth)) = queue.pop_front() {
        if dist(mn, (h,w)) > dist((x,y), (h,w)) {
            mn = (x,y);
        }

        if depth + 1 > k {
            continue;
        }
        for i in 0..4 {
            let nx = x as isize + dx[i];
            let ny = y as isize + dy[i];
            if nx < 0 || ny < 0 {
                continue;
            }
            let nx = nx as usize;
            let ny = ny as usize;
            if nx > h-1 || ny > w-1 || visited[nx][ny] || a[nx][ny] == '#' {
                continue;
            }
            if nx == 0 || ny == 0 || nx == h-1 || ny == w-1 {
                flag = true;
            }
            queue.push_back((nx,ny,depth+1));
            visited[nx][ny] = true;
        }
    }
    if flag {
        println!("1");
        return;
    }

    println!("{}", (dist(mn, (h,w))+k-1)/k+1);
}

use std::cmp;
use std::collections::VecDeque;

const INF: i32 = 1e9 as i32;
const DIR: [(i32, i32); 4] = [(0, -1), (0, 1), (-1, 0), (1, 0)];

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let h: usize = sc.read();
    let w: usize = sc.read();
    let k: i32 = sc.read();
    let board: Vec<_> = (0..h).map(|_| sc.chars()).collect();
    let mut dist = vec![vec![INF; w]; h];

    let mut si = 0;
    let mut sj = 0;
    for i in 0..h {
        for j in 0..w {
            if board[i][j] == 'S' {
                dist[i][j] = 0;
                si = i;
                sj = j;
            }
        }
    }

    let mut q = VecDeque::new();
    q.push_back((0, 0, si, sj));
    for _ in 0.. {
        let mut next_q = VecDeque::new();
        while let Some((time, open, i, j)) = q.pop_front() {
            if i == h - 1 || j == w - 1 || i == 0 || j == 0 {
                let turn = (time + k - 1) / k;
                println!("{}", turn);
                return;
            }
            for (di, dj) in DIR.iter().cloned() {
                let ni = (i as i32) + di;
                let nj = (j as i32) + dj;
                if ni < 0 || nj < 0 {
                    continue;
                }
                let ni = ni as usize;
                let nj = nj as usize;
                if ni >= h || nj >= w {
                    continue;
                }

                if board[ni][nj] == '#' && open > 0 && dist[ni][nj] > time + 1 {
                    dist[ni][nj] = time + 1;
                    if (time + 1) % k == 0 {
                        next_q.push_back((time + 1, k, ni, nj));
                    } else {
                        q.push_back((time + 1, open - 1, ni, nj));
                    }
                } else if board[ni][nj] == '.' && dist[ni][nj] > time + 1 {
                    dist[ni][nj] = time + 1;
                    if (time + 1) % k == 0 {
                        next_q.push_back((time + 1, k, ni, nj));
                    } else {
                        q.push_back((time + 1, open, ni, nj));
                    }
                }
            }

            let next_time = (time + k) / k * k;
            next_q.push_front((next_time, k, i, j));
        }
        q = next_q;
    }
}

