    let dx = [0,0,1,-1];
    let dy = [1,-1,0,0];
    let mut queue = VecDeque::new();
    let mut visited = vec![vec![false; w];h];
    let mut mn = (0,0);
    for x in 0..h {
        for y in 0..w {
            if a[x][y] == 'S' {
                queue.push_back((x,y,0));
                visited[x][y] = true;
                mn = (x,y);
            }
        }
    }

    while let Some((x,y,depth)) = queue.pop_front() {
        if depth > k {
            break;
        }
        if dist(mn, (h,w)) > dist((x,y), (h,w)) {
            mn = (x,y);
        }

        for i in 0..4 {
            let nx = x as isize + dx[i];
            let ny = y as isize + dy[i];
            if nx < 0 || ny < 0 {
                continue;
            }
            let nx = nx as usize;
            let ny = ny as usize;
            if nx > h-1 || ny > w-1 || visited[nx][ny] || a[nx][ny] == '#' {
                continue;
            }
            queue.push_back((nx,ny,depth+1));
            visited[nx][ny] = true;
        }
    }

    if dist(mn, (h,w)) == 0 {
        println!("1");
    } else {
        println!("{}", (dist(mn, (h,w))+k-1)/k+1);
    }
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, bytes) => {
        read_value!($next, String).into_bytes()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

