    let dy = vec![1, -1, 0, 0];
    while(now.len() != 0){
        let mut top = now.pop().unwrap();
        let d = top[0]*-1;
        let x = top[1];
        let y = top[2];
        if dist[x as usize][y as usize]<d as usize{
            continue;
        }
        for i in 0..4{
            let mut xx = dx[i]+x as i64;
            let mut yy = dy[i]+y as i64;
            if 0<=xx && xx<H as i64 && 0<=yy && yy<W as i64{

                let mut xx = xx as usize;
                let mut yy = yy as usize;
                if A[xx][yy] == '#'{
                    continue;
                }
                if dist[xx][yy]>d as usize+1{
                    dist[xx][yy] = d as usize+1;
                    now.push(vec![(d+1)*-1, xx as i64, yy as i64]);
                }
            }
        }
    }
    let mut res = INF as usize;
    for i in 0..H{
        for j in 0..W{
            if dist[i][j]<=K{
