    let h = scan.read::<usize>();
    let w = scan.read::<usize>();
    let k = scan.read::<usize>();
    let a = arr(h, |_| scan.chars());
    let mut s = 0;
    for y in 0..h { for x in 0..w {if a[y][x]=='S' {s = y * w + x;}}}
    let mut que = VecDeque::new();
    que.push_back((s, 0));
    let mut used = vec![vec![false;w];h];
    while let Some((pos, cnt)) = que.pop_front() {
        let y = pos/w;
