  ($iter:expr, [ $t:tt ]) => {{
    let len = read_value!($iter, usize);
    (0..len).map(|_| read_value!($iter, $t)).collect::<Vec<_>>()
  }};

  ($iter:expr, $t:ty) => {
    $iter.next().unwrap().parse::<$t>().expect("Parse error")
  };
}

fn main() {
  let out = std::io::stdout();
  let mut out = std::io::BufWriter::new(out.lock());
  macro_rules! puts {
    ($($format:tt)*) => (write!(out,$($format)*).unwrap());
  }
  input! {
    h: usize,
    w: usize,
    k: i32,
    field: [chars; h],
  }
  let mut start = (0, 0);
  'outer: for (i, r) in field.iter().enumerate() {
    for (j, &c) in r.iter().enumerate() {
      if c == 'S' {
        start = (i, j);
        break 'outer;
      }
    }
  }
  let mut dist = vec![vec![1 << 30; w]; h];
  dist[start.0][start.1] = 0;
  use std::collections::VecDeque;
  let mut que = VecDeque::new();
  que.push_back(start);
  let dis = [0, 1, 0, -1];
  let djs = [1, 0, -1, 0];
  while let Some((i, j)) = que.pop_front() {
    let d = dist[i][j];
    for (&di, &dj) in dis.iter().zip(djs.iter()) {
      let ni = i as i32 + di;
      let nj = j as i32 + dj;
      if ni < 0 || ni >= h as i32 || nj < 0 || nj >= w as i32 {
        continue;
      }
      let ni = ni as usize;
      let nj = nj as usize;
      if field[ni][nj] == '#' {
        continue;
      }
      if dist[ni][nj] > d + 1 {
        dist[ni][nj] = d + 1;
        que.push_back((ni, nj));
      }
    }
  }
  let mut d_edge = 1 << 30;
  for (i, r) in dist.iter().enumerate() {
    for (j, &d) in r.iter().enumerate() {
      if d <= k {
        d_edge = cmp::min(d_edge, cmp::min(
          cmp::min(i, h - 1 - i),
          cmp::min(j, w - 1 - j)
        ));
      }
    }
  }

  puts!("{}\n", (d_edge as i32 + k - 1) / k + 1);
}

#![allow(non_snake_case)]
use std::collections::VecDeque;
use std::cmp::min;
fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let H:usize = sc.read();
    let W:usize = sc.read();
    let K:usize = sc.read();
    let A: Vec< Vec<char>> = (0..H).map(|_| sc.chars()).collect();

    let mut V: Vec< Vec<usize>> = vec![ vec![K+1;W];H];
    let mut q: VecDeque< (usize, usize)> = VecDeque::new();
    let mut m:usize = H;
    for i in 0..H{
        for j  in 0..W{
            if A[i][j] == 'S' {
                V[i][j] = 0;
                q.push_back((i, j));
                m = min(m, i);
                m = min(m, H-1-i);
                m = min(m, j);
                m = min(m, W-1-j); 
                break;
            }
        }
        if !q.is_empty(){
            break;
        }
    }
    while let Some((u, v)) = q.pop_front(){
        let t = V[u][v];
        if 0 < u{
            if (A[u-1][v] == '.') && (V[u-1][v] == K+1){
                V[u-1][v] = t+1;
                m = min(m, u-1);
                if t+1 < K{
                    q.push_back((u-1,v))
                }
            }
        }
        if u < H-1{
            if (A[u+1][v] == '.')&&(V[u+1][v] == K+1) {
                V[u+1][v] = t+1;
                m = min(m, H-1-(u+1));
                if t+1 < K{
                    q.push_back((u+1,v));
                }
            }
        }
        if 0 < v{
            if (A[u][v-1] == '.') && (V[u][v-1] == K+1){
                V[u][v-1] = t+1;
                m = min(m, v-1);
                if t+1 < K{
                    q.push_back((u,v-1))
                }
            }
        }
        if v < W-1{
            if (A[u][v+1] == '.')&&(V[u][v+1] == K+1) {
                V[u][v+1] = t+1;
                m = min(m, W-1-(v+1));
                if t+1 < K{
                    q.push_back((u,v+1));
                }
            }
        }
    }
    if m == 0{
        println!("1");
        return
    }else{
        println!("{}", (m+(K-1))/K+1);
    }
}

pub struct Scanner<R> {
    stdin: R,
}

impl<R: std::io::Read> Scanner<R> {
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .stdin
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n')
            .take_while(|&b| b != b' ' && b != b'\n')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
        .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}
